template<class Cost = int>
struct Edge {
    int from, to;
    Cost cost;
    Edge(const int &from = -1, const int &to = -1, const Cost &cost = 1)
        : from(from), to(to), cost(cost) {}

    bool operator<(const Edge<Cost> &rhs) const { return this->cost < rhs.cost; }
    bool operator>(const Edge<Cost> &rhs) const { return this->cost > rhs.cost; }
};

template<class Cost = int>
struct Graph : vector<vector<Edge<Cost>>> {
    int n;
    Graph(int _n = 0) : n(_n) { this->resize(n); }

    void add_edge(const int &src, const int &dst, const Cost &cost = 1) {
        assert(0 <= src && src < n && 0 <= dst && dst < n);
        (*this)[src].emplace_back(src, dst, cost);
    }
    void add_biedge(const int &src, const int &dst, const Cost &cost = 1) {
        add_edge(src, dst, cost), add_edge(dst, src, cost);
    }
};

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);
    long long N, M; cin >> N >> M;
    Graph<> G(N);
    for (int i = 0; i < M; i++) {
        int a, b; cin >> a >> b;
        G.add_biedge(--a, --b);
    }
    auto coloring = [&]() {
        vector<int> C(N, -1); C[0] = 0;
        bool ok = true;
        auto dfs = [&](auto &&self, int curr, int prev) -> void {
            for (auto &e: G[curr]) {
                if (e.to == prev) continue;
                if (C[e.to] == -1) {
                    C[e.to] = 1 - C[curr];
                    self(self, e.to, curr);
                } else {
                    if (C[e.to] != 1 - C[curr]) ok = false;
                }
            }
        };
        dfs(dfs, 0, -1);
        if (ok) {
            long long E[2] = {0, 0};
            for (int i = 0; i < N; i++) E[C[i]]++;
            cout << E[0] * E[1] - M << "\n";
        } else {
            cout << N * (N-1) / 2 - M << "\n";
        }
    };
    coloring();
    return 0;
}

