void solve()
{
	int N, M;
	cin >> N >> M;
	vector<int> adj[N];
	set<pair<int, int>> s;
	for (int i = 0; i < M; i++)
	{
		int a, b;
		cin >> a >> b;
		a--, b--;
		if (a > b) swap(a, b);
		adj[a].push_back(b);
		adj[b].push_back(a);
		s.emplace(a, b);
	}
	int ans = 0;

	for (int k = 0; k < 2; k++)
		for (int i = 0; i < N; i++)
	{
		queue<tuple<int, int, int>> q;
