struct isBinG
{
	lint n;
	vec c;
	const vec2& g;
	bool dfs(lint pos)
	{
		rep(i, g[pos].size())
		{
			if (c[g[pos][i]] == 0)
			{
				c[g[pos][i]] = -c[pos];
				if (!dfs(g[pos][i]))
					return false;
			}
			else if (c[g[pos][i]] != -c[pos])
			{
				return false;
			}
		}
		return true;
	}

	isBinG(const vec2& g) : g(g), n(g.size()), c(n, 0) {}
	bool q(lint pos)
	{
		c[pos] = 1;
		return dfs(pos);
	}
	bool qall()
	{
		rep(i, n)
		{
			if (c[i] == 0 && q(i) == false)
				return false;
		}
		return true;
	}
};

