void DFS(vector<vector<int>> &G, vector<vector<int>> &GG, int depth, int node, vector<int>& out, int start, vector<bool> &check) {
	if (check[node]) return;
	check[node] = true;
	if (depth == 0) {
		if (not GG[start][node]) out.push_back(node);
		return;
	}
	for (auto &a : G[node]) {
		DFS(G, GG, depth - 1, a, out, start);
	}
}

void DFS(vector<vector<int>> &G, vector<vector<int>> &GG, int depth, int node, vector<int>& out, int start) {
