void merge(int x,int y) {
	x=find(x);y=find(y);
	if (x==y) return;
	if (sz[x]>sz[y]) {
		sz[x]+=sz[y];
		par[y]=x;
	} else {
		sz[y]+=sz[x];
		par[x]=y;
	}
