vector<vector<int>> graph;

int bfs() {
    state = vector<int>(n);
    for (int i = 0; i < n; i++)state[i] = -1;
    queue<int> que;
    for (auto x:graph[0])que.push(x);
    que.push(-1);
    int depth = 1;
    while (true) {
        int next = que.front();
        que.pop();
        if (next == -1) {
            if (que.empty())break;
            depth++;
            que.push(-1);
        } else {
            if (state[next] >= 0 && state[next] != depth % 2) return -1;
            state[next] = depth % 2;
            for (auto x:graph[next])
                if (state[x] < 0)que.push(x);
        }
    }
    return 0;
}

