void DFS(vector<vector<int>> &G, vector<vector<int>> &GG, int depth, int node, vector<int>& out, int start, vector<bool> &check) {
	if (check[node]) return;
	check[node] = true;
	if (depth == 0) {
		if (not GG[start][node]) out.push_back(node);
		return;
	}
	for (auto &a : G[node]) {
		DFS(G, GG, depth - 1, a, out, start, check);
	}
}

void DFS(vector<vector<int>> &G, vector<vector<int>> &GG, int depth, int node, vector<int>& out, int start) {
	vector<bool> b(G.size());
	DFS(G, GG, depth, node, out, start, b);
}

void solve() {
	int N, M; cin >> N >> M;
	int ans = 0;
	vector<vector<int>> G(N);
	vector<vector<int>> GG(N, vector<int>(N));
	REP(i, M) {
		int a, b; cin >> a >> b;
		--a;
		--b;
		G[a].push_back(b);
		G[b].push_back(a);
		GG[a][b] = true;
		GG[b][a] = true;
	}

	REP(i, N) GG[i][i] = true;

	bitset<100001> f;

	REP(start, N) {
		vector<int> res;
		queue<int> q;
		DFS(G, GG, 3, start, res, start);
		if (not res.empty()) f[start] = 1;
		for (auto &node : res) if (not GG[start][node]) {
			++ans;
			// cout << start+1 << "-" << node+1 << endl;
			q.push(node);
			G[start].push_back(node);
			G[node].push_back(start);
			GG[start][node] = true;
			GG[node][start] = true;
		}

	}
	if (not f.any()) {
		cout << ans << endl;
		return;
	}
	else f = bitset<100001>();
}

