            maps[u].push_back(fa);
        }
        return;
    }
    for(int i=0; i<Size(maps[u]); i++) {
        int v = maps[u][i];
        if(visit[v])
            continue;
        visit[v] = true;
        dfs(v, sum+1, fa);
        visit[v] = false;
    }
}

