        flag = false;
        for(int i=1; i<=n; i++) {
            visit[i] = true;
            for(int j=0; j<Size(maps[i]); j++) {
                mark[maps[i][j]] = true;
            }
            dfs(i, 0, i);
            visit[i] = false;
            for(int j=0; j<Size(maps[i]); j++) {
                mark[maps[i][j]] = false;
            }
        }
        if(!flag)
            break;
    }
    printf("%d\n", answer);
}

