// bipartite graphs
// if the given graph is bipartite, returns the way of coloring vertices
// if not, returns {-1}
std::vector<int> is_bipartite(std::vector<std::vector<int>>& g) {
    int n = (int) g.size();
    unionfind uf(2 * n);
    for (int i = 0; i < n; ++i) {
        for (auto j : g[i]) {
            assert(0 <= j && j < n);
            if (!uf.same(i, j + n)) uf.unite(i, j + n);
            if (!uf.same(i + n, j)) uf.unite(i + n, j);
