void addEdge(const unsigned int from, const unsigned int to)
{
    static edge* cur = ed;
    cur->to = to;
    cur->pre = head[from];
    head[from] = cur;
    ++cur;
}
bool dfs(const unsigned int x, const unsigned int sta)
{
    ++siz[col[x]][sta];
    vis[x] = true;
    bool ret = true;
    for (const edge* i = head[x]; i; i = i->pre)
    {
        const unsigned int to = i->to;
        if (vis[to])
        {
            if (col[to] == col[x])
                ret = false;
            continue;
        }
        col[to] = !col[x];
        ret &= dfs(to, sta);
    }
    return ret;
}
