#include <stdio.h>
#include <iostream>
#include <algorithm>
#include <utility>
#include <vector>

#define MAX 100005

typedef long long ll;

using namespace std;

struct Graph
{
    int n,m,a,b;
    vector<int> v[MAX];
    int c[MAX]={};
    int odd=0;
    int even=0;
    bool flag=false;//false<->2部ぐらふ

    void input()
    {
        cin>>n>>m;
        for(int i=0;i<m;i++)
        {
            cin>>a>>b;
            v[a].push_back(b);
            v[b].push_back(a);
        }
    }

    void dfs(int x,int col)
    {
        if(flag) return;
        for(int i=0;i<v[x].size();i++)
        {
            int y=v[x][i];
            if(c[y]==0)
            {
                c[y]=col;
                if(col==1) even++;
                    else       odd++;
                dfs(y,-1*col);
            }
            else if(c[y]!=col)
            {
                flag=true;break;
            }
        }
    }

    void solve()
    {
        dfs(1,1);
        ll ans;
        if(flag) ans=(n*(n-1))/2-m;
        else     ans=odd*even-m;

        cout<<ans<<endl;
    }

};

int main()
{
    Graph g;

    g.input();

    g.solve();

    return 0;
}

