using namespace std;
using Graph = vector<vector<ll>>;

bool is_graph(ll v, const Graph &G, vector<ll> &seen, ll flag)
{
  if (seen[v] > 0)
    return seen[v] == flag;
  else
    seen[v] = flag;

  for (auto g : G[v])
  {
    if (flag == 2)
    {
      if (!is_graph(g, G, seen, 1))
        return false;
    }
    else
    {
      if (!is_graph(g, G, seen, 2))
        return false;
    }
  }
  return true;
}
int main()
{
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  ll n, m;
  cin >> n >> m;
  Graph G(n);
  rep(i, m)
  {
    ll a, b;
    cin >> a >> b;
    a--;
    b--;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  vector<ll> seen(n);
  if (is_graph(0, G, seen, 1))
  {
    if (n % 2 == 1)
    {
      cout << (n - 1) * (n + 1) / 4 - m << endl;
    }
    else
    {
      cout << n * n / 4 - m << endl;
    }
  }
  else
  {
    cout << n * (n - 1) / 2 - m << endl;
  }

  return 0;
}

