			if (f[w[i][0]] != f[w[i][1]]) {
				if (f[w[i][0]] == 1)
					f[w[i][1]] = 2;
				else if (f[w[i][0]] == 2)	f[w[i][1]] = 1;
			}
			else { F = 1; break; }
		}
		int sum = 0,ssum=0;
		for (int i = 1; i <= n; i++)
			if (f[i] == 1)
				sum++;
			else if (f[i] == 2)
				ssum++;
		std::cout << (F==1?n+n*(n-3)/2:sum*ssum)-m << std::endl;
	return 0;
}

