using Weight = int;
using Flow = int;
struct Edge {
    int src, dst;
    Weight weight;
    Flow cap;
    Edge() : src(0), dst(0), weight(0) { }
    Edge(int s, int d, Weight w) : src(s), dst(d), weight(w) { }
};
bool operator < (const Edge &e, const Edge &f) {
    return e.weight != f.weight ? e.weight > f.weight : // pqが降順のため
        e.src != f.src ? e.src < f.src : e.dst < f.dst;
}
using Edges = vector<Edge>;
struct Graph {
    vector<Edges> adj;
    Graph(int n) : adj(n) { }
    int size() { return adj.size(); }
    Edges operator [] (int v) { return adj[v]; }
    void add_edge(int a, int b, Weight w = 1) { // graph
        adj[a].emplace_back(a, b, w);
        adj[b].emplace_back(b, a, w);
    }
    void add_arc(int a, int b, Weight w = 1) {  // digraph
        adj[a].emplace_back(a, b, w);
    }
};
using Array = vector<Weight>;
using Matrix = vector<Array>;
//---------------------------------------------------------------

int is_bipartite(Graph &G) {
    int n = G.size();
    vector<int> color(n, -1);
    int cntW = 0;
    function<bool(int, int)> dfs = [&](int u, int c) {
        if ((color[u] = c)) cntW++;
        for (Edge &e : G[u]) {
            int v = e.dst;
            if (color[v] < 0) {
                if (!dfs(v, 1 - c)) return false;
            } else if (color[v] != 1 - c) {
                return false;
            }
        }
        return true;
    };
    if (!dfs(0, 0)) return -1;
    return cntW;
}

int main() {
    int V, E; cin >> V >> E;
    Graph G(V);
    for (int i = 0; i < E; i++) {
        int a, b; cin >> a >> b;
        G.add_edge(a - 1, b - 1);
    }
    int cntW = is_bipartite(G);
    if (cntW < 0) {
        cout << (V * (V - 1) / 2 - E) << endl;
    } else {
        int cntB = V - cntW;
        cout << (cntB * cntW - E) << endl;
    }
    return 0;
}

