        edge[A[i]-1][B[i]-1] = 1;
        edge[B[i]-1][A[i]-1] = 1;
    }

    //二部グラフ判定
    bool flag = true;
    vector<int> vertex_group(N,-1);
    stack<int> ver_stack;

    vertex_group[0] = 1;
    ver_stack.push(0);

    while(!ver_stack.empty()){
        int v = ver_stack.top();

        ver_stack.pop();

        for (int j = 0; j < N; j++){
            if (edge[v][j] && vertex_group[j] == vertex_group[v])
            {
                flag = false;
                break;
            }
            //枝があってかつその頂点がまだラベルが付いていないなら
            if (edge[v][j] && vertex_group[j] == -1)
            {
                vertex_group[j] = 1 - vertex_group[v];
                ver_stack.push(j);
            }
        }

        if(!flag)
            break;
    }

    if(!flag){
        cout << N * (N - 1)/2 - M << endl;
    }else{
        int count0 = 0;
        int count1 = 0;
        for (int i = 0; i < N; i++){
            if(vertex_group[i] == 0){
                count0++;
            }else if (vertex_group[i] == 1){
                count1++;
            }
