int BipartiteGraph(Graph &g) {
        int n = g.size();
        vector<int> color(n, -1);
        int white_cnt = 0;
        function<bool (int, int, int)> dfs = [&](int u, int prev, int c) {
                color[u] = c;
                if (c == 1) white_cnt ++;
                for (auto e : g[u]) {
                    int v = e.dst;
                    if (v != prev) {
                            if (color[v] == -1) {
                                    if (!dfs(v, u, 1 - c)) return false;
                            } else if (color[v] != 1 - c) {
                                    return false;
                            }
                    }

                }
                return true;
        };
        if (!dfs(0, -1, 0)) return -1;
        return white_cnt;
}

