                que.push(make_pair(next, (node_color + 1) % 2));
            }
            else if(color[next] == 0 && node_color == 0){
                ret = false;
                break;
            }
            else if(color[next] == 1 && node_color == 1){
                ret = false;
                break;
            }
        }
    }
    if(ret){
        for (int i=0; i<n; ++i){
            //debug(color[i]);
            if(color[i] == 0){
                color1++;
            }
            else {
                color2++;
            }
        }
    }
    return ret;
}

