	rep(i, 0, sz(G[v])) {
		int n = G[v][i];
		if(used[n]) {
			int td = O[n];
			if(td == O[v]) return true;
		}
		else {
			if(dfs(n, d + 1)) return true;
		}
	}
	return false;
}

void solve() {
	cin >> N >> M;
	rep(i, 0, M) {
		int a, b;
		cin >> a >> b; a--; b--;
		G[a].pb(b); G[b].pb(a);
	}
	if(dfs(0, 0)) {
		cout << N * 1LL * (N - 1) / 2 - M << "\n"; 
		return;
	}
	int odd = 0, even = 0;
	rep(i, 0, N) {
		if(O[i]) odd++;
		else even++;
	}
	cout << odd * 1LL * even - M << "\n";
}

