void dfs(int start_v, int v, int depth, bool checked[100002]) {
  if (depth == 3) {
    return;
  }
  if (checked[v]) {
    return;
  }
  checked[v] = true;
  for (auto u : G[v]) {
    if (start_v == u) {
      continue;
    }
    if (depth == 2) {
      X[start_v].push_back(u);
    }
    dfs(start_v, u, depth + 1, checked);
  }
}

