void Dfs(int x, int fa, int d) {
	int ed = last[x], dr;
	if(vis[x]) return;
	vis[x] = true;
//	printf("%d %d\n", x, d);
	if(d == 4) {
		cnt = cnt + 2, d = 3;
	}
	while(ed != -1) {
		dr = other[ed];
		if(dr != fa) Dfs(dr, x, d + 1);
		ed = pre[ed];
	}
}
void Init() {
	all = -1; memset(last, -1, sizeof(last));
	memset(vis, 0, sizeof(vis));
	memset(ind, 0, sizeof(ind));
	for (int i = 1; i <= m; i++) {
		int u, v;
		scanf("%d%d", &u, &v);
