int max_idx,max_depth;
bool bfs(int src, vvi &v){ // v...隣接リスト
    max_idx=0, max_depth = 0;
    mem(A,-1);
    Q.push(src); // Qの初期化
    A[src] = 0; // A[スタート地点]の深さ
    while(! Q.empty()){
        int cur = Q.front();
        trc(v[cur] , cur);
        Q.pop();
        for(int x : v[cur]){ // 探索範囲
            trc(x,A[x]);
            if(A[x] == -1){ // 条件
                int dst = x;
                trc(dst);
                A[dst]=A[cur]+1; // dstの深さはA[cur]+1
                Q.push(dst); // Qにdstを追加
                if(amax(max_depth,A[dst])) max_idx = dst;
            }
            else if( (A[cur] + 1) % 2 != A[x] % 2 ){
                return false;
            }
        }
    }
    return true;
}

