bool BipartiteGraph::Dfs(int v, int c){
    color[v] = c;
    for(auto x: graph[v]){
        if(color[x] == c) return false;
        if(color[x] == 0 && !Dfs(x, -c)) return false;
    }

    return true;
}

bool BipartiteGraph::Run(){
    for(int i = 0; i < V; i++){
        if(color[i] == 0){
            if(!Dfs(i, 1)){
                return false;
            }
        }
    }
    return true;
}

