    while(cin >> N >> M){
        vector<vector<int>> g(N);
        for(int i=0;i<M;i++){
            int a, b; cin >> a >> b;
            --a; --b;
            g[a].push_back(b);
            g[b].push_back(a);
        }
        vector<vector<int>> visit(2, vector<int>(N, 0));
        queue<pair<int,int>> qu;
        qu.emplace(0, 0);
        visit[0][0] = 1;
