            auto p = qu.front(); qu.pop();
            for(auto t : g[p.second]){
                if(visit[1-p.first][t]) continue;
                visit[1-p.first][t] = 1;
                qu.emplace(1-p.first, t);
            }
        }
        int cnt[2] = {0, 0};
        for(int i=0;i<2;i++){
            for(int j=0;j<N;j++) cnt[i] += visit[i][j];
