        if(cnt[0] + cnt[1] == N){
            long long res = cnt[0] * (long long)cnt[1];
            for(int i=0;i<N;i++){
                for(int t : g[i]){
                    if(i > t) continue;
                    if(visit[0][i]+visit[0][t] == 1) --res;
                }
            }
            cout << res << endl;
