#include "bits/stdc++.h"
using namespace std;
class dsu{
private:
    const int default_size = 100100;
    vector<int> parent;
    int size;
    int find(int vertex){
        return (parent[vertex] < 0)?vertex:parent[vertex] = find(parent[vertex]);
    }
public:
    dsu(){
        this->size = default_size;
        parent.assign(size, -1);
    }
    dsu(int size){
        this->size = size;
        parent.assign(size, -1);
    }
    void clear(){
        parent.assign(size, -1);
    }
    bool isConnected(int u, int v){
        return find(u) == find(v);
    }
    bool connect(int u, int v){
        u = find(u);
        v = find(v);
        if(u != v){
            if(-parent[u] < -parent[v]) swap(u, v);
            parent[u] += parent[v];
            parent[v] = u;
        }
        return u != v;
    }
    int componentSize(int u){
        return - parent[find(u)];
    }
    bool isRoot(int u){
        return parent[u] < 0;
    }
};
const int maxn = 555;
void init(vector<vector<int> > & g, vector<int> & c, int cur, int p){
    if(p != -1) c[cur] = c[p] ^ 1;
    for(int nxt : g[cur]) if(nxt != p)
        init(g, c, nxt, cur);
}
