        scanf("%d %d", &u, &v);u--;v--;
        if(!solver.isConnected(u, v)){
            g[u].push_back(v);
            g[v].push_back(u);
            solver.connect(u, v);
        } else {
            es.push_back({u, v});
        }
    }
    vector<int> cores(n, 0);
    init(g, cores, 0, -1);
    long long qtd_z = 0;
    long long qtd_o = 0;
    for(int e = 0; e < n; e++){
        if(cores[e] == 0) qtd_z++;
        else qtd_o++;
    }
    bool full = false;
    for(auto & u : es){
        if(cores[u.first] == cores[u.second])
            full = true;
    }
    if(full) printf("%lld\n", 1ll*n*(n-1)/2 - m);
    else printf("%lld\n", qtd_z * qtd_o - m);
    return 1;
}
