constexpr i64 MOD = 1e9 + 7;
mt19937 rnd(chrono::steady_clock::now().time_since_epoch().count());
using vi = vector<i64>;
using vvi = vector<vi>;
using vvvi = vector<vvi>;
using ii = pair<i64, i64>;

class Graph {
    int n, max_color;
    vector<int> color;
    bool is_bip = true;
    map<int, int> visited;
    vvi blacks, whites;

    void dfs(int v, int c) {
        if (color[v] != -1) {
            if (color[v] != c) is_bip = false;
            return;
        }
        color[v] = c;
        visited.erase(v);
        for (int i: adj[v]) {
            dfs(i, c + 1 - c % 2 * 2);
        }
    }

public:
    vvi adj;
    vvi adj_matrix;

    Graph(int n) {
        this->n = n;
        adj = vvi(n);
    }

    void use_adj_matrix() {
        adj_matrix = vvi(n, vi(n));
    }

    void addEdge(int a, int b) {
        assert(0 <= a && a < n);
        assert(0 <= b && b < n);
        if (adj_matrix.size()) {
            adj_matrix[a][b] = 1;
            adj_matrix[b][a] = 1;
        }
        adj[a].push_back(b);
        adj[b].push_back(a);
    }

    bool is_bipartite() {
        for (int i = 0; i < n; i++) {
            visited[i] = 1;
        }
        color = vector<int>(n, -1);
        max_color = 0;
        while (visited.size()) {
            int v = (*visited.begin()).first;
            dfs(v, max_color);
            max_color += 2;
        }
        return is_bip;
    }

    bool is_connected() {
        color = vector<int>(n, -1);
        dfs(0, 0);
        for (int i = 0; i < n; i++) {
            if (color[i] == -1) {
                return false;
            }
        }
        return true;
    }

    vvi get_blacks() {
        blacks = vvi(max_color / 2);
        for (int i = 0; i < n; i++) {
            if (color[i] % 2 == 0) {
                blacks[color[i] / 2].push_back(i);
            }
        }
        return blacks;
    }

    vvi get_whites() {
        whites = vvi(max_color / 2);
        for (int i = 0; i < n; i++) {
            if (color[i] % 2 == 1) {
                whites[color[i] / 2].push_back(i);
            }
        }
        return whites;
    }
};


int main() {
    int n, m;
    cin >> n >> m;
    Graph g(n);
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        g.addEdge(a, b);
    }

    g.is_connected();
    if (g.is_bipartite()) {
        vvi blacks = g.get_blacks();
        vvi whites = g.get_whites();
        assert(blacks.size() == 1 && whites.size() == 1);
        cout << i64(blacks.front().size()) * i64(whites.front().size()) - m << endl;
    } else {
        cout << n * (n - 1) / 2 - m << endl;
    }


}

