queue<int> q;
bool judge() {
    int x = q.front();
    q.pop();

    for (auto to : node[x].edge) {
        if (node[to].visit) {
            if (node[x].clr == 1 && node[to].clr == 1)
                return false;
            else if (node[x].clr == -1 && node[to].clr == -1)
                return false;
        }

        else {
            q.push(to);
            node[to].visit = 1;
            if (node[x].clr == 1)
                node[to].clr = -1;
            else if (node[x].clr == -1)
                node[to].clr = 1;
        }
    }
    if (!q.empty())
        return judge();
    return true;
}

