using namespace std;
#define SIZE 300000
class unionfind
{
public:
	int par[SIZE];
	int ran[SIZE];
	int ren[SIZE];
	void init()
	{
		for (int i = 0; i<SIZE; i++)
		{
			par[i] = i;
			ran[i] = 0;
			ren[i] = 1;
		}
	}
	int find(int a)
	{
		if (a == par[a])return a;
		else return par[a] = find(par[a]);
	}
	void unite(int a, int b)
	{
		a = find(a);
		b = find(b);
		if (a == b)return;
		if (ran[a]>ran[b])
		{
			par[b] = a;
			ren[a] += ren[b];
		}
		else
		{
			par[a] = b;
			ren[b] += ren[a];
		}
		if (ran[a] == ran[b])ran[b]++;
	}
};
unionfind uf1, uf2;
typedef long long ll;
int deg[100000];
int sum[100000];
bool flag[100000];
int main()
{
	int num, way;
	scanf("%d%d", &num, &way);
	uf1.init();
	uf2.init();
	for (int i = 0; i < way; i++)
	{
		int za, zb;
		scanf("%d%d", &za, &zb);
		za--, zb--;
		uf1.unite(za, zb);
		uf2.unite(za * 2, zb * 2 + 1);
		uf2.unite(za * 2 + 1, zb * 2);
		deg[za]++, deg[zb]++;
	}
	ll ans = 0;
	for (int i = 0; i < num; i++)
	{
		int f = uf1.find(i);
		sum[f] += deg[i];
		if (uf1.ren[f] - 1 == deg[i])flag[f]=true;
	}
	for (int i = 0; i < num; i++)
	{
		if (uf1.find(i) == i)
		{
			if ((!flag[i]) || sum[i]>uf1.ren[i] * 2 - 2)
			{
				if (uf2.find(i * 2) == uf2.find(i * 2 + 1))
				{
					ans += (ll)(uf2.ren[uf2.find(i * 2)] / 2)*(ll)(uf2.ren[uf2.find(i * 2)] / 2 - 1) / 2;
				}
				else
				{
					ans += (ll)(uf2.ren[uf2.find(i * 2)] / 2)*(ll)(uf2.ren[uf2.find(i * 2 + 1)] / 2);
				}
			}
			else ans += sum[i] / 2;
		}
	}
	printf("%lld\n", ans - way);
}

