  return (n*(n-1))/2;
}

int main(){
  ios::sync_with_stdio(0); cin.tie(0);
  int n,m; cin>>n>>m;
  vvi G(n);
  FOR(i,n) {
    int u,v; cin>>u>>v;
    --u; --v;
    G[u].pb(v);
    G[v].pb(u);
  }
  vi E(n);
  bool ok = 1;
  vi C(2);
  vi COL(n,-1);
  function<void(int, int)> dfs = [&](int i, int c) {
    if(COL[i] == -1) {
      COL[i] = c;
    }else{
      if(COL[i] != c) ok = 0;
    }
    if(E[i]) return;
    E[i]=1;
    C[COL[i]]++;
    for(int j : G[i]) dfs(j,c^1);
  };
  lli ans=-m;
  FOR(i,n) if(!E[i]) {
    ok=1; C.assign(2,0);
    dfs(i,0);
    if(ok) {
      ans += C[0]*C[1];
    }else{
      ans += f(C[0]+C[1]);
    }
  }
  cout << ans << endl;
  return 0;
}

