// ref: http://prd-xxx.hateblo.jp/entry/2017/10/13/004256
struct BipartileGraph {
    vi colors;
    vvi edges;
    BipartileGraph(int n) : colors(n, -1), edges(n) {}
    void addEdge(int f, int t) {
        edges[f].emplace_back(t);
        edges[t].emplace_back(f);
    }
    bool build(int s, int color = 0) {
        colors[s] = color;
        for (auto &e : edges[s]) {
            if (colors[e] == color)
                return false;
            if (colors[e] == -1 && !build(e, color ^ 1))
                return false;
        }
        return true;
    }
};

int main() {
    int n, m;
    cin >> n >> m;
    BipartileGraph gr(n);
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        gr.addEdge(a, b);
    }
    bool bipartile = gr.build(0);
    if (bipartile) {
        int col1 = 0;
        int col2 = 0;
        for (int i = 0; i < n; ++i) {
            if (gr.colors[i] == 1)
                col1++;
            else
                col2++;
        }
        cout << col1 * col2 - m << "\n";
    } else {
        cout << n * (n - 1) / 2 - m << "\n";
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <stack>

using namespace std;

int n, m;
typedef long long ll;

bool Dwu(vector< vector<int> >& G)
{
    vector<bool> odw(n, false);
    stack<int> S;
    vector<int> col(n, -1);
    odw[0] = true;
    S.push(0);
    col[0] = 0;
    while (!S.empty())
    {
        int akt = S.top();
        S.pop();
        for (int i = 0; i < G[akt].size(); ++i)
        {
            if (!odw[G[akt][i]])
            {
                odw[G[akt][i]] = true;
                S.push(G[akt][i]);
                if (col[akt] == 0)
                    col[G[akt][i]] = 1;
                else
                    col[G[akt][i]] = 0;
            }
        }
    }
    for (int i = 0; i < n; ++i)
    {
        for (int j = 0; j < G[i].size(); ++j)
        {
            if (col[i] == col[G[i][j]])
                return false;
        }
    }
    return true;
}

int main()
{
    ios_base::sync_with_stdio(0);
    cin >> n >> m;
    vector< vector<int> > G(n);
    for (int i = 0; i < m; ++i)
    {
        int a, b;
        cin >> a >> b;
        --a;
        --b;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    if (!Dwu(G))
        cout << (n * (n - 1) / 2) - m;
    else
    {
        vector<bool> odw(n, false);
        stack<int> S;
        vector<int> odl(n, 0);
        odw[0] = true;
        S.push(0);
        odl[0] = 0;
        while  (!S.empty())
        {
            int akt = S.top();
            S.pop();
            for (int i = 0; i < G[akt].size(); ++i)
            {
                if (!odw[G[akt][i]])
                {
                    odw[G[akt][i]] = true;
                    S.push(G[akt][i]);
                    odl[G[akt][i]] = odl[akt] + 1;
                }
            }
        }
        int pa = 0, ni = 0;
        for (int i = 0; i < n; ++i)
        {
            if (odl[i] % 2 == 0)
                ++pa;
            else
                ++ni;
        }
        ll zab = 0;
        for (int i = 0; i < pa; ++i)
            zab += pa - 1;
        for (int i = 0; i < ni; ++i)
            zab += ni - 1;
        zab /= 2;
        cout << (n * (n - 1) / 2) - m - zab;
    }
    return 0;
}

