void Dfs(int x,int prev){
    In[x]=1;
  //  printf("Sad je u %d %d\n",x,prev);
    for(int i=0;i<V[x].size();i++){
        if(In[V[x][i]] && V[x][i]!=prev){
     //       printf("Krug %d %d\n",x,V[x][i]);
            if(abs(depth[V[x][i]]-depth[x])==2){
