struct UnionFind{
	vi data;
	UnionFind(int n):data(n,-1){}
	int Find(int i){
		return data[i]<0?i:(data[i]=Find(data[i]));
	}
	bool Unite(int a,int b){
		a=Find(a),b=Find(b);
		if(a==b) return false;
		if(-data[a]<-data[b]) swap(a,b);
		data[a]+=data[b];
		data[b]=a;
		return true;
	}
	int Size(int i){
		return -data[Find(i)];
	}
};

int main()
{
	#ifndef _GLIBCXX_DEBUG
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	constexpr char endl='\n';
	#endif

	for(ll n,m;cin>>n>>m&&n|m;){
		UnionFind uf(2*n);
		rep(i,m){
			int u,v; cin>>u>>v; u--,v--;
			uf.Unite(u,n+v);
			uf.Unite(n+u,v);
		}
		bool bipartite=uf.Find(0)!=uf.Find(n);
		if(bipartite){
			ll l=0;
			rep(i,n) l+=uf.Find(0)==uf.Find(i);
			ll r=n-l;
			cout<<l*r-m<<endl;
		}
		else
			cout<<n*(n-1)/2-m<<endl;
	}
}

