typedef long long ll;

vector<ll> G[100005];
ll res;
ll N,M;

bool h[100005][2];

struct state{
  ll v,f;
};

ll dijk(ll v){
  queue<state> q;
  h[v][0] = 1;
  while(!q.empty()){
    state p = q.front(); q.pop();
    for( ll to : G[p.v] ) {
      if( h[G[p.v][to]][1-p.f] ) continue;
      h[G[p.v][to]][1-p.f] = true;
      q.push((state){to,1-p.f});
    }
  }
  ll res = 0;
  for(ll i=0;i<N;i++){
    if( h[i][1] )  res++;
  }
  if( res == N ) return N * N - M;
  int cnt = 0;
  for(int i =0;i<N;i++){
    for(int to : G[i] ){
      if( !(h[i][1] && h[to][1]) ) cnt++;
    }
  }
  return res * (N-res) - cnt;
}
