bool is_bipartite(int current, int now_color) {
	color[current] = now_color;
	for(auto&& next : to[current]) {
		if(color[next] == now_color) return false;
		else if(!color[next] && !is_bipartite(next, -now_color)) return false;
	}
	return true;
}

