    color[v] = cur;
    for(auto next_v:edge_gragh[v]){
        if (color[next_v]!=-1){
            if(color[next_v]==cur) {
                return false;
            }
            continue;
        }
        if(!dfs(edge_gragh,next_v,1-cur)) return false;
    }
    return true;
}


