vector<int> bipartite(vector<pair<int,int>> edge){
    int M = edge.size();
    if(M==0)return {};
    int N = 0;
    for(int i=0;i<M;i++){
        N=max(N,edge[i].first+1);
        N=max(N,edge[i].second+1);
    }
    vector<int> R(N,-1);
    vector<int> S(0);
    vector<vector<int>> es(N,vector<int>(0));
    for(int i=0;i<M;i++){
        es[edge[i].first].push_back(edge[i].second);
        es[edge[i].second].push_back(edge[i].first);
    }
    //cout << N << " " << M << endl;
    //REP(i,N){REP(j,es[i].size()){cout << es[i][j]+1 << " ";}cout << endl;}
    queue<int> Q;
    vector<bool> visited(N,false);
    for(int j=0;j<N;j++){
        if(visited[j])continue;
        Q.push(j);
        R[j]=0;
        visited[j]=true;
        while(!Q.empty()){
            int q=Q.front();
            Q.pop();
            visited[q]=true;
            for(int i=0;i<es[q].size();i++){
                if(R[es[q][i]]==R[q]){
                    return S;
                }
                if(visited[es[q][i]])continue;
                Q.push(es[q][i]);
                R[es[q][i]]=1-R[q];
            }

        }
    }
    return R;
}

