        cout << n*(n-1)/2 - m << "\n";
    }else {
        int c = 1;
        for (int i = 1; i < n; ++i) {
            if(uni.root(0) == uni.root(i)) c++;
        }
        cout << (n-c) * c - m << "\n";
    }
    return 0;
}

