int N,M;
Graph G;
vector<int> col;
bool connect=false;

void bipartite_dfs(int pos, int par, int c) {
	if (col[pos] >= 0) {
		if (c != col[pos]) {
			connect = true;
			return;
		}
		else return;
	}
	col[pos] = c;
	for (auto e : G[pos]) {
		if (e.dst == par)continue;
		bipartite_dfs(e.dst, pos, 1 - c);
	}
}

