using LLI = long long int;
LLI GCD(LLI a,LLI b){ if(a<b) return GCD(b,a); else if(a%b==0) return b; else return GCD(b,a%b); }
LLI LCM(LLI a,LLI b){ return (a/GCD(a,b))*b; }
using VI  = std::vector<LLI>;
using PI  = std::pair<LLI,LLI>;
using VVI = std::vector<VI>;
using VPI = std::vector<PI>;
template<class T> bool is_odd (T x){ return   x%2 ; }
template<class T> bool is_even(T x){ return !(x%2); }
LLI combination(LLI n,LLI k,bool reset=false){
    static VVI C; static LLI n_hashed = -1;
    if(n<0){ std::cerr << "[ERROR] n must be non-negative in combination()" << std::endl; exit(1); }
    if(!(0<=k&&k<=n)){ std::cerr << "[WARNING] k should be in range [0,n] in combination()" << std::endl; return 0; }
    if(n_hashed<n || reset){
        C.resize(n+1);
        for(int i=0;i<=n;++i) C[i].resize(i+1,1); // filled with 1
        for(int i=1;i<=n;++i)for(int j=1;j<i;++j) C[i][j] = C[i-1][j-1] + C[i-1][j];
        n_hashed = n;
    }
    return C[n][k];
}
template<class T> bool has_element(const std::set<T> &set,const T &elem){ return set.find(elem)!=set.end(); }

int main() {
    std::ios::sync_with_stdio(false);
    LLI N,M;
    std::cin >> N >> M;
    VI A(M),B(M);
    rep(i,M){
        std::cin >> A[i] >> B[i];
        A[i]--; B[i]--; // 0-indexed
    }

    VVI graph(N);
    rep(i,M){
        graph[A[i]].push_back(B[i]);
        graph[B[i]].push_back(A[i]);
    }

    std::set<LLI> zero_side;
    VI flag(N,0);
    std::queue<LLI> queue;
    queue.push(0);
    bool is_bipartite = true;

    while(!queue.empty()){
        LLI pos = queue.front();
        queue.pop();
        if(flag[pos]) continue;
        flag[pos] = 1; // true
        rep(i,graph[pos].size()) {
            LLI next = graph[pos][i];
            if (!flag[next]){
                queue.push(next);
                if(!has_element(zero_side,pos)){ // pos not in zero side
                    zero_side.insert(next);
                }
            }else{
                if(has_element(zero_side,pos)==has_element(zero_side,next)){ // not bipartite !
                    is_bipartite = false;
                    break;
                }
            }
        }
    }

    // std::cout << is_bipartite << std::endl;

    if(is_bipartite){
        LLI ans = (N-zero_side.size()) * zero_side.size() - M ;
        std::cout << ans << std::endl;

    }else{
        std::cout << N*(N-1)/2 - M << std::endl;
    }

    return 0;
}

