vvll cinGraph(ll nodeNum, ll edgeNum, bool isDirected){//無向false、有向true
	vvll to(nodeNum);
	REP(i, edgeNum){
		ll v, u; cin >> v >> u;
		v--; u--;
		to[v].push_back(u);
		if (!isDirected) to[u].push_back(v);
	}
	return move(to);
}

ll N, M;
vvll to;
vll done; //0:未 -1:白 1:黒

bool dfs(ll v){
	EACH(u, to[v]){
		if (done[u] == done[v]) return false;
		if (done[u] == 0){
			done[u] = -done[v];
			dfs(u);
		}
	}
	return true;
}



void solve()
{
	cin >> N >> M;
	to = cinGraph(N, M, false);
	done.resize(N);
	done[0] = 1;
	bool isBi = dfs(0);

	if (!isBi){
		ll ans = N*(N-1)/2 - M;
		cout << ans << '\n';
		return;
	}

	ll A=0;
	EACH(e, done){
		if (e==1) A++;
	}
	ll B = N-A;
	ll ans = A*B-M;
	cout << ans << '\n';
}


int main(){
	solve();
	return 0;
}

