void dfs(int now, int pre, int pre2, int pre3) {
    set<int> se2;
    int cnt = 0;
    if (pre != -1) {
        se2.emplace(pre);
        cnt++;
    }
    if (pre2 != -1) {
        se2.emplace(pre2);
        cnt++;
    }
    if (pre3 != -1) {
        se2.emplace(pre3);
        cnt++;
    }
    if (cnt != se2.size()) return;
    //if (min(now, pre3)+1==3) cerr << min(now, pre3)+1 << " " << max(now, pre3)+1 << endl;
    if (pre3 != -1 && G[now].count(pre3) == 0  && now != pre3 && se.count(MP(min(now, pre3), max(now, pre3))) == 0) {
        se.emplace(MP(min(now, pre3), max(now, pre3)));
    }
    FORE(e, G[now]) {
        if (e != pre && (pre2 != e) && pre3 != e && (pre3 == -1 || u2.count(MP(e, pre3)) == 0)) {
            u2.emplace(MP(e, pre3));
            dfs(e, now, pre, pre2);
        }
    }
}

