using Graph = vector<vector<int>>;

vector<int> color;

bool dfs(Graph &G, int v, int c) {
    color[v] = c;
    for(auto next_to : G[v]) {
        if(color[next_to] == c) return false;
        if(color[next_to] == 0 && !dfs(G, next_to, -c)) return false;
    }
    return true;
}

