template< typename T >
bool dfs(WeightedGraph<T>& g, int idx, int par, int col) {
    bool ret=true;
    if(g[idx].col == -1) {
        g[idx].col = col;
        for(auto& e:g[idx].edges){
            if(e.to == par) continue;
            ret &= dfs(g, e.to, idx, (col+1)&1);
        }
    }
    if(g[idx].col != col) return false;
    return ret;
}

