bool dfs(vector<vector<int > >& G, int u, vector<bool>& visited, int& count, int depth, int s) {
    visited[u] = true;

    int V = G.size();
    if (depth == 3 ) {
        if (G[u][s] == 0) {
            G[u][s]++; G[s][u]++; count++; return true;}
