#include <bits/stdc++.h>
using namespace std;

bool is_bipartite (const vector<vector<int>>& g) {
    int n = g.size(), ret = 1;
    struct UnionFind {
        vector<int> data;
        UnionFind(int sz) : data(sz, -1) { }
        bool unite(int x, int y) {
            if ((x = root(x)) == (y = root(y))) { return false; }
            if (data[x] > data[y]) { swap(x, y); }
            data[x] += data[y]; data[y] = x; return true;
        }
        bool same(int x, int y) { return root(x) == root(y); }
        int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }

    } uf(2*n);
    for (int x = 0; x < n; x++) {
        for (auto& y : g[x]) { uf.unite(x, y+n); uf.unite(x+n, y); }
    }
    for (int x = 0; x < n; x++) if (uf.same(x, x+n)) { ret = 0; break; }
    return ret;
}

