    UnionFind UF(2*N);
    long long A,B;
    REP(i,M){
        cin >> A >> B;A--;B--;
        UF.unite(A,B + N);
        UF.unite(A + N,B);
    }
    long long sum = 0,sq = 0;
    REP(i,N) sum += i;


    REP(i,N){
        if(UF.same(i,i + N)){
            cout << sum - M << endl;
            return 0;
        }
    }
    ll b = 0,w = 0;
    REP(i,N){
		UF.deep(i,0);
        if(UF.deep(i,0) % 2 == 0) b++;
        else w++;
    }
    sq = b*w;
    cout << sq - M << endl;
}

