//Bipartite_Matching
class Bipartite_Graph {
public:
	int V;
	vector<vector<int>> graph;
	vector<int> color;

	Bipartite_Graph(const int V) :V(V), graph(vector<vector<int>>(V)), color(vector<int>(V, 0)) {
	}

	void make_edge(const int from, const int to) {
		graph[from].push_back(to);
	}

	bool dfs(const int i,const int c) {
		color[i] = c;
		for (auto j : graph[i]) if (color[j] == c || (color[j] == 0 && !dfs(j, -c))) return false;
		return true;
	}

	bool solve(void) {
		for (int i = 0; i < V; ++i) if (color[i] == 0 && !dfs(i, 1)) return false;
		return true;
	}
};


int main() {
	ll N, M; cin >> N >> M;
	Bipartite_Graph BG(N);
	REP(i, M) {
		int a, b; cin >> a >> b;
		a--; b--;
		BG.make_edge(a, b);
		BG.make_edge(b, a);
	}
	if (BG.solve()) {
		ll cnt1 = 0, cnt2 = 0;
		REP(i, N) (BG.color[i] == 1 ? cnt1 : cnt2)++;
		cout << cnt1 * cnt2 - M << endl;
	}
	else {
		cout << N * (N - 1) / 2 - M << endl;
	}

	return 0;
}

