  if (dfs(0, 1, col, g)) {
    ll b1 = 0, b2 = 0;
    rep(i, n) {
      if (col[i] == 1) ++b1;
      else ++b2;
    }
    ccout << b1 * b2 - m << endl;
  } else
    ccout << n * (n - 1) / 2 - m << endl;

}

