bool isbipartite = true;
void check()
{
    std::queue<int> q;
    int col = 0;
    q.push(1);
    color[1] = 0;
    while(!q.empty())
    {
        int siz = q.size();
        for(int i=0;i<siz;i++)
        {
            int x = q.front();
            q.pop();
            cnt[col]++;
            for(int next : g[x])
            {
                if(color[next] == -1)
                {
                    q.push(next);
                    color[next] = 1 - col;
                }
                else if(color[next] == col)
                {
                    isbipartite = false;
                    return;
                }
            }
        }
        col = 1 - col;
    }
}
int main()
{
    memset(color,-1,sizeof(color));
    scanf("%d%d",&n,&m);
    for(int i=0;i<m;i++)
    {
        int a,b;
        scanf("%d%d",&a,&b);
        g[a].push_back(b);
        g[b].push_back(a);
    }
    check();
    long long int ans = 0;
    for(int i=1;i<=n;i++)
    {
        if(isbipartite)
            ans += cnt[color[i]] - g[i].size();
        else
            ans += (n - 1 - g[i].size());
    }
    printf("%lld", ans/2);
}

