template<typename T, typename U>
constexpr auto modulo(T a, U b) {
    using R = common_type_t<T,U>;
    assert(0 < b);
    R r = a % b;
    return r >= 0 ? r : r+b;
}

template<typename T>
constexpr T clamp(T x, T lo, T hi) {
    assert(lo <= hi);
    if(x < lo)
        return lo;
    else if(hi < x)
        return hi;
    else
        return x;
}

i64 isqrt(i64 x) {
    assert(x >= 0);

    i64 lo = 0;
    i64 hi = 3037000500LL;
    return bin_search(lo, hi, [x](i64 r) { return r*r <= x; });
}

