i64 N;
i64 M;
vector<vector<i64>> G;

vector<i64> colors;

bool dfs(i64 v, i64 c) {
    colors[v] = c;

    for(i64 to : G[v]) {
        if(colors[to] == c) return false;
        if(colors[to] != 0) continue;
        if(!dfs(to, -c)) return false;
    }

    return true;
}

bool is_bipartite() {
    colors.assign(N, 0);
    REP(i, N) {
        if(colors[i] == 0) {
            if(!dfs(i, 1)) return false;
        }
    }
    return true;
}

void solve() {
    bool bi = is_bipartite();

    i64 ans;
    if(bi) {
        i64 a = ALL(count_if, colors, [](auto c) { return c ==  1; });
        i64 b = ALL(count_if, colors, [](auto c) { return c == -1; });
        ans = a*b - M;
    }
    else {
        ans = N*(N-1)/2 - M;
    }

    PRINTLN(ans);
}

signed main(signed /*argc*/, char** /*argv*/) {
    RD(N);
    RD(M);

    G.resize(N);
    REP(_, M) {
        i64 a,b; RD(a); RD(b); --a; --b; // 0-based
        G[a].emplace_back(b);
        G[b].emplace_back(a);
    }



    solve();

    EXIT();
}

