void coloring(std::vector<std::set<int>>const& edge, std::vector<int>&vertexes, int v, int c)
{
	if (vertexes[v] & c)
	{
		return;
	}
	else
	{
		vertexes[v] |= c;
		for (auto const& n : edge[v])
		{
			coloring(edge, vertexes, n, 3 - c);
		}
	}
}

void Main()
{
	int N, M;
	std::cin >> N >> M;
	std::vector<std::set<int>> edge(N);
	for (int i = 0; i < M; ++i)
	{
		int a, b;
		std::cin >> a >> b;
		--a; --b;
		edge[a].emplace(b);
		edge[b].emplace(a);
	}
	std::vector<int> color(N);
	coloring(edge, color, 0, 1); 
	if (std::count(color.begin(), color.end(), 3))
	{
		std::cout << N*(N - 1) / 2 - M << std::endl;
	}
	else
	{
		int a = std::count(color.begin(), color.end(), 2);
		int b = N - a;
		int ret = a*b;
		int d = 0;
		for (int i = 0; i < N; ++i)
		{
			for (auto const& e : edge[i])
			{
				if (color[i] != color[e])
				{
					++d;
				}
			}
		}
		std::cout << ret - d / 2 << std::endl;
	}
}

