const int N = 1e5 + 10;
int n, m;
vector<int> go[N];
char used[N];
char col[N];
int b, w;

int dfs(int v)
{
	if (used[v])
		return 0;
	used[v] = true;
	int sz = 1;
	for (auto e : go[v])
		sz += dfs(e);
	return sz;
}

bool colorize(int v)
{
	if (col[v] == 1)
		++b;
	else
		++w;
	for (auto e : go[v])
		if (col[e] == col[v])
			return false;
		else if(col[e] == 0)
		{
			col[e] = 3 - col[v];
			if (!colorize(e))
				return false;
		}
	return true;
}

void solve()
{
	scanf("%d%d", &n, &m);
	for(int i = 0; i < m; ++i)
	{
		int a, b;
		scanf("%d%d", &a, &b);
		--a, --b;
		go[a].push_back(b);
		go[b].push_back(a);
	}
	ll ans = 0;
	for (int i = 0; i < n; ++i)
		if (!used[i])
		{
			b = 0;
			w = 0;
			ll sz = dfs(i);
			col[i] = 1;
			if (colorize(i))
				ans += (ll)b * w;
			else
				ans += sz * (sz - 1) / 2;
		}
	printf("%lld\n", ans - m);
}

