template<class T> inline T powerM(T a,T b){if (b==0) return 1;
  T tmp = powerM(a,b/2); if (b%2==0) return tmp*tmp%MOD; else return tmp*tmp%MOD*a%MOD; }


int N,M;
Graph G;
vector<int> color;

bool dfs(int v){
  int c = color[v];
  bool ok = true;
  for (int nv : G[v]){
    if (color[nv] == c) return false;
    if (color[nv] != -1) continue;
    color[nv] = 1 - c;
    ok &= dfs(nv);
  }
  return ok;
}

int main() {
  cin >>N >>M;
