  }
  color.assign(N, -1);
  color[0] = 0;
  bool ok = dfs(0); // 二部グラフかどうか
  int black = 0, white = 0;
  rep(i, N){
    if (color[i] == 0) white++;
    else black++;
  }
  ll res;
  if (ok){
    // 二部グラフなら辺の数は(0の数)*(1の数)になる
    res = black * white;
  }else{
    // 二部グラフでないなら任意の頂点間に辺が存在する
    res = (ll)N * (ll)(N-1) / 2LL;
  }
  cout <<res - M <<endl;
