    x.clear();
    do {
      x += c;
      c = getchar_unlocked();
    } while (c != ' ' && c != '\n' && c != EOF);
  }
  template <class T>
  inline void read(vector<T>& v) {
    for (auto& x : v) read(x);
  }
  template <class Head, class... Tail>
  inline void read(Head& head, Tail&... tail) {
    read(head);
    read(tail...);
  }
  template <class T>
  inline void write(T x) {
    char buf[32];
    int p = 0;
    if (x < 0) {
      x = -x;
      putchar_unlocked('-');
    }
    if (x == 0) putchar_unlocked('0');
    while (x > 0) {
      buf[p++] = (x % 10) + '0';
      x /= 10;
    }
    while (p) {
      putchar_unlocked(buf[--p]);
    }
  }
  inline void write(string x) {
    for (char c : x) putchar_unlocked(c);
  }
  inline void write(const char s[]) {
    for (int i = 0; s[i] != 0; ++i) putchar_unlocked(s[i]);
  }
  template <class T>
  inline void write(vector<T> v) {
    for (auto itr = v.begin(); itr + 1 != v.end(); ++itr) {
      write(*itr);
      write(separator);
    }
    write(v.back());
  }
  template <class Head, class... Tail>
  inline void write(Head head, Tail... tail) {
    write(head);
    write(separator);
    write(tail...);
  }
  template <class Head, class... Tail>
  inline void writeln(Head head, Tail... tail) {
    write(head, tail...);
    write("\n");
  }
  void set_separator(string s) { separator = s; }
} io;

struct Graph {
  vector<vector<int>> G;
  vector<int> color;
  int N;
  Graph(int _N) {
    N = _N;
    G.resize(N);
  }
  void add_edge(int u, int v) { G[u].push_back(v); }
  bool dfs_bipartite(int u) {
    bool ret = 1;
    for (int v : G[u]) {
      if (color[v] == -1) {
        color[v] = 1 - color[u];
        ret &= dfs_bipartite(v);
      } else if (color[v] == color[u]) {
        return 0;
      }
    }
    return ret;
  }
  bool is_bipartite() {
    color.resize(N, -1);
    color[0] = 0;
    return dfs_bipartite(0);
  }
};

int main() {
  ll N, M;
  io.read(N, M);
  Graph graph(N);
  REP(i, M) {
    int A, B;
    io.read(A, B);
    graph.add_edge(A - 1, B - 1);
    graph.add_edge(B - 1, A - 1);
  }
  bool ret = graph.is_bipartite();
  ll ans;
  if (ret) {
    int cnt[2] = {};
    REP(i, N) cnt[graph.color[i]]++;
    ans = cnt[0] * cnt[1];
  } else {
    ans = N * (N - 1) / 2;
  }
  io.writeln(ans - M);
  return 0;
}

