		for (auto &p_vertex : vertices) {
			delete p_vertex;
		}
		for (auto &p_edge : edges) {
			delete p_edge;
		}
	}
	void add_edge(Edge *p_edge) {
		(*vertices[p_edge->p_src->id]).add_edge(p_edge);
		edges.push_back(p_edge);
	}
	void add_edge(int edge_src, int edge_dst) {
		add_edge(new Edge(vertices[edge_src], vertices[edge_dst]));
	}
};

bool is_bipartite(Vertex *p_v, const Color c) {
	p_v->color = c;
	for (auto p_dst : p_v->dsts) {
		if (p_dst->color == 0 && !is_bipartite(p_dst, -c)) {
			return false;
		}
		else if (p_dst->color == c) {
			return false;
		}
	}
	return true;
}

