#define MP make_pair

typedef long long LL;
typedef vector<int> VI;
typedef pair<int, int> PII;

const double PI = acos(-1.0);
const int INF = 1000 * 1000 * 1000 + 7;
const LL LINF = INF * (LL)INF;

const int MAX = 100100;

VI g[MAX];
bool U[MAX];
int C[MAX];
int CNT[2];

int ed = 0;

bool dfs(int x, int c)
{
	C[x] = c;
	CNT[c]++;
	U[x] = true;

	bool res = true;

	ed += SZ(g[x]);

	FOR (i, 0, SZ(g[x]))
	{
		int to = g[x][i];
		if (U[to])
		{
			if (C[x] == C[to]) res = false;
			continue;
		}

		if (!dfs(to, c^1)) res = false;
	}

	return res;
}

int main()
{
	//freopen("in.txt", "r", stdin);
	//ios::sync_with_stdio(false); cin.tie(0);

	int n, m;
	scanf("%d%d", &n, &m);
	FOR (i, 0, m)
	{
		int x, y;
		scanf("%d%d", &x, &y);
		x--;
		y--;
		g[x].PB(y);
		g[y].PB(x);
	}

	LL res = 0;

	FOR (i, 0, n)
	{
		if (U[i]) continue;

		CNT[0] = CNT[1] = 0;
		ed = 0;
		bool v = dfs(i, 0);
		ed /= 2;
		if (v)
		{
			LL cnt = CNT[0] * (LL)CNT[1];
			cnt -= ed;
			res += cnt;
		}
		else
		{
			LL cnt = CNT[0] + CNT[1];
			cnt = cnt * (cnt - 1) / 2;
			cnt -= ed;
			res += cnt;
		}
	}

	cout<<res<<endl;
}

