    graph.resize(N);
    REP(i, M) {
        SS(int, A, B);
        --A, --B;
        add_edge(g, A, B);
        graph[A].PB(B);
        graph[B].PB(A);
    }

    ll base;
    ll ret = isBipartiteGraph(g);
    if (ret != -1) {
        base = ret * (N - ret);
    } else {
        base = N * (N - 1) >> 1;
    }

    base -= M;
    print(base);

}

