void bfs(int s){
	q.push(s);                                  
 	dist[s] = 0;   
 	color[s]=0;      	
	while (!q.empty()) {
	    int u = q.front(); q.pop();                        // queue: layer by layer!
	    for (int j = 0; j < (int)edge[u].size(); j++) {
	      int v = edge[u][j];                           // for each neighbors of u
	      if (!dist.count(v)) {    // dist.find(v.first) == dist.end() also ok
	        dist[v] = dist[u] + 1;
			color[v]=1-color[u];                // v unvisited + reachable
	        q.push(v);                          // enqueue v for next step
	      }
	      else if ((dist[v] % 2) == (dist[u] % 2))  {            // same parity
	        isBipartite = false;}
