using namespace std;
#define int long long

class Graph {
   private:
    struct edge {
        int to;
        edge(int i) : to(i) {}
    };
    vector<vector<edge>> edges;
    static const int COLORLESS = 0, BLACK = 1, WHITE = -1;
    const int flipColor(int color) const {
        return (color == BLACK ? WHITE : BLACK);
    }
    vector<int> colors;

   public:
    Graph(int n) { edges.resize(n); };
    int size() const { return edges.size(); };
    int countEdge() const {
        int count = 0;
        for (auto &&i : edges)
            for (auto &&j : i) count++;
        return count;
    }
    void addDirectedEdge(int from, int to) { edges[from].push_back(edge(to)); }
    void addEdge(int from, int to) {
        addDirectedEdge(from, to);
        addDirectedEdge(to, from);
    }

    // 二部グラフ判定
    bool isBipartite() {
        // 頂点を深さ優先探索
        colors.assign(size(), (int)COLORLESS);
        stack<int> stk;
        stk.push(0);
        colors[0] = BLACK;

        while (!stk.empty()) {
            const int p = stk.top();
            stk.pop();
            for (auto &&next_edge : edges[p]) {  // すべての隣接する頂点を調べる
                const int np = next_edge.to;
                // 今の頂点と隣接する頂点が同色なら偽
                if (colors[np] == colors[p]) return false;
                // 隣接する頂点が無色なら今の頂点とは別の色で塗る
                if (colors[np] == COLORLESS) {
                    stk.push(np);
                    colors[np] = flipColor(colors[p]);
                }
            }
        }
        return true;
    }
    int countColor(int color) const {
        int count = 0;
        for (auto &&i : colors) {
            if (i == color) count++;
        }
        return count;
    }
    int countBlack() const { return countColor(BLACK); }
    int countWhite() const { return countColor(WHITE); }
};

signed main() {
    cin.tie(0);
    ios::sync_with_stdio(0);

    int n, m;
    cin >> n >> m;

    Graph g(n);
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;  // convert to 0-based
        g.addEdge(a, b);
    }

    int ans;

    // 二部グラフ判定
    if (g.isBipartite()) {
        // もし二部グラフならば、別色のノードにのみ辺をはることができる。
        // 多重辺、ループなしでできるだけ辺を追加したときの辺数は(黒頂点数)x(白頂点数)
        // 答え=最大辺数-初期辺数
        const int blacks = g.countBlack(), whites = g.countWhite();
        ans = blacks * whites - m;
    } else {
        // もし二部グラフではないならば、ある頂点は全頂点に辺を貼れる。
        // 多重辺、ループなしでできるだけ辺を追加したときの辺数は(頂点数)x(頂点数-1)/2
        // 答え=最大辺数-初期辺数
        ans = n * (n - 1) / 2 - m;
    }

    cout << ans << endl;
}

