bool dfs(int root,int depth,int v){
	if( depth == 2 ){
		int a = root;
		int b = v;
		if( a>b ){
			swap(a,b);
		}
		if( edge.find(pair<int,int>(a,b) ) != edge.end() ){
			return false;
		}
	}
	if( depth == 3 ){
		int a = root;
		int b = v;
		if( a>b ){
			swap(a,b);
		}
		if( edge.find(pair<int,int>(a,b) ) != edge.end() ){
			//辺がある。
		}else{
			gra[a].push_back(b);
			gra[b].push_back(a);
			++ANS;
			edge.insert(pair<int,int>(a,b) );
			//cout << "追加" << a << " " << b << endl;
		}
		return true;//続行で終了
	}

	visit[v] = true;
	int size = gra[v].size();
	for(int i=0;i<size;++i){
		int to = gra[v][i];
		if( visit[to] == false ){
			bool res = dfs(root,depth+1,to);
			if( res == false ){
				return res;
			}
		}
	}

	//visit[v] = false;

	return true;
}
