void go(std::vector< std::vector<int> > &g, int n, int m)
{
	bool visited[100010] = { 0 };
	int color[100010] = { 0 }, count[4] = { 0 };

	std::queue<int> q;
	q.push(0);
	bool flag = false;
	count[1] = 1;
	color[0] = 1;

	while (q.empty() == false)
	{
		int top = q.front();
		q.pop();

		if (visited[top])
			continue;
		else
			visited[top] = true;

		for (int i = 0; i < g[top].size(); ++i)
		{
			int next = g[top][i];
			if (visited[next])
			{
				if (color[next] == color[top])
				{
					flag = true;
					break;
				}
			}
			else
			{
				if (color[next] != 0 && color[next] == color[top])
				{
					flag = true;
					break;
				}

				if (color[top] == 1)
				{
					color[next] = 2;
					++count[2];
				}
				else
				{
					color[next] = 1;
					++count[1];
				}
				q.push(next);
			}
		}
	}

	if (flag)
	{
		std::cout << n * 1ll * (n - 1) / 2 - m;
	}
	else
	{
//		std::cout << count[1] << " " << count[2];
		std::cout << count[1] * 1ll * count[2] - m;
	}
}

