    memset(color, -1, sizeof color);
    color[1] = 1;
    Q.push(1);
    while(!Q.empty()){
        int u = Q.front(); Q.pop();
        for(int i = 0; i < g[u].size(); i++){
            int v = g[u][i];
            if(color[v] == color[u]) return 0;
            if(color[v] == -1){
                color[v] = 1 - color[u];
                Q.push(v);
            }
        }
    }
    return 1;
}

