int dfs(int start, int prev, int node, int dist) {
    if(dist == 3) {
        if(start != node &&
           child[start].find(node) == child[start].end()) {
            child[start].insert(node);
            child[node].insert(start);
            ans++;
            return node;
        }
        return 0;
