using namespace std;

typedef long long int lli;

class UnionFind {
public:
    vector<int> parent;
    UnionFind(int n) {
        parent.resize(n);
        REP(i, 0, n) parent[i] = i;
    }
    int Find(int a) {
        return (a == parent[a] ? a : a = Find(parent[a]));
    }
    bool isSame(int a, int b) {
        return Find(a) == Find(b);
    }
    bool Union(int a, int b) {
        if (isSame(a, b)) return false;
        int pa = Find(a);
        int pb = Find(b);
        parent[pa] = pb;
        return true;
    }
};

int main() {
    int N, M;
    cin >> N >> M;
    UnionFind uf(2 * N);
    REP (i, 0, M) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        uf.Union(a + N, b);
        uf.Union(a, b + N);
    }
    bool OK = true;
    REP (i, 0, N) if (uf.isSame(i, i + N)) OK = false;
    if (OK) {
        lli x = 0, y = 0;
        REP (i, 0, N) {
            if (uf.isSame(0, i)) x++;
            else y++;
        }
        cout << x * y - M << endl;
    } else {
        cout << (lli)N * (N - 1) / 2 - M << endl;
    }
    return 0;
}

