void bfs(int s, vvi &g, vi &dis) {
	queue<int> q;
	dis[s] = 0; q.push(s);
	while (!q.empty()) {
		int u = q.front(); q.pop();
		for (int v : g[u]) {
			if (dis[v] != -1) continue;
			q.push(v); dis[v] = dis[u] + 1;
		}
	}
}

bool bip_con(int s, vvi &g, const vi &dis) {
	queue<int> q; vb r(g.size());
	q.push(s); r[s] = true;
	while (!q.empty()) {
		int u = q.front(); q.pop();
		for (int v : g[u]) {		
			if ((dis[v] - dis[u]) % 2 == 0) return false;
			if (!r[v]) {
				q.push(v); r[v] = true;
			}
		}
	}
	return true;
}

bool bip_con(int s, vvi &g, const vi &dis, vb &r) {
	queue<int> q;
	q.push(s); r[s] = true;
	while (!q.empty()) {
		int u = q.front(); q.pop();
		for (int v : g[u]) {		
			if ((dis[v] - dis[u]) % 2 == 0) return false;
			if (!r[v]) {
				q.push(v); r[v] = true;
			}
		}
	}
	return true;
}
bool bip(vvi &g, const vi &dis) {
	vb r(g.size());
	rep(s, g.size()) {
		if (!r[s]) {
			r[s] = true;
			if (!bip_con(s, g, dis, r)) return false;
		}
	}
	return true;
}

