template <class Graph>
void dfs1(const Graph& g, u32 v, i32 cur_type, std::vector<i32>& t) {
  t[v] = cur_type;
  for (u32 next: g[v]) {
    if (t[next] == -1) {
      dfs1(g, next, cur_type ^ 1, t);
    } else if ((t[next] & ~4) == (t[v] & ~4)) {
      t[v] |= 4;
      t[next] |= 4;
    }
  }
}

template <class Graph>
void dfs2(const Graph& g, u32 v, std::vector<bool>& used, std::vector<i32>& t, bool x) {
  if (t[v] & 4) {
    x = true;
  }
  if (x) {
    t[v] |= 4;
  }
  used[v] = true;
  for (u32 next: g[v]) {
    if (!used[next]) {
      dfs2(g, next, used, t, x);
    }
  }
}

