const int MAX = 1e5 + 5;
vector<int> adj[MAX];
int color[MAX];
int n, m;

ll bfs(int source) {
	memset(color, -1, sizeof color);
	queue<int> q;
	q.push(source);
	color[source] = 0;
	ll w = 0, b = 0;
	while(!q.empty()) {
		int cur = q.front(); q.pop();
		w += color[cur] == 0;
		b += color[cur] == 1;
		for(auto &each : adj[cur]) {
			if(color[each] == -1) {
				color[each] = !color[cur];
				q.push(each);
			}
			else if(color[cur] == color[each]) {
				return (1LL * n * (n - 1)) / 2LL;
			}
		}
	}
	return w * b;
}

int main() {
	scanf("%d %d", &n, &m);
	fori(i, 0, m) {
		int u, v;
		scanf("%d %d", &u, &v);
		adj[u].push_back(v);
	}

	ll p = bfs(1);
	printf("%lld\n", p - m);

	return 0;
}

