using namespace std;
class UnionFind {
  vector<int> p;
public:
  UnionFind (int n) : p(n, -1) {}
  int root(int x) {
    return p[x] < 0 ? x : p[x] = root(p[x]);
  }
  bool same(int x, int y) {
    return root(x) == root(y);
  }
  bool unite(int x, int y) {
    x = root(x); y = root(y);
    if (x == y) return false;
    if (p[y] < p[x]) swap(x, y);
    if (p[x] == p[y]) --p[x];
    p[y] = x;
    return true;
  }
};
int main(void)
{
  LL n,m;
  cin >> n >> m;
  vector<LL> v(n);

  UnionFind uf = UnionFind(n*2);
  REP(i,m) {
    int x,y;
    cin >> x >> y;
    --x; --y;
    uf.unite(x,y+n);
    uf.unite(x+n,y);
  }
  LL answer;
  if(uf.same(0,n)) answer = n*(n-1)/2-m;
  else {
    LL l,r;
    REP(i,n) uf.same(0,i) ? ++l : ++r;
    answer = l*r-m;
  }

  cout << answer << endl;
  return 0;
}

