void solve() {
  cin >> n >> m;
  for(int i = 0; i < m; i++) {
    int a, b;
    cin >> a >> b;
    edges[a].push_back(b);
    edges[b].push_back(a);
  }
  queue<int> q;
  q.push(1);
  dp[1] = 1;
  while(!q.empty()) {
    int curr = q.front(); q.pop();
    for(int out: edges[curr]) {
      if(dp[out] == dp[curr]) {
        cout << n*(n-1LL) / 2 - m << "\n";
