const LL LLINF = 1e18;

const int MAX = 1e5 + 10;
int n, m;
set<int> G[MAX];

LL ans = 0;
set<PII> se;
set<PII> u2;

void dfs(int now, int pre, int pre2, int pre3) {
    unordered_set<int> se2;
    int cnt = 1;
    se2.insert(now);
    if (pre != -1) {
        se2.emplace(pre);
        cnt++;
    }
    if (pre2 != -1) {
        se2.emplace(pre2);
        cnt++;
    }
    if (pre3 != -1) {
        se2.emplace(pre3);
        cnt++;
    }
    if (cnt != se2.size()) return;
    if (pre3 != -1 && G[now].count(pre3) == 0  && now != pre3 && se.count(MP(min(now, pre3), max(now, pre3))) == 0) {
        se.emplace(MP(min(now, pre3), max(now, pre3)));
    }
    FORE(e, G[now]) {
        if (se2.count(e) == 0 && (pre3 == -1 || u2.count(MP(e, pre3)) == 0)) {
            if (pre3 != -1) u2.emplace(MP(e, pre3));
            dfs(e, now, pre, pre2);
        }
    }
}

int main(void) {
    scanf("%d%d", &n, &m);
    REP(i, m) {
        int a, b;
        scanf("%d%d", &a, &b);
        a--;b--;
        G[a].emplace(b);
        G[b].emplace(a);
    }
    VI nxt;
    REP(i, n) nxt.EB(i);
    while (true) {
        FORE(j, nxt) dfs(j, -1, -1, -1);
        if (se.size() == 0) break;
        nxt.clear();
        FORE(e, se) {
            //cerr << e.first+1 << " " << e.second+1 << " " << i + 1 << endl;
            G[e.first].emplace(e.second);
            G[e.second].emplace(e.first);
            nxt.EB(e.first);
            nxt.EB(e.second);
            ans++;
        }
        se.clear();
        u2.clear();
    }
    cout << ans << endl;
}

