ll solve(){
    queue<ll> que;
    que.push(0);
    col[0]=1;
    while(que.size()){
        int now=que.front();que.pop();
        col[now]==1?blo++:whi++;
        for(auto w:v[now]){
            if(col[w]==0){
                col[w]=-col[now];
                que.push(w);
            }else if(col[w]==col[now]){
                return (n*(n-1)/2)-m;
            }
        }
    }
    return blo*whi-m;
}

