bool vis[N];
ll ans;
void dfs(int u, int p, int depth){
	D[u]=depth;
	vis[u]=true;
	oth[u].resize(2);
	++oth[u][depth%2];
	for(int i=0; i<g[u].size(); ++i){
		int d=g[u][i];
		if(d!=p)
		if(d!=p && !vis[d]){
			dfs(d,u,depth+1);
			for(int k=0; k<2; ++k)
				ans+=1ll*oth[u][k]*oth[d][k^1];
			for(int k=0; k<2; ++k)
				oth[u][k]+=oth[d][k];
			--ans;
		}else if(vis[d] && D[d]>D[u] && D[d]%2==D[u]%2){
			for(int k=0; k<2; ++k)
				ans+=1ll*oth[u][k]*oth[d][k];
			for(int k=0; k<2; ++k)
				oth[u][k]+=oth[d][k^1];
			if(oth[d][(depth%2)^1])
				--ans;
		}
	}
}
