vector<int> v[N_MAX];
int col[N_MAX],blo,whi;

ll solve(){
    queue<pint> que;
    que.push({0,0});
    col[0]=1;
    while(que.size()){
        pint now=que.front();que.pop();
        col[now.first]==1?blo++:whi++;
        for(auto w:v[now.first]){
            if(w==now.second)continue;
            if(col[w]==0){
                col[w]=-col[now.first];
                que.push({w,now.first});
            }else if(col[w]==col[now.first]){
                return (n*(n-1)/2)-m;
            }
        }
    }
    return blo*whi-m;
}

