void dijkstra(int s){
  priority_queue<P,vector<P>,greater<P>> que;
  fill(d,d+n,INF);
  d[s]=0;
  que.push(P(0,s));

  while(!que.empty()){
   P p=que.top();que.pop();
   int v=p.second;
   if(d[v]<p.first)continue;
   for(int i=0;i<G[v].size();i++){
     edge e=G[v][i];
