using namespace std;

struct UF {
	vector<int> belong;
	vector<int> size;
	void resize(int n) {
		belong.assign(n + 1, -1);
		size.assign(n + 1, 1);
	}
	inline int root(int b) {
		if (belong[b] == -1) {
			return b;
		}
		belong[b] = root(belong[b]);
		return belong[b];
	}
	void merge(int a, int b) {
		a = root(a);
		b = root(b);
		if (a == b)return;
		belong[a] = b;
		size[b] += size[a];
	}
};
UF uf;
int main() {
	int n;
	int m;
	scanf("%d%d", &n, &m);
	uf.resize(n);
	for (int i = 0; i < m; i++) {
		int a, b;
		scanf("%d%d", &a, &b);
		a--;
		b--;
		uf.merge(a, b);
	}
	long long int way = 0;
	for (int i = 0; i < n; i++) {
		if (uf.root(i) == i) {
			long long int sz = uf.size[i];
			if (sz >= 3) {
				way += sz*(sz - 1) / 2LL;
			}
		}
	}
	way -= m;
	printf("%lld\n", way);
	return 0;
}

