const int maxn = 1e5 + 5;
int other[10 * maxn],last[10  * maxn],pre[10 * maxn],vis[10 * maxn];
int all = -1;
long long sum = 0;
queue<int>seq;

void build(int x,int y){
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
}

bool bfs(int x,int y){
	int dt = last[x];
	while(dt != -1){
		int dr = other[dt];
		if(dr == y) return false;
		dt = pre[dt];
	}
	return true;
}

void dfs1(int x,int fa,int deep){
	int dt = last[x];
	while(dt != -1){
		int dr = other[dt];
		if(dr != fa){
			if(deep == 2){
				if(vis[dr] == 0) seq.push(dr),vis[dr] = 1;
				return;
			}
			dfs1(dr,x,deep + 1);
		}
		dt = pre[dt];
	}
}

void dfs(int s,int x,int fa,int deep){
	int dt = last[x];
	while(dt != -1){
		int dr = other[dt];
		if(dr != fa){
			if(deep == 3){
				if(bfs(dr,s) && s != dr){
					dfs1(dr,0,1);
					sum++;
					build(s,dr);
					build(dr,s);
					if(vis[dr] == 0) seq.push(dr),vis[dr] = 1;
				}
				return;
			}
			dfs(s,dr,x,deep + 1);
		}
		dt = pre[dt];
	}
}

int main(){
	int n,m;
	scanf("%d %d",&n,&m);
	memset(last,-1,sizeof(last));
	for(int i = 1;i <= m;i++){
		int x,y;
		scanf("%d %d",&x,&y);
		build(x,y);
		build(y,x);
	}
	for(int i = 1;i <= n;i++){
		seq.push(i);
		vis[i] = 1;
	}
	while(!seq.empty()){
		int x = seq.front();
		if(!seq.empty()) seq.pop();
		vis[x] = 0;
		dfs(x,x,0,1);
	}
	printf("%lld\n",sum);
}

