using namespace std;

struct UnionFind
{
    vector< int > data;

    UnionFind(int sz)
    {
        data.assign(sz, -1);
    }

    bool unite(int x, int y)
    {
        x = find(x), y = find(y);
        if(x == y) return(false);
        if(data[x] > data[y]) swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return(true);
    }

    int find(int k)
    {
        if(data[k] < 0) return(k);
        return(data[k] = find(data[k]));
    }

    int size(int k)
    {
        return(-data[find(k)]);
    }
};

struct Bipartite_Graph : UnionFind
{
    vector< int > color;

    Bipartite_Graph(int v) : color(v + v, -1), UnionFind(v + v) {}

    bool bipartite_graph_coloring()
    {
        for(int i = 0; i < color.size() / 2; i++) {
            int a = find(i);
            int b = find(i + (int) color.size() / 2);
            if(a == b) return (false);
            if(color[a] < 0) color[a] = 0, color[b] = 1;
        }
        return (true);
    }

    bool operator[](int k)
    {
        return (bool(color[find(k)]));
    }
};

int main(){
    long N, M;
    cin >> N >> M;
    Bipartite_Graph roads(N);
    for(int i = 0; i < M; i++){
        int A, B;
        cin >> A >> B;
        roads.unite(A - 1, B - 1 + N);
        roads.unite(A - 1 + N, B - 1);
    }
    if(roads.bipartite_graph_coloring()){
        long counter = 0;
        for(int i = 0; i < N; i++){
            counter += roads[i];
        }
