	{
		int A, B;
		cin >> A >> B;
		--A;
		--B;
		G[A].push_back(B);
		G[B].push_back(A);
	}

	auto isBipartite = true;
	stack<int> s;
	vector<int> part(N);
	s.push(0);
	part[0] = 1;
	int partNum[] = { 0, 0, 1 };
	while (!s.empty())
	{
		auto u = s.top();
