				{
					isBipartite = false;
					break;
				}
				continue;
			}

			part[v] = -part[u];
			++partNum[part[v] + 1];
			s.push(v);
		}

		if (!isBipartite)
		{
			break;
		}
	}

	if (!isBipartite)
	{
		cout << (ll)N * (N - 1) / 2 - M << endl;
	}
	else
	{
		cout << (ll)partNum[0] * partNum[2] - M << endl;
