inline bool has_odd_cycle() {
    bool res = false;
    // {{next, from}, depth}
    queue<pair<PI, li>> q;
    q.push({{0, -1}, -1});
    while (!q.empty()) {
        li from = q.front().F.S;
        li now = q.front().F.F;
        li depth_now = q.front().S + 1;
        q.pop();
        if (depth[now] >= 0) {
            if (depth[now] % 2 != depth_now % 2) {
                res = true;
            }
            continue;
        }
        depth[now] = depth_now;
        rep(i, sz(edge[now])) {
            const li next = edge[now][i];
            if (next == from)continue;
            q.push({{next, now}, depth_now});
        }
    }
    return res;
}

