bool isBipartite;
vector<int16_t> visited;
void dfs(Graph &G){
  int64_t N = G.size();
  visited = vector<int16_t>(N+1,0);
  stack<Edge> st;
  st.push(Edge{N,0,0});
  visited[N] = 2;
  isBipartite = true;
  while(!st.empty()){
    auto top = st.top();
    st.pop();
    int64_t from = top.f, to = top.t;
    if(visited[to]!=0){
      continue;
    }
    visited[to] = 3 - visited[from];
    // print(to, visited[to]);
    for(auto i=G[to].begin();i!=G[to].end();i++){
      if(visited[(*i).t] == 0) {
        st.push((*i));
      }else{
        if (visited[(*i).t] == visited[to]){
          isBipartite = false;
        }
      }
    }
  }
  // cout << isBipartite << endl;
}

