    }

    vector<int> col(n+1);
    stack<P> st;
    st.emplace(1, 1);
    bool bipartite = true;
    while(not st.empty()){
        int v = st.top().first;
        int c = st.top().second;
        st.pop();

        if(col[v] != 0){
            if(col[v] != c){
                bipartite = false;
                break;
            }
            continue;
        }
        col[v] = c;

        for(int u : edge[v]){
            st.emplace(u, c * -1);
        }
    }

    int b = 0;
    int w = 0;
    rep(i, n){
        if(col[i+1] == 1){
            b++;
        }else{
            w++;
        }
    }

    if(bipartite){
        cout << b * w - m << endl;
    }else{
        cout << n * (n-1) / 2 - m << endl;
    }

    return 0;
}

