void bfs(int s, vvi &g, vi &dis) {
	queue<int> q;
	dis[s] = 0; q.push(s);
	while (!q.empty()) {
		int u = q.front(); q.pop();
		for (int v : g[u]) {
			if (dis[v] != -1) continue;
			q.push(v); dis[v] = dis[u] + 1;
		}
	}
}

bool bip_con(int s, vvi &g, const vi &dis) {
	queue<int> q; vb r(g.size());
	q.push(s); r[s] = true;
	while (!q.empty()) {
		int u = q.front(); q.pop();
		for (int v : g[u]) {		
			if ((dis[v] - dis[u]) % 2 == 0) return false;
			if (!r[v]) {
				q.push(v); r[v] = true;
			}
		}
	}
	return true;
}

bool bip_con(int s, vvi &g, const vi &dis, vb &r) {
	queue<int> q;
	q.push(s); r[s] = true;
	while (!q.empty()) {
		int u = q.front(); q.pop();
		for (int v : g[u]) {		
			if ((dis[v] - dis[u]) % 2 == 0) return false;
			if (!r[v]) {
				q.push(v); r[v] = true;
			}
		}
	}
	return true;
}
bool bip(vvi &g, const vi &dis) {
	vb r(g.size());
	rep(s, g.size()) {
		if (!r[s]) {
			r[s] = true;
			if (!bip_con(s, g, dis, r)) return false;
		}
	}
	return true;
}

int main() {
	// 0-ind
	ll N, M; cin >> N >> M;
	vi A(M), B(M);
	vvi g(N + 1, vi());
	rep(i, M) {
		cin >> A[i] >> B[i]; A[i]--; B[i]--;
		g[A[i]].push_back(B[i]); g[B[i]].push_back(A[i]);
	}	
	vi dis(N, -1);
	bfs(0, g, dis);
	if (bip(g, dis)) {
		ll E = 0, O = 0;
		rep(i, N) if (dis[i] % 2 == 0) E++; else O++;
		ll ans = E * O;
		rep(i, M) if ((dis[A[i]] - dis[B[i]]) % 2 != 0) ans--;
		cout << ans << endl;
	} else {		
		cout << N * (N - 1) / 2 - M << endl;
	}	
}

