    for (int i = 0; i < M; ++i) {
        int a, b;
        cin >> a >> b;
        G[a-1].push_back(b-1);
        G[b-1].push_back(a-1);
    }

    // 探索
    color.assign(N, -1);
    bool is_bipartite = true;
    for (int v = 0; v < N; ++v) {
        if (color[v] != -1) continue; // v が探索済みだったらスルー
        if (!dfs(G, v)) is_bipartite = false;
    }
    int sum = 0;
    rep(i,n){
        sum += color[v];
    }
    if(is_bipartite){
      cout << sum*(N-sum)-M << endl;
    }else{
      cout << (N*(N-1))/2 - M << endl;
    }
}

