const int N = 2e5 + 23;

vector<int> adj[N];
int n, m;

int color[N];
bool dfs(int u, int c) {
    color[u] = c;
    bool res = true;
    for(int v : adj[u]) {
        if(color[v] == -1) {
            res = res and dfs(v, 1 - c);
        }
        if(color[v] == c) {
            return false;
        }
    }
    return res;
}

bool bipartite() {
    memset(color, -1, sizeof color);
    return dfs(1, 0);
}

inline ll solve() {
    ll res = 0;
    if(bipartite()) {
        int w = 0;
        fori(i, 1, n + 1) {
            if(color[i] == 0) {
                ++w;
                res -= adj[i].size();
            }
        }
        ll b = n - w;
        res += (b * w);
    }
    else {
        res = (((ll) n * (n - 1)) / 2) - m;
    }
    return res;
}

