    scanf("%d %d", &n, &m);
    fori(i, 0, m) {
        int u, v;
        scanf("%d %d", &u, &v);
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    ll ans = solve();
    cout << ans << '\n';

