	int* parent_p_m;	// 根である場合は自分自身の添え字を入れる
	int* rank_p_m;
	int* size_p_m;		// 集合のサイズ(根に大きさを書く)

	bool Is_valid_index(int index);
	int Root_of_rec(int index);
public:
