vector<int> G[100000];
bool RED[100000];
bool used[100000];

bool rec(int i, bool red) {
	if (used[i]) return RED[i] == red;
	used[i] = true;
	RED[i] = red;

	bool ret = true;
	for (int to : G[i]) {
		ret &= rec(to, !red);
	}
	return ret;
}

