vector<int> par;

int root(int x) {
    if (par[x] < 0) return x;
    return par[x] = root(par[x]);
}

int size(int x) {
    return -par[root(x)];
}

void merge(int x, int y) {
    if (size(x) < size(y)) swap(x, y);
    int rx = root(x);
    int ry = root(y);
    if (rx == ry) return;
    par[rx] += par[ry];
    par[ry] = rx;
}



