class UnionFind {
	vector<int> data;
	vector<int> rank;
	int root(int a) {
		return data[a] < 0 ? a : data[a] = root(data[a]);
	}
public:
	UnionFind(int n) : data(n, -1), rank(n, 1) {}
	bool Find(int a, int b) {
		return root(a) == root(b);
	}
	void Union(int a, int b) {
		a = root(a);
		b = root(b);
		if (a == b) return;
		if (rank[a] < rank[b]) {
			data[a] += data[b];
			data[b] = a;
		}
		else {
			data[b] += data[a];
			data[a] = b;
			if (rank[a] == rank[b]) rank[b]++;
		}
	}
	int Size(int a) {
		return -data[root(a)];
	}
	int Rank(int a) {
		return rank[root(a)];
	}
};

int main()
{
	ios::sync_with_stdio(false), cin.tie(0);
	ll N, M;
	cin >> N >> M;
	UnionFind uf(N * 2);
	bool two = true;
	for (int i = 0, a, b; i < M; i++) {
		cin >> a >> b; a--; b--;
		uf.Union(N + a, b);
		uf.Union(a, N + b);
		if (uf.Find(a, N + a) || uf.Find(b, N + b)) {
			two = false;
		}
	}
	cout << (two ? N / 2 * (N - N / 2) - M : N * (N - 1) / 2 - M) << endl;
	return 0;
}

