typedef pair<int,int> P;
int n, m;
vector<int> G[N];
int d[N];
set<P> used;
long long odd,even;

void dfs(int x,int dep){

  d[x]=dep;

  for(int i=0;i<G[x].size();i++){

    int nx=G[x][i];

    if(d[nx]!=-1) continue;

    used.insert(P(min(x,nx),max(x,nx)));

    dfs(nx,dep+1);
  }

}

int main(){

  cin>>n>>m;

  int A, B;

  for(int i=0;i<m;i++){
    scanf("%d %d",&A,&B);
    G[A-1].push_back(B-1);
    G[B-1].push_back(A-1);
  }

  memset(d,-1,sizeof(d));

  d[0]=0;

  for(int i=0;i<G[0].size();i++)

    if(d[G[0][i]]==-1) dfs(G[0][i],1);

  bool flag=false;

  for(int i=0;i<n;i++)
    for(int j=0;j<G[i].size();j++){

      int ni=G[i][j];

      if(used.count(P(min(i,ni),max(i,ni)))) continue;

      if((d[i]+d[ni])%2==0) flag=true;
    }

  long long ans=0;

  for(int i=0;i<n;i++)
    if(d[i]%2) odd++;
    else even++;

  ans+=odd*even;

  if(flag){
    ans+=odd*(odd-1)/2;
    ans+=even*(even-1)/2;
  }

  ans-=m;

  cout<<ans<<endl;

  return 0;
}

