			int next = tree[v][i];
			if (dist[next] == -1) {
				dist[next] = 1-dist[v];
				q.push(next);
			}
		}
	}
	int odd = 0, even = 0;
	for (int i = 0; i < n; i++) {
		if (dist[i] == 0) even++;
		else odd++;
	}
	bool flag = false;
	for (int i = 0; i < m; i++) if (dist[a[i]] == dist[b[i]]) flag = true;
	if (flag) cout << n*(n - 1) / 2 - m << endl;
	else cout << odd*even - m << endl;
	return 0;
}

