using namespace std;
using u64 = std::uint_fast64_t;

class UnionFind {
public:
  vector<int> parent;

  UnionFind(int n) : parent(n, -1) {
  }

  int root(int x) {
    if (parent[x] < 0) {
      return x;
    } else {
      return parent[x] = root(parent[x]);
    }
  }

  bool issame(int x, int y) {
    return root(x) == root(y);
  }

  int size(int x) {
    return -parent[root(x)];
  }

  bool unite(int x, int y) {
    int rx = root(x), ry = root(y);
    if (rx == ry) return false;
    if (parent[rx] > parent[ry]) swap(rx, ry);
    parent[rx] += parent[ry];
    parent[ry] = rx;
    return true;
  }
};

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  int N, M;
  cin >> N >> M;
  UnionFind uf(2 * N);
  for (int i = 0; i < M; i++) {
    int a, b;
    cin >> a >> b;
    a--, b--;
    uf.unite(a, b + N);
    uf.unite(b, a + N);
  }
  if (uf.issame(0, N)) {
    cout << static_cast<u64>(N) * (N - 1) / 2 - M << '\n';
    return 0;
  }

  u64 cnt = 0;
  for (int i = 0; i < N; i++) {
    if (uf.issame(0, i)) cnt++;
  }

  cout << (static_cast<u64>(N) - cnt) * cnt - M << '\n';
  return 0;
}

