using namespace std;

struct UF {
	vector<int> belong;
	vector<int> size;
	void resize(int n) {
		belong.assign(n + 1, -1);
		size.assign(n + 1, 1);
	}
	inline int root(int b) {
		if (belong[b] == -1) {
			return b;
		}
		belong[b] = root(belong[b]);
		return belong[b];
	}
	void merge(int a, int b) {
		a = root(a);
		b = root(b);
		if (a == b)return;
		belong[a] = b;
		size[b] += size[a];
	}
};
UF uf;
#define MAX 100002
int col[MAX];
vector<int> v[MAX];

int ed ;
inline bool dfs(int b,int c,int pr=-1) {
	if (col[b] != -1) {
		if (col[b] == c) {
			return true;
		}
		return false;
	}
	col[b] = c;
	bool ok = true;
	for (int go : v[b]) {
		if (pr == go)continue;
		ok&=dfs(go, c ^ true, b);
		ed++;
	}
	return ok;
}

