lli N, M;
vector<vector<int>> G;
signed main()
{
  IOS; /* making cin faster */
  SCANLLD2(N, M);
  G.resize(N);
  REP(_, M)
  {
    int u, v;
    SCAND2(u, v);
    --u;
    --v;
    G[u].push_back(v);
    G[v].push_back(u);
  }

  vector<int> d(N, -1);
  deque<int> dq;
  dq.push_back(0);
  d[0] = 0;

  while (not dq.empty())
  {
    int u = dq.front();
    dq.pop_front();

    for (int v : G[u])
    {
      if (d[v] == -1)
      {
        dq.push_back(v);
        d[v] = (d[u] ^ 1);
      }
      else if ((d[v] ^ d[u]) == 0)
      {
        PRINTLLD(N * (N - 1) / 2 - M);
        return 0;
      }
    }
  }

  vector<lli> num(2, 0);
  REP(i, N)
  {
    num[d[i]]++;
  }
  PRINTLLD(num[0] * num[1] - M);
}

