void dfs(int from, int to, int color) {
	if (from == -1) for(int i=0;i<n;i++) c[i]=-1;
	if (c[to] == 0 || c[to] == 1) {
		if (c[to] != color) noco=true; return;
	} else c[to]=color;
	for(int next:v[to]) {
		if (from == next) continue;
		dfs(to, next, color^1);
	}
}
