		if (c[i] == 1) h++;
	}
	if (noco) {
		for(int i=0;i<n;i++) {
			if (c[i] == -1) continue;
			used+=v[i].size();
		}
		used/=2;
		cout<<(w+h)*(w+h-1)/2-used<<endl;
	} else {
