pair<int, int> is_bipartite (const vector<vector<int>>& g) {
    assert(g.size());
    int n = g.size(), s = 0, t = 0, f = 1;
    vector<int> c(n, 0); c[0] = 1;
    queue<int> que; que.emplace(0);
    while (not que.empty()) {
        int v = que.front(); que.pop();
        for (const auto& u : g[v]) {
            if (c[u] != 0) { if (c[u] == c[v]) f = 0; }
            else { c[u] = c[v] * -1; que.emplace(u); }
        }
    }
    if (not f) return make_pair(s, t);
    for (int &e : c) { s += (e == 1); t += (e == -1); }
    return make_pair(s, t);
}

int main() {
    int n, m;
    long long ans;
    cin >> n >> m;
    vector<vector<int>> g(n);
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        g[a].emplace_back(b);
        g[b].emplace_back(a);
    }

    int s, t; tie(s, t) = is_bipartite(g);
    if (s and t) ans = (long long) s * t - m;
    else ans = (long long) n * (n - 1) / 2 - m;
    cout << ans << endl;
    return 0;
}

