bool isBiparateGraph() {
	check.resize(N, -1);
	stack<pll> st;
	st.push(pll(0, 0));   //頂点、色
	while (!st.empty()) {
		pll cur = st.top();
		st.pop();
		if (check[cur.first] == -1) {
			check[cur.first] = cur.second;
			for (ll ch : edges[cur.first]) {
				st.push(pll(ch, 1 - cur.second));
			}
		}
		else {
			if (check[cur.first] != cur.second) {
				return false;
			}
		}
	}
	return true;
}

