		edges[b].push_back(a);
	}
	bool isb = isBiparateGraph();
	if (isb) {
		ll zero = 0, one = 0;
		for (ll n = 0; n < N; n++) {
			if (check[n] == 0)zero++;
			else one++;
		}
		cout << zero * one - M << endl;
		return 0;
	}
