using Graph = vector<vector<int>>;
Graph G;
vector<int> color;
int black_cnt = 0;
// white 0, black 1
bool dfs(int cn, int cn_color){
    color[cn] = cn_color;
    if (cn_color == 1) black_cnt++;
    bool ok = true;
    for (auto next: G[cn]){
        if (color[next] == -1) {
            color[next] = 1 - cn_color;
            ok = dfs(next, color[next]);
            continue;
        }
        if (cn_color == color[next]) return false;
        else continue;
    }
    return ok;
}

