void build(int x,int y){
	pre[++all] = last[x];
	last[x] = all;
	other[all] = y;
}

bool bfs(int x,int y){
	int dt = last[x];
	while(dt != -1){
		int dr = other[dt];
		if(dr == y) return false;
		dt = pre[dt];
	}
	return true;
}

void dfs1(int x,int fa,int deep){
	int dt = last[x];
	while(dt != -1){
		int dr = other[dt];
		if(dr != fa){
			if(deep == 2){
				if(vis[dr] == 0) seq.push(dr),vis[dr] = 1;
				return;
			}
			dfs1(dr,x,deep + 1);
		}
		dt = pre[dt];
	}
}

void dfs(int s,int x,int fa,int deep){
	int dt = last[x];
	while(dt != -1){
		int dr = other[dt];
		if(dr != fa){
			if(deep == 3){
				if(bfs(dr,s) && s != dr){
					dfs1(dr,0,1);
					sum++;
					build(s,dr);
					build(dr,s);
					printf(" %d %d\n",s,dr);
					if(vis[dr] == 0) seq.push(dr),vis[dr] = 1;
				}
				return;
			}
			dfs(s,dr,x,deep + 1);
		}
		dt = pre[dt];
	}
}

