#include <unordered_set>

struct UnionFind {
  std::vector<int> data;
  UnionFind(int size) : data(size, -1) { }
  bool unionSet(int x, int y) {
    x = root(x); y = root(y);
    if (x != y) {
      if (data[y] < data[x]){ int tmp = x; x = y; y = tmp; }
      data[x] += data[y]; data[y] = x;
    }
    return x != y;
  }
  bool findSet(int x, int y) {
    return root(x) == root(y);
  }
  int root(int x) {
    return data[x] < 0 ? x : data[x] = root(data[x]);
  }
  int size(int x) {
    return -data[root(x)];
  }
};

int main(void)
{
  int N, M;
  std::cin >> N >> M;

  using vec_t = std::vector<int>;
  std::vector<vec_t> matrix(N, vec_t(N, 0));
  std::vector<std::pair<int, int> > M_in;

  for(int i = 0; i < M; ++i){
    int s, e;
    std::cin >> s >> e;
    s -= 1; e -= 1;
    matrix[s][e] = matrix[e][s] = 1;
    M_in.push_back(std::make_pair(s, e));
  }

  auto u = UnionFind(N);
  for(auto p: M_in){
    int s = p.first;
    int e = p.second;
    for(int i = 0; i < N; ++i){
      if(s != i && matrix[e][i]){
	u.unionSet(s, i);
      }
      if(e != i && matrix[s][i]){ u.unionSet(e, i); }
    }
  }

  std::vector<std::unordered_set<int> > directConnections(N);

  for(int i = 0; i < N; ++i){
    auto r = u.root(i);
    for(int j = 0; j < N; ++j){
      if(matrix[i][j]){ directConnections[r].insert(j); }
    }
  }

  std::vector<vec_t> after_matrix = matrix;
  for(int i = 0; i < N; ++i){
    int r = u.root(i);
    for(auto n: directConnections[r]){
      after_matrix[i][n] = after_matrix[n][i] = 1;
    }
  }

  for(int i = 0; i < N; ++i){ after_matrix[i][i] = 0; }
  int sum = 0;
  for(int i = 0; i < N; ++i){
    for(int j = 0; j < N; ++j){
      sum += after_matrix[i][j];
    }
  }

  std::cout << (sum / 2) - M << std::endl;

  return 0;
}

