                if (used[j] == used[i]) {
                    return false;
                }
            } else {
                used[j] = used[i] ^ 1;
                if (not dfs(j, i)) return false;
            }
        }
        return true;
    };
    used[0] = 0;
    if (not dfs(0, -1)) {
        return -1;
    } else {
        return count(whole(used), 0);
    }
}

int main() {
    // input
    int n, m; scanf("%d%d", &n, &m);
    vector<vector<int> > g(n);
    repeat (i, m) {
        int a, b; scanf("%d%d", &a, &b); -- a; -- b;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    // solve
    int k = check_bipartite_graph(g);
    ll result = k == -1 ?
        n *(ll) (n - 1) / 2 - m :
        k *(ll) (n - k) - m;
    // output
    printf("%lld\n", result);
    return 0;
}

