const ll TARGET = 100000;

int res = 0;

void dfs(Graph &g, unordered_set<ll> &connected, int depth, int from, int via,
         int to) {
  ll key = max(to, from) * TARGET + min(to, from);

  if (depth == 3) {
    if (connected.count(key)) {
      // cout << from << " - " << to << " connected,";
      return;
    }

    // cout << "connect " << from << " - " << to << endl;

    g.at(from).push_back(to);
    g.at(to).push_back(from);
    connected.insert(key);

    res++;
    return;
  }

  for (int i = 0; i < g.at(to).size(); i++) {
    int n = g.at(to).at(i);

    if (via == n || from == n) {
      continue;
    }

    // cout << from << " -> " << to << " -> " << n << " @ " << depth + 1 <<
    // endl;
    dfs(g, connected, depth + 1, from, to, n);
  }
}

bool isBipartite(Graph &g, vector<int> &colors) {
  colors.resize(g.size());
  colors.assign(g.size(), -1);

  struct Node {
    int number;
    int color;
  };

  stack<Node> s;

  for (int i = 0; i < g.size(); i++) {
    if (colors[i] == -1) {
      s.push(Node{number : i, color : 0});
    }

    while (!s.empty()) {
      auto node = s.top();
      s.pop();

      colors.at(node.number) = node.color;

      for (int i = 0; i < g[node.number].size(); i++) {
        auto next = g[node.number].at(i);

        if (colors[next] == node.color) {
          return false;
        }

        if (colors[next] != -1) {
          continue;
        }

        s.push(Node{number : next, color : 1 - node.color});
      }
    }
  }

  return true;
}

