template <typename V,typename Weight>
class Adjacency_List {
public:
	vector<vector<pair<V,Weight>>> E;
	V sz;
	Adjacency_List(V v) : E(v),sz(v){}
	void addEdgeDirected(V from,V to,Weight dis){
		E[from].push_back(make_pair(to,dis));
	}
	void addEdgeUndirected(V from,V to,Weight dis){
		E[from].push_back(make_pair(to,dis));
		E[to].push_back(make_pair(from,dis));
	}
};

template <typename V,typename Weight>
pair<bitset<c>,bitset<c>> separate(vector<vector<pair<V,Weight>>> &E) {
	typedef bitset<c> bs;
	queue<pair<int,bool>> que;
	que.push(make_pair(0,true));
	bs S1(0),S2(0);
	while (!que.empty()) {
		pair<int,bool> n = que.front();que.pop();
		if (n.second && S2[n.first]) {
			return make_pair(bs(0),bs(0));
		}
		if ((!(n.second)) && S1[n.first]) {
			return make_pair(bs(0),bs(0));
		}
		if (n.second) {
			S1.set(n.first);
			for (int i = 0;i < E[n.first].size();i++) {
				V next = E[n.first][i].first;
				if (S2[next]) continue;
				que.push(make_pair(next,!(n.second)));
			}
		}
		else {
			S2.set(n.first);
			for (int i = 0;i < E[n.first].size();i++) {
				V next = E[n.first][i].first;
				if (S1[next]) continue;
				que.push(make_pair(next,!(n.second)));
			}
		}
	}
	return make_pair(S1,S2);
}

int main(void) {
	long long N,M,x,y;
	cin >> N >> M;
	Adjacency_List<int,int> e(N);
	REP(i,M) {
		cin >> x >> y;
		e.addEdgeUndirected(x-1,y-1,1);
	}
	auto p = separate(e.E);
	long long s1 = p.first.count();
	long long s2 = p.second.count();
	if (s1 == 0 && s2 == 0) cout << (N * (N-1))/2LL - M <<  endl;
	else cout << s1 * s2 - M << endl;
}

