struct BipartiteGraph {
	struct Edge {
		const int from;
		const int to;
		Edge(const int from, const int to) :
			from(from),
			to(to)
			{}
	};
	const int V;
	vector<vector<Edge>> G;
	vector<int> color;
	BipartiteGraph(const int V) :
		V(V),
		G(vector<vector<Edge>>(V, vector<Edge>())),
		color(vector<int>(V, -1))
		{}
	void addEdge(const int from, const int to) {
		G[from].emplace_back(from, to);
		G[to].emplace_back(to, from);
	}
	bool dfs(const int from, const int col) {
		color[from] = col;
		bool ret = true;
		for(Edge e : G[from]) {
			if(color[e.to] == -1) {
				ret &= dfs(e.to, col ^ 1);
			}
			if(color[e.to] == col) {
				return false;
			}
		}
		return ret;
	}
	int bipart() {
		if(not dfs(0, 0)) throw "NOT Bipartite Graph";
		int ret = 0;
		for(int i : color) ret += i;
		return ret;
	}
};


int main() {
	int64_t n, m; cin >> n >> m;
	BipartiteGraph bg(n);
	for(int i = 0; i < m; ++i) {
		int a, b; cin >> a >> b;
		--a, --b;
		bg.addEdge(a, b);
	}
	try {
		int64_t b = bg.bipart();
		int64_t w = n - b;
		cout << b * w - m << '\n';
	}
	catch(...) {
		cout << n * (n - 1) / 2 - m << '\n';
	}
	return 0;
}

