	ios::sync_with_stdio(false);

	vector<ll> dist(100001, INF);
	vector<ll> tree[100001];
	ll n, m; cin >> n >> m;
	for (int i = 0; i < m; i++) {
		int a, b; cin >> a >> b;
		a--; b--;
		tree[a].push_back(b);
		tree[b].push_back(a);
	}
	dist[0] = 0;
	queue<P> q;
	q.push(P(0, 0));//点、距離
	while (!q.empty()) {
		P nex = q.front(); q.pop();
		int d = nex.second, v = nex.first;
		for (int i = 0; i < (int)tree[v].size(); i++) {
			int next = tree[v][i];
			if (dist[next] == INF) {
				dist[next] = d + 1;
				q.push(P(next, d + 1));
			}
		}
	}
	ll odd = 0, even = 0;
	for (int i = 0; i < n; i++) {
		if (dist[i] % 2 == 0) even++;
		else odd++;
	}
	if (n - 1 == m) {
		//cout << n*(n - 1) / 2 - m - even*(even - 1) / 2 - odd*(odd - 1) / 2 << endl;
		cout << odd*even - m << endl;
