template <typename T>
class undigraph {
public:
  struct edge{
    int from;
    int to;
    T cost;
  };

  vector< vector<int> > v;
  vector<edge> edges;

  int n;

  undigraph(int n){
    v.resize(n);
  }

  void add(int from,int to,T cost = 1){
    v[from].push_back(edges.size());
    v[to].push_back(edges.size());
    edges.push_back({from, to, cost});
  }
};

template <typename T>
vector <T> dijkstra(const undigraph<T> &g, int start) {
  vector<T> dist(g.n, numeric_limits<T>::max());
  priority_queue<pair<T, int>, vector<pair<T, int> >, greater<pair<T, int> > > s;
  dist[start] = 0;
  s.emplace(dist[start], start);

  while(!s.empty()){
    int expected = s.top().first;
    int base = s.top().second;
    if(expected != dist[base]){
      continue;
    }
    s.pop();
    for(int id:g.v[base]){
      auto &e = g.edges[id];
      int to = base ^ e.from ^ e.to;
      if(dist[base] + e.cost < dist[to]){
	dist[to] = dist[base] + e.cost;
	s.emplace(dist[to],to);
      }
    }
  }
  return dist;
}

int i,j;

int main(){
  int n,m,a,b;
  cin>>n>>m;
  undigraph<int> g(n);
  g.n=n;
  for(i=0;i<m;i++){
    cin>>a>>b;
    g.add(a-1,b-1);
  }
  vector<int> dist = dijkstra(g,0);

  for(auto &e:g.edges){
    if(dist[e.from]%2 == dist[e.to]%2){
      cout<<n*(n-1)/2-m<<endl;
      return 0;
    }
  }
  int c=0;
  for(int i=0;i<n;i++){
    c+=dist[i]%2?1:0;
  }
  cout<<c*(n-c)-m<<endl;
  return 0;
}

