void solve(int time, int start, int pre)
{
	if (time == 0) 
	{

		if (pre != start&&edge[pre][start] != 1)
		{
			edge[pre][start] = 1;
			edge[start][pre] = 1;

			++answer;

			solve(2, start, pre);
		}

		return;

	}

	for (int i = 0; i < N; ++i)
	{
		if (pre == i) { continue; }

		if (edge[pre][i] == 0) { continue; }

		solve(time - 1, start, i);
	}
}


