namespace Graph{
    int V;
    vector<vector<int>> G;
    vector<int> color;
    bool dfs(int v,int c){
        color[v]=c;
        for(int node:G[v]){
            if(color[node]==c) return false;
            if(color[node]==0 and !dfs(node,-c)) return false;
        }
        return true;
    }
    bool isBipartiteGraph(const vector<vector<int>>& g){
        G=g;
        V=G.size();
        color.assign(V,0);
        for(int i=0;i<V;i++)
            if(color[i]==0 and !dfs(i,1)) return false;
        return true;
    }
    vector<int> getColor(){
        return color;
    }
};

