void Get3Dist() {
  for (int i = 0; i < M; i++) {
    vector<int> v1, v2;
    int A = edge[i].first;
    int B = edge[i].second;

    for (auto v : G[A]) {
      if (v == B) {
        continue;
      }
      for (auto u : G[B]) {
        if (u == A) {
          continue;
        }
        if (v == u) {
          continue;
        }
        if (G[v].find(u) == G[v].end()) {
          X[v].push_back(u);
        }
      }
    }
  }
  M = 0;
}

int main() {
  cin >> N >> M;

  for (int i = 0; i < M; i++) {
    int A, B;
    cin >> A >> B;
    edge[i] = P(A, B);
    G[A].insert(B);
    G[B].insert(A);
  }

  int ans = 0;
  while (true) {
    for (int i = 1; i <= N; i++) {
      X[i].clear();
    }

    Get3Dist();

    bool update = false;
    for (int i = 1; i <= N; i++) {
      for (auto u : X[i]) {
        if (G[i].find(u) == G[i].end()) {
          update = true;
          ans++;
          edge[M++] = P(i, u);
          G[i].insert(u);
          G[u].insert(i);
        }
      }
    }
    if (!update) {
      break;
    }
  }

  cout << ans << endl;


  return 0;
}

