using ll1d = vector<ll>;
using ll2d = vector<ll1d>;
using ll3d = vector<ll2d>;

struct Edge {
  ll fr, to;
  Edge(ll fr, ll to) {
    this->fr = fr;
    this->to = to;
  };

  bool operator<(const Edge &edge) const {
    return fr != edge.fr ? edge.fr < fr : to < edge.to;
  }
};

bool dfs(const ll& v, const ll& c, vector<ll> &col, ll2d& g) {
  col[v] = c;
  rep(i, g[v].size()) {
    if (col[g[v][i]] == c) return false;
    if (col[g[v][i]] == 0 and !dfs(g[v][i], -c, col, g)) return false;
  }
  return true;
}

void solve(istream &ccin = cin, ostream &ccout = cout) {
  ll n, m;
  ccin >> n >> m;
  ll2d g(n);
  rep(i, m) {
    ll a, b;
    ccin >> a >> b;
    --a;
    --b;
    g[a].push_back(b);
    g[b].push_back(a);
  }

  ll1d col(n, 0);
  if (dfs(0, 1, col, g)) {
    ll b1 = 0, b2 = 0;
    rep(i, n) {
      if (col[i] == 1) ++b1;
      else ++b2;
    }
    ccout << b1 * b2 - m << endl;
  } else
    ccout << n * (n - 1) / 2 - m << endl;

}

int main() {
  ios::sync_with_stdio(false);
  solve();
  return 0;
}

