#include <bits/stdc++.h>
using namespace std;

vector<int> graph[100005];
int col[100005];
int cnt[3];
bool bipartite;

long long ans;

void dfs(int t)
{
    cnt[col[t]]++;
    for (int nxt : graph[t])
    {
        if (col[nxt])
        {
            if (col[nxt] == col[t]) bipartite = false;
            continue;
        }
        col[nxt] = col[t] ^ 3;
        dfs(nxt);
    }
}

int main()
{
    int n, m;
    scanf("%d%d",&n,&m);
    for (int i = 0; i < m; i++)
    {
        int a, b;
        scanf("%d%d",&a,&b);
        graph[a].push_back(b);
        graph[b].push_back(a);
    }

    for (int i = 1; i <= n; i++)
    {
        if (col[i]) continue;
        cnt[1] = cnt[2] = 0;
        bipartite = true;
        col[i] = 1;
        dfs(i);

        if (bipartite) ans += cnt[1] * 1LL * cnt[2];
        else ans += (cnt[1] + cnt[2]) * 1ll * (cnt[1] + cnt[2] - 1) / 2;
    }

    printf("%lld\n", ans - m);
}

