	}
	for(auto k:R[j][1]) if(i!=k){
		R[i][2].insert(k);
		R[k][2].insert(i);
	}
	for(auto k:R[i][1]) for(auto l:R[j][1]) if(!R[k][1].count(l) && k!=l){
		ans += 1 + addEdges(k, l);
	}
	for(auto k:R[j][2]) if(!R[i][1].count(k) && k!=i){
		ans += 1 + addEdges(i, k);
	}
	for(auto k:R[i][2]) if(!R[j][1].count(k) && k!=j){
		ans += 1 + addEdges(j, k);
	}
	return ans;
}


