int getdepth(vector<int> &depth, vector<vector<int>> &edges){
    int n = edges.size();
    int husai = 0;
    depth[0] = 0;
    queue<pair<int,int>> q;
    q.push(make_pair(0, -1));
    int parent = -1;
    int accum_odd = 0;
    int accum_even = 0;
    int ret = 0;

    while(!q.empty()){
        auto t = q.front();
        q.pop();
        int now = t.first;
        int parent = t.second;

        if(depth[now]%2==0){
            ret += max(0, accum_odd - 1);
            accum_even++;
        }
        else{
            ret += max(0, accum_even-1);
            accum_odd++;
        }
        for(int e: edges[now]){
            if(e == parent)
                continue;
            else if(depth[e] != -1 && (depth[now] - depth[e])%2==0){
                return -1;
            }
            else if(depth[e] != -1 && depth[now] - depth[e] > 1){
                husai++;
            }
            else{
                depth[e] = depth[now] + 1;
                q.push(make_pair(e, now));
            }
        }
    }
    return ret - husai;
}

