li bip(vector<vector<int>>& adj,int a=0,int part=1){
  static li va=0;
  int n=adj.size();
  static vector<int> seen(n,0);
  seen[a]=part;
  if(part==1) va++;
  for(int v:adj[a]){
    if(seen[v]){
      if(seen[v]==seen[a]) return 0;
      continue;
    }
    if(not bip(adj,v,part*(-1))) return 0;
  }
  return va;
