        node[b].edge.push_back(a);
    }
    q.push(1);
    node[1].clr = 1;
    node[1].visit = 1;

    if (judge()) {
        int B = 0, W = 0;
        for (int i = 1; i <= N; i++) {
            if (node[i].clr == 1) B++;
            else W++;
        }
        cout << B * W - M << endl;
    }
    else {
        cout << N * (N - 1) / 2 - M << endl;
    }
}

