		int v = q.front(); q.pop();
		for (int i = 0; i < (int)tree[v].size(); i++) {
			int next = tree[v][i];
			if (dist[next] == INF) {
				dist[next] = dist[v] + 1;
				q.push(next);
			}
		}
	}
	int odd = 0, even = 0;
