    random_shuffle(V[i].begin(), V[i].end());
  }
  int visited[100010];
  fill(visited, visited+100010, 0);
  int color[100010];
  fill(color, color+100010, 0);
  int parent[100010];
  stack<state> S;
  S.push(state(0, -1, 1));
  while (!S.empty()) {
    int now = get<0>(S.top());
    int from = get<1>(S.top());
    int clr = get<2>(S.top());
    // cerr << "now = " << now << ", from = " << from << endl;
    S.pop();
    if (visited[now] == 0) {
      visited[now] = true;
      parent[now] = from;
      color[now] = clr;
      // cerr << "parent[" << now << "] = " << from << endl;
      S.push(state(now, now));
      for (auto x : V[now]) {
        if (x != parent[now]) {
          S.push(state(x, now, 3-clr));
        }
      }
    } else if (visited[now] == 1) {
      if (from != now) {
        if (color[now] == 3) continue;
        if (color[now] == clr) continue;
        color[now] = 3;
        for (auto x : V[now]) {
          if (x != parent[now]) {
            S.push(state(x, now, 3-clr));
          }          
        }
      } else {
        visited[now] = 2;
      }
    }
  }
  for (auto i = 0; i < 100010; ++i) {
    visited[i] = (color[i] == 3);
  }
  ll ans = 0;
  for (auto i = 0; i < N; ++i) {
    if (visited[i]) continue;
    stack<cond> SS;
    SS.push(cond(i, 0));
    ll cnt[2] = {0, 0};
    while (!SS.empty()) {
      int now = get<0>(SS.top());
      int depth = get<1>(SS.top());
      SS.pop();
      if (!visited[now]) {
        visited[now] = true;
        cnt[depth%2]++;
        for (auto x : V[now]) {
          if (!visited[x]) {
            SS.push(cond(x, depth+1));
          }
        }
      }
    }
    ans += cnt[0] * cnt[1];
  }
  ll L = 0;
  for (auto i = 0; i < N; ++i) {
    if (color[i] == 3) L++;
  }
  cerr << "L = " << L << endl;
  ans += L * (L-1) / 2 + L * (N-L) - M;
  cout << ans << endl;
}

