const int N = 411111;
vector<int> a[N];

int main() {
	int n = nxt(), m = nxt();
	for (int i = 0; i < m; ++i) {
		int u = nxt() - 1, v = nxt() - 1;
		a[u].push_back(v + n);
		a[v].push_back(u + n);
		a[u + n].push_back(v);
		a[v + n].push_back(u);
	}

	long long ans = 0;

	int cl = 0;
	vector<int> used(n + n, 0);
	for (int i = 0; i < n; ++i) {
		if (used[i]) {
			continue;
		}
		vector<int> st = {i};
		++cl;
		used[i] = 2 * cl;
		int cnt_ev = 0, cnt_od = 0;
		while (!st.empty()) {
			int v = st.back();
			st.pop_back();
			if (used[v] % 2) {
				cnt_od += 1;
			} else {
				cnt_ev += 1;
			}
			for (int x : a[v]) {
				if (used[x]) {
					continue;
				}
				// cerr << v + 1 << " <-> " << x + 1 << "\n";
				used[x] = 4 * cl - 1 - used[v];
				st.push_back(x);
			}
		}
		// cerr << cnt_od << " " << cnt_ev << "\n";
		ans += cnt_od * 1ll * cnt_ev;
	}

	for (int i = 0 ; i < n; ++i) {
		if ((used[i] - 1) / 2 == (used[i + n] - 1) / 2) {
			--ans;
		}
	}

	cout << ans / 2 - m << "\n";

	return 0;
}

