		}
}
	}
	int odd = 0, even = 0;
	for (int i = 0; i < n; i++) {
		if (dist[i] % 2 == 0) even++;
		else odd++;
	}
	if (n - 1 == m) {
		cout << n*(n - 1) / 2 - m - even*(even - 1) / 2 - odd*(odd - 1) / 2 << endl;
	}
	else {
		int cnt = 0;
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < (int)tree[i].size(); j++){
				int a = i, b = tree[i][j];
