struct BipartiteMatching {
  vector< vector< int > > graph;
  vector< int > match, alive, used;
  int timestamp;

  BipartiteMatching(int n) : graph(n), alive(n, 1), used(n, 0), match(n, -1), timestamp(0) {}

  void add_edge(int u, int v) {
    graph[u].push_back(v);
    graph[v].push_back(u);
  }

  bool dfs(int idx) {
    used[idx] = timestamp;
    for(auto &to : graph[idx]) {
      int to_match = match[to];
      if(alive[to] == 0) continue;
      if(to_match == -1 || (used[to_match] != timestamp && dfs(to_match))) {
        match[idx] = to;
        match[to] = idx;
        return true;
      }
    }
    return false;
  }

  int bipartite_matching() {
    int ret = 0;
    for(int i = 0; i < graph.size(); i++) {
      if(alive[i] == 0) continue;
      if(match[i] == -1) {
        ++timestamp;
        ret += dfs(i);
      }
    }
    return ret;
  }

  void output() {
    for(int i = 0; i < graph.size(); i++) {
      if(i < match[i]) {
        cout << i << "-" << match[i] << endl;
      }
    }
  }
};

struct PartiallyPersistentUnionFind {

    using pint = pair<int, int>;

    // last[i]が-1でならその頂点iは根である
    // あるtに対してt < last[i]が成り立つなら, tにおいて頂点iは根である
    // last[i]は一度しか更新されない ⇔ 縮約を行わない

    // historyはmergeが行われるたびにemplace_backされる
    // history[i].FIはtでソートされているため, 要素数をみるだけでsizeを求められる
    vector<int> par, last;
    vector<vector<pint>> history;

    PartiallyPersistentUnionFind(int n) : par(n, -1), last(n, -1), history(n) {
        for(auto &vec : history) vec.emplace_back(-1, -1);
    }

    void init(int n){
        par.assign(n, -1); last.assign(n, -1); history.assign(n, vector<pint>());
        for(auto &vec: history) vec.emplace_back(-1, -1);
    }

    int root(int t, int x){
        if(last[x] == -1 || t < last[x]) return x;
        return root(t, par[x]);
    }

    bool issame(int t, int x, int y){
        return root(t, x) == root(t, y);
    }

    bool merge(int t, int x, int y){
        x = root(t, x);
        y = root(t, y);

        if(x == y) return false;
        // xとyをmergeする
        if( par[x] > par[y]) swap(x, y);
        par[x] += par[y];
        par[y] = x;
        // yが根でなくなったのはtなので lastに記録する
        last[y] = t; 
        history[x].emplace_back(t, par[x]);
        return true;
    }

    int size(int t, int x){
        x = root(t, x);

        return -prev(lower_bound(history[x].begin(), history[x].end(), make_pair(t, 0)))->second;
    }
};

