void bfs() {
    std::queue<int> Q;
    Q.push(0);
    while(!Q.empty()) {
        int cv = Q.front();
        for (auto it : gr[cv]) {
            if (visited[it] == 0) {
                Q.push(it);
                visited[it] = 1;
            }
            if (odd[cv]) {
                even[it] = 1;
            }
            if (even[cv]) {
                odd[it] = 1;
            }

        }
        Q.pop();
    }
}

