void visit(int v, int c) {
  colors[v] = c;
  colorCounter[c]++;
  for (int w : adjlist[v]) {
    if (colors[w] == -1) {
      visit(w, 1 ^ c);
    } else if (colors[w] != (1 ^ c)) {
      bipartite = false;
    }
  }
}

