    adjlist[b].push_back(a);
  }

  bipartite = true;
  colors.resize(n, -1);
  visit(0, 1);

  ll maxEdges;
  if (bipartite) {
    maxEdges = colorCounter[0] * colorCounter[1];
  } else {
    maxEdges = 1LL * n * (n - 1) / 2;
  }
