                                // 塗られていないなら 0

// 頂点を塗る
// 頂点vをcで塗るところから初めて，隣接頂点を塗りながら辿っていく
// 連結なら1回で，すべて辿れる！
bool dfs(int v, int c) {
  color[v] = c;                 // 頂点vをcで塗る
  REP(i,0, G[v].size()) {
    // 隣接している頂点が同じ色で塗られてたら false
    if (color[G[v][i]] == c) return false;
    // 隣接頂点が塗られていないなら，-c で塗ってみる．
    // 塗れないなら false
    if (color[G[v][i]] == 0 && !dfs(G[v][i], -c)) return false;
  }
  // vから辿っていって全て塗れた:
  return true;
}

int main()
{
  cin >> N >> M;
  REP(i,0,M) {
    int A,B;
    cin >> A >> B;
    --A; --B;                   // Use 0-indexed
    // 無向グラフ
    G[A].push_back(B);
    G[B].push_back(A);
  }

  // どこも塗られてない
  REP(i,0,N) color[i] = 0;

  int ans;
  if (dfs(0, 1)) {              // 2色で塗れたので，2部グラフ

    // REP(i,0,N) {
    //   cout << color[i] << " ";
    // }
    // cout << endl;

    // 色1で塗った頂点の数
    int B = 0;
    REP(i,0,N) {
      if (color[i] == 1) ++B;
    }
    ans = B * (N - B) - M;
  } else {                      // 2部グラフでない
    ans = N * (N - 1) / 2 - M;
  }

  cout << ans << endl;

  return 0;
}

