void solve(std::istream &in, std::ostream &out) {
  int n, m;
  in >> n >> m;
  vector<vector<int>> graph(n);
  for (int i = 0, x, y; i < m; ++i) {
    in >> x >> y;
    --x;
    --y;
    graph[x].push_back(y);
    graph[y].push_back(x);
  }
  vector<int> col(n, -1);
  col[0] = 0;
  queue<int> que;
  que.push(0);
  bool bipartite = true;
  while (!que.empty()) {
    int u = que.front();
    que.pop();
    for (int v : graph[u]) {
      if (col[v] != -1) {
        bipartite &= col[v] == 1 - col[u];
      } else {
        col[v] = 1 - col[u];
        que.push(v);
      }
    }
  }
  if (bipartite) {
    int cnt = accumulate(col.begin(), col.end(), 0, std::plus<>());
    out << (int64_t) cnt * (n - cnt) - m << '\n';
  } else {
    out << (int64_t) n * (n - 1) / 2 - m << '\n';
  }
}

