bool find1(int x,int y){
  int l,r,m;
  if(g[x].size()>g[y].size()){
    l=x;
    x=y;
    y=l;
  }
  sort(g[x].begin(),g[x].end());
  l=0;r=g[x].size()-1;
  while(l+1<r){
    m=(l+r)/2;
    if(g[x][m]>=y) r=m;
    else l=m;
  }
  if((g[x][l]==y)||(g[x][r]==y)) return true;
  else return false;
}

int bfs(int s){
  queue<bfsi> q;
  q.push(bfsi(s,s,0));

  int res=0;
  while(q.size()){
    bfsi bf=q.front();
    q.pop();
    if(bf.z==3){
      if(!find1(bf.x,bf.y)){
	res++;
	g[bf.x].pb(bf.y);
	g[bf.y].pb(bf.x);
	//printf("::%d %d\n",bf.x,bf.y);
      }

    }
    else{
      for(int i=0;i<g[bf.y].size();i++){
	if(bf.x==g[bf.y][i]) continue;
	q.push(bfsi(bf.x,g[bf.y][i],bf.z+1));
      }
    }
  }
  return res;
}

