template <typename T>
struct Graph {
    int V, E;
    struct Edge {
        int from, to;
        T cost;
    };
    vector<vector<Edge>> edge;
    vector<vector<T>> dist;
    vector<Edge> es;

    Graph(int V, int E) : V(V), E(E) {
        edge.assign(V, vector<Edge>(0));
        dist.assign(V, vector<T>(0));
    }

    void input(bool is_direct, bool inputc, bool index0 = false) {
        int a, b;
        T c = 0;
        for (int i = 0; i < E; i++) {
            cin >> a >> b;
            if (inputc) cin >> c;
            if (!index0) a--, b--;
            edge[a].push_back((Edge){a, b, c});
            es.push_back((Edge){a, b, c});
            if (!is_direct) {
                edge[b].push_back((Edge){b, a, c});
                es.push_back((Edge){b, a, c});
            }
        }
        if (!is_direct) E *= 2;
    }

    void add_edge(int from, int to, T cost, bool is_direct) {
        edge[from].push_back({from, to, cost});
        es.push_back({from, to, cost});
        if (!is_direct) {
            edge[to].push_back({to, from, cost});
            es.push_back({to, from, cost});
            E++;
        }
        E++;
    }

    vector<int> B, W;
    vector<int> color;

    bool coloring(int v = 0, bool c = true, int from = -1) {
        if (color.size() == 0) color.assign(V, 0);
        if (color[v] && color[v] - 1 != c) return false;
        if (color[v] && color[v] - 1 == c) return true;

        color[v] = c + 1;
        if (c) W.push_back(v);
        if (!c) B.push_back(v);

        for (const auto& e : edge[v]) {
            int to = e.to;
            if (!coloring(to, !c)) return false;
        }
        return true;
    }
};

int main() {
    ll N, M;
    cin >> N >> M;
    Graph<int> g(N, M);
    g.input(false, false);
    if (g.coloring())
        cout << (ll)g.B.size() * g.W.size() - M << endl;
    else
        cout << N * (N - 1) / 2 - M << endl;
    return 0;
}

