class unionfind {
public:
    int _n;
    std::vector<int> d;

    unionfind(int n) :_n(n) {
        d.resize(n, -1);
    }

    int find(int x) {
        assert(0 <= x && x < _n);
        if (d[x] < 0) return x;
        return d[x] = find(d[x]);
    }

    void unite(int x, int y) {
        assert(0 <= x && x < _n);
        assert(0 <= y && y < _n);
        x = find(x);
        y = find(y);
        if (x == y) return;
        if (d[x] > d[y]) std::swap(x, y);
        d[x] += d[y];
        d[y] = x;
    }

    bool same(int x, int y) {
        assert(0 <= x && x < _n);
        assert(0 <= y && y < _n);
        return find(x) == find(y);
    }

    int size(int x) {
        assert(0 <= x && x < _n);
        return -d[x];
    }

    // bipartite graphs
    // if the given graph is bipartite, returns the way of coloring vertices
    // if not, returns {-1}
    static std::vector<int> is_bipartite(std::vector<std::vector<int>>& g) {
        int n = (int) g.size();
        unionfind uf(2 * n);
        for (int i = 0; i < n; ++i) {
            for (auto j : g[i]) {
                assert(j < n);
                if (!uf.same(i, j + n)) uf.unite(i, j + n);
                if (!uf.same(i + n, j)) uf.unite(i + n, j);
            }
        }
        // this is not bipartite graph
        if (uf.same(0, n)) {
            return {-1};
        }
        std::vector<int> color(n);
        for (int i = 0; i < n; ++i) {
            color[i] = uf.same(0, i);
        }
        return color;
    }
};

