bool is_graph(ll v, const Graph &G, vector<ll> &seen, ll flag)
{
  if (seen[v] > 0)
    return seen[v] == flag;
  else
    seen[v] = flag;

  for (auto g : G[v])
  {
    if (flag == 2)
    {
