using namespace std;

struct Graph {
    struct Vertex { int n, k; };
    struct Edge { int i, n; };
    Graph(int n, int m) : v(n, { -1, -1 }), e(m), n(n), m(0), b(0) {}
    void add_edge(int i, int j) {
        e[m] = { j, v[i].n };
        v[i].n = m;
        m++;
    }
    void dfs(int i, int p, int k) {
        if (v[i].k < 0) v[i].k = k; else { b |= k != v[i].k; return; }
        for (int j = v[i].n; j >= 0; j = e[j].n) {
            Edge& o = e[j];
            if (o.i == p) continue;
            dfs(o.i, i, k ^ 1);
        }
    }
    int64_t foo() {
        int64_t k = 0;
        int c[2] = {};
        for (int i = 0; i < n; i++) {
            c[v[i].k]++;
        }
        for (int i = 0; i < n; i++) {
            int l = 0;
            for (int j = v[i].n; j >= 0; j = e[j].n) {
                l++;
            }
            k += c[v[i].k ^ 1] - l;
        }
        return k / 2;
    }
    vector<Vertex> v;
    vector<Edge> e;
    int n, m;
    int b;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n, m;
    cin >> n >> m;

    Graph g(n, m * 2);
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;

        g.add_edge(a, b);
        g.add_edge(b, a);
    }

    g.dfs(0, -1, 0);

    if (g.b) {
        cout << (int64_t)n * (n - 1) / 2 - m << endl;
    } else {
        cout << g.foo() << endl;
    }

    return 0;
}

