struct edge{int to, cost, id;};

class Graph
{
public:
    int N;
    vector<vector<edge>> G;
    vec col;
    vec num;

    Graph(int N): N(N){
        G = vector<vector<edge>>(N, vector<edge>(0));
        col = vec(N, -1);
        num = vec(2, 0);
    }

    void add_Directed_edge(int from, int to, int cost = 1, int id = 0){
        G[from].push_back(edge({to, cost, id}));
    }

    void add_Undirected_edge(int v1, int v2, int cost = 1, int id = 0){
        add_Directed_edge(v1, v2, cost, id);
        add_Directed_edge(v2, v1, cost, id);
    }


    bool dfs(int v, int c){
        if(col[v] != -1){
            if(col[v] != c) return false;
            else return true;
        }else{
            col[v] = c;
            num[c]++;
        }
        for(auto e: G[v]){
            if(!dfs(e.to, 1 - c)) return false;
        }
        return true;
    }

};

signed main(){

    int N, M; cin >> N >> M;
    Graph G(N);
    REP(i, M){
        int a, b; cin >> a >> b;
        G.add_Undirected_edge(a - 1, b - 1);
    }
    bool f = G.dfs(0, 0);
    if(!f){
        Out(N * (N - 1) / 2 - M);
    }else{
        Out(G.num[0] * G.num[1] - M);
    }

    return 0;
}

