      for(int j = 0; j < N; j++){
        V[i][j] = C[i][j];
      }
    }
    //count
    count = 0;
    for(int i = 0; i < N; i++){
      for(int j = i; j < N; j++){
        if(V[i][j] != 0) count++;
      }
