constexpr int N_MAX = 1e5;
int N, M;
vector<si> G1(N_MAX);
vector<si> G2(N_MAX);

void setupG2(int root, int node, int depth) {
  if (depth > 1) {
    for (auto c : G1[node]) {
      setupG2(root, c, depth-1);
    }
    return;
  }

  assert(depth == 1);
  for (auto c : G1[node]) {
    if (c <= root) continue;
    G2[root].insert(c);
    G2[c].insert(root);
  }
}

int find3(int root) {
   int ret = 0;
   vi plus;

   for (auto c2 : G2[root]) {
     for (auto c : G1[c2]) {
       if (c <= root || G1[root].count(c)) continue;
       plus.emplace_back(c);
     }
   }

   for (auto p : plus) {
     if (G1[root].count(p)) continue;

     G1[root].insert(p);
     G1[p].insert(root);
     ret++;

     for (auto c : G1[p]) {
       if (c <= root) continue;
       G2[root].insert(c);
       G2[c].insert(root);
     }
   }

   return ret;
}

int main(int argc, char** argv) {
  cin >> N >> M;
  for (int i=0; i<M; i++) {
    int A, B;
    cin >> A >> B;
    A--; B--; // 0-indexed
    G1[A].insert(B);
    G1[B].insert(A);
  }

  for (int i=0; i<N; i++) {
    setupG2(i, i, 2);
  }

  ll ret = 0;

  for (int i=0; i<N; i++) {
//cerr << "HOGE " << i << endl;

    while (true) {
      int x = find3(i);
      if (x==0) break;
      ret += x;
    }
  }

  for (int i=0; i<N; i++) {
//cerr << "HOGE " << i << endl;

    while (true) {
      int x = find3(i);
      if (x==0) break;
      ret += x;
    }
  }

  cout << ret << endl;

  return 0;
}

