constexpr int N_MAX = 100000;
queue<int> Q;
int A[N_MAX + 10]; // 深さを記入する配列
bool bfs(int src, vvi &v){ // v...隣接リスト
    mem(A,-1);
    Q.push(src); // Qの初期化
    A[src] = 0; // A[スタート地点]の深さ
    while(! Q.empty()){
        int cur = Q.front();
        trc(v[cur] , cur);
        Q.pop();
        for(int x : v[cur]){ // 探索範囲
            trc(x,A[x]);
            if(A[x] == -1){ // 条件
                int dst = x;
                trc(dst);
                A[dst]=A[cur]+1; // dstの深さはA[cur]+1
                Q.push(dst); // Qにdstを追加
            }
            else if( (A[cur] + 1) % 2 != A[x] % 2 ){
                return false;
            }
        }
    }
    return true;
}

