bool is_bigraph(int n) {
  for (int next_n : G[n]) {
    // if adjacent node has same color.
    if (C[next_n] == C[n])
      return false;
    // if adjacent node doesn't have color.
    else if (C[next_n] == 0) {
      C[next_n] = C[n] * -1;
      if (!is_bigraph(next_n))
        return false;
    }
  }
  return true;
}

