        int A, B;
        cin >> A >> B;
        A--, B--;
        G[A].emplace_back(B);
        G[B].emplace_back(A);
    }
    auto t = BipartiteGraph(G);
    if(t == -1) {
        print(N * (N - 1) / 2 - M);
    } else {
        print(t * (N - t) - M);
    }
}

