        a--;b--;
        u.merge(a,b+n);
        u.merge(b,a+n);
    }
    if(u.same(0,n)){
        cout << n*(n-1)/2-m << endl;
        return 0;
    }
    else{
        ll ans = 0;
        rep(i,n){
            if(u.same(0,i)){
                ans++;
            }
        }
        cout << ans * (n-ans)-m << endl;
        return 0;
    }
}

