        int a, b; cin >> a >> b; a--; b--;
        g[a].emplace_back(b);
        g[b].emplace_back(a);
    }
    color.assign(V, -1);
    color[0] = 0;
    ll ans = 0;
    if (!is_bipartite(0)) {
        ans = 1LL * V * (V - 1) / 2;
    } else {
        for (int i = 0; i < V; i++) ans += color[i];
        ans *= V - ans;
    }
    ans -= E;
    cout << ans << endl;
    return 0;
}

