template <typename V,typename Weight>
class Adjacency_List {
public:
	vector<vector<pair<V,Weight>>> E;
	V sz;
	Adjacency_List(V v) : E(v),sz(v){}
	void addEdgeDirected(V from,V to,Weight dis){
		E[from].push_back(make_pair(to,dis));
	}
	void addEdgeUndirected(V from,V to,Weight dis){
		E[from].push_back(make_pair(to,dis));
		E[to].push_back(make_pair(from,dis));
	}
};

template <typename V,typename Weight>
pair<long long,long long> separate(vector<vector<pair<V,Weight>>> &E) {
	queue<pair<int,int>> que;
	que.push(make_pair(0,0));
	long long S1 = 0,S2 = 0;
	while (!que.empty()) {
		pair<int,int> n = que.front();que.pop();
		if (n.second && ((S2 >> n.first) & 1)) return make_pair(-1,-1);
		if ((!n.second) && ((S1 >> n.first) & 1 )) return make_pair(-1,-1);
		if (n.second) {
			S1 |= (1 << n.first);
			for (int i = 0;i < E[n.first].size();i++) {
				V next = E[n.first][i].first;
				if ((S2 >> next) & 1) continue;
				que.push(make_pair(next,(n.second+1)%2));
			}
		}
		else {
			S2 |= (1 << n.first);
			for (int i = 0;i < E[n.first].size();i++) {
				V next = E[n.first][i].first;
				if ((S1 >> next) & 1) continue;
				que.push(make_pair(next,(n.second+1)%2));
			}
		}
	}
	return make_pair(S1,S2);
}

