	Adjacency_List<int,int> e(N);
	REP(i,M) {
		cin >> x >> y;
		e.addEdgeUndirected(x-1,y-1,1);
	}
	auto p = separate(e.E);
	cout << (__builtin_popcountll(p.first))*(__builtin_popcountll(p.second)) - M << endl;
}

