	vector<int> ids_dst;
	Vertices dsts;
	Color color;
	Vertex(int id) :
		id(id), color(0) { }
	void add_edge(Edge *p_e);
};
typedef vector<Vertex*> Vertices;

struct Edge {
	Vertex *p_src, *p_dst;
	Edge(Vertex *p_src, Vertex *p_dst) :
		p_src(p_src), p_dst(p_dst) { }
};

void Vertex::add_edge(Edge *p_e) {
	edges.push_back(p_e);
	dsts.push_back(p_e->p_dst);
}

struct Graph {
	Vertices vertices;
	Edges edges;
	Graph(int nvertices) {
		for (int id = 0; id < nvertices; id++) {
			vertices.push_back(new Vertex(id));
		}
	}
	~Graph() {
		for (auto &p_vertex : vertices) {
			delete p_vertex;
		}
		for (auto &p_edge : edges) {
			delete p_edge;
		}
	}
	void add_edge(Edge *p_edge) {
		(*vertices[p_edge->p_src->id]).add_edge(p_edge);
		edges.push_back(p_edge);
	}
	void add_edge(int edge_src, int edge_dst) {
		add_edge(new Edge(vertices[edge_src], vertices[edge_dst]));
	}
	int get_nblacks() { //color=1
		int count = 0;
		for (auto &p_vertex : vertices) {
			if (p_vertex->color == 1) {
				count++;
			}
		}
		return count;
	}
};

bool is_bipartite(Vertex *p_v, const Color c) {
	p_v->color = c;
	for (auto p_dst : p_v->dsts) {
		if (p_dst->color == 0 && !is_bipartite(p_dst, -c)) {
			return false;
		}
		else if (p_dst->color == c) {
			return false;
		}
	}
	return true;
}

int N, M;
int A, B;

void solve() {
	long long ans;

	cin >> N >> M;
	Graph g(N + 1);
	for (int i = 0; i < M; i++)
	{
		cin >> A >> B;
		g.add_edge(A, B);
		g.add_edge(B, A);
	}
	long long nedges_possible;
	if (is_bipartite(g.vertices[1], 1)) {
			const int nblacks = g.get_nblacks();
			nedges_possible = (long long)nblacks * (N-nblacks);
	}
	else {
		nedges_possible = (long long)N * (N - 1) / 2;
	}
	ans = nedges_possible - M;

	cout << ans << endl;

	return;
}

int main() {
	solve();
	return 0;
