typedef long long ll;
ll l=0,r=0;
int bj[500010] = {0};
bool playbfs(vector<int> nn[],int n)
{
	int t,t1;
	queue<int> bfs;
	bfs.push(1);
	bj[1] = 1;
	while(!bfs.empty())
	{
		int w;
		int t;
		w = bfs.front();
		bfs.pop();
		if(bj[w]&1)
			l++;
		else
			r++;
		for(t=0;t<nn[w].size();t++)
		{
			if(bj[nn[w][t]] == 0)
			{
				bj[nn[w][t]] = bj[w]+1;
				bfs.push(nn[w][t]);
			}
			else
			{
				if(bj[w]%2 == bj[nn[w][t]]%2)
					return 0;
			}
		}
	}
	return 1;
}
int main()
{
	ll n,m;
	scanf("%lld%lld",&n,&m);
	vector<int> nn[n+1];
	int t;
	for(t=0;t<m;t++)
	{
		int a,b;
		scanf("%d%d",&a,&b);
		nn[a].push_back(b);
		nn[b].push_back(a);
	}
	if(playbfs(nn,n))
		printf("%lld\n",l*r-m);
	else
		printf("%lld\n",n*(n-1)/2-m);
	return 0;
}

