template <typename T>
struct WeightedGraph
{
    int n;
    vector<vector<Edge<T>>> g;

    WeightedGraph(int n) : n(n){
        g.resize(n);
    }

    void init(int n_){
        n = n_;
        g.resize(n_);
    }

    void add_edge(int from, int to, T cost){
        g[from].push_back((Edge<T>){to, cost});
    }
};

struct Graph
{
    int n;
    vector<vector<int>> g;

    Graph(int n) : n(n){
        g.resize(n);
    }

    void init(int n_){
        n = n_;
        g.resize(n_);
    }

    void add_edge(int from, int to){
        g[from].push_back(to);
    }
};

int main()
{
    ll n, m;
    cin >> n >> m;
