int N, M;
vector<vector<int>> G;
struct item
{
  int oore;
  int dist;
  int id;

  bool operator<(const struct item &other) const
  {
    return dist > other.dist;
  }
};

signed main()
{
  IOS; /* making cin faster */
  SCAND2(N, M);
  G.resize(N);
  REP(_, M)
  {
    int u, v;
    SCAND2(u, v);
    --u;
    --v;
    G[u].push_back(v);
    G[v].push_back(u);
  }

  vector<vector<int>> d(2, vector<int>(N, INF));
  vector<vector<bool>> used(2, vector<bool>(N, false));
  d[0][0] = 0;
  d[1][0] = -1;

  priority_queue<item> pq;
  pq.push({0, 0, 0});

  while (not pq.empty())
  {
    item r = pq.top();
    pq.pop();

    if (d[r.oore][r.id] < r.dist)
    {
      continue;
    }

    used[r.oore][r.id] = true;

    for (auto v : G[r.id])
    {
      int oore_new = r.oore ^ 1;

      if (not used[oore_new][v] and d[r.oore][r.id] + 1 < d[oore_new][v])
      {
        d[oore_new][v] = d[r.oore][r.id] + 1;
        pq.push({oore_new, d[oore_new][v], v});
      }
    }
  }

  vector<int> nums0;
  set<int> st1;

  REP(i, N)
  {
    if (0 <= d[0][i] and d[0][i] < INF)
    {
      nums0.push_back(i);
    }

    if (0 <= d[1][i] and d[1][i] < INF)
    {
      st1.insert(i);
    }
  }

  lli ans = -M;
  for (auto elem : nums0)
  {
    ans += SIZ(st1);
    if (0 < st1.count(elem))
    {
      --ans;
    }
  }

  PRINTLLD(ans);
}

