bool paint(int pos, const Graph &G, vector<int> &col, int color) {
	if (col[pos] == 1 - color) {
		return false;
	}
	col[pos] = color;
	for (Edge e : G[pos]) {
		int to = e.to;
		if (col[to] == -1) {
			if (!paint(to, G, col, 1 - color)) {
				return false;
			}
		}
		else {
			if (col[to] == color) {
				return false;
			}
		}
	}
	return true;
}

