bool is_graph(int v, const Graph &G, vector<int> &seen, int flag)
{
  if (seen[v] > 0)
    return seen[v] == flag;
  else
    seen[v] = flag;

  for (auto g : G[v])
  {
    if (flag == 2)
    {
      if (!is_graph(g, G, seen, 1))
        return false;
    }
    else
    {
      if (!is_graph(g, G, seen, 2))
        return false;
    }
  }
  return true;
}
