bool checkBipartite(Graph &g, int n){
    vector<int> color(n, -1);
    queue<pair<int, int>> que;
    // snd -> 0 or 1
    que.push(make_pair(0, 0));
    bool ret = true;
    while(!que.empty() && ret){
        auto p = que.front();
        int node = p.fst;
        int node_color = p.snd;
        color[node] = node_color;
        //debugpair(node, node_color);
        que.pop();
        for (int i=0; i<(int)g[node].size(); ++i){
            auto next = g[node][i].dst;
            if(color[next] == -1){
                que.push(make_pair(next, (node_color + 1) % 2));
            }
            else if(color[next] == 0 && node_color == 0){
                ret = false;
                break;
            }
            else if(color[next] == 1 && node_color == 1){
                ret = false;
                break;
            }
        }
    }
    if(ret){
        for (int i=0; i<n; ++i){
            if(color[i] == 0){
                color1++;
            }
            else {
                color2++;
            }
        }
    }
    return ret;
}

