using namespace std;


struct Node{
    ll sink;
    ll pos;
    ll cost;
    bool operator< (const Node &r) const{
        if(cost != r.cost)  return cost < r.cost;
        if(sink != r.sink)  return sink < r.sink;
        return pos < r.pos;
    }
};

int main(){
    ll n, m;
    cin >> n >> m;
    vector<ll> a(m);
    vector<ll> b(m);
    rep(i, m)   cin >> a[i] >> b[i];

    set<ll> g[n];
    rep(i, m){
        g[a[i]-1].insert(b[i]-1);
        g[b[i]-1].insert(a[i]-1);
    }

    priority_queue<Node> que;
    rep(i, n)   que.push({i, i, 0});

    while(!que.empty()){
        Node node = que.top(); que.pop();

        if(3 < node.cost)   continue;
        if(node.cost == 3){
            if(g[node.sink].count(node.pos) == 0){
                que.push({node.pos, node.sink, 1});
                que.push({node.sink, node.pos, 1});
                for(auto to : g[node.pos])  que.push({to, node.sink, 2});
                for(auto to : g[node.sink]) que.push({to, node.pos, 2});

                g[node.sink].insert(node.pos);
                g[node.pos].insert(node.sink);
            }
            continue;
        }

        for(auto to : g[node.pos]){
            if(to != node.sink) que.push({node.sink, to, node.cost+1});
        }
    }


    ll cnt = 0;
    rep(i, n)   cnt += g[i].size();

    cout << cnt/2 - m << endl;


    return 0;
}

