vector<int> bipartite(vector<pair<int,int>> edge){
    int M = edge.size();
    if(M==0)return {};
    int N = 0;
    for(int i=0;i<M;i++){
        N=max(N,edge[i].first+1);
        N=max(N,edge[i].second+1);
    }
    vector<int> R(N,-1);
    vector<int> S(N,0);
    vector<vector<int>> G(N,vector<int>(0));
    for(int i=0;i<M;i++){
        G[edge[i].first].push_back(edge[i].second);
        G[edge[i].second].push_back(edge[i].first);
    }
    //cout << N << " " << M << endl;
    //REP(i,N){REP(j,G[i].size()){cout << G[i][j]+1 << " ";}cout << endl;}
    queue<int> Q;
    for(int j=0;j<N;j++){
        if(R[j]!=-1)continue;
        Q.push(j);
        R[j]=0;
        while(!Q.empty()){
            int q=Q.front();
            Q.pop();
            for(int i=0;i<G[q].size();i++){
                if(R[G[q][i]]==R[q]){
                    return S;
                }
                if(R[G[q][i]]!=-1)continue;
                Q.push(G[q][i]);
                R[G[q][i]]=R[q]^1;
            }

        }
    }
    return R;
}

