using namespace std;

struct UF {
	vector<int> belong;
	vector<int> size;
	void resize(int n) {
		belong.assign(n + 1, -1);
		size.assign(n + 1, 1);
	}
	inline int root(int b) {
		if (belong[b] == -1) {
			return b;
		}
		belong[b] = root(belong[b]);
		return belong[b];
	}
	void merge(int a, int b) {
		a = root(a);
		b = root(b);
		if (a == b)return;
		belong[a] = b;
		size[b] += size[a];
	}
};
UF uf;
#define MAX 100002
int col[MAX];
vector<int> v[MAX];

int ed ;
inline bool dfs(int b,int c,int pr=-1) {
	if (col[b] != -1) {
		if (col[b] == c) {
			return true;
		}
		return false;
	}
	col[b] = c;
	bool ok = true;
	for (int go : v[b]) {
		if (pr == go)continue;
		ok&=dfs(go, c ^ true, b);
		ed++;
	}
	return ok;
}

int main() {
	memset(col, -1, sizeof(col));
	int n;
	int m;
	scanf("%d%d", &n, &m);
	uf.resize(n);
	for (int i = 0; i < m; i++) {
		int a, b;
		scanf("%d%d", &a, &b);
		a--;
		b--;
		uf.merge(a, b);
		v[a].push_back(b);
		v[b].push_back(a);
	}
	long long int way = 0;
	for (int i = 0; i < n; i++) {
		ed = 0;
		if (uf.root(i) == i) {
			bool can=dfs(i,0);
			if (can == false) {
				long long int sz = uf.size[i];
				if (sz >= 3) {
					way += sz*(sz - 1) / 2LL;
				}
				else {
					way += ed;
				}
			}
			else {
				if (uf.size[i] >= 3) {
					long long int sz = uf.size[i];
					long long int f = sz / 2;
					long long int ff = sz - f;
					way += f*ff;
					continue;
					way += f*(f - 1) / 2LL;
					f = sz - (sz / 2);
					way += f*(f - 1) / 2LL;
					way += ed;
				}
				else {
					way += ed;
				}
			}
		}
	}
	way -= m;
	printf("%lld\n", way);
	return 0;
}

