class UnionFind {
public:
    vector<int> parent;
    UnionFind(int n) {
        parent.resize(n);
        REP(i, 0, n) parent[i] = i;
    }
    int Find(int a) {
        return (a == parent[a] ? a : parent[a] = Find(parent[a]));
    }
    bool isSame(int a, int b) {
        return Find(a) == Find(b);
    }
    bool Union(int a, int b) {
        if (isSame(a, b)) return false;
        int pa = Find(a);
        int pb = Find(b);
        parent[pa] = pb;
        return true;
    }
};

