    int sz;
	public:
    UF(int sz):sz(sz){data.resize(sz,-1);}
    bool unite(int x,int y){
        x=root(x);y=root(y);
        if(x==y)return 0;
        if(data[x]>data[y])swap(x,y);
		data[x]+=data[y];
		data[y]=x;
		sz--;
        return 1;
    }
    inline int root(int x){return data[x]<0?x:data[x]=root(data[x]);}
    inline bool same(int x, int y){return root(x)==root(y);}
    inline int size(){return sz;}
	inline int size(int x){return -data[root(x)];}
};

int main(){
    lint n,m;
    cin>>n>>m;
    UF uf(n*2);
    rep(i,m){
        lint s,t;
        cin>>s>>t;
        s--;t--;
        uf.unite(s,t+n);
        uf.unite(s+n,t);
    }
    lint cnt=0;
    rep(i,n){
        if(uf.same(i,i+n)){
            cout<<n*(n-1)/2-m<<endl;
            return 0;
        }else{
            cnt+=uf.same(0,i);
        }
    }
    cout<<cnt*(n-cnt)-m<<endl;
}

