void solve(istream& cin, ostream& cout) {
  l n, m; cin >> n >> m;
  Graph g(n);
  F(i, 0, m) {
    l a, b; cin >> a >> b; a--; b--;
    g.add_undirected(a, b);
  }
  bool bipartite = true;
  vl c(n, -1);
  c[0] = 0;
  queue<l> q;
  q.emplace(0);
  l white = 0;
  while (not q.empty()) {
    auto a = q.front(); q.pop();
    if (c[a]) white++;
    l t = 1 - c[a];
    for (auto e : g.adj[a]) {
      if (c[e.to] == -1) {
        c[e.to] = t;
        q.emplace(e.to);
        continue;
      }
      bipartite = bipartite and c[e.to] == t;
    }
  }
  if (L(bipartite)) {
    cout << (white * (n - white) - m) << lf;
  } else {
    cout << (n * (n - 1) / 2 - m) << lf;
  }
}

