int main(void) {
  long N, M;
  cin >> N >> M;

  unordered_map<long, vector<long> > data;

  for (long i = 0; i < M; i++) {
    long A, B;
    cin >> A >> B;
    data[A].push_back(B);
    data[B].push_back(A);
  }

  queue<long> todo;
  unordered_map<long, long> hops;
  bool is_nibu_graph = true;

  todo.push(1);
  hops[1] = 1;

  while (is_nibu_graph and !todo.empty()) {
    long now = todo.front();
    todo.pop();
    long next_hop = hops[now] + 1;
    for (long next_node: data[now]) {
      if (hops[next_node] == 0) {
        hops[next_node] = next_hop;
        todo.push(next_node);
        continue;
      }
      if ((next_hop - hops[next_node]) % 2 == 0) {
        continue;
      }
      is_nibu_graph = false;
      break;
    }
  }

  if (is_nibu_graph) {
    long odd = 0;
    for (auto it = hops.begin(); it != hops.end(); it++) {
      if (it->second % 2 == 1) odd++;
    }
    long even = N - odd;
    cout << (odd * even) - M << endl;
  } else {
    cout << N * (N-1) / 2 - M << endl;
  }

  return 0;
}

