// 頂点sと頂点tの間に長さkの奇数長パスが存在すると必ずsとtの間に辺が張られることを示す。
// i番目に通る頂点をv_iとする。
// k = 1 の場合すでに辺がある。
// k >= 3 の場合v_(k-3)とv_kの間に辺を張ることができ、
// 長さk-2奇数長のs-tパスを得ることができる。
// これを繰り返して長さ3になったとき辺を張ることができる。
// よって、ある２頂点間に奇数長パスがあれば辺を張れることが示された。

int main() {
    ll n, m;
    cin >> n >> m;    

    G.resize(n);
    rep(i, m) {
        ll a, b;
        cin >> a >> b;
        a--;  b--;
        G[a].pb(b);
        G[b].pb(a);
    }

    color.assign(n, -1);
    bool nibuGraph = true;
    rep(v, n) {
        if(color[v] != -1) {
            continue;
        }
        if(!dfs(v)) {
            nibuGraph = false;
        }
    }

    // 二部グラフの場合
    // 異なる頂点集合間の２頂点を結ぶパスは奇数長なのですべて辺を張ることができる。
    // 逆に、同じ頂点集合間の２頂点を結ぶパスは偶数長なので辺を張ることはできない。
    if(nibuGraph) {
        ll cntW = 0, cntB = 0;
        rep(v, n) {
            if(color[v] == 0) {
                cntW++;
            }
            else if(color[v] == 1) {
                cntB++;
            }
        }
        out(cntW*cntB - m);
        re0;
    }

    // 二部グラフでない場合
    // 「二部グラフ」 ⇔ 「奇数長サイクルが存在しない」 より
    // 「二部グラフでない」 ⇒ 「奇数長サイクルが存在」
    // あるs-tパスが偶数長だったとしても奇サイクルを用いて奇数長パスにできる
    // よって操作を続けると最終的に完全グラフにできる
    out(n*(n-1)/2 - m);
    re0;
}

