using namespace std;

class UF {
public:
	vector<int> rank;
	vector<int> p;

	UF() {}
	UF(int size) {
		rank.resize(size, 0);
		p.resize(size, 0);
		for (int i = 0;i < size;i++) makeSet(i);
	}

	void makeSet(int x) {
		p[x] = x;
		rank[x] = 0;
	}

	bool same(int x, int y) {
		return findSet(x) == findSet(y);
	}

	void unite(int x, int y) {
		link(findSet(x), findSet(y));
	}

	void link(int x, int y) {
		if (rank[x] > rank[y]) {
			p[y] = x;
		}
		else {
			p[x] = y;
			if (rank[x] == rank[y]) {
				rank[y]++;
			}
		}
	}

	int findSet(int x) {
		if (x != p[x]) {
			p[x] = findSet(p[x]);
		}
		return p[x];
	}
};

int num(int a) {
	int tmp = 0;

	tmp = a * (2 + (a - 1)) / 2;


	return tmp;

}

signed main() {
	int N, M;
	cin >> N >> M;

	UF load(N);

	int ans = 0;
	for (int i = 0;i < M;i++) {
		int p, q;
		cin >> p >> q;
		p--; q--;//0-indexed

		if (load.findSet(p) == load.findSet(q)) ans--;
		load.unite(p, q);
	}


	map<int, int> mp;
	for (int i = 0;i < N;i++) {
		mp[load.findSet(i)]++;
	}

	for (auto k: mp) {
		if (k.second <= 3) {
			continue;
		}
		else if (k.second == 4) {
			ans++;
		}
		else if (k.second % 2 == 0) {
			ans += num(k.second / 2) * 2 - k.second / 2 - k.second + 1;
		}
		else {
			ans += num(k.second - 1) - k.second + 1;
		}
		//cout << ans << endl;
	}

	cout << ans << endl;
	return 0;
}

