using namespace std;

int is_bipartite(const vector<vector<int>> &adj_lists, int cur,
                 vector<int> &gs) {
  int ret = 1;
  for (int nxt : adj_lists[cur]) {
    if (gs[nxt] == 0) {
      gs[nxt] = -gs[cur];
      if (!is_bipartite(adj_lists, nxt, gs)) {
        ret = 0;
        break;
      }
    } else {
      if (gs[nxt] == gs[cur]) {
        ret = 0;
        break;
      }
    }
  }
  return ret;
}

