void BFS(){
    queue<int> Q;
    dis[0]=0;
    Q.push(0);
    while(!Q.empty()){
        int a=Q.front();
        Q.pop();
        for(int i=0;i<S[a].size();i++){
            int b=S[a][i];
            if(dis[b]!=-1) continue;
            dis[b]=dis[a]+1;
            Q.push(b);
        }
    }
}


