/* is_bipartite.cpp
    二部グラフ判定を深さ優先探索（DFS）で行う

    not verified: AtCoder CODE FESTIVAL 2017 qual B  C - 3 Steps
        https://code-festival-2017-qualb.contest.atcoder.jp/tasks/code_festival_2017_qualb_c
*/
#include <bits/stdc++.h>
using namespace std;

struct Edge {
    long long to;
};
using Graph = vector<vector<Edge>>;

bool dfs(const Graph &G, int v, int c, pair<int, int> &num, vector<int> &color) {
    bool ret = true;
    color[v] = c;
    if (c == 1) {
        num.first++;
    } else if (c == -1) {
        num.second++;
    }
    for (auto e : G[v]) {
        if (color[e.to] == 0 && !dfs(G, e.to, -c, num, color)) {
            ret = false;
        } else if (color[e.to] == c) {
            ret = false;
        }
    }
    return ret;
}

/* is_bipartite(G,nums): 二部グラフかどうか
 nums[i] := i 番目の連結成分の {左ノード数, 右ノード数}, 「dir = 1: 左、-1: 右」
*/
int is_bipartite(const Graph &G, vector<pair<int, int>> &nums) {
    bool ret = true;
    int N = G.size();
    vector<int> color(N, 0);
    for (int i = 0; i < N; i++) {
        if (color[i] == 0) {
            pair<int, int> num = {0, 0};
            if (!dfs(G, i, 1, num, color)) {
                ret = false;
            }
            nums.push_back(num);
        }
    }
    return ret;
}

int main() {
    int N, M;
    cin >> N >> M;
    Graph G(N);
    for (int i = 0; i < M; i++) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        G[a].push_back({b});
        G[b].push_back({a});
    }

    vector<pair<int, int>> nums;
    if (is_bipartite(G, nums)) { // 完全二部グラフ
        /*for (auto i : nums) {
            cout << "left:" << i.first << " right:" << i.second << endl;
        }*/
        cout << (N / 2) * ((N + 1) / 2) - M << endl;
    } else { // 完全グラフ
        cout << N * (N - 1) / 2 - M << endl;
    }
    return 0;
}

