        if (dep % 2) d[k] = 1;
        else d[k] = 2;
    }
    for (auto &i : G[k]) {
        if (!vis[i]) {
            dfs(i, dep + 1);
        }
        else if (d[i] % 2 == dep % 2) {
            dual = 0;
            return;
        }
    }
}

int main() {
    ll n, m;
    cin >> n >> m;
    int x[m], y[m];
    vis.assign(n, 0);
    for (int i = 0; i < m; i++) {
        cin >> x[i] >> y[i];
        x[i]--;  y[i]--;
        G[x[i]].push_back(y[i]);
        G[y[i]].push_back(x[i]);
    }

    dfs(0, 0);
    if (dual) {
        ll p = 0, q = 0;
        for (int i = 0; i < n; i++) {
            if (d[i] == 1) p++;
            else q++;
        }
        ll ans = p * q;
        for (int i = 0; i < m; i++) {
            if (d[x[i]] != d[y[i]]) ans--;
        }
        cout << ans << endl;
    }
    else {
        cerr << 0 << endl;
        cout << n * (n - 1) / 2 - m << endl;
    }
}

