int hantei(vector<int> &c,vector<pair<int,int>> p) {
  int result=0;
  for (pair<int,int> x:p) {
    int a=x.first;int b=x.second;
    if (c[a]==c[b])  {
      result=-1;
      break;
    }
  }
  if (result!=-1) {
    int a,b;
    for (int i=0;i<N;i++) {
      if (c[i]==1) a++;
      else if(c[i]==2) b++;
    }
    result=a*b;
  }
  return result;
}

