bool is2graph_dfs(Graph<V, E>& G, int pos, int par = -1, int color = 1)
{
	if (par == -1) {
		if (G.v[pos].color) return true;
	}
	if (G.v[pos].color && G.v[pos].color != color) return false;
	if (G.v[pos].color) return true;
