int n, m;
int pairU[N], pairV[N];
int dist[N];

vector < int > g[N];

int bfs(){
    queue < int > Q;
    for(int i = 1; i <= n; i++){
        if(pairU[i] == 0){
            Q.push(i); dist[i] = 0;
        }else {
            dist[i] = INF;
        }
    }
    dist[0] = INF;
    while(!Q.empty()){
        int u = Q.front(); Q.pop();
        if(dist[u] < dist[0]){
            for(int i = 0; i < g[u].size(); i++){
                int v = g[u][i];
                if(dist[pairV[v]] == INF){
                    dist[pairV[v]] = dist[u] + 1;
                    Q.push(pairV[v]);
                }
            }
        }
    }
    return (dist[0] != INF);
}

int dfs(int u){
    if(u){
        for(int i = 0; i < g[u].size(); i++){
            int v = g[u][i];
            if(dist[pairV[v]] == dist[u] + 1){
                if(dfs(pairV[v])){
                    pairU[u] = v;
                    pairV[v] = u;
                    return 1;
                }
            }
        }
        dist[u] = INF;
        return 0;
    }
    return 1;
}

int HopCroft_Karp(){
    int matching = 0;
    memset(pairU, 0, sizeof pairU);
    memset(pairV, 0, sizeof pairV);
    while(bfs()){
        for(int i = 1; i <= n; i++){
            if(pairU[i] == 0){
                if(dfs(i)) matching++;
                else return 0;
            }
        }
    }
    return matching;
}

