    for(int i = 1; i <= m; i++){
        int u, v;
        fastScan(u); fastScan(v);
        g[u].pb(v); g[v].pb(u);
    }
    int bipart = HopCroft_Karp();
    if(bipart){
        ll lft = bipart / 2, rgt = n - (bipart / 2);
        ll ans = lft * rgt - m;
        printf("%lld\n", ans);
    }else {
        ll ans = 1ll * n * (n - 1);
        ans /= 2;
        ans -= m;
        printf("%lld\n", ans);
    }
}

