bool isBipartite(vvi& graph, int n, int cl = 0) {
    color[n] = cl;
    for (auto x : graph[n]) {
        if (color[x] != -1) {
            if (color[x] == cl) return false;
            continue;
        }
        if (!isBipartite(graph, x, 1 - cl)) return false;
    }
    return true;
}

