			merge(v[i][j], v[i][j - 1]);
	}
	for (int i = 1; i <= n; ++i) {
		fa[i] = find_root(i);
		vf[fa[i]].push_back(i);
	}
	for (int i = 1; i <= n; ++i)
		if (fa[i] == i) {
			set <int> s;
			for (auto k : vf[i])
				for (auto j : v[k])
					s.insert(j);
