	cin.tie(0);
	ios::sync_with_stdio(false);

	vector<int> dist(100001, -1),a(100001),b(100001);
	vector<int> tree[100001];
	int n, m; cin >> n >> m;
	for (int i = 0; i < m; i++) {
		cin >> a[i] >> b[i];
		a[i]--; b[i]--;
		tree[a[i]].push_back(b[i]);
		tree[b[i]].push_back(a[i]);
	}
	dist[0] = 0;
	queue<int> q;
	q.push(0);//点、距離
	while (!q.empty()) {
		int v = q.front(); q.pop();
		for (int i = 0; i < (int)tree[v].size(); i++) {
			int next = tree[v][i];
			if (dist[next] == -1) {
				dist[next] = dist[v] + 1;
				q.push(next);
			}
		}
	}
	int odd = 0, even = 0;
	for (int i = 0; i < n; i++) {
		if (dist[i] % 2 == 0) even++;
		else odd++;
	}
	bool flag = false;
	for (int i = 0; i < m; i++) if (dist[a[i]] % 2 != dist[b[i]] % 2) flag = true;
	if (flag) cout << n*(n-1)/2 - m << endl;
	else cout << odd*even - m << endl;
	return 0;
}

