	vector<int> dist(n, -1);
	vector<vector<int> > tree(n);
	for (int i = 0; i < m; i++) {
		int a, b; cin >> a >> b;
		a--; b--;
		tree[a].push_back(b);
		tree[b].push_back(a);
	}
	dist[0] = 0;
	queue<int> q;
	bool flag = false;
	q.push(0);//点、距離
	while (!q.empty()) {
		int v = q.front(); q.pop();
		for (int i = 0; i < (int)tree[v].size(); i++) {
			int next = tree[v][i];
			if (dist[next] == -1) {
				dist[next] = 1-dist[v];
				q.push(next);
			}
			else if(dist[next]==1-dist[v]){
				continue;
			}
			else {
				flag = true;
				break;
			}
		}
	}
	int cnt=0;
	for (int i = 0; i < n; i++) {
		cnt += dist[i];
	}
	if (flag) cout << n*(n - 1) / 2 - m << endl;
	else cout << cnt*(n-cnt) - m << endl;
	return 0;
}

