int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll n,m;cin>>n>>m;
    Graph g(n);
    for(int i=0;i<m;i++){
        int a,b;cin>>a>>b;a--;b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }
    vector<int> v(n,-1); // -1:not visited
    ll res=n*(n-1)/2-m;
    bool f = true;
    queue<int> q;
    v[0]=0;
    q.push(0);
    while(!q.empty()){
        int p=q.front();q.pop();
        int col=v[p];
        for(int i=0;i<(int)g[p].size();i++){
            int next=g[p][i];
            if(v[next]==-1){
                v[next]=1-col;
                q.push(next);
            }
            else if(v[next]+col==1) continue;
            else{
                f=false;
            }
        }
    }
    if(!f){
        cout<<res<<endl;
        return 0;
    }
    ll cnt=0;
    for(int i=0;i<n;i++) if(v[i]) cnt++;
    //cout<<cnt<<endl;
    res -= cnt*(cnt-1)/2;
    cnt = n-cnt;
    res -= cnt*(cnt-1)/2;
    cout<<res<<endl;
}

