const int MAXN=1e5+5,MAXM=1e7+5;
int n,m,ans,s;
int he[MAXN];
bool cannt[MAXN],vis[MAXN];

struct line{int to,nex;}ed[MAXM<<1];

inline void addE(int u,int v){
	static int cnt=0;
	ed[++cnt]=(line){v,he[u]};
	he[u]=cnt;
}

void DFS(int u,int dis){
	if(dis==3){
		if(cannt[u]) return;
		addE(s,u),addE(u,s);
		cannt[u]=true;
		++ans;
		return;
	}
	vis[u]=true;
	for(int i=he[u],v;i;i=ed[i].nex){
		v=ed[i].to;
		if(!vis[v]) DFS(v,dis+1);
	}
	vis[u]=false;
}

int main(){
	scanf("%d%d",&n,&m);
	for(int i=1,u,v;i<=m;++i){
		scanf("%d%d",&u,&v);
		addE(u,v),addE(v,u);
	}
	for(int i=1;i<=n;++i){
		memset(vis,false,sizeof(vis));
		memset(cannt,false,sizeof(cannt));
		for(int j=he[i];j;j=ed[j].nex)
			cannt[ed[j].to]=true;
		s=i,DFS(i,0);
	}
	printf("%d",ans);
	return 0;
}

