bool Dwu(vector< vector<int> >& G)
{
    vector<bool> odw(n, false);
    stack<int> S;
    vector<int> col(n, -1);
    odw[0] = true;
    S.push(0);
    col[0] = 0;
    while (!S.empty())
    {
        int akt = S.top();
        S.pop();
        for (int i = 0; i < G[akt].size(); ++i)
        {
            if (!odw[G[akt][i]])
            {
                odw[G[akt][i]] = true;
                S.push(G[akt][i]);
                if (col[akt] == 0)
                    col[G[akt][i]] = 1;
                else
                    col[G[akt][i]] = 0;
            }
        }
    }
    for (int i = 0; i < n; ++i)
    {
        for (int j = 0; j < G[i].size(); ++j)
        {
            if (col[i] == col[G[i][j]])
                return false;
        }
    }
    return true;
}

