using namespace std;

int N, M;
vector<vector<int>> m, tmp;

void show_matrix(vector<vector<int>> m){
  for(int i = 0; i < N; i++){
    for(int j = 0; j < N; j++){
      if(j ==  N-1){
        cout << m[i][j] << endl;
      }else{
        cout << m[i][j] << " ";
      }
    }
  }
  return;
}

vector<vector<int>> cubed(vector<vector<int>> m){
  vector<vector<int>> res1(N), res2(N);
  for(int i = 0; i < N; i++){
    res1[i].resize(N, 0);
    res2[i].resize(N, 0);
  }
  // 二乗
  for(int i = 0; i < N; i++){
    for( int j = 0; j < N; j++){
      for(int h = 0; h < N; h++){
        res1[i][j] += m[i][h] * m[h][j];
      }
    }
  }
  // ３乗
  for(int i = 0; i < N; i++){
    for( int j = 0; j < N; j++){
      for(int h = 0; h < N; h++){
        res2[i][j] += res1[i][h] * m[h][j];
      }
    }
  }
  return res2;
}

vector<vector<int>> matrix_norm(vector<vector<int>> m){
  vector<vector<int>> t(N);
  for(int i = 0; i < N; i++){
    t[i].resize(N, 0);
  }
  for(int i = 0; i < N; i++){
    for(int j = 0; j < i; j++){
      if(m[i][j] != 0){
        t[i][j] = 1;
        t[j][i] = 1;
      }
    }
  }
  return t;
}

int count_path(vector<vector<int>> m){
  // normalized vector m
  int c = 0;
  for(int i = 0; i < N; i++){
    for(int j = 0; j < i; j++){
      c += m[i][j];
    }
  }
  return c;
}


int main(int argc, char *argv[]){
  // 遷移行列を作り、それを三回かけて行ける場所をつなぐ。
  cin >> N >> M;
  //vector<vector<int>> m(N), tmp(N);
  m.resize(N);
  tmp.resize(N);
  for(int i = 0; i < N; i++){
    m[i].resize(N, 0);
    tmp[i].resize(N, 0);
  }
  int a, b;
  for(int i = 0; i < M; i++){
    cin >> a >> b;
    a--;
    b--;
    m[a][b] = 1;
    m[b][a] = 1;
  }

  //show_matrix(m);
  tmp = cubed(m);


  int new_pathes, curr_pathes = count_path(m);
  int new_bridges = 0;
  int dis;
  //printf("debug in front of do-while\n");
  do {
    tmp = cubed(m); // ３乗
    tmp = matrix_norm(tmp); // 正規化
    //show_matrix(tmp);
    new_pathes = count_path(tmp); // count
    dis = new_pathes - curr_pathes;
    new_bridges += dis;

    //後処理（次回のため）
    m = tmp;
    curr_pathes = new_pathes;
    /* code */
    //printf("dis = %d\n", dis);
  } while(dis > 0);

  cout << new_bridges << endl;

  return 0;
}

