	for (int i = 0; i < m; i++) {
		int a, b;
		scanf("%d%d", &a, &b);
		a--;
		b--;
		uf.merge(a, b);
		v[a].push_back(b);
		v[b].push_back(a);
	}
	long long int way = 0;
	for (int i = 0; i < n; i++) {
		ed = 0;
		if (uf.root(i) == i) {
			bool can=dfs(i,0);
			if (can == false) {
				long long int sz = uf.size[i];
				if (1/*sz >= 3*/) {
					way += sz*(sz - 1) / 2LL;
				}
			}
			else {
				if (1/*uf.size[i] >= 3*/) {
					long long int sz = uf.size[i];
					long long int f = sz / 2;
					long long int ff = sz - f;
					way += f*ff;
					continue;
					way += f*(f - 1) / 2LL;
					f = sz - (sz / 2);
					way += f*(f - 1) / 2LL;
					way += ed;
				}
			}
		}
	}
	way -= m;
	printf("%lld\n", way);
	return 0;
}

