struct UnionFind{
private:
    vector<int> par;
    vector<int> rank;
public:
    UnionFind(int n){
        par.resize(n);
        rank.resize(n);
        for (int i=0;i<n;i++){
            par[i]=i;
            rank[i]=0;
        }
    }
    int root(int x){
        if(par[x]==x)return x;
        else return par[x]=root(par[x]);
    }
    bool issame(int x,int y){
        return root(x)==root(y);
    }
    bool merge(int x,int y){
        x=root(x);
        y=root(y);
        if(x==y)return false;
        if(rank[x]<rank[y])swap(x,y);
        if(rank[x]==rank[y])++rank[x];
        par[y]=x;
        return true;
    }
};

int main(){
    ll n,m;
    cin>>n>>m;
    UnionFind uf(2*n);
    for(int i=0;i<m;i++){
        int a,b;
        cin>>a>>b;
        --a,--b;
        uf.merge(a,b+n);
        uf.merge(a+n,b);
    }
    bool b=true;
    for(int i=0;i<n;i++){
        if(uf.issame(i,i+n)){
            b=false;
            break;
        }
    }
    if(b){
        int par=uf.root(0);
        ll cnt=0;
        for(int i=0;i<n;i++){
            if(uf.root(i)==par)++cnt;
        }
        cout<<cnt*(n-cnt)-m<<endl;
    }
    else{
        cout<<n*(n-1)/2-m<<endl;
    }
}

