using namespace std;
const int MAX = 1e5+10;
const int WHITE = 0;

//int list[MAX][MAX];
//int color[MAX];
int N, M;

bool bi_partite(int s, int c, vector<vector<int> > &list, vector<int> &color){
    stack<pair<int,int> > S;
    S.push(make_pair(s, c));
    color[s] = c;

    while(!S.empty()){
        int u, c_u;
        tie(u, c_u) = S.top(); S.pop();
        color[u] = c_u;

        for(int j=0;j<list[u].size();j++){
            int v = list[u][j];
            if(color[v] == c_u) return false;
            if(color[v] == WHITE){
                S.push(make_pair(v, -c_u));
            }
        }
    }
    return true;
}

int main(){
    cin >> N >> M;
    vector<vector<int> > list(N,vector<int>());
    vector<int> color(N,WHITE);
    for(int i=0;i<M;i++){
        int a,b;
        cin >> a >> b;
        a--; b--;
        list[a].push_back(b);
        list[b].push_back(a);
    }
    bool flag = bi_partite(0,1,list, color);
    if(!flag){
        cout << N*(N-1)/2 - M << endl;
    }else{
        long long count_b = 0;//, count_w = 0;
        for(int i=0;i<N;i++){
            if(color[i] == 1) count_b++;
            //else if(color[i] == -1) count_w++;
        }
        cout << count_b * (N - count_b) - M << endl;
    }

    return 0;
}

#include<bits/stdc++.h>
