typedef long long ll;

struct node{
	int v, nxt;
}edge[200050];

ll b[100050], cntt[2], cnt3, flag/*有无奇环*/, cnt, head[100050], flag2/*有无环*/;

void add(int u, int v){
	edge[++cnt] = (node){v, head[u]};
	head[u] = cnt;
}

void dfs(int u, int fa){
	cnt3++;
	for(int i = head[u]; i; i = edge[i].nxt){
		int v = edge[i].v;
		if(v == fa) continue;
		if(b[v]!=-1) {
			flag2 = 1;
			if(!flag && b[v] == b[u]) flag = 1;
			continue;
		}
		b[v] = b[u] ^ 1;
		cntt[b[v]]++;
		dfs(v, u);
	}
}

int main(){
	int n, m;
	scanf("%d %d", &n, &m);
	for(int i = 1; i <= m; i++) {
		int a, b;
		scanf("%d %d", &a, &b);
		add(a, b), add(b, a);
	}
	ll ans = 0;
	memset(b, -1, sizeof(b));
	for(int i = 1; i <= n; i++) if(b[i]==-1) {
		b[i] = 1;
		cnt3 = cntt[0] = 0;
		cntt[1] = 1; flag = 0, flag2 = 0;
		dfs(i, 0);
		if(flag2){
			if(flag == 1) ans += (cnt3 * (cnt3-1)) >> 1;
			else ans += cntt[1] * cntt[0];
		}
		else {
			ans += cnt3-1;
			if(cnt3 >= 3){
				ll p1 = ((cnt3-4)>>1) + 1;
				ll t = ((p1+1) * p1)>>1;
				if(cnt3&1) ans += 2*t;
				else ans += 2*t-p1;
			}
		}
	}
	printf("%lld", ans-m);
}

