class Solver {
  public:
    int N, M;
    vector<vector<int>> E;
    set<int> go2(int now) {
        set<int> a;
        for(int nxt : E[now]) a.insert(nxt);
        set<int> res;
        for(int i : a) {
            for(int nxt : E[i]) res.insert(nxt);
        }
        return res;
    }
    int go(int now) {
        int res = 0;
        set<int> nexts;
        queue<int> que;
        for(int nxt : E[now]) {
            nexts.insert(nxt);
            que.push(nxt);
        }
        while(que.size()) {
            int n = que.front(); que.pop();
            for(int nxt : E[n]) {
                for(int nxt2 : E[nxt]) {
                    if(now == nxt2 or nexts.count(nxt2)) continue;
                    if(not nexts.count(nxt2)) {
                        // cerr << now << " -> " << nxt2 << endl;
                        res++;
                        nexts.insert(nxt2);
                        E[now].push_back(nxt2);
                        E[nxt2].push_back(now);
                        que.push(nxt2);
                    }
                }
            }
        }
        return res;
    }
    bool solve() {
        cin >> N >> M;
        E.resize(N);       
        rep(i, M) {
            int a, b; cin >> a >> b;
            a--; b--;
            E[a].push_back(b);
            E[b].push_back(a);
        }        
        vector<int> visited(N);
        int ans = 0;
        rep(i, N) {
            ans += go(i);
        }
        cout << ans << endl;        
        return 0;
    }
};

