void Ssort(int no, char *month[]){
    int i, j;
    char *temp;
    for(i=0; i<no; i++){
        for(j=i+1; j<no; j++){
            if(strcmp((month[i]),(month[j]))>0){
                temp = *(month+i);
                *(month+i) = *(month+j);
                *(month+j) = temp;
            }
        }    
    }
}

