class ListG {
public:
    // there's directed edge between A and B
    // if to[A] has element B
    vector<vector<int>> to; 

    map<pair<int, int>, ll> cost;
    void setCost(int u, int v, ll c) { 
        cost[{min(u, v), max(u, v)}] = c;
    }
    ll getCost(int u, int v) {
        return cost[{min(u, v), max(u, v)}];
    }

    ListG(int s) : root(-1) {
        size = s;
        to = make_v<vector<int>>(size);
    }

    void setDirectedEdge(int f, int t) {
        to[f].push_back(t);
    }
    void setIndirectedEdge(int v1, int v2) {
        setDirectedEdge(v1, v2);
        setDirectedEdge(v2, v1);
    }

    void readGraph(int edgeNum, bool directed = false) {
        REP(i, edgeNum) {
            int u, v; cin >> u >> v; u--, v--;
            if (directed)
                setDirectedEdge(u, v);
            else
                setIndirectedEdge(u, v);
        }
    }

    void dfs(vector<char> &visiting, vector<char> &visited, int current, vector<vector<int>> &cloop) {
        for (auto&& next : to[current]) {
            if (visited[next]) continue;
            if (visiting[next]) {
                cloop[current].push_back(next);
                visited[next] = 1;
                dfs(visiting, visited, next, cloop);
                visited[next] = 0;
            } else {
                visiting[next] = 1;
                dfs(visiting, visited, next, cloop);
                visiting[next] = 0;
            }
        }
    }

    // return max depth
    int makeTree(int r) {
        root = r;
        p = make_v<int>(size);
        p[root] = -1;
        depth = make_v<int>(size);
        int maxDepth = 0;
        makeFixPoint([&](auto rec, int c, int d) -> void {
            depth[c] = d;
            chmax(maxDepth, d);
            REP(i, to[c].size()) {
                int next = to[c][i];
                if (p[c] == next) continue;
                p[next] = c;
                rec(next, d + 1);
            }
        })(root, 0);
        // count leaf node
        auto idxs = make_v<int>(size);
        iota(all(idxs), 0);
        leaf_idx = set<int>(all(idxs));
        REP(i, size) {
            if (i == root) continue;
            leaf_idx.erase(p[i]);
        }
        return maxDepth;
    }

    pair<int, int> isBipartite() {
        auto color = make_v<int>(size);
        fill_v(color, 0);

        auto rec = makeFixPoint([&](auto rec, int v, int c) -> bool {
            color[v] = c;
            for (const auto& next : to[v]) {
                if (color[next] == c)
                    return false;
                if (color[next] == 0 and not rec(next, -c))
                    return false;
            }
            return true;
        });

        pair<int, int> ret = {-1, -1};
        REP(i, size) {
            if (color[i] == 0)
                if (not rec(i, 1))
                    return ret;
        }
        ret = {0, 0};
        REP(i, size) {
            if (color[i] > 0) ret.first++;
            else ret.second++;
        }
        return ret;
    }

    void makeEulerTour() {
        assert(root >= 0);
        et_begin = make_v<int>(size);
        et_end = make_v<int>(size);
        tmp_k = 0;
        etdfs(root, -1);
    }

    vector<vector<int>> children() {
        assert(root >= 0);
        auto ret = make_v<vector<int>>(size);
        REP(i, size) {
            int prt = p[i];
            if (prt == -1) continue;
            ret[prt].push_back(i);
        }
        return ret;
    }

    int stronglyConnectedConponent() {
        auto rto = make_v<vector<int>>(size);
        REP(from, size) {
            for (auto&& t : to[from])
                rto[t].push_back(from);
        }
        auto cmp = make_v<int>(size);
        fill_v(cmp, 0);
        auto used = make_v<char>(size);
        fill_v(used, 0);
        vector<int> rets; // return index in order
        REP(i, size) {
            makeFixPoint([&](auto dfs, int v) -> void {
                if (used[v]) return;
                used[v] = 1;
                for (auto&& t : to[v])
                    dfs(t);
                rets.push_back(v);
            })(i);
        }
        fill_v(used, 0);
        int ret = 0;
        REPR(i, rets.size()-1) {
            makeFixPoint([&](auto rdfs, int v, int k) -> void {
                if (used[v]) return;
                used[v] = 1;
                cmp[v] = k;
                for (auto&& rt : rto[v])
                        rdfs(rt, k);

                rets.push_back(v);
            })(rets[i], ret++);
        }
        return ret;
    }

    vector<int> topologicalSorted() {
        vector<int> ret;
        auto used = make_v<char>(size);
        fill_v(used, 0);
        REP(i, size) {
            makeFixPoint([&](auto dfs, int v) -> void {
                if (used[v]) return;
                used[v] = 1;
                for (auto&& t : to[v]) 
                    dfs(t);
                ret.push_back(v);
            })(i);
        }
        reverse(all(ret));
        return ret;
    }

    void dfsTree(ListG& dfst) {
        auto visited = make_v<char>(size);
        auto prt = make_v<int>(size);
        fill_v(visited, 0);
        fill_v(prt, 0);
        stack<int> st;
        st.push(0);
        while (st.size()) {
            int c = st.top(); st.pop();
            if (visited[c]) continue;
            visited[c] = 1;
            if (c != 0) dfst.setIndirectedEdge(c, prt[c]);
            for (const auto& next : to[c]) {
                prt[next] = c;
                st.push(next);
            }
        }
    }

    int size, root;
    vector<int> p; // parent for each node. parent of root = -1
    vector<int> depth; // for each node. depth of root node = 0
    vector<int> euler_tour;
    vector<int> et_begin, et_end;
    set<int> leaf_idx;

    int tmp_k;
private:
    void etdfs(int vidx, int pidx) {
        et_begin[vidx] = tmp_k;
        euler_tour.push_back(vidx);
        tmp_k++;
        REP(i, to[vidx].size()) {
            if (to[vidx][i] != pidx) {
                etdfs(to[vidx][i], vidx);
                euler_tour.push_back(vidx);
                tmp_k++;
            }
        }
        et_end[vidx] = tmp_k;
    }
};

