struct UnionFind {
  vector< int > data;

  UnionFind(int sz) {
    data.assign(sz, -1);
  }

  bool unite(int x, int y) {
    x = find(x), y = find(y);
    if(x == y) return (false);
    if(data[x] > data[y]) swap(x, y);
    data[x] += data[y];
    data[y] = x;
    return (true);
  }

  int find(int k) {
    if(data[k] < 0) return (k);
    return (data[k] = find(data[k]));
  }

  int size(int k) {
    return (-data[find(k)]);
  }
};

template< typename T >
struct edge {
  int src, to;
  T cost;

  edge(int to, T cost) : src(-1), to(to), cost(cost) {}

  edge(int src, int to, T cost) : src(src), to(to), cost(cost) {}

  edge &operator=(const int &x) {
    to = x;
    return *this;
  }

  operator int() const { return to; }
};

template< typename T >
using Edges = vector< edge< T > >;
template< typename T >
using WeightedGraph = vector< Edges< T > >;
using UnWeightedGraph = vector< vector< int > >;
template< typename T >
using Matrix = vector< vector< T > >;

template< typename T >
vector< T > dijkstra(WeightedGraph< T > &g, int s) {
  const auto INF = numeric_limits< T >::max();
  vector< T > dist(g.size(), INF);

  using Pi = pair< T, int >;
  priority_queue< Pi, vector< Pi >, greater< Pi > > que;
  dist[s] = 0;
  que.emplace(dist[s], s);
  while(!que.empty()) {
    T cost;
    int idx;
    tie(cost, idx) = que.top();
    que.pop();
    if(dist[idx] < cost) continue;
    for(auto &e : g[idx]) {
      auto next_cost = cost + e.cost;
      if(dist[e.to] <= next_cost) continue;
      dist[e.to] = next_cost;
      que.emplace(dist[e.to], e.to);
    }
  }
  return dist;
}

bool solve(){
  ll n,m;cin>>n>>m;
  //偶数でしか行けない点
  WeightedGraph<ll>G(n);
  vector<ll>a(m);
  vector<ll>b(m);
  rep(i,m){
    cin>>a[i]>>b[i];a[i]--;b[i]--;
    G[a[i]].emplace_back(b[i],1);
    G[b[i]].emplace_back(a[i],1);
  }
  auto d=dijkstra(G,0);
  UnionFind uf(n+1);
  //奇数は奇数同士偶数は偶数同士結ぶ
  ll u=n;
  rep(i,n){
    if(d[i]%2==0)uf.unite(0,i);
    else{
      uf.unite(u,i);
    }
  }
  bool isOK=false;
  rep(i,m){
    ll A=a[i];
    ll B=b[i];
    if(uf.find(A)==uf.find(B))isOK=true;
  }

  ll even=uf.size(0);
  ll odd=uf.size(n)-1;
  ll ans=0;
  if(isOK)ans=n*(n-1)/2-m;
  else ans=even*odd-m;
  cout<<ans<<endl;
  return false;
}


signed main(){
	ios::sync_with_stdio(false);
	cin.tie(nullptr);
	cout<<fixed;
	cout<<setprecision(30);
	return solve();
}

