const int N=1e5+1e3+7;

struct node{
	int ne,to;
}edg[N*2+1];

int n,m,cnt,head[N],c[N],flag;

void build(int u,int v)
{
	++cnt;
	edg[cnt].to=v;
	edg[cnt].ne=head[u];
	head[u]=cnt;
}

void dfs(int i,int cur)
{
	for(int tmp=head[i];tmp;tmp=edg[tmp].ne)
	{
		int v=edg[tmp].to;
		if(c[v]==-1)
		{
			c[v]=cur;
			dfs(v,cur^1);
		}
		else
		{
			if(c[v]!=c[i])
				continue;
			else
				flag=true;
		}
	}
}

int main()
{
	memset(c,-1,sizeof(c));
	scanf("%d%d",&n,&m);
	for(int i=1;i<=m;i++)
	{
		int u,v;
		scanf("%d%d",&u,&v);
		build(u,v);
		build(v,u);
	}
	c[1]=1;
	dfs(1,0);
	if(flag)
	{
		cout<<1ll*n*(n-1)/2-m;
	}
	else
	{
		long long cnt=0;
		for(int i=1;i<=n;i++)
			if(c[i])
				cnt++;
		cout<<cnt*(n-cnt)-m;
	}
}

