bool BFS(){
	queue<int> que;
	que.push(0);
	bi[0]=0;
	while(!que.empty()){
		int f=que.front();
		que.pop();
		if(bi[f]==0)b++;
		else w++;
		for(auto t:graph[f]){
			if(bi[t]==-1){
				bi[t]=(bi[f]+1)%2;
				que.push(t);
			}
			else if(bi[t]==bi[f])return false;
		}
	}
	return true;
}

