using namespace std;
using namespace atcoder;

void C3Steps(std::istream& in, std::ostream& out) {
    int n, m;
    in >> n >> m;
    dsu d(2 * n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        in >> u >> v;
        --u; --v;
        d.merge(u, v + n);
        d.merge(u + n, v);
    }
    if (d.same(0, n)) {
        out << 1LL * n * (n - 1) / 2 - m << '\n';
    } else {
        long long ans = 0;
        for (int i = 0; i < n; ++i) if (d.same(0, i)) ++ans;
        ans *= n - ans;
        out << ans - m << '\n';
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    std::istream& in(std::cin);
    std::ostream& out(std::cout);
    C3Steps(in, out);
    return 0;
}

