using namespace std;
int n, m;
vector<int> v[100001];
map<pair<int, int>, bool> isConnected;
map<pair<int, pair<int, int> >, int> memo;
bool used[100001];

int threeSteps(int pos, int from, int step)
{
  pair<int, pair<int, int> > idx = make_pair(pos, make_pair(from, step));
  if (memo.count(idx) != 0)
    return memo[idx];
  if (step == 3 && !isConnected[make_pair(pos, from)] && pos != from)
  {
    v[from].push_back(pos);
    v[pos].push_back(from);
    isConnected[make_pair(pos, from)] = isConnected[make_pair(from, pos)] = true;
    memo[idx] = 0;
    return threeSteps(pos, from, 1) + 1;
  }
  else if (step >= 3)
    return memo[idx] = 0;

  int ret = 0;
  for (int i = 0; i < v[pos].size(); i++)
  {
    if (!used[v[pos][i]])
    {
      used[v[pos][i]] = true;
      ret += threeSteps(v[pos][i], from, step + 1);
      memo[make_pair(v[pos][i], make_pair(from, step + 1))] = 0;
      used[v[pos][i]] = false;
    }
  }
  memo[idx] = 0;
  return ret;
}

int main(void)
{
  int a, b;
  scanf("%d %d", &n, &m);
  for (int i = 0; i < m; i++)
  {
    scanf("%d %d", &a, &b);
    v[a].push_back(b);
    v[b].push_back(a);
    isConnected[make_pair(a, b)] = isConnected[make_pair(b, a)] = true;
  }
  int ans = 0;
  for (int i = 1; i <= n; i++)
  {
    for (int j = 0; j < v[i].size(); j++)
    {
      ans += threeSteps(v[i][j], i, 1);
      memo[make_pair(v[i][j], make_pair(i, 1))] = 0;
    }
  }
  printf("%d\n", ans);
}

