#include <bits/stdc++.h>
using namespace std;
#define MAX_N 100001

int n, m, tmp1, tmp2;
int cou = 0;
vector<set<int>> graph(MAX_N, set<int>{});

void search(int root, int cur, int remain, int from) {
  auto link = graph[cur];
  if (remain == 1) {
    for (auto itr = link.begin(); itr != link.end(); ++itr) {
      if (*itr == from) continue;
      auto rootlink = graph[root];
      if ((rootlink.find(*itr) == rootlink.end()) && (*itr != root)) {
        cou++;
        graph[root].insert(*itr);
        graph[*itr].insert(root);
      }
    }
  }
  else {
    for (auto itr = link.begin(); itr != link.end(); ++itr) {
      if (*itr == from) continue;
      search(root, *itr, (remain - 1), cur);
    }
  }
}

int main(void){
  scanf("%d %d", &n, &m);
  for (int i = 0; i < m; ++i) {
    scanf("%d %d", &tmp1, &tmp2);
    graph[tmp1].insert(tmp2);
    graph[tmp2].insert(tmp1);
  }

  for (int i = 1; i <= n; ++i) {
    search(i, i, 3, -1);
  }
  printf("%d\n", cou);

}

