	}

	//ここまで共通
	// minの場合はpush_backの値をdekaiにする

	void update(ll i, ll k) {  // i番目をkに更新
		ll v = i + m - 1;
		seg[v] = k;
		while(v > 0) {
			v = (v - 1) / 2;

			seg[v] = seg[v * 2 + 1] + seg[v * 2 + 2];
			//改造時はここを変える
		}
	}
	ll query(ll a, ll b, ll k, ll l, ll r) {  //区間[a,b)での最大値を求める
