			if(!tr.same(i, t)) {
				tr.unite(i, t);
			} else {
				res--;
			}
		}
	}

	vll ans(n);
	rep(i, n) { ans[i] = tr.root(i); }
	sll s;
	rep(i, n * 2) {
		ll r = tr.root(i);
		if(s.count(r))
			continue;
		else {
			s.insert(r);
