struct dsu {
    vector<int> p;
    vector<int> sz;
    int n;

    dsu(int _n) : n(_n) {
        p.resize(n);
        iota(p.begin(), p.end(), 0);
        sz.assign(n, 1);
    }

    inline int get(int x) {
        if (p[x] == x) {
            return x;
        } else {
            return p[x] = get(p[x]);
        }
    }
    inline bool unite(int x, int y) {
        x = get(x);
        y = get(y);
        if (x == y) {
            return false;
        }
        if (sz[x] < sz[y]) {
            swap(x, y);
        }
        p[x] = y;
        sz[y] += sz[x];
        return true;
    }
    inline bool same(int x, int y) {
        return (get(x) == get(y));
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int n, m;
    cin >> n >> m;
    dsu uf(2 * n);
    for (int i = 0; i < m; i++) {
        int x, y;
        cin >> x >> y;
        x--, y--;
        uf.unite(x, n + y);
        uf.unite(y, n + x);
    }
    int b = 0;
    for (int i = 0; i < 2 * n; i++) {
        if (uf.get(i) == i) {
            b++;
        }
    }
    if (b == 1) {
        ll ans = 1LL * n * (n - 1) / 2;
        ans -= m;
        cout << ans << '\n';
    } else if (b == 2) {
        vector<ll> t(2 * n);
        for (int i = 0; i < n; i++) {
            t[uf.get(i)]++;
        }
        sort(t.rbegin(), t.rend());
        ll ans = t[0] * t[1] - m;
        cout << ans << '\n';
    } else {
        assert(false);
    }
    return 0;
}

