bool is_biparate(const vector<vector<int>>& G, vector<int>& color) {
    queue<int> q;
    color.resize(G.size());
    color[0] = 1; // 0: undef, 1: black, 2: white
    REP(i, G[0].size()) {
        q.push(G[0][i]);
        color[G[0][i]] = 2;
    }

    while (!q.empty()) {
        int p = q.front();
        q.pop();
        REP(i, G[p].size()) {
            int t = G[p][i];
            if (color[p] == color[t]) {
                return false;
            }
            if (color[t] != 0) continue;
            q.push(t);
            color[t] = color[p] == 1 ? 2 : 1;
        }
    }
    return true;
}

