bool dfs(int cur, vector<vector<int>> &graph, vector<int> &check, vector<bool> &visit){
  if(visit[cur]) return true;
  visit[cur] = true;

  for(auto next : graph[cur]){
    if(check[next] == check[cur]) return false;

    if(check[next] == -1){
      check[next] = (check[cur]==0 ? 1 : 0);
    }

    if(!dfs(next, graph, check, visit)) return false;
  }
  return true;
}

bool is_bipartite_graph(vector<vector<int>> &graph, int &a, int &b){
  vector<int> check(graph.size(), -1);
  vector<bool> visit(graph.size(), false);

  check[0] = 0;

  if(dfs(0, graph, check, visit)){
    a = b = 0;
    for(auto x : check) if(x) ++a; else ++b;
    return true;
  }else{
    return false;
  }
}

