typedef long long ll;

struct UnionFind{
	vector<int> par,rank;
	UnionFind(int n) :par(n + 1),rank(n + 1,1){
		for(int i = 1;i <= n;i++) par [i] = i;
	}
	int find(int x){
		return par [x] == x ? x : par [x] = find(par [x]);
	}
	bool unite(int x,int y){
		x = find(x);
		y = find(y);
		if(x == y) return false;
		if(rank [x] < rank [y]) swap(x,y);
		rank [x] += rank [x] == rank [y];
		par [y] = x;
		return true;
	}
	bool same(int x,int y){
		return find(x) == find(y);
	}
};

int N,M;

int main()
{
	scanf("%d%d",&N,&M);
	UnionFind uf(N * 2);
	FOR(i,0,M){
		int a,b;
		scanf("%d%d",&a,&b);
		uf.unite(a,b + N);
		uf.unite(a + N,b);
	}

	if(uf.same(1,1 + N)){
		printf("%lld\n",(ll) N * (N - 1) / 2 - M);
	}
	else{
		ll x = 0,y = 0;
		FOR(i,1,N + 1){
			if(uf.same(1,i)){
				x++;
			}
			else{
				y++;
			}
		}
		printf("%lld\n",x * y - M);
	}

	return 0;
}

