#include <bits/stdc++.h>
using namespace std;
using Graph = vector<vector<int>>;
Graph G;
vector<int> color;
int black_cnt = 0;
vector<bool> is_black;
// white 0, black 1
bool dfs(int cn, int cn_color){
    color[cn] = cn_color;
    if (cn_color == 1) is_black[cn] = true;
    bool ok = true;
    for (auto next: G[cn]){
        if (color[next] == -1) {
            color[next] = 1 - cn_color;
            ok = dfs(next, color[next]);
            continue;
        }
        if (cn_color == color[next]) return false;
        else continue;
    }
    return ok;
}

int main() {
    int N, M;
    cin >> N >> M;
    G.resize(N);
    is_black.assign(N, false);
    for (int i = 0; i < M; i++) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    color.assign(N, -1);
    bool is_bipartite = dfs(0, 0);
    int ans = 0;
    if (is_bipartite) {
        black_cnt = count(is_black.begin(), is_black.end(), true);
        ans = black_cnt * (N - black_cnt) - M;
    }
    else ans = (N - 1) * N / 2 - M;
    cout << ans << endl;
    return 0;
}

