          ans++;
          v.pb(mp(min(a1,b1),max(a1,b1)));
          se.insert(mp(min(a1,b1),max(a1,b1)));
          vv[a1].pb(b1);
          vv[b1].pb(a1);
        }
      }
    }
    index++;
    if(index==v.sz)break;
  }
  cout << ans << endl;
  return 0;
}

