template <class Graph>
bool dfs1(const Graph& g, u32 v, i32 cur_type, std::vector<i32>& t) {
  t[v] = cur_type;
  bool flag = false;
  for (u32 next: g[v]) {
    if (t[next] == -1) {
      flag |= dfs1(g, next, cur_type ^ 1, t);
    } else if (t[v] == t[next]) {
      flag |= true;
    }
  }
  return flag;
}

