	{
		int a,b;
		scanf("%d %d",&a,&b);
		v[a].PB(b);v[b].PB(a);
	}

	set<int> can;
	set<int> dont;

	dont.insert(1);

	queue<pair<int,int> > q;

	REP(i,v[1].size())
	{
		q.push(MP(v[1][i],1));
	}

	while(!q.empty())
	{
		pair<int,int> tmp = q.front();q.pop();
		REP(i,v[tmp.FI].size())
		{
			int tt = v[tmp.FI][i];
			int iscan,isdont;
			if(can.find(tt) != can.end())
			{
				iscan = 1;
			}
			else
			{
				iscan = 0;
			}
			if(dont.find(tt) != dont.end())
			{
				isdont = 1;
			}
			else
			{
				isdont = 0;
			}

			if(iscan == 0 && isdont == 0)
			{
				q.push(MP(tt,(tmp.SE+1) % 2));

				if((tmp.SE+1) % 2 == 1)
				{
					can.insert(tt);
				}
				else
				{
					dont.insert(tt);
				}
			}
			else
			{
				if( iscan == 1 && (tmp.SE+1) % 2 == 0)
				{
					q.push(MP(tt,0));
				}
				if( iscan == 0 && (tmp.SE+1) % 2 == 1)
				{
					can.insert(tt);
					dont.erase(tt);
					q.push(MP(tt,1));
				}
