void add(int u,int v){
	link[++tot]=head[u];
	to[tot]=v;
	head[u]=tot;
}
void dfs(int x){
	if(flag) return ;
	for(int i=head[x];i;i=link[i]){
		if(d[to[i]]==d[x]) flag=1;
		if(d[to[i]]) continue;
