#include <bits/stdc++.h>
using namespace std;

const int MAXN = 200005;

struct node {
	int to, next;
} edge[MAXN*2];
int head[MAXN*2], top = 0;
inline void push(int i, int j)
{ edge[++top] = (node) {j, head[i]}, head[i] = top; }

int fa[MAXN], mark[MAXN], siz[MAXN], n, m;
inline int findf(int nd)
{ return fa[nd]?fa[nd]=findf(fa[nd]):nd; }
long long ans = 0;

int depth[MAXN], dsiz[MAXN], vis[MAXN];

void dfs_siz(int nd, int fa)
{
	dsiz[nd] = 1;
	for (int i = head[nd]; i; i = edge[i].next) {
		int to = edge[i].to;
		if (to == fa || vis[to]) continue;
		dfs_siz(to, nd), dsiz[nd] += dsiz[to];
	}
}

void dfs_choose(int nd, int fa, const int totsiz, int &cur, int &dt)
{
	int ths = totsiz-dsiz[nd];
	for (int i = head[nd]; i; i = edge[i].next) {
		int to = edge[i].to;
		if (to == fa || vis[to]) continue;
		dfs_choose(to, nd, totsiz, cur, dt);
		ths = max(ths, dsiz[to]);
	}
	// cerr << nd << " " << ths << endl;
	if (ths <= dt) cur = nd, dt = ths;
}

void dfs_paint(int nd, int fa, int &odd, int &even, int cur)
{
	if (cur) odd++;
	else even++;
	// cerr << nd << "---" << cur << endl;
	for (int i = head[nd]; i; i = edge[i].next) {
		int to = edge[i].to;
		if (to == fa || vis[to]) continue;
		dfs_paint(to, nd, odd, even, 1-cur);
	}
}

void calc(int nd)
{
	dfs_siz(nd, 0);
	int center = 0, dt = n+1;
	dfs_choose(nd, 0, dsiz[nd], center, dt);
	vis[center] = 1;
	// cerr << center << endl;
	int odd = 0, even = 0;
	for (int i = head[center]; i; i = edge[i].next) {
		int to = edge[i].to;
		if (vis[to]) continue;
		int o = 0, e = 0;
		dfs_paint(to, center, o, e, 1);
		ans += o;
		ans += (long long)even*o+(long long)odd*e;
		odd += o, even += e;
		// cerr << o << " " << e << " " << odd << " " << even << endl;
	}
	// cerr << center << " " << ans << endl;
	for (int i = head[center]; i; i = edge[i].next) {
		int to = edge[i].to;
		if (vis[to]) continue;
		calc(to);
	}
}

int main()
{
	scanf("%d%d", &n, &m);
	for (int i = 1; i <= n; i++) siz[i] = 1;
	for (int i = 1; i <= m; i++) {
		int u, v; scanf("%d%d", &u, &v);
		push(u, v), push(v, u);
		u = findf(u), v = findf(v);
		if (u == v) mark[u] = 1;
		else mark[u] |= mark[v], siz[u] += siz[v], fa[v] = u;
	}
	for (int i = 1; i <= n; i++) 
		if (fa[i] == 0) {
			if (mark[i]) ans += (long long)siz[i]*(siz[i]-1)/2;
			else calc(i);
		}
	cout << ans-m << endl;
	return 0;
}

