public:
    int u, v, cost;
    Edge(int u, int v, int cost=1):
        u(u), v(v), cost(cost) {}
    bool operator < (const Edge& e) const {
        return cost != e.cost ? cost > e.cost : // for min-priority queue
            u != e.u ? u < e.u : v < e.v;
    }
};
using Edges = vector<Edge>;
using Graph = vector<Edges>;


bool dfs(Graph& G, int u, vector<bool>& visited, int& count, int depth, int s) {
    visited[u] = true;

    if (depth == 3 ) {
        for(auto& e: G[u]) if (e.v == s) return false;
        G[s].pb(Edge(s,u));
        G[u].pb(Edge(u,s));
        count++;
        return true;
    }
    bool find = false;
    for(auto& e: G[u]) {
        if (!visited[e.v])
            if(dfs(G, e.v, visited, count, depth+1, s)) find = true;
    }

    return find;
}

