  }
  int visited[100010];
  fill(visited, visited+100010, 0);
  int color[100010];
  fill(color, color+100010, 0);
  int parent[100010];
  stack<state> S;
  S.push(state(0, -1, 1));
  while (!S.empty()) {
    int now = get<0>(S.top());
    int from = get<1>(S.top());
    int clr = get<2>(S.top());
    // cerr << "now = " << now << ", from = " << from << endl;
    S.pop();
    if (visited[now] == 0) {
      visited[now] = true;
      parent[now] = from;
      color[now] = clr;
      // cerr << "parent[" << now << "] = " << from << endl;
      S.push(state(now, now, 3-clr));
      for (auto x : V[now]) {
        if (x != parent[now]) {
          S.push(state(x, now, 3-clr));
        }
      }
    } else if (visited[now] == 1) {
      if (from != now) {
        if (color[now] == clr) continue;
        color[now] = 3;
        color[from] = 3;
        int back = parent[from];
        while (back != now) {
          color[back] = 3;
          back = parent[back];
        }
      } else {
        visited[now] = 2;
      }
    }
  }
  for (auto i = 0; i < 100010; ++i) {
    visited[i] = (color[i] == 3);
