using namespace std;
using vecint = vector<int>;
using ll = int64_t;
using Graph = vector<vecint>;

bool dfs(const Graph &g, vecint &clr, vector<bool> &vis, int i = 0, int c = 1) {
  vis[i] = true;
  clr[i] = c;
  for (int j : g[i]) {
    if (!vis[j]) {
      if (!dfs(g, clr, vis, j, 3-c))
        return false;
    } else if (clr[j] != 3-c) {
      return false;
    }
  }
  return true;
}

