const int INF = numeric_limits<int>::max() / 2;

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);

	vector<int> dist(100001, INF);
	vector<int> tree[100001];
	int n, m; cin >> n >> m;
	for (int i = 0; i < m; i++) {
		int a, b; cin >> a >> b;
		a--; b--;
		tree[a].push_back(b);
		tree[b].push_back(a);
	}
	dist[0] = 0;
	queue<P> q;
	q.push(P(0, 0));//点、距離
	while (!q.empty()) {
		P nex = q.front(); q.pop();
		int d = nex.second, v = nex.first;
		for (int i = 0; i < (int)tree[v].size(); i++) {
			int next = tree[v][i];
			if(dist[next]==INF){
				dist[next] = d + 1;
				q.push(P(next, d + 1));
		}
}
	}
	int odd = 0, even = 0;
	for (int i = 0; i < n; i++) {
		if (dist[i] % 2 == 0) even++;
		else odd++;
	}
	if (n - 1 == m) {
		//cout << n*(n - 1) / 2 - m - even*(even - 1) / 2 - odd*(odd - 1) / 2 << endl;
		cout << odd*even - m << endl;
	}
	else {
		int cnt = 0;
		for (int i = 0; i < n; i++) {
			for (int j = 0; j < (int)tree[i].size(); j++){
				int a = i, b = tree[i][j];
				if (dist[a] % 2 == dist[b] % 2) cnt++;
			}
		}
		if(cnt!=0) cout << n*(n - 1) / 2 - m << endl;
		else cout << odd*even - m << endl;
		//else cout << n*(n - 1) / 2 - m - even*(even - 1) / 2 - odd*(odd - 1) / 2 << endl;
	}
	return 0;
}

