					}
					if (l == 0)
					{
						has_loop = true;
					}
				}
			}
		}
	}

	int all = 0;
	if (!has_loop)
	{
		if (N % 2 == 0)
		{
			int k = N - 1;
			all += k;
			for (int i = 0; i < k / 2; i++)
			{
				all += (i + 1) * 2;
			}
			all -= k / 2;
		}
		else
		{
			int k = N - 1;
			all += k;
			for (int i = 0; i < (k / 2) - 1; i++)
			{
