			if(cnt3 >= 3){
				int p1 = ((cnt3-4)>>1) + 1;
				int t = ((p1+1) * p1)>>1;
				if(cnt3&1) ans += 2*t;
				else ans += 2*t-p1;
			}
		}
	}
	printf("%d", ans-m);
}

