#include <iostream>
#include <vector>
using namespace std;
using Graph = vector<vector<int>>;

Graph G;

int sum = 0;

void dfs(Graph &G, int v, int start, int cur = 0) {
    if (cur == 3) {
        // ...

        // 初めの場所に戻ってきてる時はリターン。
        if (v == start) return;

        // 既にstartとvがつながっている時もリターン。
        for (auto next_v : G[v]) {
            if (next_v == start) return;
        }

        // それ以外の時は新しい線を引く。
        // printf("new line! : (%d %d)\n", start, v);
        sum++;
        G[v].push_back(start);
        G[start].push_back(v);

        return;
    }

    for (auto next_v : G[v]) {
        if (next_v == v) continue;

        dfs(G, next_v, start, cur + 1);
    }
}

int main() {
    int N, M;

    cin >> N >> M;

    // Graph G(N);
    G.resize(N);

    for (int i = 0; i < M; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;

        G[a].push_back(b);
        G[b].push_back(a);
    }

    for (int i = 0; i < N; i++) {
        dfs(G, i, i);
    }

    // cout << G.size() - M << endl;
    cout << sum << endl;
}

