    stack<int> nodeids;
    nodeids.push(0);
    while (!nodeids.empty()) {
        int nod = nodeids.top();
        nodeids.pop();
        for (auto dstnod : edg[nod]) {
            if (colors[dstnod] == -1) {
                colors[dstnod] = 1 - colors[nod];
                nodeids.push(dstnod);
            }
        }
    }
    int twocolor = true;
    for (auto e : alledg) {
        if (colors[e.first] == colors[e.second]) {
            twocolor = false;
            break;
        }
    }
    int expected;
    if (twocolor && N % 2 == 0) {
        expected = N * N / 4;
    } else if (twocolor) {
        expected = (N + 1) * (N - 1) / 4;
    } else {
        expected = N * (N - 1) / 2;
    }
    // print(expected, M, twocolor);
    cout << (expected - M) << endl;
}

