                if (!isBG) {
                    total += (ll)cnt[r]*(cnt[r]-1)/2;
                    break;
                }
            }
        }
        if (!isBG) continue;

        int g1=0;
        int g2=0;
        rep(i, n) {
            if(color[i]==1 && uf.root(i)==r) g1++;
            else if (color[i]==-1 && uf.root(i)==r)g2++;
        }
        total += (ll)g1*g2;
    }
    cout << (total-(ll)m) << endl;
    return 0;
}

