      --a, --b;
      graph[a].push_back(b);
      graph[b].push_back(a);
    }

    LLI a,b;
    if(is_bipartite_graph(graph,a,b)){
      cout << a*b-M << endl;
    }else{
      cout << N*(N-1)/2-M << endl;
    }
  }

  return 0;
}

