        G[b].push_back(a);
    }

    // 探索
    color.assign(N, -1);
    bool is_bipartite = true;
    for (int v = 0; v < N; ++v) {
        if (color[v] != -1) continue; // v が探索済みだったらスルー
        if (!dfs(G, v)) is_bipartite = false;
    }

    if (is_bipartite){
      cout << b*w-M << endl;
    }
    else{
      cout << N*(N-1)/2-M << endl;
    }
}

