vvll NPath;

bool search(int pos, vll& dp){
  ll ans = true;
  for(auto y : NPath[pos]){
    if(dp[y]==-1){
      dp[y] = 1-dp[pos];
      ans &= search(y, dp);
    }else if(dp[y]==dp[pos]){
      return false;
    }
  }
  return ans;
}

