  ll N, M;
  IN(N,M);
  NPath.resize(N);
  REP(i,M){
    ll A, B;
    IN(A,B);
    A--; B--;
    NPath[A].pb(B);
    NPath[B].pb(A);
  }

  //2部グラフかどうか
  vll dp(N, -1);
  dp[0] = 0;
  if(!search(0, dp)){
    OUT(N*(N-1)/2-M);
  }else{
    ll num0=0;
