using namespace std;

map<int,int> graph[100000];
map<int,int> three_step[100000];

int cnt = 0;
void compute_step(int s,int n,int step){
  if(step == 0){
    if(s!=n&&graph[s][n]==0){
      three_step[s][n] = 1;
      three_step[n][s] = 1;
      graph[s][n] = 1;
      graph[n][s] = 1;
      cnt++;
    }
    return;
  }
  for(const auto &next:graph[n]){
    if(step == 2&&next.first==s) continue;
    compute_step(s,next.first,step-1);
  }
}

int main(){
  int N,M;
  cin >> N >> M;

  for(int i=0;i<M;++i){
    int a,b;
    cin >> a >> b;
    graph[a-1][b-1] = 1;
    graph[b-1][a-1] = 1;
  }

  for(int i=0;i<N;++i){
    compute_step(i,i,3);
  }
  cout << cnt << endl;

  return 0;
}

