bool isBipartiteGraph(vector<vector<int>>& E, vector<int>& color, int v, int c) {
	if( color[v] != 0 ) {
		return (color[v] == c); 	
	}
	color[v] = c;
	for(auto& e : E[v]) {
		if( isBipartiteGraph(E,color,e,2-(c-1)) == false ) return false;
	}
	return true;
}


