#include <bits/stdc++.h>

using namespace std;

const long long N = 1e5 + 10;

long long n, m, ans, col[ N ];
vector< long long > adj[ N ];

bool dfs( long long now, long long parent ) {
  for ( auto child : adj[ now ] )
    if ( child != parent ) {
      if ( col[ child ] != -1 ) {
        if ( col[ child ] == col[ now ] )
          return false;
        continue;
      }
      col[ child ] = col[ now ] ^ 1;
      if ( !dfs( child, now ) )
        return false;
    }
  return true;
}
int main() {
  ios_base::sync_with_stdio(0);cin.tie(0);cout.setf(ios::fixed);cout.precision(20);
