  color.assign(N, -1);
  if (dfs(G, 0)) {
    int b = 0, w = 0;
    for (int i = 0; i < N; i++) {
      if (color[i])
        b++;
      else
        w++;
    }
    cout << b * w - M << endl;
  } else {
    cout << N * (N - 1) / 2 - M << endl;
  }

  return 0;
}

