void addedge(int u, int v)
{
    edge[tot].to = v;
    edge[tot].next = head[u];
    head[u] = tot++;
}

void dfs(int u, int color)
{
    if(flag) return;
    col[u] = color;
    if(color == 1)
        ++c1;
    else
        ++c2;
    for(int i = head[u]; i != -1; i = edge[i].next)
    {
        int v = edge[i].to;
        if(!col[v])
            dfs(v,3-color);
        else if(col[v] == color)
        {
            flag = true;
            return;
        }
    }
}

