    for(int i = 0; i < m; ++i)
    {
        cin >> u >> v;
        addedge(u,v);
        addedge(v,u);
    }
    dfs(1,1);
    if(flag)
        cout << n*(n-1)/2-m;
    else
        cout << c1*c2-m << endl;
