{
	v[++ e] = vv;
	nex[e] = beg[uu];
	beg[uu] = e;
}

void dfs(int u , int type)
{
	if (type == 1)
	{
		for (int i = beg[u] ; i ; i = nex[i])
		{
			if (!w[v[i]])
			{
				w[v[i]] = 1;
				dfs(v[i] , 2);
			}
		}
	}
	if (type == 2)
	{
		for (int i = beg[u] ; i ; i = nex[i])
		{
			if (!b[v[i]])
			{
				b[v[i]] = 1;
				dfs(v[i] , 1);
			}
		}
	}
}

void BFS()
{
	q.push(1);
	b[1] = 1;
	while (!q.empty())
	{
		int u = q.front();
		q.pop();
		isin[u] = 0;
		if (b[u])
		{
			for (int i = beg[u] ; i ; i = nex[i])
			{
				if (!w[v[i]])
				{
					w[v[i]] = 1;
					if (!isin[v[i]])
					{
							q.push(v[i]),
							isin[v[i]] = 1;
					}
				}
			}
		}
		if (w[u])
		{
			for (int i = beg[u] ; i ; i = nex[i])
			{
				if (!b[v[i]])
				{
					b[v[i]] = 1;
					if (!isin[v[i]])
					{
							q.push(v[i]),
							isin[v[i]] = 1;
					}
				}
			}
		}
	}
}

