{
	For(i , 1 , n)
	{
		if (w[i] && !b[i])
			++ cntw;
		if (b[i] && !w[i])
			++ cntb;
		if (w[i] && b[i])
			++ cntbw;
	}
	printf("%d\n" , cntw * cntb + cntb * cntbw + cntbw * cntw + cntbw * (cntbw - 1) / 2 - m);
}

