// v: 現在探索中の頂点、p: v の親 (v が根のときは -1)
void dfs(const UnWeightedGraph &G, int v, int p) {
    for(auto nv : G[v]) {
        if(nv == p) continue;  // nv が親 p だったらダメ
        dfs(G, nv, v);         // v は新たに nv の親になります
    }
}

// d: 頂点 v の深さ
vector<int> depth;
void dfs(const UnWeightedGraph &G, int v, int p, int d) {
    depth[v] = d;
    for(auto nv : G[v]) {
        if(nv == p) continue;  // nv が親 p だったらダメ
        dfs(G, nv, v, d + 1);  // d を 1 増やして子ノードへ
    }
}

int BipartiteGraph(const UnWeightedGraph &g) {
    int n = g.size();
    vector<int> color(n, -1);
    int white_cnt = 0;
    function<bool(int, int, int)> dfs = [&](int v, int prev, int c) {
        color[v] = c;
        if(c == 1) white_cnt++;
        for(auto nv : g[v]) {
            if(nv == prev) continue;

            if(color[nv] == -1) {
                if(!dfs(nv, v, 1 - c)) return false;
            } else if(color[nv] != 1 - c) {
                return false;
            }
        }
        return true;
    };
    if(!dfs(0, -1, 0)) return -1;
    return white_cnt;
}

