		if (same(a, a + N) || same(b, b + N))flag = false;
	}
	int cnt = 0;
	rep(i, N) {
		if (same(0, i))cnt++;
	}
	cout << (flag ? cnt*(N - cnt) - M : N*(N - 1) / 2 - M) << endl;


	return 0;
}

