#define MAX_N 100001

int n, m, tmp1, tmp2;
int cou = 0;
vector<set<int>> graph(MAX_N, set<int>{});
int done[MAX_N][4] = {{}};

int search(int root, int cur, int remain) {
  if (done[cur][remain] == 1) return 0;
  auto link = graph[cur];
  if (remain == 1) {
    for (auto itr = link.begin(); itr != link.end(); ++itr) {
      if ((graph[root].find(*itr) == graph[root].end()) && (*itr != root)) {
        cou++;
        graph[root].insert(*itr);
        graph[*itr].insert(root);
        for (int i = 1; i < 4; ++i) {
          done[root][i] = 0;
          done[*itr][i] = 0;
        }
      }
    }
    done[cur][remain] = 1;
  }
  else {
    for (auto itr = link.begin(); itr != link.end(); ++itr) {
      search(root, *itr, (remain - 1));
      done[cur][remain] = 1;
    }
  }
  return 0;
}


