struct UnionFind {
    vector<int> par, rank;

    UnionFind(int n) : par(n , -1), rank(n, 0) { }
    void init(int n) { par.assign(n, -1), rank.assign(n, 0); }

    int root(int x) {
        if (par[x] == -1) return x;
        else return par[x] = root(par[x]); //ここで経路圧縮
    }

    bool same(int x, int y) {
        return root(x) == root(y);
    }

    bool unite(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (rank[x] < rank[y]) swap(x, y);
        if (rank[x] == rank[y]) ++rank[x];
        par[y] = x;
        return true;
    }
};

int main() {
    int N, M; cin >> N >> M ;
    UnionFind tree(2 * N);
    rep(i, M) {
        int a, b; cin >> a >> b;
        a--; b--;
        tree.unite(a, b + N);
        tree.unite(a + N, b);
    }
    bool g = true;
    rep(i, N) {
        if (tree.same(i, i + N)) {
            g = false;
            break;
        }
    }
    if (!g) {
        cout << N*(N - 1) / 2 - M << endl;
    }
    else {
        int l = 0;
        rep(i, N) {
            if (tree.same(0, i)) l++;
        }
        cout << l*(N - l) - M << endl;
    }

}

