int main()
{
    ios_base::sync_with_stdio(0);

    lli n, m; cin >> n >> m;

    vvi g(n + 1);

    for(int i = 0; i < m; i++)
    {
        int a, b; cin >> a >> b;

        g[a].push_back(b);
        g[b].push_back(a);
    }

    vi vv(n + 1);
    vi path;

    dfs(g, vv, 1, path);

    int z = path.back();

    vi vis(n + 1);

    vis[z] = 1;

    queue<vi> q;

    q.push({z, 1});

    while(!q.empty())
    {
        auto e = q.front(); q.pop();

        int nd = e[0];
        int lv = e[1];

        for(auto x : g[nd])
        {
            int plv = vis[x];

            if(!plv)
