template<class T=int> class undigraph : public graph<T> {
public:
    using graph<T>::g;
    using graph<T>::n;
    using graph<T>::edges;
    using graph<T>::_used;
    int eid = 0;
    undigraph(int n) : graph<T>(n) {
    }
