void add(int u, int v){
	edge[++cnt] = (node){v, head[u]};
	head[u] = cnt;
}

void dfs(int u, int fa){
	cnt3++;
	for(int i = head[u]; i; i = edge[i].nxt){
		int v = edge[i].v;
		if(v == fa) continue;
		if(b[v]!=-1) {
			flag2 = 1;
			if(!flag && b[v] == b[u]) flag = 1;
			if(b[v] != b[u]) st = u; 
			continue;
		}
		b[v] = b[u] ^ 1;
		dfs(v, u);
	}
}

void dfs2(int u){
	for(int i = head[u]; i; i = edge[i].nxt){
		int v = edge[i].v;
		if(b2[v]) continue;
		b2[v] = 1;
		cntt[b[v]]++;
		dfs2(v);
	}
}

