class Factorial {
public:
    ll cmb(ll a, ll b) {
        if (a == 0 && b == 0) return 1;
        if (a < b || a < 0 || b < 0) return 0;
        ll c = 1;
        for (int i = a,j=1; i > a - b; i--,j++) {
            c *= i;
            c /= j;
        }
        return c;
    }
};

