ll col[N_MAX],blo,whi;

ll solve(){
    queue<int> que;
    que.push(0);
    col[0]=1;blo++;
    while(que.size()){
        int now=que.front();que.pop();
        for(auto w:v[now]){
            if(col[w]==0){
                col[w]=-col[now];
                col[w]==1?blo++:whi++;
                que.push(w);
            }else if(col[w]==col[now]){
                return (n*(n-1)/2)-m;
            }
        }
    }
    return blo*whi-m;
}

