          res[0] = -1;
          return res;
        }else if(not did[to]){
          q.push(to);
          res[to] = 1 - res[from];
          did[to] = true;
        }
      }
    }
  }
  return res;
}

int main(){
  ll n,m;
  cin >> n >> m;
  vector<vector<ll>> G(n);
  FOR(i,0,m){
    ll a,b;
    cin >> a >> b;
    a--,b--;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  auto res = calc(G);
  if(res[0]>-1){
    ll b=0,w=0;
    b = count(res.begin(), res.end(),1);
    w = count(res.begin(), res.end(),0);
    ll ans = b*w-m;
    cout << ans << endl;
  }else{
    ll ans = n*(n-1)/2-m;
    cout << ans << endl;
  }
}

