using namespace std;

void solve()
{
	int N, M;
	cin >> N >> M;
	vector<int> adj[N];
	set<pair<int, int>> s;
	for (int i = 0; i < M; i++)
	{
		int a, b;
		cin >> a >> b;
		a--, b--;
		if (a > b) swap(a, b);
		adj[a].push_back(b);
		adj[b].push_back(a);
		s.emplace(a, b);
	}
	int ans = 0;

	for (int k = 0; k < 2; k++)
		for (int i = 0; i < N; i++)
	{
		queue<tuple<int, int, int>> q;
		q.emplace(-1, i, 0);
		vector<vector<int>> vst(4, vector<int>(N));
		vst[0][0] = 1;
		while (!q.empty())
		{
			auto t = q.front();
			q.pop();
			int p = get<0>(t), v = get<1>(t), x = get<2>(t);
			//cout << p << ' ' << v << ' ' << x << endl;
			for (int nv : adj[v])
			{
				if (p == nv || vst[x+1][nv]) continue;
				vst[x+1][nv] = 1;
				if (x == 2)
				{
					if (i == nv) continue;
					int a = min(i, nv), b = max(i, nv);
					if (s.find({a, b}) == s.end())
					{
						ans++;
						adj[i].push_back(nv);
						adj[nv].push_back(i);
						//cout << i << ' ' << nv << endl;
						s.emplace(a, b);
					}
				}
				else
				{
					q.emplace(v, nv, x+1);
				}
			}
		}
	}
	cout << ans << endl;
}

int main(void)
{
	solve();
	//cout << "yui(*-v・)yui" << endl;
	return 0;
}

