      add.push_back({ x,i });
      ans++;
      dfs(i, 1, -2);
      update = true;
    }
    return;
  }
  is[i] = 1;
  p.push_back(i);
  for (auto& j : v[i]) {
    if (is[j])continue;
    dfs(j, cnt + 1);
  }
  p.pop_back();
  is[i] = 0;
}

vector<int>solve2(int i) {
  vector<int> res;
  for (auto& j : ad[i]) {
    for (auto& a : ad[j]) {
      res.push_back(a);
    }
  }
  return res;
}

