  is.resize(n);
  update = false;
  rep(i, n) {
    dfs(i, 0);
  }
  err(0);
  v = ad;

  vector<pair<int, int>> c;
  while (add.size()) {
    swap(c, add);
    add.clear();

    for (auto& i : c) {
      auto t = solve2(i.first);
      for (auto& j : t) {
        if (i.second != j && ad[i.second].insert(j).second) {
          ad[j].insert(i.second);
