vector<int> graph[200005];
int dist[200005];

bool dfs(int v, int p, int d) {
    dist[v] = d;

    bool res = false;
    for (int to : graph[v]) {
        if (to == p) continue;
        if (dist[to] < 0) {
            res = res || dfs(to, v, d + 1);
        } else if (dist[to] % 2 != (d + 1) % 2) {
            return true;
        }
    }
    return res;
}

