    if (flag) {
        cout << N * (N - 1) / 2 - M << endl;
    } else {
        ll cnt = 0;
        for (int i = 1; i < N; i += 2) {
            cnt += N - i;
        }
        cout << cnt - M << endl;
    }

    return 0;
}

