bool is_bipartite_graph(int n, vector<vector<int>>& g, vector<int>& t){
    bool flg = false;
    t.assign(n, -1);
    queue<int> q; q.push(0); t[0] = 0;
    while(not q.empty()) {
        auto p = q.front(); q.pop();
        for (auto & elm : g[p]) {
            if(t[elm] == -1) t[elm] = not t[p];
            else {
                if(t[elm] == t[p]) {
                    flg = true; break;
                }
                continue;
            }
            q.push(elm);
        }
        if(flg) break;
    }

    return (not flg);
}

