bool bfs(Vec<Vec<int> >& table, Vec<int>& color) {
    queue<int> que;
    que.push(0);
    color[0] = 1;

    while (!que.empty()) {
        int now = que.front();
        que.pop();
        int len = table[now].size();
        for (int i = 0; i < len; i++) {
            int target = table[now][i];
            if (color[target] == 0) {
