bool dfs(vector<vector<Z>> const& graph, vector<Z>& color, Z pos) {
  bool ok = true;
  for (auto&& v : ix(graph, pos)) {
    if (ix(color, v) != -1) {
      if (ix(color, v) == ix(color, pos)) {
        return false;
      }
      continue;
    }
    ix(color, v) = 1 - ix(color, pos);
    ok &= dfs(graph, color, v);
  }
  return ok;
}

