int main()
{
    int N, M;
    cin>>N>>M;
    vector<vector<int>> E(N);
    for (int i=0; i<M; i++)
    {
        int A, B;
        cin>>A>>B;
        E[A-1].push_back(B-1);
        E[B-1].push_back(A-1);
    }
    vector<int> X(N);

    function<bool(int, int, int)> f = [&](int c, int p, int x)
    {
        if (X[c]==x)
            return true;
        if (X[c]==-x)
            return false;
        X[c] = x;
        for (int e: E[c])
        if (e != p)
            if (!f(e, c, -x))
                return false;
        return true;
    };

    if (f(0, -1, 1))
    {
        int c1 = 0;
        int c2 = 0;
        for (int x: X)
            (x == 1 ? c1 : c2)++;
        cout<<(long long)c1*c2 - M<<endl;
    }
    else
    {
        cout<<(long long)N*(N-1)/2 - M<<endl;
    }
}

