bool isBipartite(int v, int prev,int c) {
	color[v]=c;
	++(c==0?b:w);
	for(auto e:G[v]) {
		if(e==prev) continue;
		if(color[e]==c) return false;
		if(color[e]!=-1) continue;
		isBipartite(e,v,1-c);
	}
	return true;
}

