void dfs(int u, int fa){
	cnt3++;
	for(int i = head[u]; i; i = edge[i].nxt){
		int v = edge[i].v;
		if(v == fa) continue;
		if(b[v]) {
			flag2 = 1;
			if(!flag && (b[v]&1)) flag = 1;
			continue;
		}
		b[v] = b[u] + 1;
		if(b[u]&1) cnt2++;
		else cnt1++;
		dfs(v, u);
	}
}

