		add(a, b), add(b, a);
	}
	int ans = 0;
	for(int i = 1; i <= n; i++) if(!b[i]) {
		b[i] = 1;
		cnt3 = cnt2 = 0;
		cnt1 = 1; flag = 0, flag2 = 0;
		dfs(i, 0);
		if(flag2){
			if(flag == 1) ans += (cnt3 * (cnt3-1)) >> 1;
			else ans += cnt1 * cnt2;
		}
		else {
			ans += cnt3-1;
			if(cnt3 >= 3){
				int p1 = ((cnt3-4)>>1) + 1;
				int t = ((p1+1) * p1)>>1;
				if(cnt3&1) ans += 2*t;
				else ans += 2*t-p1;
			}
		}
	}
	printf("%d", ans-m);
}

