inline int read()
{
	char ch = getchar(); int x = 0, flag = 0;
	while (!isdigit(ch)){ if (ch == '-') flag = 1; ch = getchar(); }
	while (isdigit(ch)){ x = x * 10 + ch - '0'; ch = getchar(); }
	return flag ? -x : x;
}

inline void add(int x, int y)
{
	e[++ cnt].to = y; e[cnt].nex = head[x]; head[x] = cnt;
}

inline void dfs(int u, int c)
{
	color[u] = c;
	for (int i = head[u]; i; i = e[i].nex){
		int v = e[i].to;
		if (color[v] == -1) dfs(v, c^1);
		else if (color[v] == c) flag = false;
	}
}

int main()
{
	n = read(), m = read();
	for (int i = 1; i <= m; i ++){
		int x = read(), y = read();
		add(x, y); add(y, x);
	}
	memset(color, -1, sizeof color);
	for (int i = 1; i <= n; i ++)
		if (color[i] == -1) dfs(i, 0);
	long long ans;
	//printf("%d\n", flag);
	if (!flag){
		ans = 1LL*n*(n-1)/2;
		ans -= m; printf("%lld\n", ans);
	} else{
		int sum = 0;
		for (int i = 1; i <= n; i ++)
			if (color[i] == 0) sum ++;
		ans = 1LL*sum*(n-sum);
		ans -= m; printf("%lld\n", ans);
	}
	return 0;
}

