int V,E;

// 頂点を 1 と -1 で塗る深さ優先探索で二部グラフか判定する
bool dfs(int v, int c) {
  // 頂点 v を c で塗る
  color[v] = c;
  for(int i = 0; i < G[v].size(); ++i){
    // 頂点 G[v][i] は既に辺がある隣接頂点で，隣接頂点が同じ色で塗られていたら二部グラフでない
    if(color[G[v][i]] == c) return false;
    // 隣接頂点がまだ塗られておらず，そこを -c で塗ると塗り切れないなら二部グラフでない
    if(color[G[v][i]] == 0 && !dfs(G[v][i], -c)) return false;
  }
  // 塗りきれたら二部グラフ
  return true;
}

// 頂点 i を 1 で塗り始めて二部グラフか判断する
bool bp(){
  for (int i = 0; i < V; ++i){
    // 頂点 i が塗られていなければ 1 で塗り始め，結果を見守る
    if (color[i] == 0){
      if (!dfs(i, 1)) {
        return false;
      }
    }
  }
  return true;
}

int main(){
  cin >> V >> E;
  for(int i = 0; i < E; ++i){
    int s, t;
    cin >> s >> t;
    G[s].push_back(t);
    G[t].push_back(s);
  }
  if(bp){
    // 二部グラフである
    int B = 0, W = 0;
    for(int i = 0; i < V; ++i){
      if(color[i] == 1) ++B;
      if(color[i] == -1) ++W;
    }
    W = V - B;
    cout << B*W - E << endl;
  }else{
    // 二部グラフでない
    cout << V*(V - 1) / 2 - E << endl;
  }
  return 0;
}

