bool hantei(int b,vector<int> &used,vector<int> &c,int p) {
  bool result=true;
  for (int x:g[b]) {
    if (x==p) continue;
    if (c[x]==0) {
      if (c[b]==1) c[x]=2;
      else if (c[b]==2) c[x]=1;
      result=hantei(x,used,c,b);
      if (!result) break;
    }
    else {
      if (used[x]==0) {
        if (c[x]==c[b]) {
          result=false;
          break;
        }
        result=hantei(x,used,c,b);
        if (!result) break;
      }
    }
  }
  used[b]=1;
  return result;
}

