using namespace std;

class UnionFind {
    vector<int> par;
    int n;

public:
    UnionFind(int n) : par(n, -1) {}

    int find(int x) {
        if (par[x] < 0) return x;
        return par[x] = find(par[x]);
    }

    bool unite(int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return false;
        if (par[x] > par[y]) swap(x, y);
        par[x] += par[y];
        par[y] = x;
        return true;
    }

    bool same(int x, int y) {
        return find(x) == find(y);
    }
};

int main() {
    int n, m, a, b;
    cin >> n >> m;

    UnionFind uf(2 * n);

    for (int i = 0; i < m; i++) {
        cin >> a >> b;
        a--; b--;
        uf.unite(a, b+n);
        uf.unite(a+n, b);
    }

    if (uf.same(0, n)) {
        cout << n * (n - 1) / 2 - m << "\n";
    } else {
        int c = 1;
        for (int i = 1; i < n; i++) {
            if (uf.same(0, i)) {
                c++;
            }
        }
        cout << c * (n - c) - m << "\n";
    }

    return 0;
}

