    G[a].push_back(b);
    G[b].push_back(a);
  }

  // 探索
  color.assign(N, -1);
  bool is_bipartite = dfs(G, 0);

  if (is_bipartite) {
    int B = 0, W = 0;
    for (int i = 0; i < N; i++) {
      color[i] == 0 ? B++ : W++;
    }
    cout << B * W - M << endl;
  } else {
    cout << N * (N - 1) / 2 - M << endl;
  }
}

