	inline long long GridWays(int fx, int fy, int sx = 0, int sy = 0)
	{
		fx -= sx, fy -= sy;
		if (fx < 0 || fy < 0)
		{
			return 0LL;
		}
		long long Res = fact[fx + fy];
		Res *= inv[fx];
		Res %= (long long)MODULO;
		Res *= inv[fy];
		Res %= (long long)MODULO;
		return Res;
	}
	long long GreatCD(long long xx, long long yy)
	{
		if (xx > yy)
		{
			swap(xx, yy);
		}
		if (xx == 0LL)
		{
			return yy;
		}
		return GreatCD(yy%xx, xx);
	}
	inline void MMod(long long &xx, int mmod = 0)
	{
		switch (mmod)
		{
		case (0):
			xx %= (long long)MODULO;
			if (xx < 0LL)
			{
				xx += (long long)MODULO;
