int par[250000];
int rank1[250000];
const int Nmax = 100000;
void init(int n)
{
    for(int i = 0; i < n; i++){
        par[i] = i;
        rank1[i] = 0;
    }
}

int find(int x)
{
    if(par[x] == x){
        return x;
    } else {
        return par[x] = find(par[x]);
    }
}

void unite(int x, int y)
{
    x = find(x);
    y = find(y);
    if(x == y){
        return ;
    }
    if(rank1[x] , rank1[y]){
        par[x] = y;
    } else {
        par[y] = x;
        if(rank1[x] == rank1[y]){
            rank1[x]++;
        }
    }
}

bool same(int x, int y)
{
    return find(x) == find(y);
}

int main() {
    //cout.precision(10);
    long long n, m;
    cin >> n >> m;
    init(240000);
    for(int i = 0; i < m; i++){
        int a, b;
        cin >> a >> b;
        unite(a, b + Nmax);
        unite(a + Nmax, b);
    }
    for(int i = 0; i <= 2 * Nmax; i++){
        find(i);
    }
    bool checker = true;
    for(int i = 1; i <= n; i++){
        if(!same(1, i)){
            checker = false;
        }
    }
    if(checker){
        cout << n * (n - 1) / 2 - m << endl;
        return 0;
    }
    long long number[2];
    number[0] = 0;
    number[1] = 0;
    for(int i = 1; i <= n; i++){
        if(same(1, i)){
            number[0]++;
        } else {
            number[1]++;
        }
    }
    cout << number[0] * number[1] - m << endl;
    return 0;
}

