vector< vector<int> > gra;
set<pair<int,int> > edge;
vector<bool> visit;
LL ANS = 0;

bool dfs(int root,int depth,int v){
	if( depth == 2 ){
		int a = root;
		int b = v;
		if( a>b ){
			swap(a,b);
		}
		if( edge.find(pair<int,int>(a,b) ) != edge.end() ){
			return false;
		}
	}
	if( depth == 3 ){
		int a = root;
		int b = v;
		if( a>b ){
			swap(a,b);
		}
		if( edge.find(pair<int,int>(a,b) ) != edge.end() ){
			//辺がある。
		}else{
			gra[a].push_back(b);
			gra[b].push_back(a);
			++ANS;
			edge.insert(pair<int,int>(a,b) );
			//cout << "追加" << a << " " << b << endl;
		}
		return true;//続行で終了
	}

	visit[v] = true;
	int size = gra[v].size();
	for(int i=0;i<size;++i){
		int to = gra[v][i];
		if( visit[to] == false ){
			bool res = dfs(root,depth+1,to);
			if( res == false ){
				return res;
			}
		}
	}

	//visit[v] = false;

	return true;
}
void solve(){
	int N,M;
	cin >> N >> M;
	gra = vector< vector<int> >(N);
	vector< vector< edge_base > > G(N);
	for(int i=0;i<M;++i){
		int u,v;
		cin >> u >> v;
		--u;--v;
		gra[u].push_back(v);
		gra[v].push_back(u);
		if( u>v ){
			swap(u,v);
		}
		edge.insert( pair<int,int>(u,v) );
		G[u].push_back( make_edge_base(v,1) );
		G[v].push_back( make_edge_base(u,1) );
	}
	///////////////
	//3以上の奇数ループを探す

	int root = 0;
	priority_queue<pair<LL,int>,vector<pair<LL,int> >,
		greater<pair<LL,int> > > que;
	vector<LL> dist(N,LINF);
	dist[root] = 0;
	que.push(pair<LL,int>(0,root));//距離、頂点番号

	int flag = 0;
	while( que.size() ){
		pair<LL,int> p = que.top();que.pop();
		int v = p.second;
		if( dist[v] < p.first ){
			int res = (p.first -dist[v]);//ループの距離
			if( res>=3 && res&1 ){
				flag = res;
				break;
			}
			continue;
		}
		for(int i=0;i < (int)G[v].size();++i){
			edge_base e = G[v][i];
			if( dist[e.to] > dist[v] + e.cost ){
				dist[e.to] = dist[v] + e.cost;
				que.push(pair<LL,int>(dist[e.to],e.to));
			}
		}
	}
	if( flag ){
		LL temp = N;
		cout << temp*(temp-1)/2 - M << endl;
		return;
	}
	////////////////
	int  LOOP = 2;
	while(LOOP--)
	{
	for(int i=0;i<N;++i){
		visit.assign(N,false);
		bool res = dfs(i,0,i);
		if( res == false ){
			LL temp = N;
			cout << temp*(temp-1)/2 - M << endl;
			return;
		}
	}
	}

	cout << ANS << endl;
}

