bool dfs(mat G,ll v,ll cur = 0) {
  color[v] = cur;
  for(auto next_v : G[v]) {
    // 隣接頂点がすでに色確定していた場合
    if (color[next_v] != -1) {
      if (color[next_v] == cur) return false; // 同じ色が隣接したらダメ
      continue;
    }

    // 隣接頂点の色を変えて、再帰的に探索 (一回でも false が返ってきたら false)
    if (!dfs(G, next_v , 1 - cur)) return false;
  }
  return true;
}

