int N, M;
vector<vector<int>>E;
vector<char>used;
ll ans2 = 0;

int status[100000];
int cost[100000];
void dijkstra(int s) {
	for (int i = 0; i < N; i++) {
		status[i] = 0;
		cost[i] = 1e9; 
	}
	cost[s] = 0;
	status[s] = 1;

	priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>>U;
	U.push(make_pair(cost[s], s));
	while (!U.empty()) {
		//探索が終わってない中でコスト最小の点
		int u = U.top().second; U.pop();

		if (status[u] == -1) continue;

		status[u] = -1;

		//コスト最少の点を探る
		for (int j = 0; j < E[u].size(); j++) {
			//if (used[E[u][j]])continue;
			if (cost[E[u][j]] > cost[u] + 1) {
				cost[E[u][j]] = cost[u] + 1;
				if (cost[E[u][j]] == 3) {
					E[s].push_back(E[u][j]);
					E[E[u][j]].push_back(s);
					cost[E[u][j]] = 1;
					ans2++;
				}

				status[E[u][j]] = 1;
				U.push(make_pair(cost[E[u][j]], E[u][j]));
			}
		}
	}
}

int main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	cin >> N >> M;
	E.resize(N);
	used.resize(N);
	for (int i = 0; i < M; i++) {
		int a, b; cin >> a >> b;
		a--; b--;
		E[a].push_back(b);
		E[b].push_back(a);
	}


	long long ans = 0;

	if (M == N - 1) {
		for (int i = 0; i < N; i++) {
			dijkstra(i);
		}
		cout << ans2 << endl;
	}
	else {
		for (int i = 0; i < N; i++)ans += i;
		cout << ans - M << endl;
	}

    return 0;
}

