const int MAX = 100100;

vector<int> E[MAX];
int d[MAX];

void dfs(int x) {
  for (int y: E[x]) {
    if (d[y] == 0) {
      d[y] = d[x] + 1;
      dfs(y);
    }
  }
}

int main(void) {
  int N, M;
  scanf("%d %d", &N, &M);
  REP(i, M) {
    int a, b;
    scanf("%d %d", &a, &b); --a, --b;
    E[a].push_back(b);
    E[b].push_back(a);
  }

  d[0] = 1;
  dfs(0);

  int cnt1 = 0;
  REP(i, N) {
    if (d[i]%2) cnt1++;
  }

  bool odd_cycle = false;
  REP(x, N) for (int y: E[x]) {
    if ((d[x] + d[y]) % 2 == 0) {
      odd_cycle = true;
    }
  }

  llint total = 0;
  if (odd_cycle) {
    total = N * 1LL * (N - 1) / 2;
  } else {
    total = cnt1 * 1LL * (N - cnt1);
  }

  total -= M;
  printf("%lld\n", total);
  return 0;
}

