using Graph = vector<vector<int>>;

const ll TARGET = 100000;

int res = 0;

void dfs(Graph &g, unordered_set<ll> &connected, int depth, int from, int via,
         int to) {
  ll key = max(to, from) * TARGET + min(to, from);

  if (depth == 3) {
    if (connected.count(key)) {
      // cout << from << " - " << to << " connected,";
      return;
    }

    // cout << "connect " << from << " - " << to << endl;

    g.at(from).push_back(to);
    g.at(to).push_back(from);
    connected.insert(key);

    res++;
    return;
  }

  for (int i = 0; i < g.at(to).size(); i++) {
    int n = g.at(to).at(i);

    if (via == n || from == n) {
      continue;
    }

    // cout << from << " -> " << to << " -> " << n << " @ " << depth + 1 <<
    // endl;
    dfs(g, connected, depth + 1, from, to, n);
  }
}

bool isBipartite(Graph &g, vector<int> &colors) {
  colors.resize(g.size());
  colors.assign(g.size(), -1);

  struct Node {
    int number;
    int color;
  };

  stack<Node> s;
  s.push(Node{number : 0, color : 0});

  while (!s.empty()) {
    auto node = s.top();
    s.pop();

    colors.at(node.number) = node.color;

    for (int i = 0; i < g[node.number].size(); i++) {
      auto next = g[node.number].at(i);

      if (colors[next] == node.color) {
        return false;
      }

      if (colors[next] != -1) {
        continue;
      }

      s.push(Node{number : next, color : 1 - node.color});
    }
  }

  return true;
}

int main() {
  int N, M;
  cin >> N >> M;

  Graph g(N);
  unordered_set<ll> connected;
  for (int i = 0; i < M; i++) {
    int a, b;
    cin >> a >> b;
    a--;
    b--;
    g.at(a).push_back(b);
    g.at(b).push_back(a);

    ll key = max(a, b) * TARGET + min(a, b);
    connected.insert(key);
  }

  // 愚直にDFSで繋ぐとTLE
  // for (int i = 0; i < N; i++) {
  //   dfs(g, connected, 0, i, i, i);
  // }

  // cout << res << endl;

  vector<int> colors;

  if (isBipartite(g, colors)) {
    int B = 0, W = 0;

    for (int i = 0; i < colors.size(); i++) {
      if (colors[i] == 0) {
        B++;
      } else {
        W++;
      }
    }

    if (B + W < N) {
      cout << g.at(N * 2)[0];
    }

    cout << B * W - M << endl;

  } else {
    cout << N * (N - 1) / 2 - M << endl;
  }
}

