class Node {
public:
	int type;
	vector<int> childs;
	Node() {
		type = -1;
	}
};

vector<Node> nodes;

bool dfs(int now, int prev, int val) {
	if (nodes[now].type == -1) {
		nodes[now].type = val;
	} else {
		return nodes[now].type == val;
	}

	for (int next : nodes[now].childs) {
		if (next == prev) continue;
		bool flag = dfs(next, now, 1 - val);
		if (!flag) return false;
	}

	return true;
}

