bool bfs( int s ) {

    Color[s] = 1;

    queue<int> Q;

    for ( int i = 0; i < P[s].size(); i++ ) {
        Q.push(P[s][i]);
        Color[P[s][i]] = 0;
    }

    while ( !Q.empty() ) {        
        int c = Q.front();
        Q.pop();

        int color = 1-Color[c];

        for ( int i = 0; i < P[c].size(); i++ ) {
            int n = P[c][i];

            if ( Color[n] != -1 && Color[n] != color ) { return false; }
            if ( Color[n] == -1 ) { Q.push(n); }
            Color[n] = color;
        }

    }

    return true;
}

bool dfs( int v, int pre, int color ) {

    Color[v] = color;
    bool ret = true;

    for ( int i = 0; i < P[v].size(); i++ ) {
        int n = P[v][i];

        if ( n == pre ) { continue; }
        if ( Color[n] == 1-color ) { continue; }
        if ( Color[n] != -1 && Color[n] != 1-color ) { return false; }        

        bool t = dfs( n, v, 1-color );
        if ( !t ) { ret = t; }
    }

    return ret;
}



