vector<int> g[101010];

int color[101010]; //must be initialized to -1
int bipartite_graph(int v, int prev, int c) {
        color[v] = c;
        int cnt = c;
        bool ok = true;
        for (auto u : g[v]) if (u != prev) {
                if (color[u] == -1) {
                        int get = bipartite_graph(u, v, 1 - c);
                        if (get == -1) ok = false;
                        cnt += get;
                } else if (color[u] != 1 - c) {
                        ok = false;
                }
        }
        if (!ok) return -1;
        return cnt;
}

