      if (visited[p] == 1) count++;
      for (const auto &e : g.adj[p]) {
        if (visited[e.dst] == -1) {
          visited[e.dst] = (visited[p] + 1) % 2;
          container.push(e.dst);
        }
      }
    }
    cout << count * (N - count) - M << endl;
  } else {
