int is_bipartite(Graph &G) {
    int n = G.size();
    vector<int> color(n, -1);
    int cntW = 0;
    function<bool(int, int)> dfs = [&](int u, int c) {
        if ((color[u] = c) > 0) cntW++;
        for (Edge &e : G[u]) {
            int v = e.dst;
            if (color[v] == c) return false;
            if (color[v] < 0 && !dfs(v, 1 - c)) return false;
        }
        return true;
    };
    if (!dfs(0, 0)) return -1;
    return cntW;
}

int main() {
    int V, E; cin >> V >> E;
    Graph G(V);
    for (int i = 0; i < E; i++) {
        int a, b; cin >> a >> b;
        G.add_edge(a - 1, b - 1);
    }
    int cntW = is_bipartite(G);
    if (cntW < 0) {
        cout << ((long long)V * (V - 1) / 2 - E) << endl;
    } else {
        int cntB = V - cntW;
        cout << ((long long)cntB * cntW - E) << endl;
    }
    return 0;
}

