vector<ll> coloring(const vector<vector<ll>>& G) {
    const ll n = G.size();
    vector<ll> color(n, -1);
    queue<ll> Q;
    Q.push(0);
    color[0] = 0;
    while ( !Q.empty() ) {
        ll v = Q.front(); Q.pop();
        each(to, G[v]) {
            if (color[to] < 0) {
                color[to] = 1-color[v];
                Q.push(to);
            }
            else if (color[to] != 1-color[v]) {
                throw -1;
            }
        }
    }
    return color;
}
