int main()
{
    scanInt(N);
    scanInt(M);
    vector<unordered_map<int, ll>> edges(N);
    loop(i, M){
        scanInt(Ai); --Ai;
        scanInt(Bi); --Bi;
        edges[Ai].emplace(Bi, 1);
        edges[Bi].emplace(Ai, 1);
    }
    // vector<pair<char, char>> flags(N, make_pair(false, false));
    // flags[0].first = true;
    bool all_flag = false;

    /* 木構造を作る */
    struct Node {
        int parent = -1; // 親ノードのi
        ll distance = -1; // 根からの距離
        vector<int> children; // 子ノード（複数）のi
    };
    vector<Node> nodes(N); // 各ノード（木構造）
    array<int, 2> count = {0, 0};
    function<void(int, ll)> makeTree = [&](int n, ll dist){ // 頂点n以下の木構造を作る
        if (all_flag) return;
        nodes[n].distance = dist;
        ++count[dist % 2];
        for (auto& e : edges[n]){
            auto& next = e.first;
            if (next == nodes[n].parent) continue; // 親に戻らない
            // if (nodes[next].distance != -1 || 0 < nodes[next].children.size()) continue; // 余分な辺がある場合は、既に訪れた頂点を弾く処理をする
            if (nodes[next].distance != -1){ // 余分な辺がある場合
                if (nodes[n].distance % 2 == nodes[next].distance % 2){ // 偶奇不一致
                    all_flag = true;
                    break;
                }else{
                    continue;
                }
            }
            nodes[n].children.emplace_back(next);
            nodes[next].parent = n;
            makeTree(next, dist + e.second);
        }
    };
    const int R = 0; // 根
    nodes[R].parent = -1; // 根の親は適当に入れておく
    makeTree(R, 0); // 根（距離0）から始める
    if (all_flag){
        printf("%lld\n", static_cast<ll>(N) * (N - 1) / 2 - M);
    }else{
        printf("%lld\n", static_cast<ll>(count[0]) * count[1] - M);
    }
}

