struct Graph
{
    ll n,m,a,b;
    vector<ll> v[MAX];
    ll c[MAX]={};
    ll odd=0;
    ll even=0;
    bool flag=false;//false<->2部ぐらふ

    void input()
    {
        cin>>n>>m;
        for(ll i=0;i<m;i++)
        {
            cin>>a>>b;
            v[a].push_back(b);
            v[b].push_back(a);
        }
    }

    void dfs(ll x,ll col)
    {
        if(flag) return;
        for(ll i=0;i<v[x].size();i++)
        {
            ll y=v[x][i];
            if(c[y]==0)
            {
                c[y]=col;
                if(col==1) even++;
                    else       odd++;
                dfs(y,-1*col);
            }
            else if(c[y]!=col)
            {
                flag=true;break;
            }
        }
    }

    void solve()
    {
        dfs(1,1);
        ll ans;
        if(flag) ans=(n*(n-1))/2-m;
        else     ans=odd*even-m;

        cout<<ans<<endl;
    }

};

