bool dfs(int v, int c) {
  colors[v] = c;
  for (const auto& n : G[v]) {
    if (colors[n] == c) return false;
    if (colors[n] == 0 && !dfs(n, -c)) return false;
  }
  return true;
}

bool is_bipartite_graph() {
  for (int i = 1; i <= N; ++i) {
    if (colors[i] == 0) {
      if (!dfs(i, 1)) {
        return false;
      }
    }
  }
  return true;
}

