    G[B].push_back(A);
  }

  if (is_bipartite_graph()) {
    LL cnta = 0, cntb = 0;
    for (int i = 1; i <= N; ++i) {
      if (colors[i] < 0) ++cnta;
      else       ++cntb;
    }
    cout << cnta*cntb - M << endl;
  } else {
    cout << N*(N-1LL)/2LL - M << endl;
  }
}

