ll solve(ll N, ll M, vi& a, vi& b) {
    if (N <= 3) return 0;

    vvi next(N);
    rep(i,M) {
        next[a[i]].pb(b[i]);
        next[b[i]].pb(a[i]);
    }

    vi side(N, -1);
    queue<ii> q;
    q.emplace(0, 0);
    while (!q.empty()) {
        ii t = q.front(); q.pop();
        int n = t.first, s = t.second;
        if (side[n] == -1) {
            side[n] = s;

            for (int ch : next[n]) {
                q.emplace(ch, 1-s);
            }
        } else {
            if (side[n] != s) {
                return N*(N-1)/2 - M;
            }
        }
    }
    vll st(2, 0);
    rep(i,N) st[side[i]]++;
    return st[0] * st[1] - M;
}

int main() {
    int N, M; scanf("%d%d", &N, &M);
    vi a(M), b(M);
    rep(i,M) {
        scanf("%d%d", &a[i], &b[i]);
        --a[i]; --b[i];
    }
    cout << solve(N,M,a,b) << endl;
    return 0;
}

