bool binary_graph(UG es){
  vector<int> b(es.size());
  b[0]=1;
  queue<int> q;
  q.push(0);
  while(!q.empty()){
    int x=q.front();
    q.pop();
    for(auto e:es[x]){
      if(b[e]==0){
        b[e]=-1*b[x];
        q.push(e);
      }
      else if(b[e]*b[x]==1)
        return false;
    }
  }
  return true;
}

