bool dfs(ll u, vector<ll> &graph, vector<vector<ll>> &side) {
  ll Gu = graph.at(u);
  for(ll i = 0; i < side.at(u).size(); i++) {
    ll v = side.at(u).at(i);
    if(graph.at(v) != -1) {
      if(graph.at(v) == Gu) return false;
      continue;
    }
    graph.at(v) = abs(graph.at(u) - 1);
    if(!dfs(v, graph, side)) return false;
  }
  return true;
}

