    cin >> a >> b;
    --a, --b;
    uf.unite(a, b + n);
    uf.unite(b, a + n);
  }
  if(uf.same(0, n)) {
    cout << (n * (n-1) >> 1) - m << endl;
  } else {
    int cnt = 0;
    for(int i = 0;i < n; ++i) {
      if(uf.same(0, i)) ++cnt;
    }
    cout << cnt * (n - cnt) - m;
  }
  return 0;
}

