void bfs() {
    visited = vector<bool>(n);
    queue<int> que;
    for (auto x:graph[0])que.push(x);
    que.push(-1);
    int depth = 1;
    while (true) {
        int next = que.front();
        que.pop();
        if (next == -1) {
            if (que.empty())break;
            depth++;
            que.push(-1);
        } else {
            if (depth % 2 == 1)visited[next] = true;
            for (auto x:graph[next])
                if (!visited[x])que.push(x);
        }
    }
}

