using graph = VVI;

void dfs(const graph &g, int node, int parity) {
	auto conn = g[node];
	for (auto to : conn) {
		if (flag[to] & (1 << parity))continue;
		cnt[parity]++;
		flag[to] |= (1 << parity);
		dfs(g, to, 1 - parity);
	}
	return;
}

