int main(){
  long long int N, M;
  cin >> N >> M;
  vector< vector<int> > G(N);
  for(int i = 0; i < M; ++i){
    int a, b;
    cin >> a >> b;
    --b;--a;
    G[a].push_back(b);
    G[b].push_back(a);
  }
  vector<int> C(N, 0);
  C[0] = 1;
  bool f = true;
  queue<int> wait;
  wait.push(0);
  while(!wait.empty()){
    int i = wait.front();
    wait.pop();
    for(int j = 0; j < G[i].size(); ++j){
      int v = G[i][j];
      if(!C[v]){
        C[v] = -C[i];
        wait.push(v);
      }else if(C[v] != -C[i]){
        f = false;
        break;
      }
    }
    if(!f) break;
  }
  if(f){
    long long int c = 0;
    for(int i = 0; i < N; ++i){
      if(C[i] > 0) ++c;
    }
    cout << c*(N-c) - M << endl;
  }else cout << N*(N-1)/2 - M << endl;
  return 0;
}

