void dfs(int pos)
{
	d[pos][0] = true;
	queue< pair<int, int> > q;
	q.push({pos, 0});
	vis[pos][0] = 1;
	while (q.size())
	{
		int u = q.front().first, l = q.front().second;
		q.pop();
		for (int i = 0; i < a[u].size(); i++)
		{
			int v = a[u][i];
			if (!vis[v][(l+1)%2])
			{
				vis[v][(l+1)%2] = 1;
				d[v][(l+1)%2] = true;
				q.push({v, (l+1)%2});
			}
		}
	}
}

