//N点連結グラフの二部グラフ判定
//Gはグラフの隣接リスト表現
//colorは大きさNの配列。二部グラフだったとき、独立集合がここに返ってくる
//vは探索を始める点。cは探索を始める点に塗る色
//vと同じ独立集合に含まれる点はcに塗られ、そうでない点は-cに塗られる
//colorは先に0で埋めておく
vector<int> color;
bool is_bipartite_graph (vector<vector<int>> G, int v, int c){
    color[v] = c;
    for (int next_v : G[v]){
        if(color[next_v] == 0 && !is_bipartite_graph(G, next_v, -c)){
            return false;
        }
        else if(color[next_v] == c){
            return false;
        }
    }
    return true;
}


int main(){
    int N, M;
    cin >> N >> M;
    vector<vector<int>> G(N);
    int x, y;
    for (int i = 0; i < M; i++) {
        cin >> x >> y; x--; y--;
        G[x].push_back(y);
        G[y].push_back(x);
    }

    color.resize(N);
    fill(ALL(color), 0);    
    if(is_bipartite_graph(G, 0, 1)){
        int a, b;
        a = 0; b = 0;
        for (int i = 0; i < N; i++) {
            if(color[i] == 1){
