constexpr i64 max_loop = 100;

void solve() {
    //constexpr i64 mod = 1'000'000'007;
    i64 N,M;
    cin >> N >> M;
    vector<i64> A(M),B(M);
    rep(i,0,M){
        cin >> A[i] >> B[i];
        --A[i];
        --B[i];
    }

    vector<vector<i64>> g(N);
    rep(i,0,M){
        g[A[i]].emplace_back(B[i]);
        g[B[i]].emplace_back(A[i]);
    }

    vector<i64> color(N,-1);
    function<bool(i64,i64)> dfs=[&](i64 u,i64 c){
        if(color[u]==-1) color[u]=c;
        else return color[u]==c;

        for(i64 v:g[u]){
            if(!dfs(v,1-c)) return false;
        }
        return true;
    };

    if(dfs(0,0)){
        // 二部グラフ
        vector<i64> cnt(2);
        rep(i,0,N) ++cnt[color[i]];
        i64 ans=cnt[0]*cnt[1]-M;
        cout << ans << endl;
    }else{
        cout << N*(N-1)/2-M << endl;
    }
}

