int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);

	cin >> N >> M;
	vector<vector<int>>edge(N + 1);
	vector<bool>loop(N + 1, false);
	for (int i = 0; i < M; i++) {
		cin >> L >> R;
		edge[L].push_back(R);
		edge[R].push_back(L);
	}
	vector<int>dis(N + 1, INT_MAX);
	dis[1] = 0;
	queue<int>Q;
	Q.push(1);
	while (!Q.empty()) {
		int cn = Q.front();
		int c = dis[cn];
		Q.pop();
		for (auto i : edge[cn]) {
			if (dis[i] > c + 1) {
				dis[i] = c + 1;
				Q.push(i);
			}
		}
	}
	bool complete = false;
	for (int i = 1; i <= N; i++) {
		for (auto j : edge[i]) {
			if (dis[i] % 2 == dis[j] % 2) {
				complete = true;
			}
		}
	}
	long long int odd = 0, even = 0;
	for (int i = 1; i <= N; i++) {
		if (dis[i] % 2) {
			odd++;
		}
		else {
			even++;
		}
	}
	if (complete) {
		cout << N*(N - 1) / 2 - M << endl;
	}
	else {
		cout << odd*even - M << endl;
	}
