int getdepth(vector<int> &depth, vector<vector<int>> &edges){
    int n = edges.size();
    int husai = 0;
    depth[0] = 0;
    queue<pair<int,int>> q;
    q.push(make_pair(0, -1));
    int parent = -1;
    int accum_odd = 0;
    int accum_even = 0;
    int ret = 0;

    while(!q.empty()){
        auto t = q.front();
        q.pop();
        int now = t.first;
        int parent = t.second;

        if(depth[now]%2==0){
            ret += max(0LL, accum_odd - 1);
            accum_even++;
        }
        else{
            ret += max(0LL, accum_even-1);
            accum_odd++;
        }
        for(int e: edges[now]){
            if(e == parent)
                continue;
            else if(depth[e] != -1 && (depth[now] - depth[e])%2==0){
                return -1;
            }
            else if(depth[e] != -1 && depth[now] - depth[e] > 1){
                husai++;
            }
            else if(depth[e] != -1 && depth[now] - depth[e] == 1)
                continue;
            else{
                depth[e] = depth[now] + 1;
                q.push(make_pair(e, now));
            }
        }
    }
    return ret - husai;
}

signed main(){
    int n, m;
    cin >> n >> m;
    vector<vector<int>> edges(n);
    for(int i=0;i<m;i++){
        int a, b;
        cin >> a >> b;
        a--, b--;
        edges[a].push_back(b);
        edges[b].push_back(a);
    }

    vector<int> depth(n, -1);

    int ret = getdepth(depth, edges);

    cout << (ret==-1?(n*(n-1)/2-m):ret) << endl;

    return 0;
}

