const int N = 100002;

vector<int> g[N];
int part[N];

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    memset(part, 255, sizeof(part));

    int n, m;
    cin >> n >> m;

    for (int i = 0; i < m; i++) {
        int a,b;
        cin >> a >> b;
        a--;
        b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    if (n < 4) {
        cout << 0 << endl;
        return 0;
    }

    list<int> q;
    q.push_back(0);
    part[0] = 0;

    bool is2 = true;
    while (q.size() != 0 && is2) {
        int curr = q.front();
        q.pop_front();
        for (int j = 0; j < g[curr].size(); j++) {
            int next = g[curr][j];
            if (part[next] == -1) {
                part[next] = 1 - part[curr];
                q.push_back(next);
            } else {
                if (part[next] != (1 - part[curr])) {
                    is2 = false;
                    break;
                }
            }
        }
    }

    if (is2) {
        int cnt1 = 0;
        for (int i = 0; i < n; i++) {
            cnt1 += part[i];
            if (part[i] == -1) {
                cerr << i << " failed!" << endl;
            }
        }
        int cnt0 = n - cnt1;
        cout << (1LL * cnt0 * cnt1 - m) << endl;
    } else {
        cout << (1LL * n * (n-1) / 2 - m) << endl;
    }

    return 0;
}

