// -1,0,1のいずれか. 0は未着色
bool isbipartite(int v, int par, int color, vector<int> &data, const graph &g) {
  if (data[v] != 0)
    if (data[v] != color) {
      return false;
    } else {
      return true;
    }
  data[v] = color;
  for (auto u : g[v]) {
    if (u == par)
      continue;
    if (!isbipartite(u, v, -color, data, g))
      return false;
  }
  return true;
}

