bool bip_con(int s, vvi &g, vi &dis) {
	queue<int> q;
	dis[s] = 0; q.push(s);
	while (!q.empty()) {
		int u = q.front(); q.pop();		
		for (int v : g[u]) {			
			if (dis[v] == -1) {
				q.push(v); dis[v] = dis[u] + 1;
			} else if (dis[v] - dis[u] % 2 == 0) return false;
		}
	}
	return true;
}
bool bip(vvi &g, vi &dis) {
	rep(s, g.size()) if (dis[s] == -1 and !bip_con(s, g, dis)) return false;
	return true;
}

