		g[A[i]].push_back(B[i]); g[B[i]].push_back(A[i]);
	}	
	vi dis(N, -1);
	bool res = bip_con(0, g, dis);	
	if (res) {
		ll E = 0, O = 0;
		rep(i, N) if (dis[i] % 2 == 0) E++; else O++;
		ll ans = E * O;
		rep(i, M) if ((dis[A[i]] - dis[B[i]]) % 2 != 0) ans--;
		cout << ans << endl;
	} else {
		dbs(N, M, N * (N - 1) / 2);
		cout << N * (N - 1) / 2 - M << endl;
	}	
}

