const size_t MAX_N = 1e5 + 5;

int par[MAX_N << 1], sz[MAX_N << 1], n, m;

inline int getPar(int x) {
    return par[x] = (par[x] - x ? getPar(par[x]) : x);
}

inline void Union(int x, int y) {
    x = getPar(x); y = getPar(y);
    par[y] = x; sz[x] += sz[y];
}

int main() {
    scanf("%d%d", &n, &m);
    for (int i = 1, _ = n << 1; i <= _; ++i) {
        par[i] = i;
        sz[i] = (i <= n);
    }
    for (int i = 0, a, b; i < m; ++i) {
        scanf("%d%d", &a, &b);
        if (getPar(a) == getPar(b) || getPar(a + n) == getPar(b + n)) 
            return cout << 1LL * n * (n - 1) / 2 - m, 0;
        Union(a, b + n);
        Union(b, a + n);
    }
    long long res = 1;
    for (int i = 1, _ = n << 1; i <= _; ++i)
        if (getPar(i) == i) res *= sz[i];
    return cout << res - m, 0;
}

