}

long long solve(long long N, long long M, const vector<vector<int>> & Es, const vector<pair<int, int>> & edges){
    vector<int> color(N, 0);
    color[0] = 1;
    dfs(0, color, Es);
    bool all_connected = false;
    for (auto &edge : edges){
        int v = edge.first;
        int u = edge.second;
        if (color[v] == color[u]){
            all_connected = true;
            break;
        }
    }
    if (all_connected){
        return N * (N - 1)/ 2 - M;
    }else{
        long long N1 = 0;
        long long N2 = 0;
        for (int i = 0; i < N; ++i){
            if (color[i] == 1){
                ++N1;
            }else{
                ++N2;
            }
        }
        return N1 * N2 - M;
    }
}



