void dfs(int u, int sum, int fa) {
    if(sum > 3)
        return;
    if(sum == 3) {
        if(!mark[u]) {
            answer++;
            flag = true;
            mark[u] = true;
            maps[fa].push_back(u);
            maps[u].push_back(fa);
        }
        return;
    }
    for(int i=0; i<Size(maps[u]); i++) {
        int v = maps[u][i];
        if(visit[v])
            continue;
        visit[v] = true;
        dfs(v, sum+1, fa);
        visit[v] = false;
    }
}

