const int N=100005;
bitset<N> map[N];
int dis[N];
int ans,m,n,x,y;
char ind[N];

void bfs(int s)
{
	queue<int> q;
	q.push(s);map[s].set(s);
	memset(dis,0,sizeof(dis));
	memset(ind,0,sizeof(ind));
	dis[s]=0,ind[s]=1;
	while(!q.empty())
	{
		int u=q.front();q.pop();ind[u]=0;
		for(int i=map[u]._Find_next(0);i<=n;i=map[u]._Find_next(i))
		{
			int v=i;
			if(v==s||v==u)    continue;
			dis[v]=dis[u]+1;
			if(dis[v]==3&&!map[s].test(i))
			{
				map[i].set(s);
				map[s].set(i),ans++;//printf("%d %d\n",s,i);
			}
			else	if(dis[v]<3&&!ind[v])	ind[v]=1,q.push(v);
		}
	}
} 

void solve()
{
	for(int i=1;i<=n;++i)
		bfs(i);
	printf("%d\n",ans);	
}

