inline int read()
{
	int x=0,f=1;char ch=getchar();
	while(ch<'0'||ch>'9'){if(ch=='-')f=-1;ch=getchar();}
	while(ch>='0'&&ch<='9'){x=x*10+ch-'0';ch=getchar();}
	return x*f;
}
void add_edg(int x,int y)
{
	e_sum++;
	e[e_sum].next=first[x];
	first[x]=e_sum;
	e[e_sum].to=y;
}

void dfs(int x)
{
	cnt[col[x]]++;
	for(int i=first[x];i;i=e[i].next)
	{
		int w=e[i].to;
		if(!col[w]) col[w]=3-col[x],dfs(w);
		else if(col[w]==col[x]) flag=1;
	}
}

int main()
{
	n=read();m=read();
	for(int i=1;i<=m;i++)
	{
		int x=read(),y=read();
		add_edg(x,y);add_edg(y,x);
	}
	for(int i=1;i<=n;i++)
		if(!col[i])
		{
			cnt[1]=cnt[2]=0;
			col[i]=1;flag=0;
			dfs(i);
			if(flag) ans+=1ll*(cnt[1]+cnt[2])*(cnt[1]+cnt[2]-1)/2;
			else ans+=1ll*cnt[1]*cnt[2];
