const int maxn = 100005;

struct Edge {
    int v, x;
} E[maxn*2];

int l[maxn], e, n, m;
typedef long long ll;

void init() {
    memset(l, -1, sizeof(l)); e = 0;
}

inline void insert(int u, int v) {
    E[e].v = v, E[e].x = l[u], l[u] = e++;
    E[e].v = u, E[e].x = l[v], l[v] = e++;
}

int cr[maxn][2];
int vis[maxn];

int cnt[2];

void cal(int u) {
    queue<pair<int, int> > q;
    cnt[0] = cnt[1] = 0;
    memset(cr, 0, sizeof(cr));
    cr[u][0] = 1;
    q.push(make_pair(u, 0));
    while (!q.empty()) {
        pair<int, int> f = q.front(); q.pop();
        for (int p = l[f.first]; p >= 0; p = E[p].x) {
            if (!cr[E[p].v][!f.second]) {
                cr[E[p].v][!f.second] = 1;
                q.push(make_pair(E[p].v, !f.second));
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        if (cr[i][0]) cnt[0]++;
        if (cr[i][1]) cnt[1]++;
    }
}

ll ans = 0;

int tmp = 0;

void dfs(int u) {
    vis[u] = 1;
    ans += cnt[tmp^1];
    if (cr[u][tmp^1]) ans--;
    for (int p = l[u]; p >= 0; p = E[p].x) {
        if (!vis[E[p].v]) {
            vis[E[p].v] = 1;
            tmp = tmp^1;
            dfs(E[p].v);
            tmp = tmp^1;
        }
    }
}

int main() {
    init();
    scanf("%d%d", &n, &m);
    for (int i = 1; i <= m; i++) {
        int a, b;
        scanf("%d%d", &a, &b);
        insert(a, b);
    }
    for (int i = 1; i <= n; i++) {
        if (!vis[i]) {
            tmp = 0;
            cal(i);
            dfs(i);
        }
    }
    cout << ans/2-m << endl;
    return 0;
}

