template<typename T> class graph {
public :
    struct edge {
        int to;
        T cost;
        edge(int t, T c) : to(t), cost(c) {}
    };

    struct edge2 {
        int from, to;
        T cost;
        edge2(int f, int t, T c) : from(f), to(t), cost(c) {}
    };

    vector<vector<edge>> g;
    vector<edge2> edges;
    int n;
    graph(int n) : n(n) {
        g.resize(n);
    }
    virtual void add(int from, int to, T cost) = 0;
};

template<class T=int> class undigraph : public graph<T> {
public:
    using graph<T>::g;
    using graph<T>::n;
    using graph<T>::edges;
    undigraph(int n) : graph<T>(n) {
    }
    void add(int f, int t, T cost = 1) {
        assert(0 <= f && f < n && 0 <= t && t < n);
        g[f].emplace_back(t, cost);
        g[t].emplace_back(f, cost);
        edges.emplace_back(f, t, cost);
        edges.emplace_back(t, f, cost);
    }
};

template<typename T =ll> class digraph : public graph<T> {
public:
    using graph<T>::g;
    using graph<T>::n;
    using graph<T>::edges;
    digraph(int n) : graph<T>(n) {
    }
    void add(int f, int t, T cost = 1) {
        assert(0 <= f && f < n && 0 <= t && t < n);
        g[f].emplace_back(t, cost);
        edges.emplace_back(f, t, cost);
    }
};
template<class T> bool nibu(const graph<T> &g) {
    UnionFind uf(g.n * 2);
    for (auto &&e :g.edges)uf.unite(e.from, e.to + g.n), uf.unite(e.from + g.n, e.to);
    return uf.same(0, g.n);
}
template<class T> vector<T> dijkstra(const graph<T> &g, int s) {
    assert(inc(0, s, g.n));
    vector<T> dis(g.n, MAX(T));
    priority_queue<pair<T, int>, vec<pair<T, int>>, greater<pair<T, int>>> q;
    dis[s] = 0;
    q.emplace(0, s);
    while (q.size()) {
        T nowc = q.top().F;
        int i = q.top().S;
        q.pop();
        if (dis[i] != nowc)continue;
        for (auto &&e  : g.g[i]) {
            int to = e.to;
            T cost = nowc + e.cost;
            if (dis[to] > cost) {
                dis[to] = cost;
                q.emplace(dis[to], to);
            }
        }
    }
    return dis;
}
