int idx[3000100];
long long res;
int ee1[3000100];
int ee2[3000100];
int eeL;

int exist_p(int u, int f)
{
	vector<int>::iterator it = lower_bound(G[f].begin(), G[f].end(), u);
	if(it < G[f].end() && *it==u)
		return 1;
	else
		return 0; 
}

void dfs(int dep, int u, int f)
{
	int i;
	int v;
	if(dep == 3){
		if( exist_p(u, f) == 0){
			if(u > f){
				e1[eL] = f;
				e2[eL] = u;
				eL ++;
			}
		}
		return ;
	}
	for(i=0; i<G[u].size(); i++){
		v = G[u][i];
		if(vis[v] == 0){
			vis[v] = 1;
			dfs(dep+1, v, f);
			vis[v] = 0;
		}
	}
}

bool cmp(int aa, int bb)
{
	if(e1[aa] < e1[bb])
		return true;
	if(e1[aa] > e1[bb])
		return false;
	if(e2[aa] < e2[bb])
		return true;
	return false;
}

void solve()
{
	int i;
	res = 0;
	while(1){
		for(i=0; i<N; i++){
			sort(G[i].begin(), G[i].end() );
		}
		eL = 0;
		for(i=0; i<N; i++){
			vis[i] = 1;
			dfs(0, i, i);
			vis[i] = 0;
		}
		if(eL == 0)
			break;
		for(i=0; i<eL; i++){
			idx[i] = i;
		}
		sort(idx, idx+eL, cmp);
		eeL = 1;
		ee1[0] = e1[idx[0]];
		ee2[0] = e2[idx[0]];
		for(i=1; i<eL; i++){
			if(e1[idx[i]]!=e1[idx[i-1]] || e2[idx[i]]!=e2[idx[i-1]]){
				ee1[eeL] = e1[idx[i]];
				ee2[eeL] = e2[idx[i]];
				eeL ++;
			}
		}
		res += eeL;
		for(i=0; i<eL; i++){
			G[ee1[i]].push_back(ee2[i]);
			G[ee2[i]].push_back(ee1[i]);
		}
	}
	printf("%lld\n", res);
}

