#include <bits/stdc++.h>
using namespace std;

template <typename T>
struct graph {

	struct edge {
		int from, to;
		T cost;
	};

	vector<edge> edges;
	vector<vector<int>> g;
	int n;

	graph(int n) : n(n) {
		g.resize(n);
	}

	virtual void add(int from, int to, T cost) = 0;
};

template <typename T>
struct undirected_graph : graph<T> {
	using graph<T>::edges;
	using graph<T>::g;
	using graph<T>::n;

	undirected_graph(int n) : graph<T>(n) {
	}

	void add(int from, int to, T cost = 1) {
		assert(0 <= from && from < n && 0 <= to && to < n);
		g[from].emplace_back(edges.size());
		g[to].emplace_back(edges.size());
		edges.push_back({from, to, cost});
	}
};

template <typename T>
vector<T> dijkstra(const graph<T> &g, int start){
	assert(0 <= start && start < g.n);
	vector<T> dist(g.n, numeric_limits<T>::max());
	priority_queue<pair<T, int>, vector<pair<T, int>>, greater<pair<T, int>>> s;
	dist[start] = 0;
	s.emplace(dist[start], start);
	while (!s.empty()) {
		int expected = s.top().first;
		int i = s.top().second;
		s.pop();
		if (dist[i] != expected) {
			continue;
		}
		for (int id : g.g[i]) {
			auto &e = g.edges[id];
			int to = e.from ^ e.to ^ i;
			if (dist[i] + e.cost < dist[to]) {
				dist[to] = dist[i] + e.cost;
				s.emplace(dist[to], to);
			}
		}
	}
	return dist;
}

