const int MAX_N = (int)1e5 + 5;
set<int> G[MAX_N];

int res;
bool is_ok(int curr, int prev, int pprev, int ppprev){
	if (ppprev != -1){
		 if(!G[curr].count(ppprev) && !G[ppprev].count(curr)){
			++res;
			G[curr].insert(ppprev);
			G[ppprev].insert(curr);
			return true;
		}else{
			return false;
		} // end if
	} // end if

	bool ans = false;
	set<int>::iterator it = G[curr].begin();
	for (; it != G[curr].end(); ++it){
		int v = (*it);
		if (v != prev && v != pprev && v != ppprev){
			ans |= is_ok(v, curr, prev, pprev);
		} // end if
	} // end for

	return ans;
}

