struct UnionFind{
    vector<int> par,r;

    //はじめに全てが根であるとしておく
    UnionFind(int N):par(N),r(N,1){iota(par.begin(),par.end(),0);}

    int root(int x){//根に当たるまで再帰で探す
        if(par[x] == x) return x;
        else return par[x] = root(par[x]);
    }

    bool same(int x,int y){//つながっているかどうか判定
        return par[x] == par[y];
    }

    int size(int x){ //根の大きさを判定する
        return r[root(x)];
    }

    void unite(int x, int y){//根が同じでなかったらつなげる
        x = root(x), y = root(y);
        if(x == y) return;
        if(r[x] < r[y]) swap(x,y); //値を小さいほうを根にする
        r[x] += r[y];
        par[y] = x;
        return;
    }
};

signed main() {
    cin.tie(0);
	ios::sync_with_stdio(false);
    int N,M;cin >> N >> M;
    UnionFind UF(2*N);
    int A,B;
    REP(i,M){
        cin >> A >> B;
        UF.unite(A,B + N);
        UF.unite(A + N,B);
    }
    int sum = 0,sq = (N + 1)/2 * N/2;
    REP(i,N) sum += i;


    REP(i,N){
        if(UF.same(i,i + N)){
            cout << sum - M << endl;
            return 0;
        }
    }
    cout << sq - M << endl;
}

