using namespace std;

const int MAXN = 100000 + 10;
const int MAXM = 200000 + 10;

int N, M;
int To[MAXM], Next[MAXM], Node[MAXN], nE;
int Vis[MAXM * 2];
int Q[MAXN * 2];

void InsertEdge(int a, int b)
{
	To[nE] = b;
	Next[nE] = Node[a];
	Node[a] = nE ++;
}

int BFS()
{
	int nQ = 0;
	memset(Vis, -1, sizeof(Vis));
	Q[nQ ++] = 0;
	Vis[0] = 0;

	int Tot = 0;
	for (int h = 0; h < nQ; h ++)
	{
		int i = Q[h];
		for (int jj = Node[i >> 1]; jj != -1; jj = Next[jj])
		{
			int j = To[jj];
			int conjb = ((j << 1) | (i & 1)) ^ 1;
			if (Vis[conjb] == -1)
			{
				Vis[conjb] = Vis[i] + 1;
				Q[nQ ++] = conjb;
			}
		}
	}
	return -1;
}

void Work()
{
	scanf("%d%d", &N, &M);
	memset(Node, -1, sizeof(Node));
	nE = 0;
	for (int i = 0; i < M; i ++)
	{
		int a, b;
		scanf("%d%d", &a, &b);
		a --;
		b --;
		InsertEdge(a, b);
		InsertEdge(b, a);
	}
	BFS();

	long long x = 0, y = 0, z = 0;
	for (int i = 0; i < N; i ++)
	{
		if (Vis[(i << 1)] != -1 && Vis[(i << 1) + 1] != -1) z ++;
		else if (Vis[(i << 1)] != -1) x ++;
		else y ++;
	}
	long long Ans = (x * y) + (x * z) + (y * z) + (z * (z - 1) / 2) - M;
	printf("%lld\n", Ans);
}

int main()
{
	Work();
	return 0;
}

