using namespace std;


class UT
{
    int par[MAX];
    int rank[MAX];
    int dis[MAX];
    bool used[MAX];
    int rnum[4];
    int n;
    public:
    int calc(void)
    {
        for(int i = 0;i < n;i++)
        {
            if(used[par[i]])
                continue;

            used[par[i]] = true;
            for(int j = 0;j < n;j++)
            {
                int r0,r1,r2,r3;
                if(par[j] == par[i] && dis[j] < 4)
                {
                    rnum[dis[j]]++;
                }
            }
        }

        return rnum[0]*rnum[3]+rnum[1]*rnum[2];
    }
    UT(int x)
    {
        n = x;
        for(int i = 0;i < x;i++)
        {
            par[i] = i;
            rank[i] = 0;
            dis[i] = 0;
            used[i] = false;
        }
    }

    bool same(int x,int y)
    {
        return root(x) == root(y);
    }

    int root(int x)
    {
        return par[x] == x ? x : par[x] = root(par[x]);
    }

    void unite(int x,int y)
    {
        x = root(x);
        y = root(y);

        if(x == y)
            return;

        if(rank[x] < rank[y])
        {
            par[x] = y;
            dis[par[x]] += dis[y];
        } else {
            par[y] = x;
            dis[par[y]] += dis[x];
            if(rank[x] == rank[y]) {
                rank[x]++;
                dis[x]++;
            }
        }
    }
};

