    cin>>n>>m;
    UT ut(n);

    for(int i = 0;i < m;i++)
    {
        int a,b;
        cin>>a>>b;
        a--;
        b--;
        ut.unite(a,b);
    }

    cout<<ut.calc()<<endl;

    return 0;
}

