s64 N;
s64 M;

vector<vector<int>> G;

unordered_set<pair<int,int>,pairhash> E;

bool edge_exists(int a, int b)
{
    if(a > b) swap(a, b);
    return E.count(make_pair(a,b));
}

void edge_add(int a, int b)
{
    if(a > b) swap(a, b);
    E.insert(make_pair(a,b));
}

s64 bfs(int start)
{
    s64 res = 0;

    queue<tuple<int,int,int,int>> que;

    que.push(make_tuple(start,-1,-1,-1));

    while(!que.empty()) {
        auto t = que.front(); que.pop();
        int v   = get<0>(t);
        int p   = get<1>(t);
        int pp  = get<2>(t);
        int ppp = get<3>(t);

        if(p >= 0 && pp >= 0 && ppp >= 0) {
            if(!edge_exists(v, ppp)) {
#ifdef DEBUG
                DPRINTLN(v, ppp);
#endif
                G[v].emplace_back(ppp);
                G[ppp].emplace_back(v);
                edge_add(v, ppp);
                ++res;
            }
            continue;
        }

        for(int to : G[v]) {
            if(to == v) continue;
            if(to == p) continue;
            if(to == pp) continue;
            que.push(make_tuple(to,v,p,pp));
        }
    }

    return res;
}

void solve()
{
    s64 ans = 0;

    for(;;) {
        s64 subtotal = 0;
        REP(i, N) {
            s64 c = bfs(i);
            subtotal += c;
        }
        if(subtotal == 0) break;
        ans += subtotal;
    }

    PRINTLN(ans);
}

signed main(signed /*argc*/, char** /*argv*/)
{
    RD(N);
    G.resize(N);
    RD(M);

    REP(_, M) {
        int a, b; RD(a); RD(b); --a; --b; // 0-based
        G[a].emplace_back(b);
        G[b].emplace_back(a);
        edge_add(a, b);
    }

    solve();

    return 0;
}

