// 連結な重みなしグラフGは二部グラフであるか？
// 二部グラフなら各頂点集合の要素数をPairで返し，そうでなければmake_pair(-1, -1)を返す．
P getBipartiteGraphCount(vector< vector<int> > G) {
    vector<int> color(G.size(), 0);
    stack<int> st;
    st.push(0);
    color[0] = 1;
    bool isBipartite = true;

    while (!st.empty()) {
        int p = st.top(); st.pop();
        for (int i = 0; i < G[p].size(); i++) {
            if (color[G[p][i]] == color[p]) {
                // G is not bipartite
                isBipartite = false;
                while(!st.empty()) st.pop();
                break;
            }
            if (color[G[p][i]] == 0) {
                st.push(G[p][i]);
                color[G[p][i]] = (-1) * color[p];
            }
        }
    }
    if (isBipartite) {
        int countPlus = 0;
        int countMinus = 0;

        for (int i = 0; i < G.size(); i++) {
            if (color[i] > 0) countPlus++;
            else if (color[i] < 0) countMinus++;
        }
        // if countPlus + countMinus < G.size(), G is not connected
        return (countPlus + countMinus == G.size() ? make_pair(countPlus, countMinus) : make_pair(-1, -1));
    } else return make_pair(-1, -1);
}

int main() {

    int N, M;
    cin >> N >> M;

    vector< vector<int> > G(N, vector<int>(0));
    for (int i = 0; i < M; i++) {
        int A, B;
        cin >> A >> B;
        A--; B--;
        G[A].push_back(B);
        G[B].push_back(A);
    }

    P result = getBipartiteGraphCount(G);

    if (result.first > 0) cout << (result.first * result.second - M) << endl;
    else cout << (N * (N - 1) / 2 - M) << endl;

    return 0;
}

