using Graph = vector<vector<int>>;

// 二部グラフ判定
vector<int> color;
bool dfs(const Graph &G, int v, int cur = 0) {
    color[v] = cur;
    for (auto next_v : G[v]) {
        // 隣接頂点がすでに色確定していた場合
        if (color[next_v] != -1) {
            if (color[next_v] == cur) return false; // 同じ色が隣接したらダメ
            continue;
        }

        // 隣接頂点の色を変えて、再帰的に探索 (一回でも false が返ってきたら false)
        if (!dfs(G, next_v , 1 - cur)) return false;
    }
    return true;
}

void solve(){
    int N, M;
    cin >> N >> M;
    Graph g(N);
    rep(i,M){
        int a, b;
        cin >> a >> b;
        a--; b--;
        g[a].push_back(b);
        g[b].push_back(a);
    }

    bool f = true;
    color.assign(N,-1);
    rep(v,N){
        if (color[v] != -1) continue; // v が探索済みだったらスルー
        if (!dfs(g, v)) f = false;
    }

    dump(f);
    if(f){
        int c=0, d=0;
        rep(i,N){
            if(color[i]==0) c++;
            else d++;
        }
        dump(color);
        cout << c*d - M << endl;
    }else
        cout << N*(N-1)/2 - M << endl;
}

signed main(){
    cout << fixed << setprecision(18);
    cerr << fixed << setprecision(18);
    solve();
}

