#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

vector<ll> G[100005];
ll res;
ll N,M;

bool h[100005][2];

struct state{
  ll v,f;
};

ll dijk(ll v){
  queue<state> q;
  h[v][0] = 1;
  while(!q.empty()){
    state p = q.front(); q.pop();
    for( ll to : G[p.v] ) {
      if( h[G[p.v][to]][1-p.f] ) continue;
      h[G[p.v][to]][1-p.f] = true;
      q.push((state){to,1-p.f});
    }
  }
  ll res = 0;
  for(ll i=0;i<N;i++){
    if( h[i][1] )  res++;
  }
  if( res == N ) return N * N - M;
  return res * (N-res) - M;
}
int main(){
  cin >> N >> M;
  for(ll i=0;i<M;i++){
    ll a,b; cin >> a >> b; --a; --b;
    G[a].emplace_back( b );
    G[b].emplace_back( a );
  }
  cout << dijk(0) << endl;
}

