        }
        dfs( root, next, 3-flag, ret );
    }

    if(flag==1) ret[0]++;
    if(flag==2) ret[1]++;

    if(root==curr) {
        //printf("ret=%d %d %d\n", ret[0], ret[1], ret[2]);
        if(ret[2]) ans += (ret[0]+ret[1])*(ret[0]+ret[1]-1)/2;
        else       ans += ret[0]*ret[1];
    }

    return;
}

int main(int argc, char* argv[])
{
    int n, m;
    scanf("%d%d", &n, &m);

    g.resize(n);
    vis.resize(n);
    int i;
    for(i=0; i<m; i++) {
        int a, b;
        scanf("%d%d", &a, &b);
        g[a-1].push_back(b-1);
        g[b-1].push_back(a-1);
    }

    ans=0;
    for(i=0; i<n; i++) {
        if(!vis[i]) {
            long ret[3]={0, 0, 0};   // num of 0/1, flag
            dfs(i, i, 1, ret);
        }
    }
    printf("%lld\n", ans-m);

    return 0;
}

