  cin >> V >> E;
  for(int i = 0; i < E; ++i){
    int s, t;
    cin >> s >> t;
    G[s].push_back(t);
    G[t].push_back(s);
  }
  if(bp){
    // 二部グラフである
    int B = 0, W = 0;
    for(int i = 0; i < V; ++i){
      if(color[i] == 1) ++B;
      if(color[i] == -1) ++W;
    }
    W = V - B;
    cout << B*W - E << endl;
  }else{
    // 二部グラフでない
    cout << V*(V - 1) / 2 - E << endl;
  }
  return 0;
}

