        for(auto nv:G[v]){
            if(color[nv]!=-1){
                if(color[nv]==cur) return false;
                continue;
            }
            if(!self(self, nv,1-cur)) return false;
        }
        return true;
    };
    bool bipartite = true;
    int cnt = 0;
    REP(v,N){
        if(color[v]!=-1) continue;
        if(!dfs(dfs, v)) bipartite = false;
    }
    if(!bipartite){
        cout << N * (N - 1) / 2 - M << endl;
        return;
    }
    REP(i,N) if(color[i]) cnt++;
    cout << cnt * (N - cnt) - M << endl;
}
