		G[b[i]].push_back(a[i]);
		used.insert(P(a[i],b[i]));
	}
	for(long long i=0;i<n;i++)
	{
		for(long long j=0;j<G[i].size();j++)
		{
			long long pt=G[i][j];
			for(long long k=0;k<G[G[i][j]].size();k++)
			{
				long long tp=G[G[i][j]][k];
				if(G[G[i][j]][k]==i)continue;
				rep(l,G[tp].size())
				{
					if(G[tp][l]==pt||G[tp][l]==i)
					{
						continue;
					}
					if(i<G[tp][l])
					{
						used.insert(P(i,G[tp][l]));
						que.push(P(i,G[tp][l]));
					}
				}
			}
		}
	}
	while(!que.empty())
	{
		P p=que.front();que.pop();
		ans++;
		//cout<<p.first<<" "<<p.second<<endl;
		rep(i,G[p.first].size())
		{
			rep(j,G[p.second].size())
			{
				if(G[p.first][i]==G[p.second][j])continue;
				ss=G[p.first][i];
				tt=G[p.second][j];
				if(ss>tt)
				{
					sw=ss;
					ss=tt;
					tt=sw;
				}
				set<P>::iterator ite;
				ite=used.find(P(ss,tt));
				if(ite==used.end())
				{
					used.insert(P(ss,tt));
					que.push(P(ss,tt));
				}
			}
		}
	}
	cout<<ans<<endl;
	return 0;
}

