	///////////////
	//3以上の奇数ループを探す

	int root = 0;
	priority_queue<pair<LL,int>,vector<pair<LL,int> >,
		greater<pair<LL,int> > > que;
	vector<LL> dist(N,LINF);
	dist[root] = 0;
	que.push(pair<LL,int>(0,root));//距離、頂点番号

	int flag = 0;
	while( que.size() ){
		pair<LL,int> p = que.top();que.pop();
		int v = p.second;
		if( dist[v] < p.first ){
			int res = (p.first -dist[v]);//ループの距離
			if( res>=3 && res&1 ){
				flag = res;
				break;
			}
		}
		for(int i=0;i < (int)G[v].size();++i){
			edge_base e = G[v][i];
			if( dist[e.to] > dist[v] + e.cost ){
				dist[e.to] = dist[v] + e.cost;
				que.push(pair<LL,int>(dist[e.to],e.to));
			}
		}
	}
	if( flag ){
		LL temp = N;
		cout << temp*(temp-1)/2 - M << endl;
		return;
	}
	////////////////
	int  LOOP = 3;
	while(LOOP--)
	{
	for(int i=0;i<N;++i){
