void sol(int o){
    if(o>n){
        o-=n;
        odd[o]=1;
        for(int i=head[o];~i;i=edges[i].next){
            if(!eve[edges[i].to]){
                sol(edges[i].to);
            }
        }
    }
    else{
        eve[o]=1;
        for(int i=head[o];~i;i=edges[i].next){
            if(!odd[edges[i].to]){
                sol(edges[i].to+n);
            }
        }
    }
}
