    cin >> a >> b;
    a--;
    b--;
    g.at(a).push_back(b);
    g.at(b).push_back(a);

    ll key = max(a, b) * TARGET + min(a, b);
    connected.insert(key);
  }

  // 愚直にDFSで繋ぐとTLE
