				iscan = 0;
			}
			if(dont.find(tt) != dont.end())
			{
				isdont = 1;
			}
			else
			{
				isdont = 0;
			}

			if(iscan == 0 && isdont == 0)
			{
				q.push(MP(tt,(tmp.SE+1) % 2));

				if((tmp.SE+1) % 2 == 1)
				{
					can.insert(tt);
				}
				else
				{
					dont.insert(tt);
				}
			}
			else
			{
				if( iscan == 1 && (tmp.SE+1) % 2 == 0)
				{
					q.push(MP(tt,0));
				}
				if( iscan == 0 && (tmp.SE+1) % 2 == 1)
				{
					can.insert(tt);
					dont.erase(tt);
					q.push(MP(tt,1));
