int add_edge(int from, int to, int d)
{
    if (d == 3){
        if (from != to && edge[from].count(to) == 0){
            edge[from].insert(to);
            edge[to].insert(from);
            // cout << from << " " << to << endl;
            return 1;
        }
        return 0;
    }

    int cnt = 0;
    for (set<int>::iterator i = edge[to].begin(); i != edge[to].end(); ++i){
        cnt += add_edge(from, *i, d + 1);
    }
    return cnt;
}

