vector<int> color;

int N, M;

int black = 0;
int white = 0;

bool dfs(const Graph &G, int v, int cur = 0) {
  color[v] = cur;

  for (auto next_v : G[v]) {
    if (color[next_v] != -1) {
      if (color[next_v] == cur) {
        return false;
      } else {
        continue;
      }
    }
    if (!dfs(G, next_v, 1 - cur)) return false;
  }
  return true;
}

