    if (color[v] != -1) continue;
    if (!dfs(G, v)) is_bipartite = false;
  }

  if (is_bipartite) {
    for (auto i : color) {
      black = (i == 0) ? black + 1 : black;
      white = (i == 1) ? white + 1 : white;
    }
