pair<bool,vector<ll>> isBi(graph &G,ll N){
    vector<ll> col(N,-1);
    queue<ll> q;
    q.push(0);
    col[0] = 0;
    while(!q.empty()){
        ll current = q.front();q.pop();
        for (int i = 0; i < G[current].size(); ++i) {
            ll next = G[current][i];
            if(col[next] != -1){
                if(col[next] == col[current]){
                    return make_pair(false,vector<ll>(N,-1));
                }
                continue;
            }
            col[next] = 1 - col[current];
            q.push(next);
        }
    }
    return make_pair(true,col);
}

