void search(ll s, ll v, ll count, union_find uf) {
	if (count == 3) {
		if (!uf.same(s, v)) {
			uf.unite(s, v);
			G[s].push_back(v);
			G[v].push_back(s);
			ans++;
		}
	}

	REP(i, G[v].size()) {
		search(s, G[v][i], count++, uf);
	}
}

