/*
    如果是二分图 染色后n1*n2-m
    如果不是二分图 存在环
    环长度为奇数 换上任意两点可以连边
    环长度不可能为偶 为偶数可以看作二分图
*/
int n, m, u, v;
struct Edge {
    int to, next;
} edge[2 * maxn];
int head[maxn];
int vis[maxn];
int bingraph[2];        // 二分图两部分计数
int color[maxn];
int cnt;
void addedge(int u, int v)
{
    edge[++cnt] = {v, head[u]};
    head[u] = cnt;
    edge[++cnt] = {u, head[v]};
    head[v] = cnt;
}

bool flag;
void dfs(int u)
{
    vis[u] = 1;
    bingraph[color[u]]++;
    for (int i = head[u]; i != -1; i = edge[i].next)
    {
        int v = edge[i].to;
        if (!vis[v]) {
            color[v] = 1 - color[u];
            dfs(v);
        }
        if (vis[v] && color[v] == color[u]) {
            flag = true;
            return;
        }
    }
}

int main()
{
    while(scanf("%d%d", &n, &m) == 2)
    {
        memset(bingraph, 0, sizeof(bingraph));
        memset(head, -1, sizeof(head));
        memset(color, 0, sizeof(color));
        memset(vis, 0, sizeof(vis));
        memset(edge, 0, sizeof(edge));
        flag = false;
        cnt = 0;
        for (int i = 0; i < m; i++){
            scanf("%d%d", &u, &v);
            addedge(u, v);
        }
        dfs(1);
        if (flag) printf("%lld\n", 1ll * n * (n-1) / 2 - m);
        else printf("%lld\n", 1ll * bingraph[0] * bingraph[1] - m);
    }
    return 0;
}

