    rep(i,m){
        int a,b;
        cin >> a >> b;
        a--; b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }

    ll count = BipartiteGraph();
    ll ans = 0;
    if(count == -1){
        ans = n * (n - 1) / 2 - m;
    }else{
        ans = count * (n - count) - m;
    }

    cout << ans << endl;
    return 0;
}

