bool dfs(vector<vector<int>> &graph, vector<int> &color, int v, int c)
{
    color[v] = c; //まず頂点vをcで塗る
    for (int i = 0; i < (int)graph[v].size(); i++)
    {
        // 隣り合う頂点が同じ色ならダメ
        if (color[graph[v][i]] == c)
        {
