typedef int Weight;
struct Edge{
    int from, to;
    Weight weight;
    int rev;     // 無向グラフの対の辺
    Edge(int from, int to, Weight weight) :
        from(from), to(to), weight(weight) { }
    Edge(int from, int to, Weight weight, int rev) :
        from(from), to(to), weight(weight), rev(rev){ }
};
bool operator < (const Edge &a, const Edge &b){
    if(a.weight != b.weight) return a.weight > b.weight;
    if(a.from != b.from) return a.from > b.from;
    return  a.to > b.to;
}
typedef vector<Edge> Edges;
typedef vector<Edges> Graph;
typedef vector<Weight> Array;
typedef vector<Array> Matrix;
void addFlowEdge(Graph &g, int a, int b, Weight c){
    g[a].push_back(Edge(a, b, c, g[b].size()));
    g[b].push_back(Edge(b, a, 0, g[a].size() - 1));
}
void addUndirectedEdge(Graph &g, int a, int b, Weight c){
    g[a].push_back(Edge(a, b, c, g[b].size()));
    g[b].push_back(Edge(b, a, c, g[a].size() - 1));
}

bool isBipartite(const Graph &g, int v, int c, vector<int> &color) {
    color[v] = c;
    for(auto e: g[v]) {
        if (color[e.to] < 0) {
            isBipartite(g, e.to, 1 - c, color);
        } else if(color[e.to] != 1 - c) {
            return false;
        }
    }
    return true;
}

void solve(long long N, long long M, std::vector<long long> A, std::vector<long long> B){
    Graph g(N + 1);
    for(int i = 0; i < M; ++i) {
        addUndirectedEdge(g, A[i], B[i], 0);
    }
    vector<int> c(N + 1, -1);
    bool f = isBipartite(g, 1, 0, c);
    if (f) {
        int a = 0;
        for(int i = 1; i <= N; ++i) {
            if (c[i] == 1) {
                a++;
            }
        }
        cout << max(a * (N - a) - M, 0) << endl;
    } else {
        cout << N * (N - 1) / 2 - M << endl;
    }
}

