        } else if (color[G[v][i]] == c) return false;
    }
    return true;
}

void solve() {
    if (dfs(0, c)) {
        int n_1 = 0, n_2 = 0;
        rep(i, n) {
            if (color[i] == c) n_1++;
            if (color[i] == -c) n_2++;
        }
        cout << n_1 * n_2 - m << endl;
    } else {
        cout << n * (n - 1) / 2 - m << endl;
    }
}

int main() {
    cin >> n >> m;
    rep(i, m) {
        ll a, b;
        cin >> a >> b;
        a--, b--;
        G[a].emplace_back(b);
        G[b].emplace_back(a);
    }
    solve();
    return 0;
}

