ll N,M;
vector<vector<int> > Graph;
bool visited[500010];
vector<int> top;
vector<int> topTable;
void dfs(int cur) {
  visited[cur]=true;
  for(int e:Graph[cur]) {
    if (!visited[cur])
      dfs(e);
  }
  top.push_back(cur);
}
int main(int argc, char **argv, char **envp) {
  cin >> N >> M;
  Graph.resize(N);
  REP(i, M) {
    int A,B;
    scanf("%d%d", &A, &B);
    --A;--B;
    Graph[A].push_back(B);
    Graph[B].push_back(A);
  }
  REP(i, N) {
    if (!visited[i]) {
      dfs(i);
    }
  }
  topTable.resize(N);
  REP(i,N) {
    topTable[top[i]]=i;
  }
  bool badGraph=true;
  REP(i,N) {
    for(int e:Graph[i]) {
      if (abs(long(topTable[i]-topTable[e]))%2==0) {
        badGraph=false;
      }
    }
  }
  ll answer=0;
  if (badGraph) {
    if (N%2==0) {
      answer=1ll*(N/2)*(N/2);
    } else {
      answer=1ll*(2+N-1)*((N-1)/2)/2;
    }
    answer-=M;
  } else {
    answer=1ll*N*(N-1)/2-M;
  }
  cout << answer << endl;
  return 0;
}

