int ufpar[MAX_N];
int uffndpar(int v){
	if(v==ufpar[v]){
		return v;
	}
	return ufpar[v]=uffndpar(ufpar[v]);
}
bool same(int s,int t){
	s=uffndpar(s);
	t=uffndpar(t);
	return s==t;
}
void unite(int s,int t){
	s=uffndpar(s);
	t=uffndpar(t);
	ufpar[s]=t;
}
vector<int> G[MAX_N];
int A[MAX_M],B[MAX_M];
bool used[MAX_M];
int dst[MAX_N];
void caldst(int v,int p,int d){
	dst[v]=d;
	for(auto e:G[v]){
		if(e!=p){
			caldst(e,v,d+1);
		}
	}
}
