template <class Info>
struct edge {
    int from, to;
    Info info;
    edge(int to, Info info) : to(to), info(info) {}
    edge(int from, int to, Info info) : from(from), to(to), info(info) {}
};

struct normal_edge {
    normal_edge() {}
};

template <class Info>
class graph {
   protected:
    using edge_type = edge<Info>;
    ::std::size_t N;
    ::std::vector<::std::vector<edge_type>> edges;

   public:
    graph(::std::size_t N_) : N(N_), edges(N_) {}
    virtual void add_edge(int x, int y, Info info) = 0;
    const ::std::vector<edge_type> &delta(int v) const {
        assert(v < N);
        return edges[v];
    }
    const ::std::vector<edge_type> &operator[](int v) const {
        return this->delta(v);
    }
    ::std::size_t size() const { return N; }
};

template <class Info>
class undirected_graph : public graph<Info> {
   public:
    undirected_graph(::std::size_t N) : graph<Info>(N) {}
    void add_edge(int x, int y, Info info) {
        this->edges[x].push_back(edge<Info>(x, y, info));
        this->edges[y].push_back(edge<Info>(y, x, info));
    }
};

template <class Info>
class directed_graph : public graph<Info> {
   public:
    directed_graph(::std::size_t N) : graph<Info>(N) {}
    void add_edge(int x, int y, Info info) {
        this->edges[x].push_back(edge<Info>(x, y, info));
    }
};

template <class Info>
class bipartite_graph : public undirected_graph<Info> {
    ::std::size_t A;
    ::std::size_t B;

   public:
    bipartite_graph(::std::size_t A_, ::std::size_t B_)
        : A(A_), B(B_), undirected_graph<Info>(A_ + B_) {}
    void add_edge(int x, int y, Info info) {
        undirected_graph<Info>::add_edge(x, y + A, info);
    }
};

template <typename Info>
struct is_bipartite {
    vector<int> color;
    int white_cnt = 0, n;

    bool dfs(graph<Info> &g, int v, int prev, int c) {
        color[v] = c;
        if(c == 1) white_cnt++;
        for(auto nv : g[v]) {
            if(nv.to == prev) continue;

            if(color[nv.to] == -1) {
                if(!dfs(g, nv.to, v, 1 - c)) return false;
            } else if(color[nv.to] != 1 - c) {
                return false;
            }
        }
        return true;
    }

    int operator()(graph<Info> &g) {
        color.assign(g.size(), -1);
        if(!dfs(g, 0, -1, 0)) return -1;
        return white_cnt;
    }
};

int main() {
    int_fast64_t N, M;
    cin >> N >> M;
    undirected_graph<int> g(N);
    for(int i = 0; i < M; i++) {
        int A, B;
        cin >> A >> B;
        g.add_edge(A - 1, B - 1, 1);
    }
    int_fast64_t white_cnt = is_bipartite<int>()(g);
    if(white_cnt == -1)
        cout << N * (N - 1) / 2 - M << endl;
    else
        cout << white_cnt * (N - white_cnt) - M << endl;

    return 0;
}

