bool check(int v,int c,vector<vector<int>> &edge,vector<int> &used){

    used[v]=c;
    for(int i=0;i<edge[v].size();i++){
        int to=edge[v][i];
        if(used[to]==c){
            return false;
        }
        if(used[to]!=-1) continue;
        check(to,!c,edge,used);
    }
    return true;
}

long long int cnt(int v,vector<vector<int>> &edge,vector<int> &used){

    long long int res=1;
    used[v]=100;
    for(int i=0;i<edge[v].size();i++){
        int to=edge[v][i];
        if(used[to]==100) continue;
        res+=cnt(to,edge,used);
    }
    return res;
}

pair<long long int,long long int> cnt2(int v,vector<vector<int>> &edge,vector<int> &used){

    long long int r1=0;
    long long int r2=0;
    if(used[v]) r1=1;
    else r2=1;
    used[v]=100;
    for(int i=0;i<edge[v].size();i++){
        int to=edge[v][i];
        if(used[to]==100) continue;
        auto ret=cnt2(to,edge,used);
        r1+=ret.first;
        r2+=ret.second;
    }
    return {r1,r2};
}

