const int MAX_N = 100005;

vector<int> G[MAX_N];
int flag[MAX_N];
bool ok;

void dfs(int u,int k)
{
    flag[u] = k;
    if(ok){
        return;
    }
    rep(i,G[u].size()){
        if(flag[G[u][i]] == -1){
            dfs(G[u][i],k^1);
            if(ok){
                return;
            }
        }else if(flag[G[u][i]] == k){
            ok = true;
            return;
        }
    }
}

int main()
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n,m;
    cin >> n >> m;
    rep(i,m){
        int a,b;
        cin >> a >> b;
        G[a-1].pb(b-1),G[b-1].pb(a-1);
    }
    rep(i,n){
        flag[i] = -1;
    }
    ok = false;
    dfs(0,0);
    ll zero = 0,one = 0;
    rep(i,n){
        if(flag[i] == 0){
            zero++;
        }else{
            one++;
        }
    }
    if(ok){
        cout << (ll)n*(n-1)/2 - m << endl;
    }else{
        cout << zero*one - m << endl;
    }
    return 0;
}

