inline void add_edge(int u,int v){nxt[++E]=bgn[u],bgn[u]=E,to[E]=v;}
inline bool bfs(int u)
{
	queue<int>q;
	q.push(u);col[u]=2;
	while(!q.empty())
	{
		int u=q.front();q.pop();
		for(int v,i=bgn[u];i;i=nxt[i])
		{
			if(col[v=to[i]]&&col[to[i]]==col[u])return 0;
			if(!col[v])
			{
				col[v]=col[u]^1;
				q.push(v);
			}
		}
	}
	For(i,1,n)sum[col[i]]++;
	return 1;
}
