struct UnionFind {
    vector<int> par, rank;

    UnionFind(int n) : par(n, -1), rank(n, 0) {};
    void init(int n) { par.assign(n, -1), rank.assign(n, 0); }

    int root(int x) {
        if (par[x] == -1) return x;
        else return par[x] = root(par[x]);
    }

    bool issame(int x, int y) {
        return root(x) == root(y);
    }

    bool merge(int x, int y) {
        x = root(x); y = root(y);
        if (x == y) return false;
        if (rank[x] < rank[y]) swap(x, y);
        if (rank[x] == rank[y]) ++rank[x];
        par[y] = x;
        return true;
    }

};

int main() {
    int n, m;
    cin >> n >> m;
    int a, b;
    UnionFind uf(n);

    rep(i, m) {
        cin >> a >> b;
        --a, --b;
        to[a].push_back(b);
        to[b].push_back(a);
        uf.merge(a, b);
    }
    map<int, int> cnt;
    rep(i, n) cnt[uf.root(i)]++;

    set<int> done;
    int total = 0;
    rep(i, n) {
        int r = uf.root(i);
