        rep(i, n) {
            if(color[i]==1 && uf.root(i)==r) g1++;
            else if (color[i]==-1 && uf.root(i)==r)g2++;
        }
        total += g1*g2;
    }
    cout << (total-m) << endl;
    return 0;
}

