#define MAX_N 100100
typedef pair<int, int> P;

ll threesteps(){
    vector<int> gurafu[MAX_N];
    stack<int> st;
    int migihidari[MAX_N] = {0};
    ll N, M;
    cin >> N >> M;
    REP(i, M){
        int A, B;
        cin >> A >> B;
        A--;
        B--;
        gurafu[A].push_back(B);
        gurafu[B].push_back(A);
    }
    bool nibu = true;
    int genzaichi = 0;
    ll migihidarikazu[2] = {0};
    migihidari[0] = 1;
    migihidarikazu[1] = 1;
    do{
        if(gurafu[genzaichi].empty()){
            if(st.empty())break;
            genzaichi = st.top();
            st.pop();
            continue;
        }
        int tuginogenzaichi = gurafu[genzaichi].back();
        if(migihidari[tuginogenzaichi] == migihidari[genzaichi])nibu = false;
        if(migihidari[tuginogenzaichi] == 0){
            migihidari[tuginogenzaichi] = -migihidari[genzaichi];
            migihidarikazu[(1 + 2 * migihidari[tuginogenzaichi]) / 2]++;
        }
        gurafu[genzaichi].pop_back();
        if(!gurafu[genzaichi].empty())st.push(genzaichi);
        genzaichi = tuginogenzaichi;
    }while(1);

    if(nibu)return migihidarikazu[0] * migihidarikazu[1] - M;
    else return N * (N - 1) / 2 - M;
}

int main(){
    printf("%lld\n", threesteps());
}

