	for(int i=first[x];i;i=e[i].ne){
		if(!flag)return;
		int to=e[i].to;
		if(to==fa)continue;
		if(col[to]==col[x]){flag=0;return;}
		if(ok[to])continue;
		col[to]=col[x]^1;
		if(col[to]==2)bl++;else wi++;
		dfs(to,x);
	}
}
