/*
・グラフ用テンプレート
    > Dijkstra
    > BellmanFord
    > WarshallFloyd
    > Kruskal
[応用] 単一終点最短路問題は, すべての有向辺を逆向きに張り替えると, 単一始点最短路問題に帰着できる.
[使用例]
Graph<int> g(V);                // 頂点数V, 重さの型がintのグラフを宣言
add_edge(g, a, b, c);           // グラフgに, 始点a, 終点b, 重さcの無向辺を追加
add_arc(g, a, b, c);            // グラフgに, 始点a, 終点b, 重さcの有向辺を追加
add_to_edges(edges, a, b, c);   // 辺集合edgesに, 始点a, 終点b, 重さcの辺を追加
*/

template <typename T> bool isBipartiteGraph(const Graph< T > &g) {
    int V = g.size();
    vector<int> color(V, 0);
    bool ret = true;
    function<void(int, int)> dfs = [&](int i, int clr) {
        if (color[i] != 0) return;
        color[i] = clr;
        for (auto& e: g[i]) {
            if (color[e.to] == 0) dfs(e.to, -clr);
            else if (color[e.to] == clr) ret = false;
        }
    };
    dfs(0, 1);
    return ret;
    int cnt = 0;
    for (auto& e: color) if (e == 1) ++cnt;
    return ret ? -1 : cnt;
}

/*
・二部グラフの判定
    > O(E+V) [E:辺の数, V:頂点の数]
[備考] 二部グラフならtrueを返す.
[使用例] isBipartiteGraph(g);
[その他] 二部グラフだった際に, 片方の集合の大きさが知りたい場合は, return retを削除して, intを返すようにする.
        その場合は, 二部グラフならばその集合の大きさを, そうでない場合は-1を返す.
*/

void dfss(int cur, int clr) {
    color[cur] = clr;
    EACH(nxt, graph[cur]) {
        if (color[nxt] != -1) continue;
        dfss(nxt, clr ^ 1);
    }
}

signed main() {

    SS(int, N, M);

    Graph<int> g(N);
    graph.resize(N);
    REP(i, M) {
        SS(int, A, B);
        --A, --B;
        add_edge(g, A, B);
        graph[A].PB(B);
        graph[B].PB(A);
    }

    ll base;
    if (isBipartiteGraph(g)) {
        color.assign(N, -1);
        dfss(0, 0);
        ll _0 = 0, _1 = 0;
        EACH(e, color) {
            if (e == 0) ++_0;
            else _1++;
        }
        base = _0 * _1;
    } else {
        base = N * (N - 1) >> 1;
    }

    base -= M;
    print(base);

}

