using namespace std;
const int MAX = 1e5+10;
const int WHITE = 0;

int list[MAX][MAX];
int color[MAX];
int N, M;

bool bi_partite(int s, int c){
    stack<pair<int,int> > S;
    S.push(make_pair(s, c));
    color[s] = c;

    while(!S.empty()){
        int u, c_u;
        tie(u, c_u) = S.top(); S.pop();
        color[u] = c_u;

        for(int v=0;v<N;v++){
            if(list[u][v] == 0) continue;
            if(color[v] == c_u) return false;
            if(color[v] == WHITE){
                S.push(make_pair(v, -c_u));
            }
        }
    }
    return true;
}

int main(){
    cin >> N >> M;
    for(int i=0;i<M;i++){
        int a,b;
        cin >> a >> b;
        a--; b--;
        list[a][b] = 1;
        list[b][a] = 1;
    }
    bool flag = bi_partite(0,1);
    if(!flag){
        cout << N*(N-1)/2 - M << endl;
    }else{
        int count_b = 0, count_w = 0;
        for(int i=0;i<N;i++){
            if(color[i] == 1) count_b++;
            else if(color[i] == -1) count_w++;
        }
        cout << count_b * count_w - M << endl;
    }

    return 0;
}

