			two = false;
		}
	}
	ll cnt = 0;
	for (int i = 0; i < N; i++) {
		if (uf.Find(0, i)) {
			cnt++;
		}
	}
	cout << (two ? cnt * (N - cnt) - M : N * (N - 1) / 2 - M) << endl;
	return 0;
}

