// Math
inline constexpr ll gcd(const ll a, const ll b) {
    return b ? gcd(b, a % b) : a;
}
inline constexpr ll lcm(const ll a, const ll b) { return a / gcd(a, b) * b; }

inline constexpr ll modulo(const ll n, const ll m = MOD) {
    ll k = n % m;
    return k + m * (k < 0);
}
inline constexpr ll chmod(ll &n, const ll m = MOD) {
    n %= m;
    return n += m * (n < 0);
}
inline constexpr ll mpow(ll a, ll n, const ll m = MOD) {
    ll r = 1;
    rep(i, 64) {
        if (n & (1LL << i)) r *= a;
        chmod(r, m);
        a *= a;
        chmod(a, m);
    }
    return r;
}
inline ll inv(const ll n, const ll m = MOD) {
    ll a = n, b = m, x = 1, y = 0;
    while (b) {
        ll t = a / b;
        a -= t * b;
        swap(a, b);
        x -= t * y;
        swap(x, y);
    }
    return modulo(x, m);
}

struct UFS {
    vector<ll> data;
    UFS(ll N) : data(N, -1) {}
    ll root(ll x) {
        if (data[x] < 0)
            return x;
        else
            return data[x] = root(data[x]);
    }
    bool unite(ll x, ll y) {
        ll root_x = root(x), root_y = root(y);
        if (root_x != root_y) {
            if (data[root_x] > data[root_y]) swap(root_x, root_y);
            data[root_x] += data[root_y];
            data[root_y] = root_x;
            return true;
        }
        return false;
    }
    bool same(ll x, ll y) { return root(x) == root(y); }
    bool isroot(ll x) { return x == root(x); }
    ll size(ll x) { return -data[root(x)]; }
    ll size() {
        ll cnt = 0;
        rep(i, data.size()) if (isroot(i)) cnt++;
        return cnt;
    }
};

using unionfind = UFS;
ll isBipartite(graph &G) {
    unionfind UF(2 * len(G));
    rep(i, len(G)) each(j, G[i]) {
        UF.unite(i, len(G) + j);
        UF.unite(j, len(G) + i);
    }
    if (UF.same(0, len(G))) {
        return 0;
    } else {
        ll cnt = 0;
        rep(i, len(G)) if (UF.same(0, i)) cnt++;
        return cnt;
    }
}

