bool saiki(int node, int now,long long &num1, long long &num2, vector<int> &sk, vector<vector<int>> &edges){
    if(sk[node] != -1 && sk[node] != now)
        return true;
    else if(sk[node] == now)
        return false;
    else{
        sk[node] = now;
        if(now == 0)
            num1++;
        else if(now == 1)
            num2++;

        bool ret = false;
        for(int to: edges[node]){
            ret |= saiki(to, (now+1)%2, num1, num2, sk, edges);
        }
        return ret;
    }

}

