template <class Weight>
struct Edge {
  size_t src, dst;
  Weight cost;

  Edge(size_t src, size_t dst, Weight cost=1):
    src(src), dst(dst), cost(cost)
  {}

  bool operator <(const Edge<Weight> &rhs) const {
    if (cost != rhs.cost) return cost < rhs.cost;
    if (src != rhs.src) return src < rhs.src;
    return dst < rhs.dst;
  }
};

template <class Weight>
using Graph=std::vector<std::vector<Edge<Weight>>>;

template <class Weight>
bool is_bipartite_component(
    const Graph<Weight> &g, size_t node, std::vector<int> &colors, 
    int color=1) {

  colors[node] = color;
  std::queue<size_t> q;
  q.emplace(node);
  while (!q.empty()) {
    size_t v=q.front();
    q.pop();
    for (const auto &e: g[v]) {
      if (color[v] == color[e.dst]) return false;
      if (color[e.dst]) continue;
      color[e.dst] = -color[v];
      q.emplace(e.dst);
    }
  }
  return true;
};

template <class Weight>
bool is_bipartite(const Graph<Weight> &g, std::vector<int> &colors) {
  int color=0;
  for (size_t i=0; i<g.size(); ++i) {
    if (!color[i] && !is_bipartite_component(g, i, colors, ++color))
      return false;

  return true;
}

int main() {
  size_t N, M;
  scanf("%zu %zu", &N, &M);

  Graph<int> g(N);
  for (size_t i=0; i<N; ++i) {
    size_t A, B;
    scanf("%zu %zu", &A, &B);
    --A;
    --B;

    g[A].emplace_back(A, B);
    g[B].emplace_back(B, A);
  }

  std::vector<int> color(N);
  if (is_bipartite(g, color)) {
    size_t B=std::count(color.begin(), color.end(), 1);
    printf("%zu\n", B*(N-B)-M);
  } else {
    printf("%zu\n", N*(N-1)/2-M);
  }
}

