int ans = 0;
inline int three(int source) {
    queue<iii> q;
    q.push(iii(source, source, 0));
    set<int> res;

    while(!q.empty()) {
        iii front = q.front();
        q.pop();
        int u, parent, d;
        tie(u, parent, d) = front;

        if(d == 3 and u != source and adj[source].count(u) == 0) {
            res.insert(u);
        }
        else if(d < 3) {
            for(int v : adj[u]) {
                if(v != parent) {
                    q.push(iii(v, u, d + 1));
                }
            }
        }
    }
    for(int v : res) {
        adj[source].insert(v);
        adj[v].insert(source);
    }
    return res.size();
}

