        adj[u].insert(v);
        adj[v].insert(u);
    }

    while(true)  {
        int adds = 0;
        fori(i, 1, n + 1) {
            adds += three(i);
        }
        if(adds == 0) {
            break;
        }
        ans += adds;
    }
    printf("%d\n", ans);

    return 0;
}

