struct union_find {
	vector<int> v;
	union_find(int n) : v(n, -1) {}
	int find(int x) { return v[x] < 0 ? x : v[x] = find(v[x]); }
	void unite(int x, int y) {
		x = find(x); y = find(y);
		if (x == y) return;
		if (-v[x] < -v[y]) swap(x, y);
		v[x] += v[y]; v[y] = x;
	}
	bool root(int x) { return v[x] < 0; }
	bool same(int x, int y) { return find(x) == find(y); }
	int size(int x) { return -v[find(x)]; }
};

int main() {
	int N, M; cin >> N >> M;
	vector<int> a(M), b(M);
	rep(i, M) scanf("%d%d", &a[i], &b[i]), a[i]--, b[i]--;
	union_find uf(N * 2);
	rep(i, M) uf.unite(a[i], N + b[i]), uf.unite(N + a[i], b[i]);
	bool bipartite = true;
	rep(u, N) if (uf.same(u, N + u)) bipartite = false;
	if (bipartite) {
		int x = 0, y = 0;
		rep(u, N) if (uf.same(0, u)) x++; else y++;
		cout << (ll)x * y - M << endl;
	}
	else cout << (ll)N * (N - 1) / 2 - M << endl;
}

