set<int> three_step(int k) {
  set<int> res;
  for (auto v: G[k]) {
    for (auto u: G[v]) {
      if (u == k) continue;
      for (auto x: G[u]) {
        if (HAS(G[k], x) || x == u || x == k) continue;
        res.insert(x);
      }
    }
  }
  return res;
}

