    G[A[i]].insert(B[i]);
    G[B[i]].insert(A[i]);
  }

  while (true) {
    bool change = false;
    rep(i, N) {
      auto nodes = three_step(i);
      for (auto v: nodes) {
        G[i].insert(v);
        change = true;
      }
    }
    if (!change) break;
  }

  int ans = 0;
  rep(i, N) ans += G[i].size();
  ans = ans/2 - M;

  cout << ans << endl;

  return 0;
}

