    graph[a].emplace_back(a, b);
    graph[b].emplace_back(b, a);
  }
  vector<int> color;
  if (is_bipartite(graph, color)) {
    long long black = 0, white = 0;
    REP(i, n) ++(color[i] == 1 ? black : white);
    cout << black * white - m << '\n';
  } else {
    cout << n * (n - 1) / 2 - m << '\n';
  }
  return 0;
}

