template< typename T >
bool tree_dfs(WeightedGraph<T>& g, int idx, int par, int col) {
    bool ret=true;
    if(g[idx].col == -1) g[idx].col = col;
    if(g[idx].col != col) return false;
    for(auto& e:g[idx].edges){
         if(e.to == par) continue;
         ret &= tree_dfs(g, e.to, idx, (col+1)&1);
    }
    return ret;
}

