void dfs(int s, int n, bool k,vector<int>& check,vector<set<int>>& G) {
	if (k) {
		if (check[n] < 3*s + 2) {
			if (s != n) {
				G[s].insert(n);
				G[n].insert(s);
			}

			check[n] = 3*s + 2;

			if (check[n] == 3*s + 1) k = false;			
			for (auto next : G[n]) {
				dfs(s, next, !k, check, G);
			}
		}
		else {
			return;
		}
	}
	else {
		if (check[n] > 3 * s)return;
		check[n] = 3*s + 1;
		for (auto next : G[n]) {
			dfs(s, next, !k, check, G);
		}
	}
	return;
}

