typedef tuple<int, int> state; // now, clr

ll N;
ll M;
vector<int> V[100010];

int main () {
  cin >> N >> M;
  for (auto i = 0; i < M; ++i) {
    int a, b;
    cin >> a >> b;
    --a, --b;
    V[a].push_back(b);
    V[b].push_back(a);
  }
  int visited[100010];
  fill(visited, visited+100010, 0);
  int color[100010];
  fill(color, color+100010, -1);
  stack<state> S;
  S.push(state(0, 0));
  while (!S.empty()) {
    int now = get<0>(S.top());
    int clr = get<1>(S.top());
    S.pop();
    if (visited[now] == 0) {
      visited[now] = 1;
      color[now] = clr;
      S.push(state(now, clr));
      for (auto x : V[now]) {
        S.push(state(x, 1-clr));
      }
    } else if (visited[now] == 1) {
      if (color[now] != clr) {
        cout << N * (N-1) / 2 - M << endl;
        return 0;
      }      
    }
  }
  ll black = 0;
  for (auto i = 0; i < N; ++i) {
    if (color[i] == 1) black++;
  }
  cout << black * (N - black) - M << endl;
}

