inline int read()
{
	int x=0,f=1;char ch=getchar();
	while(ch<'0' || '9'<ch){if(ch=='-')f=-1;ch=getchar();}
	while('0'<=ch && ch<='9')x=x*10+(ch^48),ch=getchar();
	return x*f;
}

const int N=500009;

int n,m,deg[N],cnt[N],col[N],tots,type;
int to[N<<1],nxt[N<<1],beg[N],tot=1;
bool vis[N],viss[N<<1];

inline void add(int u,int v)
{
	to[++tot]=v;
	nxt[tot]=beg[u];
	beg[u]=tot;
	++deg[u];
}

inline void dfs(int u)
{
	vis[u]=1;
	for(int i=beg[u],v;i;i=nxt[i])
	{
		if(!vis[v=to[i]])
		{
			col[v]=col[u]^1;
			cnt[col[v]]++;
			if(!viss[i]){tots++;viss[i]=viss[i^1]=1;}
			dfs(v);
		}
		else if(col[v]==col[u])
		{
			type=1;
			if(!viss[i])
			{
				tots++;
				viss[i]=viss[i^1]=1;
			}
		}
	}
}

int main()
{
	n=read();
	m=read();

	for(int i=1,u,v;i<=m;i++)
	{
		u=read();
		v=read();
		add(u,v);
		add(v,u);
	}

	long long ans=0;
	for(int i=1;i<=n;i++)
		if(!vis[i])
		{
			type=tots=0;
			cnt[0]=cnt[1]=0;
			col[i]=0;cnt[col[i]]=1;
			dfs(i);
			//printf("%d %d %d %d\n",cnt[0],cnt[1],tots,type);
			if(!type)
				ans+=(long long)cnt[0]*cnt[1]-tots;
			else
				ans+=(long long)(cnt[0]+cnt[1])*(cnt[0]+cnt[1]-1)/2-tots;
		}

	printf("%lld\n",ans);
	return 0;
}

