bool gg = 0;
void judge(int now){
    if (gg || vis[now]) return;
    vis[now] = 1;
    for (int i = 0; i < v[now].size(); i++){
        if (color[v[now][i]] == color[now]) {gg = 1; return;}
        color[v[now][i]] = 3 - color[now];
        judge(v[now][i]);
    }
}
int main(){
    int n, m;
    scanf("%d%d", &n, &m);
    for (int i = 0; i < m; i++){
        int a, b; scanf("%d%d", &a, &b);
        v[a].push_back(b);
        v[b].push_back(a);
    }
    color[1] = 1;
    judge(1);
    if (gg){
        cout << 1LL * n * (n - 1) / 2 - m << endl;
    }
    else{
        ll cnt1 = 0, cnt2 = 0;
        for (int i = 1; i <= n; i++){
            if (color[i] == 1) cnt1++;
            else cnt2++;
        }
        cout << cnt1 * cnt2 - m << endl;
    }
    return 0;
}
