struct UnionFind {
  vector<int> size, par;
  UnionFind(int n) {
    size.resize(n, 0);
    par.resize(n, 0);
    for(int i = 0; i < n; i++) {
      maketree(i);
    }
  }

  void maketree(int x) {
    par[x] = x;
    size[x] = 1;
  }

  int root(int x) {
    if(par[x] == x) return x;
    return par[x] = root(par[x]);
  }

  void unite(int x, int y) {
    int rx = root(x);
    int ry = root(y);
    if(rx == ry) return;
    if(size[rx] < size[ry]) par[rx] = ry;
    else {
      par[ry] = rx;
      if(size[rx] == size[ry]) size[rx]++;
    }
  }

  bool same(int x, int y) {
    int rx = root(x);
    int ry = root(y);
    return rx == ry;
  }
};

