struct uftree{
	int par[200005];
	int rank[200005];
	set<int> changed;
	bool flag;
	uftree(){
		flag=false;
	}
	void init(int n){
		if(!flag){
			for(int i=0;i<n;i++){
				par[i]=i;
				rank[i]=0;
			}
			flag=true;
		}else{
			for(set<int>::iterator it=changed.begin();it!=changed.end();it++){
				par[*it]=*it;
				rank[*it]=0;
			}
			changed.clear();
		}
	}
	int find(int x){
		if(par[x]==x)return x;
		return par[x]=find(par[x]);
	}

	void unite(int x,int y){
		x=find(x);
		y=find(y);
		if(x==y)return;
		changed.insert(x);
		changed.insert(y);
		if(rank[x]<rank[y]){
			par[x]=y;
		}else{
			if(rank[x]==rank[y])rank[x]++;
			par[y]=x;
		}
	}

	bool same(int x,int y){
		return find(x)==find(y);
	}
};

