		scanf("%d%d",&u,&v);
		u--;
		v--;
		G[u].push_back(v);
		G[v].push_back(u);
		if(uf.same(u,v)){
			cnt++;
		}
		uf.unite(u,v);
	}
	if(cnt>0){
		printf("%lld\n",(ll)n*(n-1LL)/2LL-m);
	}else{
		dfs(0,-1);
		int va=0;
		for(int i=0;i<n;i++){
			if(dist[va]<dist[i]){
				va=i;
			}
		}
		memset(dist,0,sizeof(dist));
		dfs(va,-1);
		va=0;
		for(int i=0;i<n;i++){
			if(dist[va]<dist[i]){
				va=i;
			}
		}
		if(dist[va]<=2){
			printf("0\n");
		}else{
			if((dist[va]+1LL)!=n){
				printf("%lld\n",(ll)n*(n-1LL)/2LL-m);
			}else{
				printf("%lld\n",(ll)n*(n-1LL)/2LL-m-n);
			}
		}

	}
	return 0;
}

