//約数
std::vector<int> divisor(int n) {
	std::vector<int> ret;
	for (int i = 1; i * i <= n; ++i) {
		if (n % i == 0) {
			ret.push_back(i);
			if (i * i != n) {
				ret.push_back(n / i);
			}
		}
	}
	return ret;
}

//素数判定
bool isPrime(int n) {
	if (n <= 1)return false;
	if (n == 2)return true;
	if (n % 2 == 0)return false;
	for (int i = 3; i * i <= n; i += 2) {
		if (n % i == 0)return false;
	}
	return true;
}

//素因数分解
std::map<int, int> primeFactorization(int n) {
	std::map<int, int> res;
	int k = 2;
	while (k * k <= n) {
		while (n % k == 0) {
			res[k]++;
			n /= k;
		}
		++k;
	}
	if (n != 1) {
		res[n]++;
	}
	return res;
}



