int main(){
    int N,M;
    cin >> N >> M;
    int once[N+1][N+1] = {};
    int twice[N+1][N+1] = {};
    int a,b;
    for(int i=0;i<M;i++){
        cin >> a >> b;
        once[a][b]=1;
        once[b][a]=1;
    }
    vector<int> stack;
    for(int cnt=0;cnt<4;cnt++){
        for(int i=1;i<=N;i++){
            stack.clear();
            for (int j=1;j<=N;j++){
                if (once[i][j]>0){
                    stack.push_back(j);
                }
            }
            for (auto itr1=stack.begin(); itr1!= stack.end();++itr1){
                for (auto itr2=itr1+1; itr2!= stack.end();++itr2){
                    twice[(*itr1)][(*itr2)] = 1;
                    twice[(*itr2)][(*itr1)] = 1;
                }
            }
        }
        for(int i=1;i<=N;i++){
            for (int j=1;j<=N;j++){
                if (once[i][j]>0){
                    for(int k=1;k<=N;k++){
                        if (twice[j][k] > 0 && i!=k){
                            once[i][k]=1;
                            once[k][i]=1;
                        }
                    }
                }
            }
        }
    }

    long result = 0;
    for(int i=1;i<=N;i++){
        for (int j=1;j<=N;j++){
            if (once[i][j] == 1){
                result++;
            }
            cout << once[i][j] << ' ';
        }
        cout << endl;
    }

    cout << result/2 - M  << endl;
    return 0;
}

