struct UnionFind {
    vector< int > data;
    UnionFind(int sz) {
        data.assign(sz, -1);
    }
    bool unite(int x, int y) {
        x = find(x), y = find(y);
        if(x == y) return (false);
        if(data[x] > data[y]) swap(x, y);
        data[x] += data[y];
        data[y] = x;
        return (true);
    }
    int find(int k) {
        if(data[k] < 0) return (k);
        return (data[k] = find(data[k]));
    }
    int size(int k) {
        return (-data[find(k)]);
    }
};

int main(void)
{
    cin.tie(0);
    ios::sync_with_stdio(false);
    ll n, m; cin >> n >> m;
    UnionFind uf(2 * n);
    rep (i, m) {
        int a, b; cin >> a >> b; a--; b--;
        uf.unite(2 * a, 2 * b + 1);
        uf.unite(2 * b, 2 * a + 1);
    }
    if (uf.find(0) != uf.find(1)) {
        ll x[2] = {};
        rep (i, n) x[(uf.find(2 * i) != uf.find(0))]++;
        eprintf("%lld %lld\n", x[0], x[1]);
        cout << x[0] * x[1] - m << "\n";
    } else {
        cout << n * (n - 1) / 2 - m << "\n";
    }
    return 0;
}

