#define LINT long long

int BipartiteGraph(const vector<vector<int>> &g) {
        int n = g.size();
        vector<int> color(n, -1);
        int white_cnt = 0;
        function<bool (int, int, int)> dfs = [&](int u, int prev, int c) {
                color[u] = c;
                if (c == 1) white_cnt ++;
                for (auto v : g[u]) if (v != prev) {
                        if (color[v] == -1) {
                                if (!dfs(v, u, 1 - c)) return false;
                        } else if (color[v] != 1 - c) {
                                return false;
                        }
                }
                return true;
        };
        if (!dfs(0, -1, 0)) return -1;
        return white_cnt;
}



int main(){
  int N, M;
  cin >> N >> M;
  vector<vector<int> > nlist(N);
  int a, b;
  REP(i, M){
    cin >> a >> b;
    nlist[a-1].push_back(b-1);
    nlist[b-1].push_back(a-1);
  }

  int x = BipartiteGraph(nlist);
  cout << ( (x==-1)? (LINT)N*(LINT)(N-1)/2-M : (LINT)x*(LINT)(N-x)-M ) << endl;

  return 0;
}

