bool dfs(int u, int c) {
	//色ぬって
	color[u] = c;

	//隣接した頂点へ遷移
	for (int i = 0; i < graph[u].size(); i++) {

		//隣接した頂点を取得
		int v = graph[u][i];

		//色が塗ってあって、しかも同じいろなら二部グラフでない
		if (color[v] == c) {
			return false;
		}

		//色が塗ってないなら、色を反転して遷移
		if (color[v] == 0 && !dfs(v, -c)) {
			return false;
		}
	}

	//全部の頂点巡れたら二部グラフ
	return true;
}

