    g[a].push_back(b);
    g[b].push_back(a);
  }
  int i = 1;
  int path = 0;
  bool change = false;
  bool flag = false;
  while(i < n) {
    change = false;

    for (int j = i+1; j < n+1; ++j) {
      flag = false;
      if (isInclude(i, g[j]))
        continue;
      for (int ic : g[i]) {
        for (int jc : g[j]) {
          if (isInclude(ic, g[jc])) {
            g[j].push_back(i);
            g[i].push_back(j);
            ++path;
            change = true;
            flag = true;
            break;
          }
        }
        if (flag)
          break;
      }
    }
    if (!change)
      ++i;
    else
      i = 1;
  }
  std::cout << path << std::endl;
}

