#define REP(i, limit) for(int i=0; i< limit; ++i)
#define LINT long long

//頂点0は塗分け用のノード、1~100000は1つ目のノードセット、100001~200000は二つ目のノードセット
const int MAX_N=200001;
int par[MAX_N]; //親の番号
int height[MAX_N]; //木の高さ(ランク)

//xの親番号を返す、再帰処理あり
int root(int x){
  return par[x] == x ? x : par[x] = root(par[x]);
}

//xとyの親番号が同一か判定する
bool same(int x, int y){
  return root(x) == root(y);
}

//xとyのある木を結合する
void unite(int x, int y){
  x = root(x);
  y = root(y);
  if(x == y) return; //親が同一なら結合済み。

  if(height[x] < height[y]) par[x] = y;
  else {
    par[y] = x;
    if(height[x] == height[y]) height[x]++;
  }
}

int main(){
  int N, M;
  cin >> N >> M;
  par[0]=0;
  height[0]=0;
  REP(i, N){
    par[i+1] = i+1;
    height[i+1] = 0;
    par[i+1+100000] = i+1+100000;
    height[i+1+100000] = 0;
  }
  pair<int, int> edge[M];
  REP(i, M) cin >> edge[i].first >> edge[i].second;

  unite(0, 1);
  REP(i, M){
    unite(edge[i].first, edge[i].second + 100000);
    unite(edge[i].first + 100000, edge[i].second);
  }

  //二部グラフ判定、ついでに一方の色に塗り分けた頂点の個数を数える
  bool bip=true;
  int color=0;
  REP(i, N){
    if(same(i+1, i+1+100000)) bip = false;
    if(same(0, i+1)) ++color;
  }

  LINT ans;
  if(bip) ans = (LINT)color*(LINT)(N-color)-M;
  else ans = (LINT)N*(LINT)(N-1)/2-M;

  cout << ans << endl;
  return 0;
}

