void find_3_distance(int node, int prev_node, int original_node, int depth, vector<set<int>> &G,\
                        set<int> &cand_nodes, stack<pair<int,int>> &next_cand){
//    printf("node=%d, depth=%d\n",node,depth);
    if(depth==2){
        //深さ2なので、次は3であるので、そこからつながっているノードすべてをcand_nodesに追加する
//    for(int i=0;i<G.at(node).size();i++){
    for(int temp_node: G.at(node)){
//        int temp_node = G.at(node).at(i);
        if(temp_node!=prev_node && temp_node!=original_node && cand_nodes.count(temp_node)==false){
            cand_nodes.insert(temp_node);
 //           printf("inserted node:%d\n",temp_node);
            //このtemp_nodeを深さ1のノードとして探索を再開する
            find_3_distance(temp_node, node, original_node, 1, G, cand_nodes, next_cand);
        }
    }
    return;
    }

    //次のノードをすべて列挙する
    //for(int i=0;i<G.at(node).size();i++){
    for(int temp_node: G.at(node)){
    //    int temp_node = G.at(node).at(i);
        if(temp_node!=prev_node){
            pair<int,int> next_node(temp_node,depth+1);
            next_cand.push(next_node);
        }
    }
    if(next_cand.size()==0){
        //次の行き先がないので終了
        return;
    }
    pair<int,int> next_node = next_cand.top();
    next_cand.pop();
    int next_pos, next_depth;
    tie(next_pos,next_depth) = next_node;
    find_3_distance(next_pos, node, original_node, next_depth, G, cand_nodes, next_cand);
}

