	if (g.is_bipartite()) {
		auto p = g.parts();
		// g.show(p[0]); g.show(p[1]);
		long long B = p[0].size(), W = p[1].size();
		long long ans = B * W - M;
		cout << ans << endl;
	} else {
		long long ans = N * (N - 1) / 2 - M;
		cout << ans << endl;
	}
}

