using Weight = int;
struct Edge {
  int dst;
  Weight weight;
  Edge() : dst(0), weight(0) {}
  Edge(int d, Weight w = 1) : dst(d), weight(w) {}
};
ostream &operator<<(ostream &os, const Edge &e) { return os << e.dst; }
using Edges = vector<Edge>;
using Graph = vector<Edges>;

ll solve() {
	int n = ri(), m = ri();
	Graph G(n);
	rep(i, m) {
		int u = ri() - 1;
		int v = ri() - 1;
		G[u].emplace_back(v);
		G[v].emplace_back(u);
	}
	out(G);

	bool ok = 1;

	vi C(n, -1);
	C[0] = 0;
	{
		function<void(int, int)> dfs = [&](int cur, int pre) {
			forr(nex, G[cur]) {
				if (nex.dst != pre) {
					if (C[nex.dst] == -1) {
						C[nex.dst] = 1 - C[cur];
						dfs(nex.dst, cur);
					}
					else {
						if (C[nex.dst] == C[cur]) {
							ok = 0;
							return;
						}
					}
				}
			}
		};
		dfs(0, -1);
	}
	out(C);

	if (ok) {
		vl cnt(2);
		rep(i, n) cnt[C[i]]++;
		return cnt[0] * cnt[1] - m;
	}
	else {
		return n * (n-1LL) / 2 - m;
	}
}

