  Q.push_back(0);
  Qs.push_back(0);
  ll idx=0;
  bool comp=false;
  while(idx<Q.size()) {
    ll mes=Qs[idx];
    ll me=Q[idx++];


    if(mes%2==1 && even[me] || mes%2==0 && odd[me]) {
      comp=true;
      break;
    }
    if(odd[me] || even[me])
      continue;
    if(mes%2==1) {
      odd[me]=true;
      o++;
    }
    if(mes%2==0) {
      even[me]=true;
      e++;
    }
    for(ll n:E[me]) {
      Q.push_back(n);
      Qs.push_back(mes+1);
    }
  }

  if(comp)
    cout << N*(N-1)/2 - M << endl;
  else
    cout << N*(N-1)/2 - M - o*(o-1)/2 - e*(e-1)/2 << endl;
}

