using namespace std;

void solve(vector<vector<bool>> &v, int &ans, bool &f, int p, int now, int par = -1, int count = 0){
	if(count == 3){
		if(!v[p][now] && p != now){
			ans++;
			f = false;
			//cerr << p << ' ' << now << endl;
		}
		v[p][now] = v[now][p] = true;
		return;
	}
	for(int i = 0; i < v[now].size(); i++){
		if(i != par && i != now && v[now][i]){
			solve(v, ans, f, p, i, now, count + 1);
		}
	}
}

int main(){
	int n, m;
	cin >> n >> m;
	vector<vector<bool>> v(n, vector<bool>(m, false));
	while(m--){
		int a, b;
		cin >> a >> b;
		a--;
		b--;
		v[a][b] = v[b][a] = true;
	}
	int ans = 0;
	while(true){
		bool f = true;
		for(int i = 0; i < n; i++){
			solve(v, ans, f, i, i);
		}
		if(f) break;
	}
	cout << ans << endl;
	return 0;
}

