		scan(A[i]);scan(B[i]);
		A[i]--;B[i]--;
	}
	UnionFind uf(N*2);
	rep(i,M){
		uf.unite(A[i],B[i]+N);
		uf.unite(A[i]+N,B[i]);
	}
