// 2部グラフ判定
vector<int> d(MAX, -1);
bool bfs(const vector<vector<int>> &G, int s) {
  queue<int> q;
  q.push(s);
  d[s] = 0;
  while (!q.empty()) {
    int u = q.front();
    q.pop();
    for (int i = 0; i < G[u].size(); i++) {
      if (d[G[u][i]] == -1) {
        d[G[u][i]] = (d[u] + 1) % 2;
        q.push(G[u][i]);
      }
      else if (d[G[u][i]] == d[u]) return false;
    }
  }
  return true;
}

