template<class T> struct Bipartite{

	Graph<T> G;
	bool is_bipartite = true;
	vector<int> col;
	long long cnt[2] = {0,0};

	Bipartite(Graph<T>& G):G(G),col(G.N, -1){}

	void dfs(int x,int c = 0){
		col[x] = c;
		cnt[c]++;
		for(auto e : G.g[x]){
			if(col[e.to] >= 0){
				if(col[e.to] == c){
					is_bipartite = false;
					return;
				}
			}else{
				dfs(e.to,c^1);
			}
		}
	}
	bool solve(){
		dfs(0);	
		return is_bipartite;
	}
};


