            // cout<<"bug "<<x<<" "<<s<<endl;
        }
        return;
    }
    for (int i=head[x];~i;i=edge[i].nxt)
    {
        int e = edge[i].v;
        if (vis[e]==0)
            dfs(e,dep+1,s);
    }
}
