template<class T> struct Edge{

	int to;
	T cost;

	Edge(int t = 0,T c = 1):to(t),cost(c){}

};
template<class T> struct Graph{

	int N,M;
	vector<vector<Edge<T> > > g;

	Graph(int N,int M):N(N),M(M),g(N,vector<Edge<T> >(0)){}

	void add_edge(int a,int b,T c = 1){
		g[a].emplace_back(b,c);
	}

};

template<class T> struct Bipartite{

	Graph<T> G;
	bool is_bipartite = true;
	vector<int> col;
	long long cnt[2] = {0,0};

	Bipartite(Graph<T>& G):G(G),col(G.N, -1){}

	void dfs(int x,int c = 0,int p = -1){
		col[x] = c;
		cnt[c]++;
		for(auto e : G.g[x]){
			if(e.to == p)continue;
			if(col[e.to] >= 0){
				is_bipartite =false;
				return;
			}else{
				dfs(e.to,c^1,x);
			}
		}
	}
	bool solve(){
		dfs(0);	
		return is_bipartite;
	}

};

