        es[from].push_back({to, weight});
        es[to].push_back({from, weight});
    }
    vector<Edge2> getEdge2() {
        vector<Edge2> ret;
        rep(i, n) for (auto && e : es[i]) {
            if (i < e.to) ret.push_back({i, e.to, e.weight});
        }
        return ret;
    }
