// 2部グラフかどうか
// 黒と白の2色で塗っていく
// u: 頂点，c:色
bool dfs(int u, int c) {
    used[u] = true;
    color[u] = c;
    for (auto v: edge[u]) {
        // (訪問済み and 色が違う) or (訪問してない and dfs(この頂点，違う色))
        if ((used[v] && 1 - c != color[v]) || (!used[v] && !dfs(v, 1-c))) {
            return false;
        }
    }

    return true;
}

int main(void) {
