        a--;
        b--;
        edge[a].insert(b);
        edge[b].insert(a);
    }

    if (!dfs(0, 0)) {
        // 2部グラフでない→奇数サイクルが存在（同じ色同士でのパスがあるから），
        // 任意の2頂点間に奇数長のパスを作成できる
        // よって，2頂点の組み合わせ - すでにある辺の数
        cout << N * (N - 1) / 2 - M << endl;
    } else {
        // 違う色同士の頂点間には必ず辺を貼ることができる，
        // 黒＊白 - すでにある辺
        int count = 0;
        REP(i, N) {
            count += color[i];
        }
        cout << count * (N - count) - M << endl;
    }

    return 0;
}

