struct UnionFind {
    vector<int> data;

    UnionFind(int size) : data(size, -1) {}

    bool unionSet(int x, int y) {
        x = root(x);
        y = root(y);
        if (x != y) {
            if (data[y] < data[x]) swap(x, y);
            data[x] += data[y];
            data[y] = x;
        }
        return x != y;
    }

    bool findSet(int x, int y) {
        return root(x) == root(y);
    }

    int root(int x) {
        return data[x] < 0 ? x : data[x] = root(data[x]);
    }

    int size(int x) {
        return -data[root(x)];
    }
};


void solve(ll N, ll M, vector<ll> A, vector<ll> B) {
    UnionFind uf(2 * N);
    for (int i = 0; i < M; i++) {
        A[i]--;
        B[i]--;
        uf.unionSet(2 * A[i], 2 * B[i] + 1);
        uf.unionSet(2 * A[i] + 1, 2 * B[i]);
    }
    if (uf.size(0) == N) {
        cout << (((N + 1) / 2) * (N / 2)) - M << endl;
    } else {
        assert(uf.size(0) == 2 * N);
        cout << N * (N - 1) / 2 - M << endl;
    }

}


