// ref: http://prd-xxx.hateblo.jp/entry/2017/10/13/004256
struct BipartileGraph {
    vi colors;
    vvi edges;
    BipartileGraph(int n) : colors(n, -1), edges(n) {}
    void addEdge(int f, int t) {
        edges[f].emplace_back(t);
        edges[t].emplace_back(f);
    }
    bool build(int s, int color = 0) {
        colors[s] = color;
        for (auto &e : edges[s]) {
            if (colors[e] == color)
                return false;
            if (colors[e] == -1 && !build(e, color ^ 1))
                return false;
        }
        return true;
    }
};

int main() {
    ll n, m;
    cin >> n >> m;
    BipartileGraph gr(n);
    for (int i = 0; i < m; ++i) {
        int a, b;
        cin >> a >> b;
        a--;
        b--;
        gr.addEdge(a, b);
    }
    bool bipartile = gr.build(0);
    if (bipartile) {
        int col1 = 0;
        int col2 = 0;
        for (int i = 0; i < n; ++i) {
            if (gr.colors[i] == 1)
                col1++;
            else
                col2++;
        }
        assert(col1 + col2 == n);
        cout << col1 * col2 - m << "\n";
    } else {
        cout << n * (n - 1) / 2 - m << "\n";
    }
    return 0;
}

