bool isBipartiteGraph(int v, int c) {
	color[v] = c;

	int si = g[v].size();
	for (int i = 0; i < si; ++i) {
		int nxt = g[v][i];
		if (color[nxt] == c) return false;
		if (color[nxt] == 0 and !isBipartiteGraph(nxt, -c)) return false;
