vvll cinGraph(ll nodeNum, ll edgeNum, bool isDirected){//無向false、有向true
	vvll to(nodeNum);
	REP(i, edgeNum){
		ll v, u; cin >> v >> u;
		v--; u--;
		to[v].push_back(u);
		if (!isDirected) to[u].push_back(v);
	}
	return move(to);
}

struct Bipartite{
	vvll &to; vll col;
	Bipartite(vvll &to,ll s=0):to(to),col(to.size()) {col[s]=1; if(dfs(s)) col.clear();}
	bool dfs(ll v){
		EACH(u, to[v]){
			if (col[u] == col[v]) return true;
			if (col[u] != 0) continue;
			col[u] = -col[v];
			if (dfs(u)) return true;
		}
		return false;
	}
	vll get(){ return move(col); }
};


void solve()
{
	ll N, M;  cin >> N >> M;
	vvll to = cinGraph(N, M, false);
	vll color = Bipartite(to).get();

	if (color.empty()){
		ll ans = N*(N-1)/2 - M;
		cout << ans << '\n';
		return;
	}

	ll A=0;
	EACH(e, color){
		if (e==1) A++;
	}
	ll B = N-A;
	ll ans = A*B-M;
	cout << ans << '\n';
}


int main(){
	solve();
	return 0;
}

