const int N = 1e5 + 5;

vector < vector < int > > adj (N);
vector < int > side (N, -1);
int cnt0 = 0, cnt1 = 0;

bool check_bipartite () {
  side[1] = 0;
  queue < int > q;
  q.push (1);
  while (!q.empty()) {
    int u = q.front(); q.pop();
    for (auto to : adj[u]) {
      if (side[to] == -1) {
        side[to] = side[u] ^ 1;
        q.push (to);
      } else if (side[u] == side[to]) {
        return false;
      }
    }
  }

  return true;
}

