#define SIZE 200005

using namespace std;
typedef long long int ll;
typedef pair <int,int> P;

struct UF
{
	int par[SIZE],nd[SIZE];

	void init(int n)
	{
		for(int i=0;i<n;i++)
		{
			par[i]=i;
			nd[i]=1;
		}
	}
	int find(int x)
	{
		if(x==par[x]) return x;
		return par[x]=find(par[x]);
	}
	void unite(int x,int y)
	{
		x=find(x);
		y=find(y);
		if(x==y) return;
		if(nd[x]<nd[y]) swap(x,y);
		par[y]=x;
		nd[x]+=nd[y];
	}
	bool same(int x,int y)
	{
		return find(x)==find(y);
	}
};
UF uf1,uf2;
int cnt[SIZE];

int main()
{
	int n,m;
	scanf("%d %d",&n,&m);
	uf1.init(n+2);
	uf2.init(2*n+2);
	for(int i=0;i<m;i++)
	{
		int a,b;
		scanf("%d %d",&a,&b);a--,b--;
		uf1.unite(a,b);
		uf2.unite(a,b+n);
		uf2.unite(a+n,b);
	}
	for(int i=0;i<n;i++)
	{
		int p=uf1.find(i);
		if(uf2.same(p,i)) cnt[p]++;
	}
	ll ret=0;
	for(int i=0;i<n;i++)
	{
		if(uf1.find(i)==i)
		{
			if(uf2.same(i,i+n))
			{
				int d=uf1.nd[i];
				ret+=(ll) d*(ll) (d-1)/2LL;
			}
			else
			{
				int a=cnt[i],b=uf1.nd[i]-a;
				ret+=(ll) a*(ll) b;
			}
		}
	}
	printf("%lld\n",ret-m);
	return 0;
}

