int is_bipartite(Graph &G) {
    int n = G.size();
    vector<int> color(n, -1);
    int cntW = 0;
    function<bool(int, int)> dfs = [&](int u, int c) {
        if ((color[u] = c)) cntW++;
        for (Edge &e : G[u]) {
            int v = e.dst;
            if (color[v] < 0) if (!dfs(v, 1 - c)) return false;
            if (color[v] != 1 - c) return false;
        }
        return true;
    };
    if (!dfs(0, 0)) return -1;
    return cntW;
}

