#include <bits/stdc++.h>
using namespace std;

bool is_bipartite (const vector<vector<int>>& g) {
    int n = g.size(), ret = 1;
    struct UnionFind {
        vector<int> data;
        UnionFind(int sz) : data(sz, -1) { }
        bool unite(int x, int y) {
            if ((x = root(x)) == (y = root(y))) { return false; }
            if (data[x] > data[y]) { swap(x, y); }
            data[x] += data[y]; data[y] = x; return true;
        }
        bool same(int x, int y) { return root(x) == root(y); }
        int root(int x) { return data[x] < 0 ? x : data[x] = root(data[x]); }

    } uf(2*n);
    for (int x = 0; x < n; x++) {
        for (auto& y : g[x]) { uf.unite(x, y+n); uf.unite(x+n, y); }
    }
    for (int x = 0; x < n; x++) if (uf.same(x, x+n)) { ret = 0; break; }
    return ret;
}

int main() {
    long long n, m;
    cin >> n >> m;
    long long k = n * (n - 1) / 2;
    vector<vector<int>> g(n);
    for (int i = 0; i < m; i++) {
        int a, b;
        cin >> a >> b;
        a--; b--;
        g[a].emplace_back(b);
        g[b].emplace_back(a);
    }

    if (is_bipartite(g)) {
        vector<int> col(n, 0);  col[0] = 1;
        stack<int> sta; sta.emplace(0);
        while (not sta.empty()) {
            int v = sta.top(); sta.pop();
            for (const auto &u : g[v]) {
                if (col[u] == 0) {
                    col[u] = col[v] * -1;
                    sta.emplace(u);
                }
            }
        }
        long long s = 0, t = 0;
        for (const auto &e : col) {
            if (e == 1) s++;
            else t++;
        }
        k = s * t;
    }

    cout << k - m << endl;
    return 0;
}

