const int maxn = (int) 1e5 + 5;
int n, m;
vector<int> g[maxn];

int read() {
  if (scanf("%d%d", &n, &m) < 2) {
    return false;
  }
  for (int i = 0; i < n; i++) {
    g[i].clear();
  }
  for (int i = 0; i < m; i++) {
    int v, u;
    scanf("%d%d", &v, &u);
    v--;
    u--;
    g[v].push_back(u);
    g[u].push_back(v);
  }
  return true;
}

int col[maxn];
int used[maxn];

int dfs1(int v) {
  used[v] = true;
  int res = 1;
  for (int i = 0; i < sz(g[v]); i++) {
    int u = g[v][i];
    if (used[u]) {
      continue;
    }
    res += dfs1(u);
  }
  return res;
}

pair<int, int> dfs2(int v) {
  pair<int, int> p(0, 0);
  if (col[v]) {
    p.second++;
  } else {
    p.first++;
  }
  for (int i = 0; i < sz(g[v]); i++) {
    int u = g[v][i];
    if (col[u] != -1) {
      if (col[u] == col[v]) {
        return make_pair(-1, -1);
      }
      continue;
    }
    col[u] = !col[v];
    pair<int, int> q = dfs2(u);
    if (q.first == -1) {
      return q;
    }
    p.first += q.first;
    p.second += q.second;
  }
  return p;
}

void solve() {
  for (int i = 0; i < n; i++) {
    col[i] = -1;
    used[i] = false;
  }
  long long res = -m;
  for (int i = 0; i < n; i++) {
    if (col[i] == -1 && !used[i]) {
      col[i] = 0;
      pair<int, int> p = dfs2(i);
      if (p.first == -1) {
        int k = dfs1(i);
        res += (long long) k * (k - 1) / 2;
      } else {
        res += (long long) p.first * p.second;
      }
    }
  }
  printf("%lld\n", res);
}

