#define getchar getchar_unlocked

#define INF 1000000000

inline int nextInt(void) {
	int ch;
	int minus, x;

	do {
		ch = getchar();
	} while (ch < '-');

	if (ch == '-') {
		minus = 1;
		ch = getchar();
	} else
		minus = 0;

	x = 0;
	while (ch >= '0' && ch <= '9') {
		x = x * 10 + (ch & 15);
		ch = getchar();
	}

	return minus ? -x : x;
}

typedef struct Edge {
	int to;
	struct Edge *next;
} Edge;

Edge e[100000 * 2], *adj[100000];
int e_size;
int d[100000];
int cnt[100000];
int queue[100000];
int front, rear;

void add(int from, int to) {
	e[e_size] = (Edge){to, adj[from]};
	adj[from] = e + e_size++;
}

int main(void) {
	int n, m;

	scanf("%d %d", &n, &m);
	for (int i = 0; i < m; i++) {
		const int a = nextInt() - 1, b = nextInt() - 1;
		add(a, b);
		add(b, a);
	}
	for (int i = 0; i < n; i++)
		d[i] = INF;

	d[0] = 0;
	queue[rear++] = 0;
	while (front != rear) {
		const int from = queue[front++];
		cnt[d[from]]++;
		for (Edge *p = adj[from]; p; p = p->next) {
			const int to = p->to;
			if (d[to] == INF) {
				d[to] = d[from] + 1;
				queue[rear++] = to;
			} else if (d[to] == d[from]) {
				printf("%lld\n", (long long)n * (n - 1) / 2 - m);
				return 0;
			}
		}
	}

	long long sum[2] = {0};
	for (int i = 0; i < 100000; i++)
		sum[i & 1] += cnt[i];

	printf("%lld\n", sum[0] * sum[1] - m);

	return 0;
}

import java.io.BufferedReader
import java.io.InputStream
import java.io.InputStreamReader
import java.io.PrintWriter
import java.lang.Exception
import java.util.*

fun PrintWriter.solve(sc: FastScanner) {
    val n = sc.nextInt()
    val m = sc.nextInt()
    val adj = Array(n) { mutableSetOf<Int>() }
    for (i in 0 until m) {
        val u = sc.nextInt() - 1
        val v = sc.nextInt() - 1
        adj[u].add(v)
        adj[v].add(u)
    }
    var isbipartite = true
    val color = Array(n) { 0 }
    val stack = Stack<Pair<Int, Int>>()
    stack.add(0 to 1)
    color[0] = 1
    while (stack.count() > 0) {
        val (v, c) = stack.pop()
        for (w in adj[v]) {
            if (color[w] == c) {
                isbipartite = false
                stack.clear()
                break
            } else if (color[w] == 0) {
                color[w] = -c
                stack.add(w to -c)
            }
        }
    }
    if (isbipartite) {
        val n1 = color.count { it == 1 }.toLong()
        val n2 = n - n1
        println(n1 * n2 - m)
    } else {
        println(n * (n - 1L) / 2 - m)
    }
}

fun main() {
    val writer = PrintWriter(System.out, false)
    writer.solve(FastScanner(System.`in`))
    writer.flush()
}

class FastScanner(s: InputStream) {
    private var st = StringTokenizer("")
    private val br = BufferedReader(InputStreamReader(s))

    fun next(): String {
        while (!st.hasMoreTokens()) st = StringTokenizer(br.readLine())

        return st.nextToken()
    }

    fun nextInt() = next().toInt()
    fun nextLong() = next().toLong()
    fun nextLine() = br.readLine()
    fun nextDouble() = next().toDouble()
    fun ready() = br.ready()
}

