    void solve() {
        int n = in.nextInt();
        int m = in.nextInt();
        List<List<Integer>> edges = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            edges.add(new ArrayList<>());
        }
        for (int i = 0; i < m; i++) {
            int a = in.nextInt() - 1;
            int b = in.nextInt() - 1;
            edges.get(a).add(b);
            edges.get(b).add(a);
        }
        Boolean[] bit = new Boolean[n];
        bit[0] = true;
        Deque<Integer> deque = new ArrayDeque<>();
        deque.add(0);
        boolean flag = false;
        while (!deque.isEmpty()) {
            int v = deque.poll();
            for (int u : edges.get(v)) {
                if (bit[u] == null || !bit[v] == bit[u]) {
                    if (bit[u] == null) {
                        deque.add(u);
                    }
                    bit[u] = !bit[v];
                } else {
                    flag = true;
                }
            }
        }
        long count1 = 0;
        long count2 = 0;
        for (int i = 0; i < n; i++) {
            if (bit[i]) {
                count1++;
            } else {
                count2++;
            }
        }
        if (flag) {
            out.println((long)n * (n - 1) / 2 - m);
        } else {
            out.println(count1 * count2 - m);
        }
    }

