	static class TaskX {
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			int n = in.nextInt(), m = in.nextInt();
			g = new ArrayList[n];
			g = Stream.generate(ArrayList::new).limit(n).toArray(List[]::new);

			for (int i = 0; i < m; i++) {
				int a = in.nextInt()-1, b = in.nextInt()-1;
				g[a].add(b);
				g[b].add(a);
			}

			color = new int[n];

			boolean isBipartite = true;
			for (int i = 0; i < n; i++) {
				if (color[i] == 0) {
					if(!isBipartite(i, 1)) {
						isBipartite = false;
					}
				}
			}

			long ans = 0;

			if (isBipartite) {
				long a = 0, b = 0;
				for (int i = 0; i < n; i++) {
					if(color[i] == 1) {
						a++;
					} else {
						b++;
					}
				}
				ans = a * b - m;
			} else {
				ans = n*(n-1)/2 - m;
			}

			out.println(ans);
		}

		static boolean isBipartite(int v, int c) {
			color[v] = c;
			for (int t : g[v]) {
				if (color[t] == c) {
					return false;
				}
				if (color[t] == 0 && !isBipartite(t, -c)) {
					return false;
				}
			}
			return true;
		}
	}

