                    if (s[e] != t) fill = true;
                    continue;
                }
                s[e] = t;
                queue[qs++] = (t << 24) | e;
            }
        }
        out.println((fill ? (long) n * (n - 1) / 2 : (long) c[0] * c[1]) - m);
    }

