        	N = ni();
        	M = ni();
        	int u, v;
        	for(int i=0; i < M; i++) {
        		u = ni() - 1;
        		v = ni() - 1;
        		G.add(u, v);
        		G.add(v, u);
        	}
//        	G.dump(out);
        	long ans = 0;
        	if(dfs(0, -1, 1)) {
        		ans = B * W - M;
//        		prn("1  ans = " + ans + "  B = " + B + "  W = " + W + "  M = " + M);
