    static class TaskC {
        static int MAXN = 100000 + 10;
        Vector<Integer>[] vec = new Vector[MAXN];
        int co[] = new int[MAXN];
        boolean f;

        void dfs(int u, int fa, int ok) {
            co[u] = ok;
            int p = ok ^ 1;
            for (int i = 0; i < vec[u].size() && !f; i++) {
                if (vec[u].get(i) == fa) continue;
                if (co[vec[u].get(i)] == 0) {
                    dfs(vec[u].get(i), u, p);
                } else {
                    if (co[vec[u].get(i)] != p) {
                        f = true;
                        return;
                    }
                }
            }
        }

        public void solve(int testNumber, InputReader in, OutputWriter out) {

            int n, m;
            n = in.nextInt();
            m = in.nextInt();
            for (int i = 0; i < m; i++) {
                int a, b;
                a = in.nextInt();
                b = in.nextInt();
                vec[a].add(b);
                vec[b].add(a);
            }
            f = false;
            dfs(1, -1, 0);
            if (f == true) {
                out.println("%lld\n", (long) n * (n - 1) / 2 - m);
            } else {
                int ans1 = 0, ans2 = 0;
                for (int i = 1; i <= n; i++) {
                    if (co[i] == 0) ans1++;
                    else
                        ans2 += 1;
                }
                out.println("%ld\n", (long) ans1 * ans2 - m);
            }
            return;
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void print(Object... objects) {
            for (int i = 0; i < objects.length; i++) {
                if (i != 0) {
                    writer.print(' ');
                }
                writer.print(objects[i]);
            }
        }

        public void println(Object... objects) {
            print(objects);
            writer.println();
        }

        public void close() {
            writer.close();
        }

    }
}

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.Queue;

public class Main {
	static InputStream is;
	static PrintWriter out;
	static String INPUT = "";

	static void solve()
	{
		int n = ni(), m = ni();
		DJSet ds = new DJSet(n);
		int[] from = new int[m];
		int[] to = new int[m];
		int p = 0;
		for(int i = 0;i < m;i++){
			int x = ni()-1 ,y = ni()-1;
			from[p] = x; to[p] = y; p++;
			if(ds.union(x, y)){
				ds.over[ds.root(x)] = true;
			}
		}


		long ans = -m;
		int[][] g = packU(n, from, to);
		int[] d = new int[n];
		Arrays.fill(d, 999999999);
		for(int i = 0;i < n;i++){
			if(ds.upper[i] < 0){
				int u = -ds.upper[i];
				if(ds.over[i]){
					ans += (long)u*(u-1)/2;
				}else{
					d[i] = 0;
					Queue<Integer> q = new ArrayDeque<>();
					q.add(i);
					int[] f = new int[2];
					while(!q.isEmpty()){
						int cur = q.poll();
						f[d[cur]]++;
						for(int e : g[cur]){
							if(d[e] > 2){
								d[e] = d[cur] ^ 1;
								q.add(e);
							}
						}
					}
					ans += (long)f[0]*f[1];
				}
			}
		}
		out.println(ans);
	}

	static int[][] packU(int n, int[] from, int[] to) {
		int[][] g = new int[n][];
		int[] p = new int[n];
		for (int f : from)
			p[f]++;
		for (int t : to)
			p[t]++;
		for (int i = 0; i < n; i++)
			g[i] = new int[p[i]];
		for (int i = 0; i < from.length; i++) {
			g[from[i]][--p[from[i]]] = to[i];
			g[to[i]][--p[to[i]]] = from[i];
		}
		return g;
	}

	public static class DJSet {
		public int[] upper;
		public boolean[] over;

		public DJSet(int n) {
			upper = new int[n];
			Arrays.fill(upper, -1);
			over = new boolean[n];
		}

		public int root(int x) {
			return upper[x] < 0 ? x : (upper[x] = root(upper[x]));
		}

		public boolean equiv(int x, int y) {
			return root(x) == root(y);
		}

		public boolean union(int x, int y) {
			x = root(x);
			y = root(y);
			if (x != y) {
				if (upper[y] < upper[x]) {
					int d = x;
					x = y;
					y = d;
				}
				over[x] |= over[y];
				upper[x] += upper[y];
				upper[y] = x;
			}
			return x == y;
		}

		public int count() {
			int ct = 0;
			for (int u : upper)
				if (u < 0)
					ct++;
			return ct;
		}
	}


