	class Node{
		int idx;
		HashSet<Node> nodes;
		public Node(int idx){
			this.idx = idx;
			nodes = new HashSet<>();
		}

		public boolean equals(Object o){
			return idx == ((Node)o).idx;
		}

		public int hashCode(){
			return idx;
		}
	}

	public void solve(){
		N = nextInt();
		M = nextInt();
		nodes = new Node[N];
		for(int i = 0; i < N; i++){
			nodes[i] = new Node(i);
		}

		for(int i = 0; i < M; i++){
			int a = nextInt() - 1;
			int b = nextInt() - 1;
			nodes[a].nodes.add(nodes[b]);
			nodes[b].nodes.add(nodes[a]);
		}
		int ans = 0;
		for(int i = 0; i < N; i++){
			ans += dfs(nodes[i], nodes[i], nodes[i], 0);
		}
		out.println(ans);
	}
	public int dfs(Node base, Node prev, Node cur, int d){
		if(d == 3){
			if(base != cur && !base.nodes.contains(cur)){
				base.nodes.add(cur);
				cur.nodes.add(base);

				int sum = 0;
				Node[] nn = cur.nodes.toArray(new Node[cur.nodes.size()]);
				for(Node n : nn){
					if(n != prev){
						sum += dfs(base, cur, n, 2);
					}
				}
				return sum + 1;
			}else{
				return 0;
			}

		}else{
			int sum = 0;
			Node[] nn = cur.nodes.toArray(new Node[cur.nodes.size()]);
			for(Node n : nn){
				if(n != prev){
					sum += dfs(base, cur, n, d + 1);
				}
			}
			return sum;
		}
	}


