import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.InputMismatchException;
import java.util.Map;
import java.util.TreeMap;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);

        int n = in.nextInt();
        int m = in.nextInt();

        graph = buildGraph(in, n, m);
        color = new int[n];

        long ans = 0;
        long all = (long)n  * (n - 1) / 2;
        if (!dfs(0, -1, 1)) {
            ans = all - m;
        } else {
            long white = 0;
            for (int i = 0; i < n ; i++) {
                if (color[i] == 1) {
                    white++;
                }
            }
            ans = white * (n - white) - m;
        }
        out.println(ans);
        out.flush();
    }
    static int[][] graph;
    static int[] color;

    static boolean dfs(int now, int par, int col) {
        if (color[now] != 0) {
            return color[now] == col;
        }
        color[now] = col;

        boolean res = true;
        for (int to : graph[now]) {
            if (to == par) {
                continue;
            }
            res &= dfs(to, now, -col);
        }
        return res;
    }

    static int[][] buildGraph(InputReader in, int n, int m) {
        int[][] edges = new int[m][];
        int[][] graph = new int[n][];
        int[] deg = new int[n];
        for (int i = 0 ; i < m ; i++) {
            int a = in.nextInt()-1;
            int b = in.nextInt()-1;
            deg[a]++;
            deg[b]++;
            edges[i] = new int[]{a, b};
        }
        for (int i = 0 ; i < n ; i++) {
            graph[i] = new int[deg[i]];
        }
        for (int i = 0 ; i < m ; i++) {
            int a = edges[i][0];
            int b = edges[i][1];
            graph[a][--deg[a]] = b;
            graph[b][--deg[b]] = a;
        }
        return graph;
    }

    public static void debug(Object... o) {
        System.err.println(Arrays.deepToString(o));
    }

    public static class InputReader {
        private static final int BUFFER_LENGTH = 1 << 12;
        private InputStream stream;
        private byte[] buf = new byte[BUFFER_LENGTH];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        private int next() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public char nextChar() {
            return (char) skipWhileSpace();
        }

        public String nextToken() {
            int c = skipWhileSpace();
            StringBuilder res = new StringBuilder();
            do {
                res.append((char) c);
                c = next();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        public int nextInt() {
            return (int) nextLong();
        }

        public long nextLong() {
            int c = skipWhileSpace();
            long sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = next();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = next();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public double nextDouble() {
            return Double.valueOf(nextToken());
        }

        int skipWhileSpace() {
            int c = next();
            while (isSpaceChar(c)) {
                c = next();
            }
            return c;
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}

import java.util.*;

public class Main {
    int n, m;
    ArrayList<ArrayList<Integer>> es;
    ArrayList<HashSet<Integer>> es2;
    Queue<Tuple> queue;

    public static void main(String[] args) {
        Main m = new Main();
        m.read();
        m.solve();
    }

    private void read() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        es = new ArrayList<>(n);
        es2 = new ArrayList<>(n);
        queue = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            es.add(new ArrayList<>());
            es2.add(new HashSet<>());
        }
        for (int i = 0; i < m; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            es.get(a).add(b);
            es.get(b).add(a);
        }
    }

    private void solve() {
        makeQueue();
        long ans = 0L;
        while (!queue.isEmpty()) {
            Tuple t = queue.poll();
            if (t.fst == t.snd || es.get(t.fst).contains(t.snd))
                continue;
            ans++;
//            System.out.printf("%d, %d\n", t.fst+1, t.snd+1);
            es.get(t.fst).add(t.snd);
            es.get(t.snd).add(t.fst);
            for (int i: es2.get(t.fst)) {
                queue.add(new Tuple(i, t.snd));
            }
            for (int i: es2.get(t.snd)) {
                queue.add(new Tuple(i, t.fst));
            }
        }
        System.out.println(ans);
    }

    private void makeQueue() {
        for (int i = 0; i < n; i++) {
            dfs(i, 0, i);
        }
    }

    private void dfs(int root, int depth, int current) {
        if (depth > 3)
            return;
        if (depth == 2) {
            es2.get(root).add(current);
        }
        if (depth == 3) {
            queue.add(new Tuple(root, current));
        }
        for (int nxt: es.get(current)) {
            dfs(root, depth+1, nxt);
        }
    }

    private class Tuple {
        int fst, snd;
        Tuple(int x, int y) {
            fst = x;
            snd = y;
        }
    }
}

