		int m = sc.nextInt();
		ArrayList<Integer>[] a = new ArrayList[n];
		for(int i=0; i<n; i++){
			a[i] = new ArrayList<Integer>();	
		}
		for(int i=0; i<m; i++){
			int ta = sc.nextInt() - 1;
