                throw new InputMismatchException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        boolean isEndline(int c) {
            return c == '\n' || c == '\r' || c == -1;
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] array = new int[n];
            for (int i = 0; i < n; i++)
                array[i] = nextInt();

            return array;
        }

        int[][] nextIntMap(int n, int m) {
            int[][] map = new int[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = in.nextIntArray(m);
            }
            return map;
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        long[] nextLongArray(int n) {
            long[] array = new long[n];
            for (int i = 0; i < n; i++)
                array[i] = nextLong();

            return array;
        }

        long[][] nextLongMap(int n, int m) {
            long[][] map = new long[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = in.nextLongArray(m);
            }
            return map;
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        double[] nextDoubleArray(int n) {
            double[] array = new double[n];
            for (int i = 0; i < n; i++)
                array[i] = nextDouble();

            return array;
        }

        double[][] nextDoubleMap(int n, int m) {
            double[][] map = new double[n][m];
            for (int i = 0; i < n; i++) {
                map[i] = in.nextDoubleArray(m);
            }
            return map;
        }

        String next() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));
            return res.toString();
        }

        String[] nextStringArray(int n) {
            String[] array = new String[n];
            for (int i = 0; i < n; i++)
                array[i] = next();

            return array;
        }

        String nextLine() {
            int c = read();
            while (isEndline(c))
                c = read();
            StringBuilder res = new StringBuilder();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isEndline(c));
            return res.toString();
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
	public static long solve(int n, int m, Map<Integer, List<Integer>> graph) {
		int[] color = new int[n];
		Queue<Integer> q = new LinkedList<>();
		q.offer(0);
		color[0] = 1;
		int blackCount = 1;
		int whiteCount = 0;
		while(!q.isEmpty()) {
			int next = q.poll();
			List<Integer> neighbors = graph.get(next);
			for(int neighbor : neighbors) {
				if(color[neighbor] == color[next]) {
					long total = ((long) n) * (n - 1) / 2;
					return total - m;
				} else if(color[neighbor] == 0) {
					int newColor = 3 - color[next];
					color[neighbor] = newColor;
					if(newColor == 1) {
						blackCount++;
					} else {
						whiteCount++;
					}
					q.offer(neighbor);
				}
			}
		}
		long count = 0;
		for(int i = 0; i < n; i++) {
			if(color[i] == 1) {
				count += whiteCount - graph.get(i).size();
			} else {
				count += blackCount - graph.get(i).size();
			}
		}
		return count/2;
	}
	public static void main(String[] args) throws IOException {
		BufferedReader f = new BufferedReader(new InputStreamReader(System.in));
		StringTokenizer st = new StringTokenizer(f.readLine());
		int n = Integer.parseInt(st.nextToken());
		int m = Integer.parseInt(st.nextToken());
		Map<Integer, List<Integer>> graph = new HashMap<>();
		for(int i = 0; i < n; i++) {
			graph.put(i, new ArrayList<>());
		}
		for(int i = 0; i < m; i++) {
			st = new StringTokenizer(f.readLine());
			int to = Integer.parseInt(st.nextToken()) - 1;
			int from = Integer.parseInt(st.nextToken()) - 1;
			graph.get(to).add(from);
			graph.get(from).add(to);
		}
		long answer = solve(n, m, graph);
		System.out.println(answer);
	}
}

