import java.io.*;
import java.util.*;

public class Main {
	static List<Integer>[] graph;
	static int[] col;

	public static void main(String[] args) {
		StdIn in = new StdIn();
		int n=in.nextInt(), m=in.nextInt();
		graph = new List[n];
		for(int i=0; i<n; ++i)
			graph[i] = new ArrayList<Integer>();
		for(int i=0; i<m; ++i) {
			int a=in.nextInt()-1, b=in.nextInt()-1;
			graph[a].add(b);
			graph[b].add(a);
		}
		boolean mag1 = false;
		for(int i=0; i<n; ++i) {
			if(graph[i].size()>1) {
				if(mag1) {
					mag1=false;
					break;
				}
				mag1=true;
			}
		}
		if(mag1) {
			System.out.println(0);
			return;
		}
		col = new int[n];
		Arrays.fill(col, -1);
		boolean hasOddCycle = dfs1(0, 0);
		if(hasOddCycle) {
			System.out.println((long)n*(n-1)/2-m);
		} else {
			System.out.println((long)n*n/4-m);
		}
	}

	static boolean dfs1(int node, int cCol) {
		col[node]=cCol;
		for(int neighbor : graph[node]) {
			if(col[neighbor]==-1&&dfs1(neighbor, cCol^1))
				return true;
			if(col[neighbor]==cCol)
				return true;
		}
		return false;
	}

	interface Input {
		public String next();
		public String nextLine();
		public int nextInt();
		public long nextLong();
		public double nextDouble();
	}
	static class StdIn implements Input {
		final private int BUFFER_SIZE = 1 << 16;
		private DataInputStream din;
		private byte[] buffer;
		private int bufferPointer, bytesRead;

		public StdIn() {
			din = new DataInputStream(System.in);
			buffer = new byte[BUFFER_SIZE];
			bufferPointer = bytesRead = 0;
		}

		public StdIn(String filename) {
			try{
				din = new DataInputStream(new FileInputStream(filename));
			} catch(Exception e) {
				throw new RuntimeException();
			}
			buffer = new byte[BUFFER_SIZE];
			bufferPointer = bytesRead = 0;
		}

		public String next() {
			int c;
			while((c=read())!=-1&&(c==' '||c=='\n'||c=='\r'));
			StringBuilder s = new StringBuilder();
			while (c != -1)
			{
				if (c == ' ' || c == '\n'||c=='\r')
					break;
				s.append((char)c);
				c=read();
			}
			return s.toString();
		}

		public String nextLine() {
			int c;
			while((c=read())!=-1&&(c==' '||c=='\n'||c=='\r'));
			StringBuilder s = new StringBuilder();
			while (c != -1)
			{
				if (c == '\n'||c=='\r')
					break;
				s.append((char)c);
				c = read();
			}
			return s.toString();
		}

		public int nextInt() {
			int ret = 0;
			byte c = read();
			while (c <= ' ')
				c = read();
			boolean neg = (c == '-');
			if (neg)
				c = read();
			do
			{
				ret = ret * 10 + c - '0';
			}  while ((c = read()) >= '0' && c <= '9');

			if (neg)
				return -ret;
			return ret;
		}

		public int[] readIntArray(int n) {
			int[] ar = new int[n];
			for(int i=0; i<n; ++i)
				ar[i]=nextInt();
			return ar;
		}

		public long nextLong() {
			long ret = 0;
			byte c = read();
			while (c <= ' ')
				c = read();
			boolean neg = (c == '-');
			if (neg)
				c = read();
			do {
				ret = ret * 10 + c - '0';
			}
			while ((c = read()) >= '0' && c <= '9');
			if (neg)
				return -ret;
			return ret;
		}

		public long[] readLongArray(int n) {
			long[] ar = new long[n];
			for(int i=0; i<n; ++i)
				ar[i]=nextLong();
			return ar;
		}

		public double nextDouble() {
			double ret = 0, div = 1;
			byte c = read();
			while (c <= ' ')
				c = read();
			boolean neg = (c == '-');
			if (neg)
				c = read();

			do {
				ret = ret * 10 + c - '0';
			}
			while ((c = read()) >= '0' && c <= '9');

			if (c == '.')
			{
				while ((c = read()) >= '0' && c <= '9')
				{
					ret += (c - '0') / (div *= 10);
				}
			}

			if (neg)
				return -ret;
			return ret;
		}

		private void fillBuffer() throws IOException {
			bytesRead = din.read(buffer, bufferPointer = 0, BUFFER_SIZE);
			if (bytesRead == -1)
				buffer[0] = -1;
		}

		private byte read() {
			try{
				if (bufferPointer == bytesRead)
					fillBuffer();
				return buffer[bufferPointer++];
			} catch(IOException e) {
				throw new RuntimeException();
			}
		}

		public void close() throws IOException {
			if (din == null)
				return;
			din.close();
		}
	}
}

import java.util.List;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.Scanner;

public class Main {

	static List<Set<Integer>> next = new ArrayList<Set<Integer>>();
	static int cnt = 0;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int n = sc.nextInt();
		int m = sc.nextInt();

		for (int i = 0; i < n + 1; i++) {
			next.add((Set<Integer>) Collections.newSetFromMap (new ConcurrentHashMap<Integer, Boolean>()));
		}
		for (int i = 0; i < m; i++) {
			int a = sc.nextInt();
			int b = sc.nextInt();
			next.get(a).add(b);
			next.get(b).add(a);
		}

		int idx = 1;
		while (idx <= n) {
			Set<Integer> set = new HashSet<>();
			set.add(idx);
			dfs(set, idx, 0);
			idx++;
		}

		System.out.print(cnt);

	}

	static void dfs(Set<Integer> set, int first, int distance) {
		if (distance == 3) {
			if (set.size() != 0) {
				for (int value : set) {
					if (!next.get(first).contains(value) && first != value) {
						next.get(first).add(value);
						next.get(value).add(first);
						cnt ++;
					}
				}
			}
			return;
		} else {
			for (int value : set) {
				Set<Integer> nextSet = new HashSet<>();
				nextSet = next.get(value);
				if (nextSet.size() != 0) {
					dfs(nextSet, first, distance + 1);
				}
			}
			return;
		}
	}
}

import java.io.*;
import java.util.*;

public class Main{
	int N;
	int M;
	Node[] nodes;

	class Node{
		int idx;
		HashSet<Node> nodes;
		public Node(int idx){
			this.idx = idx;
			nodes = new HashSet<>();
		}

		public boolean equals(Object o){
			return idx == ((Node)o).idx;
		}

		public int hashCode(){
			return idx;
		}
	}

	public void solve(){
		N = nextInt();
		M = nextInt();
		nodes = new Node[N];
		for(int i = 0; i < N; i++){
			nodes[i] = new Node(i);
		}

		for(int i = 0; i < M; i++){
			int a = nextInt() - 1;
			int b = nextInt() - 1;
			nodes[a].nodes.add(nodes[b]);
			nodes[b].nodes.add(nodes[a]);
		}
		int ans = 0;
		for(int i = 0; i < N; i++){
			while(true){
				int ret = dfs(nodes[i], nodes[i], nodes[i], 0);
				if(ret == 0) break;
				ans += ret;
			}
		}
		out.println(ans);
	}
	public int dfs(Node base, Node prev, Node cur, int d){
		if(d == 3){
			if(base != cur && !base.nodes.contains(cur)){
				base.nodes.add(cur);
				cur.nodes.add(base);
				return 1;
			}else{
				return 0;
			}

		}else{
			int sum = 0;
			while(true){
				int val = 0;
				for(Node n : cur.nodes){
					if(n != prev){
						val = dfs(base, cur, n, d + 1);
						if(val != 0){
							sum += val;
							break;
						}
					}
				}
				if(val == 0) break;
			}
			return sum;
		}
	}


	private static PrintWriter out;
	public static void main(String[] args){
		out = new PrintWriter(System.out);
		new Main().solve();
		out.flush();
	}

	public static int nextInt(){
		int num = 0;
		String str = next();
		boolean minus = false;
		int i = 0;
		if(str.charAt(0) == '-'){
			minus = true;
			i++;
		}
		int len = str.length();
		for(;i < len; i++){
			char c = str.charAt(i);
			if(!('0' <= c && c <= '9')) throw new RuntimeException();
			num = num * 10 + (c - '0');
		}
		return minus ? -num : num;
	}

	public static long nextLong(){
		long num = 0;
		String str = next();
		boolean minus = false;
		int i = 0;
		if(str.charAt(0) == '-'){
			minus = true;
			i++;
		}
		int len = str.length();
		for(;i < len; i++){
			char c = str.charAt(i);
			if(!('0' <= c && c <= '9')) throw new RuntimeException();
			num = num * 10l + (c - '0');
		}
		return minus ? -num : num;
	}
	public static String next(){
		int c;
		while(!isAlNum(c = read())){}
		StringBuilder build = new StringBuilder();
		build.append((char)c);
		while(isAlNum(c = read())){
			build.append((char)c);
		}
		return build.toString();
	}


	private static byte[] inputBuffer = new byte[1024];
	private static int bufferLength = 0;
	private static int bufferIndex = 0;
	private static int read(){
		if(bufferLength < 0) throw new RuntimeException();
		if(bufferIndex >= bufferLength){
			try{
				bufferLength = System.in.read(inputBuffer);
				bufferIndex = 0;
			}catch(IOException e){
				throw new RuntimeException(e);
			}
			if(bufferLength <= 0) return (bufferLength = -1);
		}
		return inputBuffer[bufferIndex++];
	}

	private static boolean isAlNum(int c){
		return '!' <= c && c <= '~';
	}
}

