        // -----------------------------------------
        // 木を処理するサンプル
        //

        Graph G = new Graph();					// グラフのリンクリスト
        int[] C = new int[100010];
        long B = 0, W = 0;
        long N, M;

        // ２部グラフチェック　２部グラフなら　true を返す
        // now : 頂点番号(0 - N-1)    parent : 親の頂点番号    color : 色
        boolean dfs(int now, int parent, int color) {
//        	prn("dfs  now = " + now + "  parent = " + parent + "  color = " + color);
        	if(C[now] != 0) {
        		if(C[now] != color) {
//        		prn("C[" + now + "] = " + C[now] + "  color = " + color + " --> return false");
	        		return false;
        		} else {
        			return true;
        		}
        	}
        	C[now] = color;
//        	prn("  set  C[" + now + "] = " + C[now]);
        	if(color == 1)	B++;
        	else			W++;
        	boolean ans = true;
        	for(Integer next : G.get(now)) {
        		if(next == parent)	continue;					// 親は処理しない
        		ans = dfs(next, now, (color == 1 ? -1 : 1));	// 子を呼ぶ
        		if(!ans)	break;
        	}
//        	prn("return " + ans);
        	return ans;
        }
        public void solve() {
        	N = ni();
        	M = ni();
        	int u, v;
        	for(int i=0; i < M; i++) {
        		u = ni() - 1;
        		v = ni() - 1;
        		G.add(u, v);
        		G.add(v, u);
        	}
//        	G.dump(out);
        	long ans = 0;
        	if(dfs(0, -1, 1)) {
        		ans = B * W - M;
//        		prn("1  ans = " + ans + "  B = " + B + "  W = " + W + "  M = " + M);
        	} else {
        		ans = N * (N-1) / 2 - M;
//        		prn("2  ans = " + ans + "  N = " + N + "  M = " + M);
        	}
        	prn(ans);
       }

