class SGraph {

	NodeList[] nlist; //隣接リスト

	public SGraph(int vnum){
		this.nlist = new NodeList[vnum];
		for(int i=0;i<vnum;i++){
			nlist[i] = new NodeList();
		}
	}

	//2部グラフかどうか判定
	boolean isBipartite(){
		//白黒で2彩色可能か判定
		boolean[] isBlack = new boolean[vnum()];
		boolean[] isChecked = new boolean[vnum()];
		java.util.ArrayDeque<Integer> q = new java.util.ArrayDeque<>();

		boolean con = true;

		while(con){

			int core = -1;
			for(int i=0;i<vnum();i++){
				if(!isChecked[i]){
					core = i;
				}
			}

			if(core!=-1){
				q.offerFirst(core);
				isBlack[core] = true;
				isChecked[core] = true;

				while(!q.isEmpty()){
					int now = q.pollFirst();

					for(int i:nextList(now)){
						if(!isChecked[i]){
							isChecked[i] = true;
							isBlack[i] = !isBlack[now];
							q.offerFirst(i);
						}
						else{
							if(isBlack[i] == isBlack[now]){
								return false;
							}
						}
					}
				}	
			}
			else{
				con = false;
			}	

		}

		return true;
	}

	int bipartiteNum(){
		//白黒で2彩色可能か判定
		boolean[] isBlack = new boolean[vnum()];
		boolean[] isChecked = new boolean[vnum()];
		java.util.ArrayDeque<Integer> q = new java.util.ArrayDeque<>();

		q.offerFirst(0);
		isBlack[0] = true;
		isChecked[0] = true;

		while(!q.isEmpty()){
			int now = q.pollFirst();

			for(int i:nextList(now)){
				if(!isChecked[i]){
					isChecked[i] = true;
					isBlack[i] = !isBlack[now];
					q.offerFirst(i);
				}
				else{
					if(isBlack[i] == isBlack[now]){
						return -1;
					}
				}
			}
		}	

		//ここに到達すれば二部グラフ
		int blacknum = 0;
		for(int i=0;i<vnum();i++){
			if(isBlack[i]){
				blacknum += 1;
			}
		}

		return Math.min(blacknum, vnum()-blacknum);
	}

	int[] distanceList(int n){

		java.util.ArrayDeque<Integer> q = new java.util.ArrayDeque<>();
		int[] d = new int[vnum()];	//nとの距離。未チェックなら-1。
