		d[n] = 0;

		while(!q.isEmpty()){
			int now = q.pollFirst();

			for(int i:nextList(now)){
				if(d[i] == -1){
					if(i==m){
						return d[now]+1;
					}

					d[i] = d[now]+1;
					q.offerLast(i);
				}
			}
		}

		return -1;
	}

