    static class TaskC {
        Graph graph;
        boolean flg = false;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();

            graph = new Graph(n);
            for (int i = 0; i < m; i++) {
                int from = in.nextInt() - 1;
                int to = in.nextInt() - 1;

                graph.addUndirectedEdge(from, to);
            }

            int[] no = new int[n];
            rec(no, 0, 1);

            if (flg) {
                long ans = n * (n - 1) / 2 - m;
                out.println(ans);
            } else {
                long cnt1 = 0;
                long cnt2 = 0;
                for (int i = 0; i < n; i++) {
                    if (no[i] == 1) {
                        cnt1++;
                    } else if (no[i] == 2) {
                        cnt2++;
                    } else {
                        throw new RuntimeException();
                    }
                }

                out.println(cnt1 * cnt2 - m);
            }
        }

        void rec(int[] no, int x, int tmpNo) {
            no[x] = tmpNo;
            for (int to : graph.get(x)) {
                if (no[to] == 0) {
                    no[to] = 3 - tmpNo;
                    rec(no, to, 3 - tmpNo);
                } else {
                    if (no[to] == tmpNo) {
                        flg = true;
                    }
                }
            }
        }

