	//連結成分数を返す
	int CCNum(){
    	boolean[] isVisited = new boolean[vnum()];
    	int CNum = 0;

    	boolean con = true;

    	while(con){
    		int core = -1;

    		for(int i=0;i<vnum();i++){
    			if(!isVisited[i]){
    				core = i;
    				break;
    			}
    		}

    		if(core==-1){
    			con = false;
    		}
    		else{

    			ArrayDeque<Integer> s = new ArrayDeque<>();
    			s.offerFirst(core);
    			isVisited[core] = true;
    			CNum += 1;

    			while(!s.isEmpty()){
    				int now = s.pollFirst();

    				for(int i:this.nextList(now)){

    					if(!isVisited[i]){
        					s.offerFirst(i);
        					isVisited[i] = true;
    					}

    				}

    			}

    		}
    	}

    	return CNum;
	}

	//連結成分に分割
	java.util.LinkedList<SGraph> CCSet(){
		java.util.LinkedList<SGraph> set = new java.util.LinkedList<>();

    	boolean[] isVisited = new boolean[vnum()];

    	boolean con = true;

    	while(con){
    		int core = -1;

    		for(int i=0;i<vnum();i++){
    			if(!isVisited[i]){
    				core = i;
    				break;
    			}
    		}

    		if(core==-1){
    			con = false;
    		}
    		else{
    			java.util.ArrayList<Integer> list = new java.util.ArrayList<>();
    			ArrayDeque<Integer> s = new ArrayDeque<>();
    			s.offerFirst(core);
    			list.add(core);
    			isVisited[core] = true;

    			while(!s.isEmpty()){
    				int now = s.pollFirst();

    				for(int i:this.nextList(now)){

    					if(!isVisited[i]){
        					s.offerFirst(i);
        					isVisited[i] = true;
        					list.add(i);
    					}
    				}

    			}

    			Collections.sort(list);;
    			int size = list.size();
    			SGraph g = new SGraph(size);

    			int[] newindex = new int[this.vnum()];

    			for(int i=0;i<list.size();i++){
    				newindex[list.get(i)] = i;
    			}

    			for(int i:list){
    				for(int j:this.nlist[i]){
    					if(i<j){
        					g.addEdge(newindex[i],newindex[j]);
    					}
    				}
    			}

    			set.add(g);

    		}
    	}

    	return set;
	}

	//2点間距離をBFSで求める。連結していないなら-1を返す。
	int distance(int n, int m){

		java.util.ArrayDeque<Integer> q = new java.util.ArrayDeque<>();
		int[] d = new int[vnum()];	//nとの距離。未チェックなら-1。
		for(int i=0;i<vnum();i++){
			d[i] = -1;
		}

		q.add(n);
		d[n] = 0;

		while(!q.isEmpty()){
			int now = q.pollFirst();

			for(int i:nextList(now)){
				if(d[i] == -1){
					if(i==m){
						return d[now]+1;
					}

					d[i] = d[now]+1;
					q.offerLast(i);
				}
			}
		}

		return -1;
	}

}

