    			isVisited[core] = true;
    			CNum += 1;

    			while(!s.isEmpty()){
    				int now = s.pollFirst();

    				for(int i:this.nextList(now)){

    					if(!isVisited[i]){
        					s.offerFirst(i);
        					isVisited[i] = true;
