public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        Task1002 solver = new Task1002();
        solver.solve(1, in, out);
        out.close();
    }

    static class Task1002 {
        int[][] dp;
        ArrayList<Integer>[] edges;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            edges = new ArrayList[n + 1];
            for (int i = 1; i <= n; ++i) edges[i] = new ArrayList<>();
            for (int i = 0; i < m; ++i) {
                int x, y;
                x = in.nextInt();
                y = in.nextInt();
                edges[x].add(y);
                edges[y].add(x);
            }
            dp = new int[n + 1][2];
            dfs(1, 0);
            int[][] cnt = new int[2][2];
            long ans = 0;
            for (int i = 1; i <= n; ++i) {
                cnt[dp[i][0]][dp[i][1]]++;
            }
            ans += 1L * cnt[1][0] * cnt[0][1];
            ans += 1L * cnt[1][0] * cnt[1][1];
            ans += 1L * cnt[0][1] * cnt[1][1];
            ans += 1L * cnt[1][1] * (cnt[1][1] - 1) / 2;
            ans -= m;
            out.println(ans);
        }

        private void dfs(int node, int odd) {
            if (dp[node][odd] > 0) return;
            dp[node][odd] = 1;
            for (int y : edges[node]) {
                dfs(y, odd ^ 1);
            }
        }

    }

    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public boolean hasNext() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    final String line = reader.readLine();
                    if (line == null) return false;
                    tokenizer = new StringTokenizer(line);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return true;
        }

        public String next() {
            if (hasNext()) return tokenizer.nextToken();
            return null;
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.util.Scanner;

public class Main {

    static int[][] graph;
    static int[] color;
    static long wCnt = 0;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        graph = buildGraph(sc, N, M);
        long ans = 0;
        color = new int[N];
        if (dfs(0, 0, 1)) {
            ans = wCnt * (N - wCnt) - M;
        } else{
           ans = ((long) N * (N - 1)) / 2 - M;
        }
        System.out.println(ans);
        sc.close();

    }

    private static boolean dfs(int pre, int cur, int c) {
        color[cur] = c;
        if(c == 1) wCnt++;
        boolean ret = true;
        for(int i = 0; i < graph[cur].length; i++){
            int x = graph[cur][i];
            if(color[x] != 0 && color[x] != -c){
                ret = false;
                break;
            }
            if(x == pre) continue;
            ret &= dfs(cur, x, -c);
        }

        return ret;
    }

    public static int[][] buildGraph(Scanner sc, int n, int m){
        int[][] graph = new int[n][];
        int[][] edges = new int[m][2];
        int[] deg = new int[n];
        for (int i = 0; i < m; i++) {
            int a = sc.nextInt() -1;
            int b = sc.nextInt() -1;
            edges[i][0] = a;
            edges[i][1] = b;
            deg[a]++;
            deg[b]++;
        }
        for (int i = 0; i < n; i++) {
            graph[i] = new int[deg[i]];
        }
        for (int i = 0; i < m; i++) {
            int a = edges[i][0];
            int b = edges[i][1];
            graph[a][--deg[a]] = b;
            graph[b][--deg[b]] = a;
        }

        return graph;
    }

}

