		int count = (int)(Math.log(M)/Math.log(3))+1;
		for(int h=0; h<count; h++){
			for(int i=1; i<=N; i++){
				Set<Integer> v = new HashSet<>();
				for(int j: nodes[i].n3){
					for(int nn: nodes[j].n2){
						if(!(i==nn)&& !nodes[i].n1.contains(nn)){
							nodes[nn].n3.add(i);
							v.add(nn);
						}
					}
				}
				nodes[i].n3.addAll(v);
			}
		}

		long ans = 0;
		for(int i=1; i<=N; i++){
			ans += nodes[i].n3.size();
		}

		System.out.println(ans/2);

	}

}

