public class Main {
    public static void main(String[] args) {
        var sc = new BasicScanner(System.in);
        int n = sc.nextInt(), m = sc.nextInt();
        var g = new IntArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new IntArrayList();
        for (int j = 0; j < m; j++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            g[a].add(b);
            g[b].add(a);
