    for (int i = 0; i < m; i++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;
      edgeCount ++;
    }

    int[][] g = packU(n, from, to);
    int[] color = new int[n];
    boolean isbi = dfs(0, 1, g,color);
    if (isbi) {
      long c1 = 0;
      for (int c : color) if (c == 1) c1 ++;
