      System.out.println(c1 * c2 - edgeCount);
    } else {
      System.out.println((long)n * (n - 1) / 2 - edgeCount);
    }
  }


  private static boolean dfs(int now, int nowColor, int[][] g, int[] color) {
    color[now] = nowColor;
    for (int next : g[now]) {
      if (color[next] == 0) {
         if(!dfs(next, -nowColor, g, color)) {
           return false;
         }
      } else {
        if (color[next] != -nowColor) {
          return false;
        }
      }
    }
    return true;
  }

  public static int[][] packU(int n, int[] from, int[] to){ return packU(n, from, to, from.length); }
  public static int[][] packU(int n, int[] from, int[] to, int sup)
  {
      int[][] g = new int[n][];
      int[] p = new int[n];
      for(int i = 0;i < sup;i++)p[from[i]]++;
      for(int i = 0;i < sup;i++)p[to[i]]++;
      for(int i = 0;i < n;i++)g[i] = new int[p[i]];
      for(int i = 0;i < sup;i++){
          g[from[i]][--p[from[i]]] = to[i];
          g[to[i]][--p[to[i]]] = from[i];
      }
      return g;
  }

