        		v = ni() - 1;
        		G.add(u, v);
        		G.add(v, u);
        	}
//        	G.dump(out);
        	long ans = 0;
        	if(dfs(0, -1, 1)) {
        		ans = B * W - M;
//        		prn("1  ans = " + ans + "  B = " + B + "  W = " + W + "  M = " + M);
        	} else {
        		ans = N * (N-1) / 2 - M;
//        		prn("2  ans = " + ans + "  N = " + N + "  M = " + M);
        	}
        	prn(ans);
