public class Main {
	private static final int MOD = 1000000007;

	public static void main(String[] args) throws Exception {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		char[] tmp = sc.next().toCharArray();
		boolean[] s = new boolean[N];
		for (int i = 0; i < N; i++) {
			s[i] = tmp[i] == '1';
		}

		long count = 0;
		while (true) {
			int prevIndex = -1;
			int max = -1;
			int maxIndex = -1;
			boolean toRight = false;
			while (true) {
				int index = -1;
				for (int i = prevIndex + 1; i < s.length - 2; i++) {
					if (s[i] && !s[i + 1] && s[i + 2]) {
						index = i;
						break;
					}
				}
				if (index == -1) {
					break;
				}
				prevIndex = index;

				int right = 0;
				for (int i = index + 3; i < s.length; i++) {
					if (!s[i]) {
						break;
					}
					right++;
				}
				int left = 0;
				for (int i = index - 1; i >= 0; i--) {
					if (!s[i]) {
						break;
					}
					left++;
				}
				if (max < right) {
					max = right;
					maxIndex = index;
					toRight = true;
				}
				if (max < left) {
					max = left;
					maxIndex = index;
					toRight = false;
				}
			}

			if (max == -1) {
				System.out.println(count);
				return;
			}

			if (toRight) {
				for (int i = 0; i <= max; i++) {
					count++;
					s[maxIndex + i + 0] = false;
