    static class TaskC {
        List<Integer>[] adj;
        int[] col;
        int[] am = new int[2];
        boolean twoColorable;

        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            adj = new List[n];
            for (int i = 0; i < n; i++) {
                adj[i] = new ArrayList<>();
            }
            for (int i = 0; i < m; i++) {
                int a = in.nextInt() - 1;
                int b = in.nextInt() - 1;
                adj[a].add(b);
                adj[b].add(a);
            }
            col = new int[n];
            Arrays.fill(col, -1);
            twoColorable = true;
            dfs(0, 0);
            long ans = 0;
            if (twoColorable) {
                ans = am[0] * (long) am[1];
            } else {
                ans = n * (long) (n - 1) / 2;
            }
            ans -= m;
            out.println(ans);
        }

        private void dfs(int v, int c) {
            col[v] = c;
            ++am[c];
            for (int u : adj[v]) {
                if (col[u] < 0) {
                    dfs(u, 1 - c);
                } else if (col[u] != 1 - c) {
                    twoColorable = false;
                }
            }
        }

    }

