import java.util.ArrayList;
import java.util.HashMap;
import java.util.Scanner;

public class Main {

    static HashMap<Integer, ArrayList<Integer>> map;
    static int[] color;
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        map = new HashMap<Integer, ArrayList<Integer>>();
        for (int i = 1; i <= N; i++) map.put(i, new ArrayList<Integer>());
        for (int i = 0; i < M; i++) {
            int a = sc.nextInt();
            int b = sc.nextInt();
            map.get(a).add(b);
            map.get(b).add(a);
        }
        color = new int[N+1];
        long ans = 0;
        if (dfs(0, 1, 1)) {
            long white = 0;
            for (int i = 1; i < N; i++) {
                if (color[i] == 1) white++;
            }
            ans = white * (N - white) - M;
        } else{
           ans = (long) N * (N - 1) / 2 - M;
        }
        System.out.println(ans);
        sc.close();

    }

    private static boolean dfs(int pre, int cur, int c) {
        if(color[cur] == 0){
            color[cur] = c;
        }else if(color[cur] != c){
            return false;
        }
        boolean ret = true;
        for(int i = 0; i < map.get(cur).size(); i++){
            int x = map.get(cur).get(i);
            if(x == pre) continue;
            ret &= dfs(cur, x, -c);
        }

        return ret;
    }

}

import java.util.*;

public class Main {
    int n, m;
    ArrayList<ArrayList<Integer>> es;
    ArrayList<HashSet<Integer>> es2;
    Queue<Tuple> queue;

    public static void main(String[] args) {
        Main m = new Main();
        m.read();
        m.solve();
    }

    private void read() {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        es = new ArrayList<>(n);
        es2 = new ArrayList<>(n);
        queue = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            es.add(new ArrayList<>());
            es2.add(new HashSet<>());
        }
        for (int i = 0; i < m; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            es.get(a).add(b);
            es.get(b).add(a);
        }
    }

    private void solve() {
        makeQueue();
        long ans = 0L;
        while (!queue.isEmpty()) {
            Tuple t = queue.poll();
            if (t.snd == t.fst)
                break;
            if (es.get(t.fst).contains(t.snd))
                continue;
            ans++;
////            System.out.printf("%d, %d\n", t.fst+1, t.snd+1);
            es.get(t.fst).add(t.snd);
            es.get(t.snd).add(t.fst);
            for (int i: es2.get(t.fst)) {
                queue.add(new Tuple(i, t.snd));
            }
            for (int i: es2.get(t.snd)) {
                queue.add(new Tuple(i, t.fst));
            }
        }
        if (queue.size() != 0)
            System.out.println((n * (n - 1)) / 2 - m);
        else
            System.out.println(ans);
    }

    private void makeQueue() {
        for (int i = 0; i < n; i++) {
            dfs(i, 0, i);
        }
    }

    private void dfs(int root, int depth, int current) {
        if (depth > 3)
            return;
        if (depth == 2) {
            es2.get(root).add(current);
        }
        if (depth == 3) {
            queue.add(new Tuple(root, current));
        }
        for (int nxt: es.get(current)) {
            dfs(root, depth+1, nxt);
        }
    }

    private class Tuple {
        int fst, snd;
        Tuple(int x, int y) {
            fst = x;
            snd = y;
        }
    }
}

