		outer:
		for(int i = 0;i < n;i++){
			if(ds.upper[i] < 0){
				int u = -ds.upper[i];
				d[i] = 0;
				Queue<Integer> q = new ArrayDeque<>();
				q.add(i);
				int[] f = new int[2];
