							d[e] = d[cur] ^ 1;
							q.add(e);
						}else if(d[e] == d[cur]){
							ans += (long)u*(u-1)/2;
							continue outer;
						}
					}
				}
				ans += (long)f[0]*f[1];
			}
		}
