    static class Solver {
    	MyInput in;
    	PrintWriter out;
        public Solver(MyInput in, PrintWriter out) {
        	this.in = in;
        	this.out = out;
        }
        // -----------------------------------------
        // 木を処理するサンプル
        //

        Graph G = new Graph();					// グラフのリンクリスト
        int N, M;
        List<PPKEY> addG = new ArrayList<PPKEY>();

        // now : 頂点番号    parent : 親の頂点番号    start : 開始位    cnt : 通過した辺の数置
        int dfs(int now, int parent, int start, int cnt) {
//        	prn("now = " + now + "  parent = " + parent + "  start = " + start + "  cnt = " + cnt);
        	if(cnt == 3) {
        		PPKEY ppkey = new PPKEY(start, now);
        		if(start == now || G.contains(start, now) || addG.contains(ppkey)) {
//        			prn(" return 0");
        			return 0;
        		} else {
        			addG.add(ppkey);
//        			prn(" return 1  start = " + start + "  now = " + now);
        			return 1;
        		}
        	}
        	int ans = 0;
        	for(Integer next : G.get(now)) {
        		if(next == parent)	continue;			// 親は処理しない
        		ans += dfs(next, now, start, cnt + 1);	// 子を呼ぶ
        	}
//        	prn("  ans = " + ans + "\n");
        	return ans;
        }
        public void solve() {
        	N = ni();
        	M = ni();
        	int u, v;
        	for(int i=0; i < M; i++) {
        		u = ni() - 1;
        		v = ni() - 1;
        		G.add(u, v);
        		G.add(v, u);
        	}
//        	G.dump(out);
        	int ans = 0;
        	int cnt;
        	while(true) {
        		cnt = 0;
            	for(int i = 0; i < N; i++) {
            		addG.clear();
	        		cnt += dfs(i, -1, i, 0);
	        		for(PPKEY p : addG) {
	        			if(!G.contains(p.getKey(), p.getVal())) {
		        			G.add(p.getKey(), p.getVal());
		        			G.add(p.getVal(), p.getKey());
	        			}
	        		}
            	}
        		if(cnt == 0)	break;
        		ans += cnt;
        	}
        	prn(ans);
       }

