import java.util.Arrays;

public class Main {

  private static void solve() {
    int n = ni();
    int m = ni();
    int[] from = new int[m];
    int[] to = new int[m];
    for (int i = 0; i < m; i ++) {
      from[i] = ni() - 1;
      to[i] = ni() - 1;
    }
    int[][] g = packU(n, from, to);
    int[] color = new int[n];
    if (dfs(0, 1, color, g)) {
      int c1 = Arrays.stream(color).filter(o -> o > 0).sum();
      int c2 = n - c1;
      System.out.println((long)c1 * c2 - m);
    } else {
      System.out.println((long)n * (n - 1) / 2 - m);
    }
  }

  private static boolean dfs(int now, int c, int[] color, int[][] g) {
    color[now] = c;
    for (int next : g[now]) {
      if (color[next] == c) {
        return false;
      } else if (color[next] == 0) {
        if (!dfs(next, -c, color, g)) {
          return false;
        }
      }
    }
    return true;
  }

  private static int[][] packU(int n, int[] from, int[] to) {
    int[][] g = new int[n][];
    int[] p = new int[n];
    for (int f : from)
        p[f]++;
    for (int t : to)
        p[t]++;
    for (int i = 0; i < n; i++)
        g[i] = new int[p[i]];
    for (int i = 0; i < from.length; i++) {
        g[from[i]][--p[from[i]]] = to[i];
        g[to[i]][--p[to[i]]] = from[i];
    }
    return g;
  }

