								//System.out.println("added bw " + Math.min(x, w) + "---" + Math.max(x, w));
								sec[Math.min(x, w)].add(Math.max(x, w));

							}
						}
					}
				}

			}
			for (int i = 0; i < adj.length; i++) {
				if (sec[i].size() > 0) {
