			}
		}

public void solve() {
	int numNode = ni();
	int numEdge = ni();
	Graph g = new Graph(numNode, numEdge, false);
	Edge edges[] = new Edge[numEdge];
	for(int i = 0; i < numEdge; i ++) {
		int a = ni() - 1;
		int b = ni() - 1;
		long c = 1;
		edges[i] = new Edge(a, b, c);
	}
	g.init(edges);
	UnionFind uf = new UnionFind(numNode * 2);
	for(Edge e : g.edges) {
		uf.unite(e.source, e.target + numNode);
		uf.unite(e.source + numNode, e.target);
	}
	if(uf.same(0, numNode)) {
		prtln((long)numNode * (numNode - 1) / 2 - numEdge);
	}else {
		long cnt = 0;
		for(int i = 0; i < numNode; i ++) {
			if(uf.same(0, i)) cnt ++;
		}
		prtln(cnt * (numNode - cnt) - numEdge);
	}
}

class UnionFind {
	int parent[];
	int size[];

	public UnionFind(int num) {
		parent = new int[num];
		size = new int[num];
		for(int i = 0; i < num; i ++) {
			initNode(i);
		}
	}

	public void initNode(int i) {
		parent[i] = i;
		size[i] = 1;
	}

	public void unite(int x, int y) {
		int xRoot = root(x);
		int yRoot = root(y);
		if(xRoot == yRoot) { return; }
		if(size[yRoot] > size[xRoot]) {
			parent[xRoot] = yRoot;
			size[yRoot] += size[xRoot];
		}else {
			parent[yRoot] = xRoot;
			size[xRoot] += size[yRoot];
		}
	}

	public int size(int i) {
		return size[root(i)];
	}

	public int root(int i) {
		if(i != parent[i]) {
			parent[i] = root(parent[i]);
		}
		return parent[i];
	}

	public boolean same(int x, int y) {
		return root(x) == root(y);
	}
}

