        var sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        IntArrayList[] g = new IntArrayList[n];
        for (int i = 0; i < n; i++) g[i] = new IntArrayList();
        for (int j = 0; j < m; j++) {
            int a = Integer.parseInt(sc.next()) - 1;
            int b = Integer.parseInt(sc.next()) - 1;
            g[a].add(b);
