public class BipartiteGraph : UnionFind
{
    private int[] color;
    public bool this[int i] { get { return IsSame(0, i); } } 
    public BipartiteGraph(int num) : base(num << 1)
    { color = Create(num << 1, () => -1); }
    public bool Coloring()
    {
        for (var i = 0; i < color.Length / 2; i++)
        {
            int a = Find(i), b = Find(i + color.Length / 2);
            if (a == b) return false;
            if (color[a] < 0)
            { color[a] = 0; color[b] = 1; }
        }
        return true;
    }
    public override bool Union(int v1, int v2)
        => base.Union(v1, v2 + color.Length / 2) && base.Union(v1 + color.Length/2, v2);
}

public class UnionFind
{
    protected int[] parent, size, rank;
    public UnionFind(int num)
    {
        parent = new int[num]; size = new int[num]; rank = new int[num];
        for (var i = 0; i < num; i++) { parent[i] = i; size[i] = 1; }
    }
    protected int Find(int i)
        => i == parent[i] ? i : (parent[i] = Find(parent[i]));
    public int Parent(int i)
        => Find(i);
    public int Size(int i)
        => size[Find(i)];
    public virtual bool Union(int v1, int v2)
    {
        v1 = Find(v1); v2 = Find(v2);
        if (v1 == v2) return false;
        if (rank[v1] < rank[v2])
            swap(ref v1, ref v2);
        parent[v2] = v1;
        size[v1] += size[v2];
        if (rank[v1] == rank[v2])
            rank[v1]++;
        return true;
    }
    public bool IsSame(int v1, int v2)
        => Find(v1) == Find(v2);
}
