namespace AtCoder
{
	public class Program
	{
		static void Main()
		{
			var cin = new Scanner();
			int n = cin.Int();
			int m = cin.Int();

			var to = Helper.Array(n * 2, x => new List<int>());
			for (int i = 0; i < m; i++) {
				int a = cin.Int() - 1;
				int b = cin.Int() - 1;
				to[a].Add(b + n);
				to[b + n].Add(a);
				to[a + n].Add(b);
				to[b].Add(a + n);
			}

			var dist = Helper.Array(n * 2, x => int.MaxValue);
			dist[0] = 0;

			var pq = new PriorityQueueG<(int v, int d)>((x, y) => x.d.CompareTo(y.d), true);
			pq.Enqueue((0, 0));
			while (pq.Count > 0) {
				var (v, d) = pq.Dequeue();
				if (d > dist[v]) {
					continue;
				}

				int nd = d + 1;
				foreach (var next in to[v]) {
					if (nd < dist[next]) {
						dist[next] = nd;
						pq.Enqueue((next, nd));
					}
				}
			}

			bool isBipartite = true;
			for (int i = 0; i < n; i++) {
				if (dist[i] != int.MaxValue && dist[i + n] != int.MaxValue) {
					isBipartite = false;
					break;
				}
			}

			var odd = new HashSet<int>();
			var even = new HashSet<int>();
			even.Add(0);
			for (int i = 1; i < n; i++) {
				if (dist[i + n] == int.MaxValue) {
					even.Add(i);
				} else {
					odd.Add(i);
				}
			}

			long ans = isBipartite
				? (long)odd.Count * even.Count - m
				: (long)n * (n - 1) / 2 - m;

			Console.WriteLine(ans);
		}
	}

	public class PriorityQueueG<T>
	{
		private readonly int reverseFactor_;
		private readonly Comparison<T> comparison_;
		private T[] heap_;

		public T Top => heap_[0];
		public int Count { get; private set; } = 0;

		public PriorityQueueG(bool reverses = false)
			: this(Comparer<T>.Default, reverses) { }

		public PriorityQueueG(int capacity, bool reverses = false)
			: this(capacity, Comparer<T>.Default.Compare, reverses) { }

		public PriorityQueueG(IComparer<T> comparer, bool reverses = false)
			: this(1024, comparer.Compare, reverses) { }

		public PriorityQueueG(Comparison<T> comparison, bool reverses = false)
			: this(1024, comparison, reverses) { }

		public PriorityQueueG(
			int capacity,
			Comparison<T> comparison,
			bool reverses = false)
		{
			heap_ = new T[capacity > 0 ? capacity : 1];
			comparison_ = comparison;
			reverseFactor_ = reverses ? -1 : 1;
		}

		public void Enqueue(T item)
		{
			if (heap_.Length == Count) {
				Extend(heap_.Length * 2);
			}

			heap_[Count] = item;
			++Count;

			int c = Count - 1;
			while (c > 0) {
				int p = (c - 1) >> 1;
				if (Compare(heap_[p], item) < 0) {
					heap_[c] = heap_[p];
					c = p;
				} else {
					break;
				}
			}

			heap_[c] = item;
		}

		public T Dequeue()
		{
			T ret = heap_[0];
			int n = Count - 1;

			var item = heap_[n];
			int p = 0;
			int c = (p << 1) + 1;
			while (c < n) {
				if (c != n - 1 && Compare(heap_[c + 1], heap_[c]) > 0) {
					++c;
				}

				if (Compare(item, heap_[c]) < 0) {
					heap_[p] = heap_[c];
					p = c;
					c = (p << 1) + 1;
				} else {
					break;
				}
			}

			heap_[p] = item;
			Count--;

			return ret;
		}

		public void Clear() => Count = 0;

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private int Compare(T x, T y)
			=> comparison_(x, y) * reverseFactor_;

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private void Extend(int newSize)
		{
			var newHeap = new T[newSize];
			heap_.CopyTo(newHeap, 0);
			heap_ = newHeap;
		}
	}

	public struct ModInt
	{
		public const long P = 1000000007;
		//public const long P = 998244353;

		public static ModInt Inverse(ModInt value) => Pow(value, P - 2);
		public static ModInt Pow(ModInt value, long k) => Pow(value.value_, k);
		public static ModInt Pow(long value, long k)
		{
			long ret = 1;
			for (k %= P - 1; k > 0; k >>= 1, value = value * value % P) {
				if ((k & 1) == 1) {
					ret = ret * value % P;
				}
			}
			return new ModInt(ret);
		}

		private long value_;

		public ModInt(long value)
			=> value_ = value;
		public ModInt(long value, bool mods)
		{
			if (mods) {
				value %= P;
				if (value < 0) {
					value += P;
				}
			}

			value_ = value;
		}

		public static ModInt operator +(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = (lhs.value_ + rhs.value_) % P;
			return lhs;
		}
		public static ModInt operator +(long lhs, ModInt rhs)
		{
			rhs.value_ = (lhs + rhs.value_) % P;
			return rhs;
		}
		public static ModInt operator +(ModInt lhs, long rhs)
		{
			lhs.value_ = (lhs.value_ + rhs) % P;
			return lhs;
		}

		public static ModInt operator -(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = (P + lhs.value_ - rhs.value_) % P;
			return lhs;
		}
		public static ModInt operator -(long lhs, ModInt rhs)
		{
			rhs.value_ = (P + lhs - rhs.value_) % P;
			return rhs;
		}
		public static ModInt operator -(ModInt lhs, long rhs)
		{
			lhs.value_ = (P + lhs.value_ - rhs) % P;
			return lhs;
		}

		public static ModInt operator *(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = lhs.value_ * rhs.value_ % P;
			return lhs;
		}
		public static ModInt operator *(long lhs, ModInt rhs)
		{
			rhs.value_ = lhs * rhs.value_ % P;
			return rhs;
		}
		public static ModInt operator *(ModInt lhs, long rhs)
		{
			lhs.value_ = lhs.value_ * rhs % P;
			return lhs;
		}

		public static ModInt operator /(ModInt lhs, ModInt rhs)
		{
			long exp = P - 2;
			while (exp > 0) {
				if (exp % 2 > 0) {
					lhs *= rhs;
				}

				rhs *= rhs;
				exp /= 2;
			}

			return lhs;
		}

		public static implicit operator ModInt(long n) => new ModInt(n, true);
		public long ToLong() => value_;
		public override string ToString() => value_.ToString();
	}

