        sw.AutoFlush = true;
#else
        sw.AutoFlush = false;
#endif
        SetOut(sw);
        Solve(new IO());
        Out.Flush();
    }

    static void Solve(IO io)
    {
        var n = io.L;
        var m = io.L;

        var grl = new List<int>[n];
        var grs = new HashSet<int>[n];
        for (var i = 0; i < n; i++) grl[i] = new List<int>();
        for (var i = 0; i < n; i++) grs[i] = new HashSet<int>();

        for (var i = 0; i < m; i++)
        {
            var a = io.I - 1;
            var b = io.I - 1;
            grl[a].Add(b);
            grl[b].Add(a);
            grs[a].Add(b);
            grs[b].Add(a);
        }

        var hasc = false;

        for (var i = 0; i < n; i++)
            foreach (var j in grl[i])
                if (grl[j].Any(grs[i].Contains)) { hasc = true; goto ExitLoop; }
        ExitLoop:;

        var max = grl.Max(x => x.Count);

        if (n == 2)
            io.Write(0);
        else if (n == 3)
            io.Write(3 - m);
        else if (n == 4)
            io.Write(hasc ? 6 - m : 4 - m);
        else if (max == n - 1 && m == n - 1)
            io.Write(0);
        else if (n % 2 == 0 && max <= (n - 5) / 2 + 3)
            io.Write(n + ((n - 5) / 2 + 1) * n / 2 - m);
        else
            io.Write(n + ((n - 3) * n / 2) - m);
    }
