			for(int i = 0;i< NM[1];i++)
			{
				var v = Ins;

				int s = Math.Min(v[0], v[1]) - 1;
				int t = Math.Max(v[0], v[1]) - 1;
				hash[s].Add(t);
				hash[t].Add(s);
			}
			int ans = 0;
			for (int i = 0; i < hash.Length; i++)
			{
				int index = 0;
				while (hash[i].Count > index)
				{
					var a = hash[i][index++];
					if (a == i) continue;
					int indexa = 0;
					while (hash[a].Count > indexa)
					{
						var b = hash[a][indexa++];
						if (b == i || b == a) continue;
						int indexb = 0;
						while (hash[b].Count > indexb)
						{
							var c = hash[b][indexb++];
							if (c == i || c == a || c == b) continue;
							if (hash[i].Contains(c)) continue;
							ans++;
							hash[i].Add(c);
							hash[c].Add(i);
						}
					}
				}
			}
			Console.WriteLine(ans);
			//Console.ReadLine();
		}
	}
}

