            count = ((long)(N))*(N-1)/2;
        }
        else{
            count = ((long)c1)*c2;
        }
        count -= M;
        sb.Append(count+"\n");
    }
    bool dfs(int v,bool b){
        state[v] = b ? 1 : 2;
        if(b){
            c1++;
        }
        else{
            c2++;
        }
        bool ans = false;
        for(int i=0;i<G[v].Count;i++){
            int t = G[v][i];
            if(state[t] == 0){
                ans |= dfs(t,!b);
            }
            else if(state[v] == state[t]){
                return true;
            }
        }
        return ans;
    }
