//1 ≤ A i , B i ≤ N
//多重辺や自己ループは存在しない
//与えられるグラフは連結である
//
//入力
//入力は以下の形式で標準入力から与えられる。
//
//N M
//A 1 B 1
//A 2 B 2
//:
//A M B M 
//
//出力
//追加できる辺の本数の最大値を出力せよ。

        public const string SiteName    = "AtCoder";
        public const string ContestName = "code_festival_2017_qualb";
        public const string ProblemName = "C";

        public void Solve()
        {
            long N = cin.ReadInt;
            long M = cin.ReadInt;

            List<int>[] edges = new List<int>[N];
            int[]       col   = new int[N];

            for (int i = 0; i < N; i++)
            {
                col[i]   = -1;
                edges[i] = new List<int>();
            }

            for (int i = 0; i < M; i++)
            {
                int a = cin.ReadInt - 1;
                int b = cin.ReadInt - 1;
                edges[a].Add(b);
                edges[b].Add(a);
            }

            col[0] = 0;

            Queue<int> queue = new Queue<int>();
            queue.Enqueue(0);

            bool isBipartite = true;

            while (queue.Count > 0)
            {
                int p = queue.Dequeue();

                foreach (int item in edges[p])
                {
                    if (col[item] == -1)
                    {
                        col[item] = 1 - col[p];
                        queue.Enqueue(item);
                    }
                    else if (col[item] == col[p])
                    {
                        isBipartite = false;
                        goto LabelA;
                    }
                }
            }

            LabelA:

            if (isBipartite)
            {
                int c = 0;
                for (int i = 0; i < N; i++)
                {
                    if (col[i] == 0)
                    {
                        c++;
                    }
                }

                cou.WriteLine(c * (N - c) - M);
            }
            else
            {
                cou.WriteLine(N * (N - 1) / 2 - M);
            }
        }
    }


