using System;
using System.Linq;
using System.Collections.Generic;

class Hello
{
    public static void Main()
    {
        var nm = Console.ReadLine().Split().Select(int.Parse).ToArray();
        int n = nm[0], m = nm[1];
        var graph = new Dictionary<int, HashSet<int>>(n);
        for (int i = 0; i < n; i++)
        {
            graph.Add(i, new HashSet<int>());
        }
        for (int i = 0; i < m; i++)
        {
            var ab = Console.ReadLine().Split().Select(int.Parse).ToArray();
            int a = ab[0] - 1, b = ab[1] - 1;
            graph[a].Add(b); graph[b].Add(a);
        }
        int count = 0;
        bool wasUpdate = false;
        do
        {
            wasUpdate = false;
            for (int i = 0; i < n; i++)
            {
                var list = new List<KeyValuePair<int, int>>();
                foreach (var edge in graph[i])
                {
                    if (!graph.ContainsKey(edge)) continue;
                    foreach (var edge2 in graph[edge])
                    {
                        if (!graph.ContainsKey(edge2)) continue;
                        foreach (var edge3 in graph[edge2])
                        {
                            if (i == edge3 || i==edge2) continue;
                            list.Add(new KeyValuePair<int, int>(i, edge3));
                        }
                    }
                }
                foreach (var item in list)
                {
                    if (!graph[item.Key].Contains(item.Value))
                    {
                        if (!graph[item.Value].Contains(item.Key))
                        {
                            wasUpdate = true;
                            count++;
                            graph[item.Key].Add(item.Value);
                            graph[item.Value].Add(item.Key);
                        }
                    }
                }
            }
        } while (wasUpdate);

        Console.WriteLine(count);

    }
}

