    class Program
    {
        static void Main(string[] args)
        {
            int N = ReadInt;
            int M = ReadInt;

            List<int>[] edge = new List<int>[N].Select(x => new List<int>()).ToArray();
            for (int i = 0; i < M; i++)
            {
                int a = ReadInt - 1;
                int b = ReadInt - 1;
                edge[a].Add(b);
                edge[b].Add(a);
            }

            bool nibu = true;
            int[] color = new int[N];
            Queue<int> que = new Queue<int>();
            que.Enqueue(0);
            color[0] = 1;
            while (que.Count > 0 && nibu)
            {
                int now = que.Dequeue();

                foreach (var to in edge[now])
                {
                    if (color[to] == color[now])
                    {
                        nibu = false;
                        break;
                    }
                    if (color[to] == 0)
                    {
                        que.Enqueue(to);
                        color[to] = color[now] == 1 ? 2 : 1;
                    }
                }
            }

            int ans = 0;
            if (nibu)
            {
                ans = color.Count(x => x == 1) * color.Count(x => x == 2) - M;
            }
            else
            {
                ans = N * (N - 1) / 2 - M;
            }

            Console.WriteLine(ans);
        }


    }


