using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.IO.Pipes;
using System.Linq;
using System.Numerics;
using System.Reflection.Metadata;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics.X86;
using System.Text;
using System.Threading;

namespace AtCoder
{
	public class Program
	{
		static void Main()
		{
			var cin = new Scanner();
			int n = cin.Int();
			int m = cin.Int();

			var to = Helper.Array(n * 2, x => new List<int>());
			for (int i = 0; i < m; i++) {
				int a = cin.Int() - 1;
				int b = cin.Int() - 1;
				to[a].Add(b + n);
				to[b + n].Add(a);
				to[a + n].Add(b);
				to[b].Add(a + n);
			}

			var dist = Helper.Array(n * 2, x => int.MaxValue);
			dist[0] = 0;

			var pq = new PriorityQueue<(int v, int d), int>(x => x.d, true);
			pq.Enqueue((0, 0));
			while (pq.Count > 0) {
				var cur = pq.Dequeue();
				if (cur.d > dist[cur.v]) {
					continue;
				}

				int nd = cur.d + 1;
				foreach (var next in to[cur.v]) {
					if (nd < dist[next]) {
						dist[next] = nd;
						pq.Enqueue((next, nd));
					}
				}
			}

			bool isBipartite = true;
			for (int i = 0; i < n; i++) {
				if (dist[i] != int.MaxValue && dist[i + n] != int.MaxValue) {
					isBipartite = false;
					break;
				}
			}

			var odd = new HashSet<int>();
			var even = new HashSet<int>();
			even.Add(0);
			for (int i = 1; i < n; i++) {
				if (dist[i + n] == int.MaxValue) {
					even.Add(i);
				} else {
					odd.Add(i);
				}
			}

			long ans = isBipartite
				? (long)odd.Count * even.Count - m
				: (long)n * (n - 1) / 2 - m;

			Console.WriteLine(ans);
		}
	}

	public class PriorityQueue<TObject, TPriority> where TPriority : IComparable<TPriority>
	{
		private readonly Func<TObject, TPriority> selector_;
		private readonly int reverseFactory_;
		private TObject[] heap_;
		private TPriority[] priorities_;

		public TObject Top => heap_[0];
		public int Count { get; private set; }

		public PriorityQueue(
			Func<TObject, TPriority> selector,
			bool reverses = false)
			: this(1024, selector, reverses) { }

		public PriorityQueue(
			int capacity,
			Func<TObject, TPriority> selector,
			bool reverses = false)
		{
			heap_ = new TObject[capacity];
			priorities_ = new TPriority[capacity];
			selector_ = selector;
			reverseFactory_ = reverses ? -1 : 1;
		}

		public void Enqueue(TObject item)
		{
			if (heap_.Length == Count) {
				Extend(heap_.Length * 2);
			}

			var priority = selector_(item);
			heap_[Count] = item;
			priorities_[Count] = priority;
			++Count;

			int c = Count - 1;
			while (c > 0) {
				int p = (c - 1) >> 1;
				if (Compare(priorities_[p], priority) < 0) {
					heap_[c] = heap_[p];
					priorities_[c] = priorities_[p];
					c = p;
				} else {
					break;
				}
			}

			heap_[c] = item;
			priorities_[c] = priority;
		}

		public TObject Dequeue()
		{
			TObject ret = heap_[0];
			int n = Count - 1;

			var item = heap_[n];
			var priority = priorities_[n];
			int p = 0;
			int c = (p << 1) + 1;
			while (c < n) {
				if (c != n - 1 && Compare(priorities_[c + 1], priorities_[c]) > 0) {
					++c;
				}

				if (Compare(priority, priorities_[c]) < 0) {
					heap_[p] = heap_[c];
					priorities_[p] = priorities_[c];
					p = c;
					c = (p << 1) + 1;
				} else {
					break;
				}
			}

			heap_[p] = item;
			priorities_[p] = priority;
			Count--;

			return ret;
		}

		public void Clear() => Count = 0;

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private int Compare(TPriority x, TPriority y)
			=> x.CompareTo(y) * reverseFactory_;

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		private void Extend(int newSize)
		{
			var newHeap = new TObject[newSize];
			heap_.CopyTo(newHeap, 0);
			heap_ = newHeap;
			var newPriorities = new TPriority[newSize];
			priorities_.CopyTo(newPriorities, 0);
			priorities_ = newPriorities;
		}
	}

	public struct ModInt
	{
		public const long P = 1000000007;
		//public const long P = 998244353;

		public static ModInt Inverse(ModInt value) => Pow(value, P - 2);
		public static ModInt Pow(ModInt value, long k) => Pow(value.value_, k);
		public static ModInt Pow(long value, long k)
		{
			long ret = 1;
			for (k %= P - 1; k > 0; k >>= 1, value = value * value % P) {
				if ((k & 1) == 1) {
					ret = ret * value % P;
				}
			}
			return new ModInt(ret);
		}

		private long value_;

		public ModInt(long value)
			=> value_ = value;
		public ModInt(long value, bool mods)
		{
			if (mods) {
				value %= P;
				if (value < 0) {
					value += P;
				}
			}

			value_ = value;
		}

		public static ModInt operator +(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = (lhs.value_ + rhs.value_) % P;
			return lhs;
		}
		public static ModInt operator +(long lhs, ModInt rhs)
		{
			rhs.value_ = (lhs + rhs.value_) % P;
			return rhs;
		}
		public static ModInt operator +(ModInt lhs, long rhs)
		{
			lhs.value_ = (lhs.value_ + rhs) % P;
			return lhs;
		}

		public static ModInt operator -(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = (P + lhs.value_ - rhs.value_) % P;
			return lhs;
		}
		public static ModInt operator -(long lhs, ModInt rhs)
		{
			rhs.value_ = (P + lhs - rhs.value_) % P;
			return rhs;
		}
		public static ModInt operator -(ModInt lhs, long rhs)
		{
			lhs.value_ = (P + lhs.value_ - rhs) % P;
			return lhs;
		}

		public static ModInt operator *(ModInt lhs, ModInt rhs)
		{
			lhs.value_ = lhs.value_ * rhs.value_ % P;
			return lhs;
		}
		public static ModInt operator *(long lhs, ModInt rhs)
		{
			rhs.value_ = lhs * rhs.value_ % P;
			return rhs;
		}
		public static ModInt operator *(ModInt lhs, long rhs)
		{
			lhs.value_ = lhs.value_ * rhs % P;
			return lhs;
		}

		public static ModInt operator /(ModInt lhs, ModInt rhs)
		{
			long exp = P - 2;
			while (exp > 0) {
				if (exp % 2 > 0) {
					lhs *= rhs;
				}

				rhs *= rhs;
				exp /= 2;
			}

			return lhs;
		}

		public static implicit operator ModInt(long n) => new ModInt(n, true);
		public long ToLong() => value_;
		public override string ToString() => value_.ToString();
	}

