public class Solver
{
	public void Solve()
	{
		long N = GetLong();
		long M = GetLong();
		int[] A = new int[M];
		int[] B = new int[M];
		for(int i = 0; i < M; i++)
		{
			A[i] = GetInt() - 1;
			B[i] = GetInt() - 1;
		}

		int[] color = new int[N];
		var adj = Enumerable.Range(0, (int)N).Select(_ => new List<int>()).ToArray();
		for(int i = 0; i < M; i++)
		{
			adj[A[i]].Add(B[i]);
			adj[B[i]].Add(A[i]);
		}

		if(isBipartite(0, 1, color, adj))
		{
			long p = (long)color.Count(x => (x == 1));
			long q = N - p;
			WriteLine(p * q - M);
		}
		else
		{
			WriteLine((N * (N - 1)) / 2 - M);
		}
	}

	private bool isBipartite(int v, int c, int[] color, List<int>[] adj)
	{
		color[v] = c;
		foreach(int u in adj[v])
		{
			if(color[u] == c)
				return false;

			if(color[u] == 0 && !isBipartite(u, -c, color, adj))
				return false;
		}
		return true;
	}
}

