using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;

static class Program
{
    static int[] Paint(int N, List<int>[] hands)
    {
        var colors = new int[N];
        var queue = new Queue<int>();
        colors[0] = 1;
        queue.Enqueue(0);
        while (queue.Count > 0)
        {
            int a = queue.Dequeue();
            foreach (int b in hands[a])
            {
                if (colors[b] == 0)
                {
                    colors[b] = -colors[a];
                    queue.Enqueue(b);
                }
                else if (colors[b] != -colors[a])
                {
                    return null;
                }
            }
        }
        return colors;
    }

    static long Solve(int N, int M, int[][] edges)
    {
        var hands = new List<int>[N];
        for (int i = 0; i < N; ++i) { hands[i] = new List<int>(); }
        foreach (var edge in edges)
        {
            int a = edge[0];
            int b = edge[1];
            hands[a].Add(b);
            hands[b].Add(a);
        }
        var colors = Paint(N, hands);
        if (colors != null)
        {
            int e = colors.Count(color => color == 1);
            int o = colors.Count(color => color == -1);
            return Math.BigMul(e, o) - M;
        }
        else
        {
            return Math.BigMul(N, N - 1) / 2 - M;
        }
    }

    static void Main(string[] args)
    {
        int[] V1 = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
        int N = V1[0], M = V1[1];
        var edges = new int[M][];
        for (int i = 0; i < M; ++i)
        {
            edges[i] = Array.ConvertAll(Console.ReadLine().Split(), x => int.Parse(x) - 1);
        }
        Console.WriteLine(Solve(N, M, edges));
    }
}

