public sealed partial class Program
{
    int n, m;
    List<int>[] es;

    bool[] color;
    bool[] done;

    // 2部グラフだったら color に色を付けつつ true を返す。
    bool Dfs(int u, bool c)
    {
        if (done[u])
        {
            return color[u] == c;
        }

        done[u] = true;
        color[u] = c;

        foreach (var v in es[u])
        {
            if (!Dfs(v, !c)) return false;
        }

        return true;
    }

    long Solve()
    {
        done = n.MakeArray(u => false);
        color = n.MakeArray(u => default(bool));

        var isBipartite = Dfs(0, false);

        // 単純グラフ上に存在できる辺の個数。
        var k = (long)n * (n - 1) / 2;

        if (isBipartite)
        {
            var p = (long)color.Count(c => c);
            var q = n - p;

            // 同じ色の点の間に存在できる辺の個数。
            var l = (p * (p - 1) / 2) + (q * (q - 1) / 2);

            // l から、同じ色の点の間にすでに存在する辺の個数を引く。
            for (var u = 0; u < n; u++)
            {
                foreach (var v in es[u])
                {
                    if (u >= v) continue;

                    if (color[u] == color[v])
                    {
                        l--;
                    }
                }
            }

            return k - (m + l);
        }
        else
        {
            return k - m;
        }
    }

    void Read()
    {
        var a = scanner;

        n = a.N();
        m = a.N();
        es = n.MakeArray(u => new List<int>());

        for (var i = 0; i < m; i++)
        {
            var u = a.N() - 1;
            var v = a.N() - 1;
            es[u].Add(v);
            es[v].Add(u);
        }
    }

    public void EntryPoint()
    {
        Read();
        WriteLine(Solve());
    }
}

