        for (int i = 0; i < N; i++)
        {
            R[i] = new List<int>();
        }
        for (int i = 0; i < M; i++)
        {
            var a = sc.NextInt() - 1;
            var b = sc.NextInt() - 1;
            R[a].Add(b);
            R[b].Add(a);
        }
