    {
        if(Col[num]==col)
        {
            return true;
        }
        else if(Col[num]==0)
        {
            Col[num] = col;
            bool c = true;
            foreach(var i in R[num])
            {
                c &= F(i, col * -1);
            }
            return c;
        }
        else
        {
            return false;
        }
    }

