			dist1Sets_new[i] = new HashSet<int>();		
		}

		for(int i=1; i<=M; i++)
		{
			int A, B;
			vals = Console.ReadLine().Split(' ');
			A = int.Parse(vals[0]);
			B = int.Parse(vals[1]);
			dist1Sets[A].Add(B);
			dist1Sets[B].Add(A);
		}

		for(int i=1; i<=N; i++)
		{
			dfs(i, -1, -1, 0);
			foreach(var n in dist1Sets_new[i])
			{
				dist1Sets[i].Add(n);	
				dist1Sets[n].Add(i);
			}

		}

		Console.WriteLine(ans);

	}

	static void dfs(int s, int d1, int d2, int step)
	{
		switch(step)
		{
			case 0:
				foreach(var i in dist1Sets[s])
				{
					dfs(s, i, d2, 1);
				}
				break;
			case 1:
				foreach(var i in dist1Sets[d1])
				{
					if(i == s)
						continue;
					dfs(s, d1, i, 2);
				}
				break;
			case 2:
				foreach(var i in dist1Sets[d2])
				{
					if(i == s || i == d1)
						continue;
					if(!dist1Sets[s].Contains(i) && !dist1Sets_new[s].Contains(i))
					{
						ans++;
						//dist1Sets[s].Add(i);
						//dist1Sets[i].Add(s);
						dist1Sets_new[s].Add(i);
						dfs(s, i, d2, 1);
					}
				}
				break;
		}
	}
