         else Console.WriteLine(n*(n-1)/2-m);//２部グラフでないとき
  }

   static void Spread(int vertex)//色を広げる
  {
    int color = result[vertex];//現在の頂点の色

    for(int i = vertex + 1; i < n; i++)
    {
      if(changeVec[vertex,i] == 0) break;//繋がっていない頂点は無視
      else
      {
        if(result[i] == 0)
        {
        result[i] = 3 - color;//隣接頂点は別の色で塗る
        Spread(i);//色を広げる
        }
        else if(result[i] == color) twoGraph = false;//色の矛盾がある
      }

    }
  }
}

