class Program
{

static string[] input = Console.ReadLine().Split(' ');
static long n = long.Parse(input[0]);
static long m = long.Parse(input[1]);
static long[] result = new long[n];//頂点0を１、隣接頂点を2と、交互に塗る。
static List<long>[] nextList = new List<long>[n];//隣接リスト
static bool twoGraph = true;//２部グラフならtrue

	 static void Main()
  {
    for(long i = 0; i < n; i++) nextList[i] = new List<long>();//リストの宣言
    for(long i = 0; i < m; i++)
    {
      long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);//１行ごとに受け取る
      nextList[nums[0]-1].Add(nums[1]-1);//隣接リストへ追加。
      nextList[nums[1]-1].Add(nums[0]-1);
    }

          result[0] = 1;
          Spread(0);//頂点0から色を広げる

         if(twoGraph) //２部グラフのとき
         {
            long whiteNum = 0;//頂点0と同じ色の頂点数
            for (long i = 0; i < n; i++)
            {
              if(result[i] == 1) whiteNum++;
            }
            Console.WriteLine(whiteNum*(n-whiteNum)-m);
         }
         else Console.WriteLine(n*(n-1)/2-m);//２部グラフでないとき
  }

   static void Spread(long vertex)//色を広げる
  {
    long color = result[vertex];//現在の頂点の色


    for(int i = 0; i < nextList[vertex].Count(); i++)
    {
      long a = (long)((List<long>)nextList[vertex])[i];
        if(result[a] == 0)
        {
          result[a] = 3 - color;//隣接頂点は別の色で塗る
          Spread(a);//色を広げる
        }
        else if(result[a] == color) twoGraph = false;//色の矛盾がある
    }
  }
}

