static class Program
{
    public static void Main()
    {
        var sw = new StreamWriter(OpenStandardOutput()) { NewLine = "\n" };
#if DEBUG
        sw.AutoFlush = true;
#else
        sw.AutoFlush = false;
#endif
        SetOut(sw);
        Solve(new IO());
        Out.Flush();
    }

    static void Solve(IO io)
    {
        var n = io.L;
        var m = io.L;

        var ans = n + (n % 2 == 0 ? ((n - 5) / 2 + 1) * n / 2 : (n - 3) * n / 2) - m;
        io.Write(ans);
    }
}

