namespace C
{
    class Program
    {
        static void Main(string[] args)
        {
            int[] nm = Console.ReadLine().Trim().Split(' ').Select(x => int.Parse(x)).ToArray();
            List<int>[] graph = new List<int>[nm[0]];
            for (int i = 0; i < nm[0]; i++)
            {
                graph[i] = new List<int>();
            }

            for (int i = 0; i < nm[1]; i++)
            {
                int[] input = Console.ReadLine().Trim().Split(' ').Select(x => int.Parse(x)).ToArray();
                graph[input[0] - 1].Add(input[1] - 1);
                graph[input[1] - 1].Add(input[0] - 1);
            }

            List<Tuple<int, int>>[] spreader = new List<Tuple<int, int>>[nm[0]];

            for (int i = 0; i < nm[0]; i++)
            {
                spreader[i] = new List<Tuple<int, int>>();
                spreader[i].Add(Tuple.Create(i, 0));
            }

            int result = 0;
            bool update = true;

            while (update)
            {
                update = false;
                for (int i = 0; i < nm[0]; i++)
                {
                    for (int sp = 0; sp < spreader[i].Count(); sp++)
                    {
                        var v = spreader[i][sp];
                        if (v.Item2 < 3)
                        {
                            for (int gr = 0; gr < graph[i].Count; gr++)
                            {
                                var w = graph[i][gr];
                                if (!spreader[w].Contains(Tuple.Create(v.Item1, v.Item2 + 1)))
                                {
                                    spreader[w].Add(Tuple.Create(v.Item1, v.Item2 + 1));
                                    update = true;
                                    if (v.Item2 + 1 == 3 && v.Item1 != w && !graph[v.Item1].Contains(w))
                                    {
                                        graph[v.Item1].Add(w);
                                        graph[w].Add(v.Item1);
                                        result++;
                                    }
                                }                                
                            }
                        }
                    }
                }
            }

            Console.WriteLine(result);
#if DEBUG
            Console.ReadKey();
#endif
        }
    }
}

