    static void Solve(IO io)
    {
        var n = io.L;
        var m = io.L;

        var grl = new List<int>[n];
        var grs = new HashSet<int>[n];
        for (var i = 0; i < n; i++) grl[i] = new List<int>();
        for (var i = 0; i < n; i++) grs[i] = new HashSet<int>();

        for (var i = 0; i < m; i++)
        {
            var a = io.I - 1;
            var b = io.I - 1;
            grl[a].Add(b);
            grl[b].Add(a);
            grs[a].Add(b);
            grs[b].Add(a);
        }

        var hasc = false;

        for (var i = 0; i < n; i++)
            foreach (var j in grl[i])
                if (grl[j].Any(grs[i].Contains)) { hasc = true; break; }

        if (n == 2)
            io.Write(0);
        else if (n == 3)
            io.Write(n - m);
        else if (grl.Max(x => x.Count) == n - 1 && m == n - 1)
            io.Write(0);
        else if (n % 2 == 0 && !hasc)
            io.Write(n + ((n - 5) / 2 + 1) * n / 2 - m);
        else
            io.Write(n + ((n - 3) * n / 2) - m);
    }
