            int n = int.Parse(tempLine[0]);
            int m = int.Parse(tempLine[1]);

            Dictionary<int, List<int>> graph = new Dictionary<int, List<int>>();
            for (int i = 0; i < n; i++)
            {
                graph.Add(i + 1, new List<int>());
            }

            for (int i=0; i < m; i++)
            {
                line = Console.ReadLine();
                string[] temp = line.Split(' ');
                int u = int.Parse(temp[0]);
                int v = int.Parse(temp[1]);

                graph[u].Add(v);
                graph[v].Add(u);
            }

            int result = 0;
            int count = (int)Math.Floor((float)n/2f);
            for(int i=n; i > count; i--)
            {
                Queue<int> q = new Queue<int>();
                q.Enqueue(i);
                for(int j=0; j<3;j++)
                {
                    Queue<int> tempQueue = new Queue<int>();
                    while(q.Count > 0)
                    {
                        tempQueue.Enqueue(q.Dequeue());
                    }
                    while(tempQueue.Count > 0)
                    {
                        int index = tempQueue.Dequeue();
                        for (int k = 0; k < graph[index].Count; k++)
                        {
                            q.Enqueue(graph[index][k]);
                        }
                    }
                }

                bool added = false;
                while(q.Count>0)
                {
                    var item = q.Dequeue();
                    if(!graph[i].Contains(item))
                    {
                        graph[i].Add(item);
                        graph[item].Add(i);
                        result++;
                    }
                }
