    {
        return long.Parse(Next());
    }
}

class Magatro
{
    private int N, M;
    private List<int>[] R;
    private int[] Col;
    private void Scan()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        M = sc.NextInt();
        R = new List<int>[N];
        for (int i = 0; i < N; i++)
        {
            R[i] = new List<int>();
        }
        for (int i = 0; i < M; i++)
        {
            var a = sc.NextInt() - 1;
            var b = sc.NextInt() - 1;
            R[a].Add(b);
            R[b].Add(a);
        }
    }

    private bool F(int num, int col)
    {
        if (Col[num] == col)
        {
            return true;
        }
        else if (Col[num] == 0)
        {
            Col[num] = col;
            bool c = true;
            foreach (var i in R[num])
            {
                c &= F(i, col * -1);
            }
            return c;
        }
        else
        {
            return false;
        }
    }

    public void Solve()
    {
        Scan();
        Col = new int[N];
        if (F(0, 1))
        {
            int a = 0;
            int b = 0;
            foreach (var i in Col)
            {
                if (i == 1) a++;
                else b++;

            }
            Console.WriteLine((long)a * b - M);
        }
        else
        {
            Console.WriteLine((long)N * (N - 1) / 2 - M);
        }
    }

    static public void Main()
    {
        new Magatro().Solve();

    }
}

