namespace CF2017_qual_B_C___3_Steps
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.WriteLine(solver());
        }
        static int solver()
        {
            var NM = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
            var N = NM[0]; var M = NM[1];

            var connection = new bool[N + 1, N + 1];
            for (int i = 0; i < M; i++)
            {
                var ab = Array.ConvertAll(Console.ReadLine().Split(' '), int.Parse);
                connection[ab[0], ab[1]] = true;
                connection[ab[1], ab[0]] = true;
            }

            var isSearch = new bool[N + 1];
            var isBlack = new bool[N + 1];
            var stack = new Stack<int>();
            stack.Push(1);
            while (stack.Count > 0)
            {
                var cur = stack.Pop();
                isSearch[cur] = true;
                for (int i = 1; i < N + 1; i++)
                {
                    if (!connection[cur, i]) continue;
                    if (isSearch[i])
                    {
                        if (isBlack[i] == isBlack[cur]) return N * (N - 1) / 2 - M;
                    }
                    else
                    {
                        isBlack[i] = !isBlack[cur];
                        stack.Push(i);
                    }
                }
            }

            var black = isBlack.Count(b => b);
            return black * (N = black) - M;
        }
    }
}

