            for (int i = 1; i <= N; i++) {
                int res = 0;
                while (res != -1) {
                    res = has_new_edge(edges, i, 4, i);
                    if (res != -1)
                    {
                        edges[i].Add(res);
                        edges[res].Add(i);
                        sum++;

                    }
                }
            }

            Console.WriteLine(sum);

        }

        static int has_new_edge(List<List<int>> data, int node,int count,int firstnode) {

            if (count == 0) {
                var nodei = data[firstnode];
                foreach (var d in data[node]) {
                    if ((!is_included(nodei, d))&&(firstnode!=d)) return d;
                }
                return -1;
            }

            List<int> tmp = data[node];

            foreach (int t in tmp) {

                int res= has_new_edge(data, t, count - 1, firstnode);
                if (res != -1) return res;

            }

            return -1;

        }

        static bool is_included(List<int> list, int num) {
            foreach (var l in list) {
                if (l == num) return true;
            }
            return false;
        }

    }
