{
    class Program
    {
        private static int Solve(int N, int M, Tuple<int, int>[] tuples)
        {
            var link1 = new HashSet<int>[N + 1];
            var link2 = new HashSet<int>[N + 1];
            for (int i = 1; i <= N; ++i)
            {
                link1[i] = new HashSet<int>();
                link2[i] = new HashSet<int>();
            }
            int count = 0;
            var queue = new Queue<Tuple<int, int>>(tuples);
            while (queue.Count > 0)
            {
                var tuple = queue.Dequeue();
                int A = tuple.Item1;
                int B = tuple.Item2;
                if (A != B && !link1[A].Contains(B) && !link1[B].Contains(A))
                {
                    foreach (var a in link1[A])
                    {
                        foreach (var b in link1[B])
                        {
                            queue.Enqueue(new Tuple<int, int>(a, b));
                        }
                    }
                    foreach (var a in link2[A]) { queue.Enqueue(new Tuple<int, int>(a, B)); }
                    foreach (var b in link2[B]) { queue.Enqueue(new Tuple<int, int>(A, b)); }
                    foreach (var a in link1[A]) { if (a != B) { link2[B].Add(a); } }
                    foreach (var b in link1[B]) { if (b != A) { link2[A].Add(b); } }
                    link1[A].Add(B);
                    link1[B].Add(A);
                    ++count;
                }
            }
            return count - M;
        }
        static void Main(string[] args)
        {
            int[] values1 = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
            int N = values1[0];
            int M = values1[1];
            var tuples = new Tuple<int, int>[M];
            for (int i = 0; i < M; ++i)
            {
                int[] values2 = Array.ConvertAll(Console.ReadLine().Split(), int.Parse);
                tuples[i] = new Tuple<int, int>(values2[0], values2[1]);
            }
            Console.WriteLine(Solve(N, M, tuples));
        }
    }
}

