        for (int i = 0; i < M; i++)
            graph.AddEdge(Reader.Int() - 1, Reader.Int() - 1);
        if (graph.IsBipartite()) Console.WriteLine((long)graph.A.Count * graph.B.Count - M);
        else Console.WriteLine((long)N * (N - 1) / 2 - M);
