public class BipartiteGraph
{
    public List<int> A = new List<int>(), B = new List<int>();
    readonly int N;
    readonly List<int>[] E;

    public BipartiteGraph(int N)
    {
        this.N = N;
        E = new List<int>[N];
        for (int i = 0; i < N; i++) E[i] = new List<int>();
    }

    public void AddEdge(int a, int b) { E[a].Add(b); E[b].Add(a); }

    public bool IsBipartite()
    {
        var mark = new int[N];
        var que = new Queue<int>();
        for (int i = 0; i < N; i++)
            if (mark[i] == 0)
                for (que.Enqueue(i); que.Count > 0; )
                {
                    int m = que.Dequeue(), v = m >> 1, parity = m & 1;
                    mark[v] = (parity << 1) - 1;
                    if (mark[v] == 1) A.Add(v);
                    else B.Add(v);
                    foreach (int next in E[v])
                        if (mark[next] == mark[v]) return false;
                        else if (mark[next] == 0) que.Enqueue(next << 1 | parity ^ 1);
                }
        return true;
    }
}


