  var isPrefix bool = true
  var err error
  for isPrefix {
    line, isPrefix, err = reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
  }
  return string(buffer)
}
func NextIntVec() []int {
  L := strings.Split(NextLine(), " ")
  N := make([]int, len(L))
  for i := range N {
    N[i], _ = strconv.Atoi(L[i])
  }
  return N
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func Output() {
  _ = writer.Flush()
}

func main() {
  NM := NextIntVec()
  N := NM[0]
  M := NM[1]
  G := make([][]int, N)
  for i := range G {
    G[i] = make([]int, 0)
  }
  for i := 0; i < M; i++ {
    AB := NextIntVec()
    A := AB[0] - 1
    B := AB[1] - 1
    G[A] = append(G[A], B)
    G[B] = append(G[B], A)
  }
  D := make([]int, N)
  for i := 1; i < N; i++ {
    D[i] = N
  }
  Q := make([]int, N)
  pos := 1
  incomplete := true
  for i := 0; i < N && incomplete; i++  {
    s := Q[i]
    for _, adj := range G[s] {
      if D[adj] < D[s] { continue }
      if D[adj] < N {
        incomplete = false
        break
      }
      D[adj] = D[s] + 1
      Q[pos] = adj
      pos += 1
    }
  }
  cnt := N * (N - 1) / 2 - M
  if incomplete {
  	OE := []int{0, 0}
  	for _, d := range D {
      OE[d % 2] += 1
  	}
    cnt -= OE[0] * (OE[0] - 1) / 2 + OE[1] * (OE[1] - 1) / 2  
  }
  Write(cnt)
  Output()
}

