				edges = append(edges, Edge{u: u, v: i})
				g[u] = append(g[u], len(edges)-1)
				edges = append(edges, Edge{u: i, v: u})
				g[i] = append(g[i], len(edges)-1)
				vis[i][u] = true
				vis[u][i] = true
				ans++
