func BipartiteJudge(G [][]int) ([]int, bool) {
	v := len(G)
	colors := make([]int, v)

	for i := 0; i < v; i++ {
		if colors[i] == 0 {
			// まだ頂点iが塗られていなければ1で塗る
			if !dfs(i, 1, colors, G) {
