		}
	}

	return colors, true
}

// 頂点を1, -1で塗っていく
func dfs(v, c int, colors []int, G [][]int) bool {
	colors[v] = c
	for _, nid := range G[v] {
		// 隣接している頂点が同じ色ならfalse
		if colors[nid] == c {
			return false
		}
		// 隣接している頂点がまだ塗られていないなら-cで塗る
		if colors[nid] == 0 && !dfs(nid, -c, colors, G) {
			return false
		}
	}

	// すべての頂点を塗れたらtrue
	return true
}

