func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	m := getNextInt(scanner)
	g := make([][]int, n)
	aa := make([]int, m)
	bb := make([]int, m)
	for i := 0; i < m; i++ {
		a := getNextInt(scanner) - 1
		b := getNextInt(scanner) - 1
		aa[i] = a
		bb[i] = b
		g[a] = append(g[a], b)
		a, b = b, a
		g[a] = append(g[a], b)
	}
	sol := solver{}
	sol.g = g
	sol.visited = make([]int, n)
	var ans int64
	ans = int64(n)*int64(n-1)/2 - int64(m)
	if sol.dfs(0, 2) {
		fmt.Fprintln(writer, ans)
		return
	}
	cc := map[int]int64{}
	for i := 0; i < n; i++ {
		cc[sol.visited[i]] = cc[sol.visited[i]] + 1
	}
	ans -= cc[1]*(cc[1]-1)/2 + cc[2]*(cc[2]-1)/2
	for i := 0; i < m; i++ {
		if sol.visited[aa[i]] == sol.visited[bb[i]] {
			ans++
			continue
		}
	}
	fmt.Fprintln(writer, ans)
}

type solver struct {
	g       [][]int
	visited []int
}

func (sol *solver) dfs(i, c int) bool {
	sol.visited[i] = c
	for _, to := range sol.g[i] {
		if sol.visited[to] == 0 {
			b := sol.dfs(to, 3-c)
			if b {
				return true
			}
			continue
		}
		if sol.visited[to] != c {
			continue
		}
		return true
	}

	return false
}

