	}

	colors, ok := BipartiteJudge(edges)
	if ok {
		white, black := 0, 0
		for _, c := range colors {
			if c == 1 {
				white++
			} else {
				black++
			}
		}
		fmt.Println(white*black - m)
	} else {
		fmt.Println(n*(n-1)/2 - m)
	}
