  for i := 1; i < N; i++ {
    D[i] = N
  }
  Q := make([]int, N)
  pos := 1
  incomplete := true
  for i := 0; i < N && incomplete; i++  {
    s := Q[i]
    for _, adj := range G[s] {
      if D[adj] < D[s] { continue }
      if D[adj] == D[s] {
        incomplete = false
        break
      }
      D[adj] = D[s] + 1
      Q[pos] = adj
      pos += 1
    }
  }
  OE := []int{0, 0}
  for _, d := range D {
    OE[d % 2] += 1
  }
  cnt := N * (N - 1) / 2 - M
  if incomplete {
    cnt -= OE[0] * (OE[0] - 1) / 2 + OE[1] * (OE[1] - 1) / 2  
  }
  Write(cnt)
  Output()
}

