type Pair struct {
	Value, Depth int
}

type Graph map[int]map[int]bool

func main() {
	reader := bufio.NewReader(os.Stdin)
	text, _ := reader.ReadString('\n')
	nm := strings.Split(strings.Trim(text, "\n"), " ")
	m, _ := strconv.Atoi(nm[1])

	graph := Graph{}

	for i := 0; i < m; i++ {
		text, _ := reader.ReadString('\n')
		ab := strings.Split(strings.Trim(text, "\n"), " ")
		a, _ := strconv.Atoi(ab[0])
		b, _ := strconv.Atoi(ab[1])
		_, ok := graph[a]
		if !ok {
			graph[a] = map[int]bool{
				b: true,
			}
		} else {
			graph[a][b] = true
		}
		_, ok = graph[b]
		if !ok {
			graph[b] = map[int]bool{
				a: true,
			}
		} else {
			graph[b][a] = true
		}
	}

	total := 0
	for {
		changed := false
		for k := range graph {
			v3 := bfs3(graph, k)
			for _, v := range v3 {
				if _, ok := graph[k][v.Value]; !ok {
					changed = true
					total++
					graph[k][v.Value] = true
					graph[v.Value][k] = true
				}
			}
		}
		if !changed {
			break
		}
	}
	fmt.Println(total)
}

func bfs3(g Graph, v int) []Pair {
	open := []Pair{Pair{v, 0}}
	close := map[int]bool{}
	for len(open) != 0 {
		curr := open[0]
		open = open[1:]
		if curr.Depth == 3 {
			open = append(open, curr)
			break
		}
		close[curr.Value] = true
		for k := range g[curr.Value] {
			if _, ok := close[k]; !ok {
				open = append(open, Pair{k, curr.Depth + 1})
			}
		}
	}

	return open
}

