	if (node < 0 || node > n) return true;
	color[node] = c;
	try {
		for (const edge of g.getArray(true)[node]) {
			if (color[edge.to] == c) return false;
			if (color[edge.to] == 0 && !dfs(edge.to, -c)) return false;
		}
	}
	catch (e) {
		return false;
	}
	return true;
};

