//最大流、O(|V||E|^2)
template Flow_Dinic() {
  class Edge {
  public:
    this(long to, long capacity) {
      this.to = to;
      this.capacity = capacity;
    }

    long to;
    long capacity;
    Edge reverse;
  }

  //gを残余グラフにする
  void residualise(ref Edge[][] g) {
    foreach (u; iota(g.length)) {
      foreach (e; g[u]) {
        if (e.capacity != 0) {
          e.reverse = new Edge(u, 0);
          e.reverse.reverse = e;
          g[e.to] ~= e.reverse;
        }
      }
    }
  }

  const long INF = long.max / 2;

  //gは残余グラフ
  //gは計算の結果書き換わる
  long solve(Edge[][] g, long s, long t) {
    long ret;
    while (true) {
      auto level = new long[](g.length);
      level[] = INF;
      auto q = DList!long(s);
      level[s] = 0;
      //level graph
      auto lg = new Edge[][](g.length, 0);
      while (!q.empty()) {
        auto u = q.front();
        q.removeFront();
        if (u == t) {
          break;
        }
        foreach (e; g[u]) {
          if (e.capacity > 0 && level[e.to] >= level[u] + 1) {
            level[e.to] = level[u] + 1;
            q.insertBack(e.to);
            lg[u] ~= e;
          }
        }
      }
      if (level[t] == INF) {
        break;
      }
      auto iter = new long[](g.length);
      long dfs(long u, long c_min) {
        if (u == t) {
          return c_min;
        }
        foreach (i; iota(iter[u], lg[u].length)) {
          iter[u] = i;
          long f = dfs(lg[u][i].to, min(c_min, lg[u][i].capacity));
          if (f > 0) {
            lg[u][i].capacity -= f;
            lg[u][i].reverse.capacity += f;
            return f;
          }
        }
        return 0;
      }

      while (true) {
        long f = dfs(s, INF);
        if (f == 0) {
          break;
        }
        ret += f;
      }
    }
    return ret;
  }
}

//Pは素数
struct ModInt(ulong P) if (P < int.max) {
  long num;
  this(long num) {
    this.num = num % P;
  }

  const auto inv() {
    return this ^^ (P - 2);
  }

  const bool opEquals()(auto ref const ModInt m) {
    return this.num == m.num;
  }

  const bool opEquals()(auto ref const long m) {
    return this.num == m;
  }

  const auto opBinary(string op)(ModInt r) {
    static if (op == "+") {
      return ModInt(this.num + r.num);
    } else static if (op == "-") {
      return ModInt(this.num + P - (r.num % P));
    } else static if (op == "*") {
      return ModInt(this.num * r.num);
    } else static if (op == "/") {
      return this * r.inv();
    } else static if (op == "^^") {
      return this ^^ r.num;
    }
  }

  const auto opBinary(string op)(long r) {
    static if (op == "^^") {
      if (r == 0) {
        return ModInt(1);
      }
      return (this * this) ^^ (r / 2) * (r % 2 == 1 ? this : ModInt(1));
    } else {
      return this.opBinary!(op)(ModInt!P(r));
    }
  }

  void opAssign(long r) {
    this.num = r % P;
  }

  void opOpAssign(string op, T)(T r) {
    this = this.opBinary!(op)(r);
  }

  string toString() {
    return this.num.to!string;
  }
}

//P(n)を最大n = N-1までメモ
class PMemo(T) {
  this(long N) {
    t = new T[](N);
    t[0] = 1;
    foreach (i; iota(1, N)) {
      t[i] = t[i - 1] * i;
    }
  }

  T p(long n) {
    return t[n];
  }

  T[] t;
}

//nCkを最大n = N-1までメモ
class CMemo(T) {
  this(long N) {
    p_memo = new PMemo!T(N);
  }

  T c(long n, long k) {
    return p_memo.p(n) / (p_memo.p(n - k) * p_memo.p(k));
  }

  PMemo!T p_memo;
}

// [l, r)を管理するセグツリー
class SegmentTree(T, alias F) if (is(typeof(binaryFun!F))) {
  alias f = binaryFun!F;
public:
  this(size_t l, size_t r, T t) {
    this.l = l;
    this.r = r;
    if (r == l + 1) {
      v = t;
    } else {
      auto m = (l + r) / 2;
      lc = new SegmentTree(l, m, t);
      rc = new SegmentTree(m, r, t);
      v = f(lc.v, rc.v);
    }
  }

  this(size_t n, T t) {
    this(0, n, t);
  }

  void update(size_t l, size_t r, T v) {
    if (this.r <= l || r <= this.l) {
      return;
    }
    if (l <= this.l && this.r <= r) {
      this.v = v;
    } else {
      lc.update(l, r, v);
      rc.update(l, r, v);
      this.v = f(lc.v, rc.v);
    }
  }

  void update(size_t idx, T v) {
    update(idx, idx + 1, v);
  }

  auto read(size_t l, size_t r) {
    assert(this.l <= l && r <= this.r);
    if (l == this.l && this.r == r) {
      return this.v;
    } else {
      if (r <= lc.r) {
        return lc.read(l, r);
      } else if (rc.l <= l) {
        return rc.read(l, r);
      } else {
        return f(lc.read(l, lc.r), rc.read(rc.l, r));
      }
    }
  }

private:
  size_t l, r;
  T v;
  SegmentTree lc, rc;
}

