proc isBipartiteGraph(g: seq2[int]): seq[bool] =
  let n = g.len()

  var stack = newSeq[int](0)
  var mark = newSeq[int](n)
  mark.fill(0)

  for v in 0..<n:
    if mark[v] != 0:
      continue

    mark[v] = 1
    stack.add(v)

    while stack.len() > 0:
      let v = stack.pop()
      for u in g[v]:
        if mark[v] == mark[u]:
          return nil
        if mark[u] == 0:
          mark[u] = -mark[v]
          stack.add(u)

  return mark.map(it => it > 0)

