def choose(n,k):
    import math
    return math.factorial(n)//(math.factorial(n-k)*math.factorial(k))
if judgeBiGragh(edges):
    ans = (N//2)*(N-N//2) - M
else:
    ans = choose(N,2)-M

print(ans)

