class Graph:
    def __init__(self, V, directed=False):
        self.V = V
        self.directed = directed
        self.adj_list = {i: [] for i in self.V}

    def add_edge(self, u, v):
        self.adj_list[u].append(v)
        if not self.directed:
            self.adj_list[v].append(u)

def bipartite(graph):
    color = {v: None for v in graph.V}
    stack = [(graph.V[0], 0)]
    while stack:
        v, c = stack.pop()
        color[v] = c
        for u in graph.adj_list[v]:
            if color[u] is None: # not visited yet
                stack.append((u, c^1)) # paint u with different color from v's one
            elif color[u] != c: # consistent
                continue
            else: # inconsistent
                return (None, None)
    parts = {0: [], 1:[]}
    for v in graph.V:
        parts[color[v]].append(v)
    return (parts[0], parts[1])

