    total_new_edges = 0

    while new_nodes:
        new_nodes = False
        for start in range(1,N+1):
            queue = [(start,0)]
            seen = {start}

            index = 0

            while index < len(queue):
                current = queue[index]
                if current[1] < 3:
                    for i in graph[current[0]]:
                        if i not in seen:
                            queue.append((i,current[1]+1))
                else:
                    if current[0] not in graph[start] and start not in graph[current[0]]:
                        graph[start].add(current[0])
                        graph[current[0]].add(start)
                        new_nodes = True
                        total_new_edges += 1

                seen.add(current[0])
                index += 1
    return total_new_edges

