def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N, M, AB):
    ans = 0
    g = defaultdict(set)
    for a, b in AB:
        g[a].add(b)
        g[b].add(a)

    def f(vs):
        if len(vs) == 4:
            u, v = vs[0], vs[-1]
            if u not in g[v]:
                g[u].add(v)
                g[v].add(u)
                return 1
        u = vs[-1]
        r = 0
        for v in list(g[u]):
            if v not in vs:
                vs.append(v)
                r += f(vs)
                vs.pop()
        return r

    ans = 0
    while True:
        prev = ans
        for i in range(1, N+1):
            ans += f([i])
        if ans == prev:
            break

    return ans


