def slv(N, M, AB):
    ans = 0
    g = defaultdict(set)
    for a, b in AB:
        g[a].add(b)
        g[b].add(a)

    def f(vs):
        if len(vs) == 4:
            return set([(vs[0], vs[-1])])
        u = vs[-1]
        ans = set()
        for v in g[u]:
            if v not in vs:
                vs.append(v)
                ans |= f(vs)
                vs.pop()
        return ans



    update = True
    ans = 0
    while update:
        update = False

        adding = set()
        for i in range(1, N+1):
            adding |= f([i])
        for a, b in adding:
            if b not in g[a]:
                g[a].add(b)
                g[b].add(a)
                update = True
                ans += 1

    return ans


