class BipartiteGraph():
    '''
    2部グラフ
    self.vertexesが1の集合と2の集合に分割
    '''
    def __init__(self, n):
        self.vertexes = [0 for _ in range(n)]

    # 2部グラフじゃなかったらfalseを返す
    def add(self, edge):  # edge = (2, 3)
        if self.vertexes[edge[0]] == 0:
            if self.vertexes[edge[1]] == 1:
                self.vertexes[edge[0]] = 2
            elif self.vertexes[edge[1]] == 2:
                self.vertexes[edge[0]] = 1
            else:
                self.vertexes[edge[0]] = 1
                self.vertexes[edge[1]] = 2
        elif self.vertexes[edge[0]] == 1:
            if self.vertexes[edge[1]] == 1:
                return False
            else:
                self.vertexes[edge[1]] = 2
        elif self.vertexes[edge[0]] == 2:
            if self.vertexes[edge[1]] == 2:
                return False
            else:
                self.vertexes[edge[1]] = 1
        return True

    def length(self):
        cnt = [0, 0]
        for i in self.vertexes:
            cnt[i-1] += 1
        return cnt

    def __str__(self):
        A = []
        B = []
        for i, v in enumerate(self.vertexes):
            if v == 1:
                A.append(str(i))
            elif v == 2:
                B.append(str(i))
        return 'A:[' + ','.join(A) + "]B:[" + ','.join(B) + "]"

