// euclidの互除法
fn gcd(a: i64, b: i64) -> i64 {
    if b == 0 { a }
    else { gcd(b, a % b) }
}
// ab = lcm(a, b)gcd(a, b)
fn lcm(a: i64, b: i64) -> i64 {
    let g = gcd(a, b);
    (a / g) * b
}
// 約数列挙 昇順ではない
fn divisors(n: i64) -> Vec<i64> {
    let mut ret = Vec::new();
    if n == 1 { ret.push(1); return ret; }
    let mut i = 1;
    loop {
        if (n % i) == 0 {
            ret.push(i);
            if (i != 1) & ((i*i) != n) {
                ret.push(n / i);
            }
        }
        i += 1; if n < (i*i) { break; }
    }
    ret.push(n);
    ret
}

fn is_max_i64(num: i64) -> bool { if num == i64::max_value() { true } else { false } }

fn dfs(mat: &mut Vec<Vec<usize>>, before: usize, current: usize, start: usize, step: usize) -> usize {
    let mut cnt = 0;
    match step {
        3 => {
            if (start != current) & !mat[current].contains(&start) {
                //println!("connected {}, {}", start, current);
                mat[current].push(start);
                mat[start].push(current);
                cnt += 1;
                for i in 0..mat[current].len() {
                    let next = mat[current][i];
                    if next == start { continue; }
                    cnt += dfs(mat, current, next, start, 2);
                }
            }
        },
        _ => {
            for i in 0..mat[current].len() {
                let next = mat[current][i];
                if next == before { continue; }
                cnt += dfs(mat, current, next, start, step + 1);
            }
        }
    }
    cnt
}


