fn solve() {
    let (n,m) = get!(usize, usize);
    let ab = get!(usize, usize; m);

    let mut nodes = vec![Vec::new(); n+1];
    for (a,b) in ab {
        nodes[a].push(b);
        nodes[b].push(a);
    }

    let mut colors = vec![None; n+1];
    let mut queue = VecDeque::new();
    queue.push_back((1,false));
    colors[1] = Some(false);
    while let Some((node, color)) = queue.pop_front() {
        for &next in &nodes[node] {
            if let Some(c) = colors[next] {
                if c == color {
                    println!("{}", n*(n-1)/2-m);
                    return;
                }
                continue;
            }
            queue.push_back((next,!color));
            colors[next] = Some(!color);
        }
    }
    let mut count = 0;
    for i in 1..n+1 {
        if colors[i].unwrap() {
            count += 1;
        }
    }
    println!("{}", count*(n-count)-m);
}

