fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn dfs(v: usize, graph: &Vec<Vec<usize>>, color: &mut Vec<i64>, n: usize) -> bool {
    let mut b = true;
    //println!("{:?}", graph);
    for i in 0..graph[v].len() {
        //println!("{}", u);
        let u = graph[v][i];
        if color[u] == 0 {
            color[u] = -color[v];
            //println!("{} {} {:?}", u, v, color);
            b = dfs(u, graph, color, n);
        } else if color[u] == color[v] {
            //println!("{} {} {:?}", u, v, color);
            return false;
        }
    }
    return b;
}

fn solve(graph: & Vec<Vec<usize>>, n: usize, m: usize) {
    let mut color = vec![0; n+1];
    color[1] = 1;
    let bipartite: bool = dfs(1, &graph, &mut color, n);
    if bipartite {
        let mut k = 0;
        for i in 0..color.len() {
            if color[i] == 1 {
                k += 1;
            }
        }
        let n = n as i64;
        let m = m as i64;
        println!("{:?}", k * (n - k) - m);
    } else {
        println!("{}", n * (n-1) / 2 - m);
    }
}

