fn bfs_dist(N:usize,E:&Vec<Vec<usize>>,start:usize) -> Vec<isize>{
    let mut D = (0..N).map(|_| -1).collect::<Vec<_>>();
    D[start] = 0;
    let mut q = vec![start];
    while q.len()>0{
        let mut qq = Vec::new();
        for &i in &q{
            for &j in &E[i]{
                if D[j]!=-1{continue;}
                D[j] = D[i]+1;
                qq.push(j);
            }
        }
        q = qq;
    }
    D
}

