fn is_bipartite(g: &Vec<Vec<usize>>) -> (bool, Option<(usize, usize)>) {
  fn dfs(v: usize, p: bool, g: &Vec<Vec<usize>>, cv: &mut Vec<Option<bool>>) -> bool {
    match cv[v] {
      None => {
        let next = &g[v];
        cv[v] = Some(p);
        next.iter().all(|&w|dfs(w,!p,g,cv))
      },
      Some(q) if q == p => {true},
      Some(q) if q != p => {false},
      _ => unreachable!()
    }
  }

  let mut canvas: Vec<Option<bool>> = vec![None; g.len()];
  let ans = dfs(1, false, g, &mut canvas);
  let b = canvas.iter().filter(|&&v|v==Some(false)).count();
  let w = canvas.iter().filter(|&&v|v==Some(true)).count();
  (ans, if ans {Some((b,w))} else {None})
}

fn read_tuple<T1: std::str::FromStr, T2: std::str::FromStr>() -> (T1, T2) {
  let mut buf = String::new();
  std::io::stdin().read_line(&mut buf).ok();
  let mut it = buf.trim().split_whitespace();
  let x = it.next().unwrap().parse::<T1>().ok().unwrap();
  let y = it.next().unwrap().parse::<T2>().ok().unwrap();
  (x, y)
}

fn read_tuples<T1: std::str::FromStr, T2: std::str::FromStr>(n: usize) -> Vec<(T1, T2)> {
  let mut vec: Vec<(T1, T2)> = vec![];
  for _ in 0 .. n {
    vec.push(read_tuple());
  }
  vec
}

