fn dfs(v: usize, ve: &[HashSet<usize>], c: bool, color: &mut [Option<bool>]) -> bool {
    color[v] = Some(c);
    for &t in ve[v].iter() {
        if color[t].map(|b| b == c).unwrap_or(false) {
            return false;
        } else {
            if color[t].is_none() && !dfs(t, ve, !c, color) {
                return false;
            }
        }
    }
    true
}

