fn solve() {
    let out = stdout();
    let mut out = BufWriter::new(out.lock());

    input!{
        n:usize,m:usize,
        ab:[(usize,usize);m]
    }

    let mut g = vec![vec![];n];
    for i in 0..m {
        let (a,b) = ab[i];
        g[a-1].push(b-1);
        g[b-1].push(a-1);
    }

    let res = is_bigraph(&g);

    if res.is_none() {
        println!("{}", n*(n-1)/2 - m);
        return
    } 

    let res = res.unwrap();
    let mut black = vec![];
    let mut white = vec![];
    for i in 0..n {
        if res[i] {
            black.push(i);
        } else {
            white.push(i);
        }
    }
    let nb = black.len();
    let nw = white.len();
    println!("{}", nb*nw-m);
}

pub fn is_bigraph(g: &[Vec<usize>]) -> Option<Vec<bool>> {
    struct Rec<'a> {
        g: &'a [Vec<usize>],
        color: Vec<i8>,
    }
    impl <'a> Rec<'a> {
        fn solve(&mut self, u: usize, color: i8) -> bool {
            self.color[u] = color;

            let mut ok = true;
            for i in 0..self.g[u].len() {
                let v = self.g[u][i];
                if self.color[v] == 0 {
                    if !self.solve(v, -1*color) {
                        ok = false
                    }
                } else {
                    if self.color[v] == color {
                        ok = false
                    }
                }
            }
            ok
        }
    }

    let n = g.len();
    let mut rec = Rec {
        g: g,
        color: vec![0;n],
    };
    let ok = rec.solve(0, 1);
    if !ok {
        return None
    }
    let mut res = vec![];
    for i in 0..n {
        if rec.color[i] == 1 {
            res.push(true)
        } else {
            res.push(false)
        }
    }
    Some(res)
}

