        graph[e.1].push( Edge{from:e.1, to:e.0, weight:1})
    }


    let mut stack: Vec<Edge> = Vec::new();
    stack.push(Edge{from:0, to:0, weight:0});

    let mut visited: Vec<bool> = vec![false; n];
    let mut color: Vec<i32> = vec![-1; n];
