fn dijkstra(s:usize, g:&Vec<Vec<(usize, i64)>>)->(Vec<usize>, Vec<i64>){
    let mut d = vec![INF;g.len()];
    let mut prev = vec![g.len();g.len()];
    d[s] = 0;
    let mut h = BinaryHeap::new();
    h.push((0, s));
    while(h.len() != 0){
        let mut top = h.pop().unwrap();
        let mut v = top.1;
        let mut l = top.0 * -1;
        if l > d[v]{
            continue;
        }
        for i in 0..g[v].len(){
            let nl = l + g[v][i].1;
            let n = g[v][i].0;
            if d[n] > nl{
                prev[n] = v;
                d[n] = nl;
                h.push((nl*-1, n));
            }
        }
    }
    (prev, d)
}
fn dijkstra2(X:usize, Y:usize, g:&Vec<Vec<char>>, xx:i64)->Vec<Vec<i64>>{
    let mut d = vec![vec![INF;g[0].len()];g.len()];
    d[X][Y] = 0;
    let mut h = BinaryHeap::new();
    h.push((0, X as i64, Y as i64));
    let dx = vec![0,0,-1, 1];
    let dy = vec![1, -1, 0, 0];
    while(h.len() != 0){
        let mut top = h.pop().unwrap();
        let mut x = top.1;
        let mut y = top.2;
        let mut l = top.0 * -1;
        if l > d[x as usize][y as usize]{
            continue;
        }
        for i in 0..4{
            let mut nx = dx[i]+x;
            let mut ny = dy[i]+y;
            if 0<=nx && nx<g.len() as i64 && 0<=ny && ny<g[0].len() as i64{
                let mut nx = nx as usize;
                let mut ny = ny as usize;
                let nl = l + if g[nx][ny] == '#'{xx}else{1};
                if d[nx][ny]>nl{
                    d[nx][ny] = nl;
                    h.push((nl*-1, nx as i64, ny as i64));
                }
            }

        }
    }
    d
}
fn solve(){
    input!{
        N:usize,
        M:usize,
        ab:[[usize;2];M],
    }
    let mut g = vec![vec![];N];
    for i in 0..M{
        let a = ab[i][0];
        let b = ab[i][1];
        g[a-1].push(b-1);
        g[b-1].push(a-1);
    }
    let mut c = vec![2;N];
    fn dfs(s:usize, cb:usize, c:&mut Vec<usize>, g:&Vec<Vec<usize>>)->bool{
        c[s] = cb;
        for i in 0..g[s].len(){
            let n = g[s][i];
            if c[n] == cb{
                return false;
            }
            if c[n] == 2 && dfs(n, (cb+1)%2, c, g) == false {
                return false;
            }
        }
        return true;
    }
    if dfs(0, 0, &mut c, &g){
        let mut a = 0;
        let mut b = 0;
        for i in 0..N{
            if c[i] == 0{
                a+=1;
            }
            else{
                b+=1;
            }
        }
        println!("{}", (a)*(b)-M);
    }
    else{
        println!("{}", N*(N-1)/2 - M);
    }
}


