pub struct GraphRec {
    n: usize,
    m: usize,
    graph: Vec<Vec<usize>>,
    cost: Vec<Option<usize>>,
    odd: bool,
}
impl GraphRec {
    pub fn new(n: usize, m: usize) -> GraphRec {
        GraphRec {
            n: n,
            m: m,
            graph: vec![vec![]; n],
            cost: vec![None; n],
            odd: false,
        }
    }
    pub fn add_edge(&mut self, u: usize, v: usize) {
        self.graph[u].push(v);
        self.graph[v].push(u);
    }
    pub fn dfs(&mut self, u: usize) {
        let d = self.cost[u].unwrap_or(0);
        for i in 0..self.graph[u].len() {
            let v = self.graph[u][i];
            if self.cost[v].is_none() {
                self.cost[v] = Some(d + 1);
                self.dfs(v);
            } else {
                let c = self.cost[v].unwrap_or(0);
                if (c + d) % 2 == 0 {
                    self.odd = true;
                }
            }
        }
    }
    pub fn solve(&mut self) {
        let n = self.n;
        self.cost[0] = Some(0);
        self.dfs(0);
        if self.odd {
            println!("{}", n * (n - 1) / 2 - self.m);
        } else {
            let mut o = vec![0; 2];
            for i in 0..n {
                o[self.cost[i].unwrap_or(0) % 2] += 1;
            }
            println!("{}", o[0] * o[1] - self.m);
        }
    }
}
