use unionfind::*;

fn main() {
    input! {
        n: usize,
        m: usize,
        es: [(usize1,usize1); m],
    }
    let mut uf = UnionFind::new(2 * n);
    for &(s, t) in &es {
        uf.unite(2 * s, 2 * t + 1);
        uf.unite(2 * s + 1, 2 * t);
    }
    if uf.is_same_set(0, 1) {
        let res = n * (n - 1) / 2 - m;
        println!("{}", res);
    } else {
        let mut a = 0;
        let mut b = 0;
        for i in 0..n {
            if uf.is_same_set(0, i) {
                a += 1;
            } else {
                b += 1;
            }
        }
        let res = a * b - m;
        println!("{}", res);
    }
}

