fn bfs(r: usize, g: &Vec<Vec<usize>>, d: &mut Vec<usize>) -> bool {
    d[r] = 0;
    let mut q = std::collections::VecDeque::new();
    q.push_back(r);
    while let Some(v) = q.pop_front() {
        let l = d[v] + 1;
        for &u in g[v].iter() {
            if d[u] > l {
                d[u] = l;
                q.push_back(u);
            } else if d[u] % 2 == d[v] % 2 {
                return false;
            }
        }
    }
    true
}

fn run() {
    input! {
        n: usize,
        m: usize,
        e: [(usize1, usize1); m],
    }
    let mut g = vec![vec![]; n];
    for &(a, b) in e.iter() {
        g[a].push(b);
        g[b].push(a);
    }
    let mut d = vec![n; n];
    let ans = if bfs(0, &g, &mut d) {
        let mut cnt = [0; 2];
        for &d in d.iter() {
            cnt[d & 1] += 1;
        }
        let mut sum = cnt[0] * cnt[1];
        for &(a, b) in e.iter() {
            if d[a] % 2 != d[b] {
                sum -= 1;
            }
        }
        sum
    } else {
        n * (n - 1) / 2 - m
    };
    println!("{}", ans);
}

